# -*- coding: utf-8 -*-
"""
Master 25-Day TOEIC Golden Certificate (860+) Curriculum.
Full 40 questions per day (20 Morning + 14 Traps + 6 Part 7) = 1,000 questions total.
All Part 7 reading passages expanded to authentic, long-form corporate business texts (175 - 240 words).
"""

import json

_RAW = {"1": {"day": 1, "date": "11/04", "phase": 1, "phase_name": "錯題庫清零與語感校正", "topic": "連介秒殺 ｜ 監督 vs. 疏忽 ｜ 資格與授權語塊", "morning": {"chunks": [{"chunk": "oversee the project", "meaning": "監督這項專案", "scenario": "Ms. Lin was appointed to oversee the project due to her extensive management experience.", "paraphrase": "oversee = supervise = manage", "alert": "注意：oversight 是名詞，指『疏忽 / 遺漏』！"}, {"chunk": "an unfortunate oversight", "meaning": "一個令人遺憾的疏忽", "scenario": "Due to an unfortunate oversight, the revised invoice was sent to the wrong vendor.", "paraphrase": "oversight = mistake = omission", "alert": ""}, {"chunk": "eligible for promotion", "meaning": "符合升遷資格", "scenario": "Only full-time staff who complete the leadership workshop are eligible for promotion.", "paraphrase": "eligible for = qualified for", "alert": "必考介系詞：eligible 後方固定搭配 for + 名詞！"}, {"chunk": "entitled to a refund", "meaning": "有權獲得退款", "scenario": "Customers receiving damaged items are entitled to a refund within 14 business days.", "paraphrase": "entitled to = have the right to", "alert": "必考介系詞：be entitled to + 名詞 / 原形動詞"}, {"chunk": "exempted from the fee", "meaning": "免除此筆費用", "scenario": "Attendees registering before Friday are automatically exempted from the fee.", "paraphrase": "exempted from = excused from", "alert": "必考介系詞：exempted 後方固定搭配 from！"}, {"chunk": "compatible with the system", "meaning": "與該系統相容", "scenario": "Please verify that the software update is compatible with the operating system.", "paraphrase": "compatible with = adaptable to = work with", "alert": "必考介系詞：compatible 固定搭配 with！"}, {"chunk": "under the direction of", "meaning": "在……指導／領導之下", "scenario": "The new research lab was constructed under the direction of Dr. Morales.", "paraphrase": "under the direction of = under the leadership of", "alert": ""}], "visual_anchor": {"title": "看到空格後有沒有「動詞」？", "rule_1": "👀 空格後有【主詞 + 動詞】➔ 秒選手拉手的「連接詞」（although, because, even if）", "rule_2": "👀 空格後只有【名詞 / V-ing】➔ 秒選單兵作戰的「介系詞」（in spite of, despite, owing to, prior to）", "golden_rule": "⚡ 教練金句：有動詞選「連」，沒動詞選「介」！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "________ the unexpected budget cuts, the marketing team managed to launch the product on schedule.", "options": {"A": "Although", "B": "In spite of", "C": "Even if", "D": "Nevertheless"}, "answer": "B", "analysis": "視覺錨點：空格後為 'the unexpected budget cuts'（純名詞片語無動詞），秒選介系詞。Although 與 Even if 後須接完整 S+V 子句；Nevertheless 為轉折副詞，不可放句首直接接名詞。", "translation": "儘管預算遭到意外縮減，行銷團隊仍成功如期推出該產品。"}, {"id": 2, "target_seconds": 15, "question": "The board has appointed Ms. Alvarez to ________ the newly established division in Tokyo.", "options": {"A": "oversee", "B": "oversight", "C": "overseeing", "D": "overseen"}, "answer": "A", "analysis": "看到不定詞結構 'to + [原形動詞]' 帶出受詞 'the newly established division'。oversee 為動詞（監督/負責）。oversight 為名詞（疏忽），語法與語意皆不合。", "translation": "董事會已指派 Alvarez 女士負責監督東京新成立的部門。"}, {"id": 3, "target_seconds": 15, "question": "Only employees who have served for over two consecutive years are ________ for the corporate leadership program.", "options": {"A": "capable", "B": "eligible", "C": "accustomed", "D": "pertinent"}, "answer": "B", "analysis": "介系詞搭配秒殺：看到空格後的 'for'，直接聯想語塊 'be eligible for'（符合……資格）。capable 搭配 of；accustomed 搭配 to；pertinent 搭配 to。", "translation": "只有連續任職超過兩年的員工，才符合參加企業領導培訓計畫的資格。"}, {"id": 4, "target_seconds": 15, "question": "Customers receiving damaged merchandise are ________ to a full monetary refund within thirty days.", "options": {"A": "entitle", "B": "entitled", "C": "entitlement", "D": "entitling"}, "answer": "B", "analysis": "固定片語結構秒殺：be entitled to + 名詞（有權獲得……）。are 為 be 動詞，後接過去分詞形容詞 entitled。entitlement 為名詞。", "translation": "收到瑕疵受損商品的顧客有權在 30 天內獲得全額退款。"}, {"id": 5, "target_seconds": 15, "question": "Non-profit educational institutions are automatically ________ from state property taxes.", "options": {"A": "exempting", "B": "exemption", "C": "exempted", "D": "exempts"}, "answer": "C", "analysis": "固定被動搭配：be exempted from + 名詞（被免除……義務/賦稅）。故選 (C) exempted。", "translation": "非營利教育機構自動免繳州財產稅。"}, {"id": 6, "target_seconds": 15, "question": "Before installing the firmware update, please verify that it is fully ________ with your current operating system.", "options": {"A": "compatible", "B": "compliant", "C": "comparative", "D": "competitive"}, "answer": "A", "analysis": "介系詞秒殺搭配：空格後為 'with'，秒選 compatible with（與……相容）。compliant 表合規；competitive 具競爭力的。", "translation": "在安裝韌體更新之前，請確認其與您目前的作業系統完全相容。"}, {"id": 7, "target_seconds": 15, "question": "The newly established oncology laboratory was constructed under the direct ________ of Dr. Morales.", "options": {"A": "direct", "B": "director", "C": "direction", "D": "directed"}, "answer": "C", "analysis": "商務高頻片語：under the direction of + 人物（在某人的領導/指導之下）。形容詞 direct 後需接名詞 direction。director 指主任，語意不通。", "translation": "新成立的腫瘤學實驗室是在莫拉萊斯博士的直接領導下建造的。"}, {"id": 8, "target_seconds": 15, "question": "The regional vice president will ________ oversee the launch of the new logistics center in Frankfurt.", "options": {"A": "personal", "B": "personally", "C": "personality", "D": "personalize"}, "answer": "B", "analysis": "視覺錨點：will ________ oversee（助動詞 will 與動詞原形 oversee 之間的夾心位置，100% 填入副詞 -ly）。故選 (B) personally（親自地）。", "translation": "區域副總裁將親自監督法蘭克福新物流中心的啟用典禮。"}, {"id": 9, "target_seconds": 15, "question": "________ severe traffic disruptions along Highway 101, several keynote speakers arrived late for the morning session.", "options": {"A": "Because", "B": "Owing to", "C": "Although", "D": "Even if"}, "answer": "B", "analysis": "空格後為 'severe traffic disruptions'（名詞片語無動詞），屬於介系詞受詞，表原因選 (B) Owing to。(A) Because、(C) Although、(D) Even if 後方均需接完整的 S+V 子句。", "translation": "由於 101 號高速公路沿線嚴重的交通中斷，幾位專題演講者在上午的會議中遲到了。"}, {"id": 10, "target_seconds": 15, "question": "Due to an administrative ________, the revised purchase order was sent to the wrong equipment supplier.", "options": {"A": "oversee", "B": "oversight", "C": "oversaw", "D": "overseeing"}, "answer": "B", "analysis": "an administrative ________（冠詞 + 形容詞 + 名詞受詞位置）。語意為『行政上的疏失/遺漏』，名詞選 (B) oversight。(A) oversee 是動詞；(C) oversaw 為過去式動詞。", "translation": "由於行政上的疏漏，修改後的採購訂單被寄到了錯誤的設備供應商手中。"}, {"id": 11, "target_seconds": 15, "question": "The CEO approved the commercial loan ________ the terms were strictly verified by the legal department.", "options": {"A": "provided that", "B": "in the event of", "C": "regardless", "D": "in spite of"}, "answer": "A", "analysis": "空格後為 'the terms were strictly verified'（S+V 完整子句），表條件假設選從屬連接詞 (A) provided that（只要 / 在……條件下）。(B) 與 (D) 是介系詞片語，後接名詞。", "translation": "只要條款經過法律部門嚴格審查，執行長便批准了該筆商業貸款。"}, {"id": 12, "target_seconds": 15, "question": "All conference attendees are strongly requested to refrain ________ taking flash photographs during the presentation.", "options": {"A": "for", "B": "from", "C": "by", "D": "at"}, "answer": "B", "analysis": "介系詞搭配秒殺：refrain from + V-ing（克制/避免做某事）。故選 (B) from。", "translation": "強烈要求所有與會者在演講進行期間請勿使用閃光燈拍照。"}, {"id": 13, "target_seconds": 15, "question": "Laboratory technicians must strictly adhere ________ safety regulations when handling flammable chemicals.", "options": {"A": "to", "B": "with", "C": "in", "D": "for"}, "answer": "A", "analysis": "介系詞秒殺搭配：adhere to + 名詞（嚴格遵守……規定）。comply 接 with；abide 接 by。故選 (A) to。", "translation": "實驗室技術人員在處理易燃化學品時，必須嚴格遵守安全規程。"}, {"id": 14, "target_seconds": 15, "question": "Mr. Davies will step ________ from his executive role after twenty years of service to the organization.", "options": {"A": "out", "B": "over", "C": "down", "D": "back"}, "answer": "C", "analysis": "片語語意秒殺：step down from + 職位（辭職/卸任）。step down 表下台卸任；step out 暫時離開；take over 接管。故選 (C)。", "translation": "在為該機構服務二十年後，戴維斯先生將卸下其主管職位。"}, {"id": 15, "target_seconds": 15, "question": "Ms. Vance has agreed to take ________ the responsibilities of department director effective immediately.", "options": {"A": "in", "B": "over", "C": "off", "D": "up"}, "answer": "B", "analysis": "片語搭配：take over the responsibilities（接管/承接職責）。take over 表接任；take off 起飛/脫下。故選 (B)。", "translation": "萬斯女士已同意立即接管部門主管的職責。"}, {"id": 16, "target_seconds": 15, "question": "Management decided to hold ________ on new capital expenditure until quarterly sales improve.", "options": {"A": "off", "B": "out", "C": "up", "D": "down"}, "answer": "A", "analysis": "高頻片語：hold off on + 名詞/V-ing（暫緩推遲……）。hold off on spending 表暫緩資本支出。故選 (A)。", "translation": "管理層決定在季度銷售額改善之前，暫緩新的資本支出。"}, {"id": 17, "target_seconds": 15, "question": "The steering committee ________ seven department heads and two external financial advisors.", "options": {"A": "consists of", "B": "is consisted of", "C": "persists in", "D": "insists on"}, "answer": "A", "analysis": "consist of（由……組成）為不及物動詞片語，絕無被動態 (is consisted of ❌)！委員會由七位主管組成，選 (A)。persist in 堅持；insist on 堅持要求。", "translation": "指導委員會由七位部門主管與兩位外部財務顧問組成。"}, {"id": 18, "target_seconds": 15, "question": "The safety inspector insisted ________ reviewing the facility's emergency evacuation protocols.", "options": {"A": "to", "B": "on", "C": "in", "D": "at"}, "answer": "B", "analysis": "介系詞秒殺搭配：insist on + V-ing/名詞（堅持要求……）。persist 接 in；depend 接 on。故選 (B)。", "translation": "安全檢查員堅持要審查該設施的緊急疏散協議。"}, {"id": 19, "target_seconds": 15, "question": "While one elevator is under maintenance, building tenants should use ________ elevators located near the north entrance.", "options": {"A": "another", "B": "other", "C": "others", "D": "one another"}, "answer": "B", "analysis": "不定代名詞範圍：空格後為複數名詞 'elevators'，修飾複數名詞秒選 (B) other。another 只能修飾單數名詞；others 是代名詞後不可接名詞；one another 表彼此（受詞）。", "translation": "當一台電梯在維修時，大樓租戶應使用位於北側入口處的其他電梯。"}, {"id": 20, "target_seconds": 15, "question": "The human resources department praised the newly recruited manager for handling complex disputes ________.", "options": {"A": "capable", "B": "capably", "C": "capability", "D": "capacitate"}, "answer": "B", "analysis": "修飾動詞片語 'handling complex disputes' 需用副詞。capably 表『稱職地 / 幹練地』。故選 (B)。", "translation": "人力資源部讚揚新招聘的經理幹練且稱職地處理了複雜的爭議。"}]}, "afternoon": {"quick_recall": [{"prompt": "Ms. Lin was appointed to ________ [監督] the infrastructure project.", "clue": "動詞，字首為 o，監督主管", "answer": "oversee (oversee the project)"}, {"prompt": "Due to an administrative ________ [疏失], the invoice was sent to the wrong vendor.", "clue": "名詞，字首為 o，不可與 oversee 混淆", "answer": "oversight (an unfortunate oversight)"}, {"prompt": "Staff members must meet tenure requirements to be eligible ________ [介系詞] the annual bonus.", "clue": "符合……資格", "answer": "for (eligible for)"}, {"prompt": "Customers are entitled ________ [介系詞] a full replacement for defective items.", "clue": "有權獲得……", "answer": "to (entitled to)"}, {"prompt": "VIP ticket holders are exempted ________ [介系詞] paying baggage surcharges.", "clue": "被免除……費用", "answer": "from (exempted from)"}, {"prompt": "Please ensure that the newly purchased scanner is compatible ________ [介系詞] our network.", "clue": "與……相容", "answer": "with (compatible with)"}], "spaced_traps": [{"id": 1, "question": "The auditor noted that the accounting discrepancy was a minor ________ rather than intentional fraud.", "options": {"A": "oversee", "B": "oversight", "C": "overseer", "D": "overseeing"}, "answer": "B", "trap_point": "名詞詞性與意義辨析：a minor + [名詞]。overseer 是監工（人），oversight 才是疏失（事物）。", "analysis": "句中對比 'rather than intentional fraud'（而非蓄意詐欺），空格需填入指『無心疏失』的名詞，故選 (B) oversight。"}, {"id": 2, "question": "The proposed software upgrade is not fully ________ with older office workstations.", "options": {"A": "proficient", "B": "compatible", "C": "vulnerable", "D": "exempted"}, "answer": "B", "trap_point": "介系詞搭配陷阱：with 出現，秒選 compatible。", "analysis": "compatible with（與……相容）。proficient 接 in；vulnerable 接 to；exempted 接 from。"}, {"id": 3, "question": "________ Mr. Henderson worked through the night, he was unable to finalize the client proposal before the morning deadline.", "options": {"A": "Despite", "B": "Although", "C": "In spite of", "D": "Owing to"}, "answer": "B", "trap_point": "看空格後有沒有動詞！後方有完整動詞 'worked'，絕不能選介系詞 (A), (C), (D)！", "analysis": "空格後為 'Mr. Henderson worked through the night'（主詞 + 動詞 worked），句意表轉折讓步，秒選從屬連接詞 (B) Although！"}, {"id": 4, "question": "The lead mechanical engineer will ________ inspect the turbine before authorizing operational testing.", "options": {"A": "thorough", "B": "thoroughly", "C": "thoroughness", "D": "through"}, "answer": "B", "trap_point": "will ________ inspect（助動詞與動詞原形之間的夾心餅乾，塞入副詞 -ly）！", "analysis": "修飾動詞 inspect，需用副詞 (B) thoroughly（徹底地 / 仔細地）。"}, {"id": 5, "question": "In the event ________ an emergency power failure, the backup generators will activate automatically.", "options": {"A": "that", "B": "of", "C": "as", "D": "for"}, "answer": "B", "trap_point": "後面是純名詞片語 'an emergency power failure'，無動詞！", "analysis": "純名詞片語選介系詞片語 in the event of。若有 S+V 句子才選 in the event that。"}, {"id": 6, "question": "All research assistants must adhere strictly ________ established biohazard containment protocols.", "options": {"A": "to", "B": "with", "C": "in", "D": "for"}, "answer": "A", "trap_point": "adhere 永遠搭配 to（遵守）！不可誤選 with。", "analysis": "adhere strictly to... 為商務英文最高頻必考片語，故選 (A)。"}, {"id": 7, "question": "While ________ the quarterly budget sheets, the controller discovered an unaccounted deficit.", "options": {"A": "examine", "B": "examining", "C": "examined", "D": "examination"}, "answer": "B", "trap_point": "分詞構句減化：主詞 主動 檢視報表並帶出受詞 'the budget sheets'！", "analysis": "主動做動作且帶受詞，while 後方減化分詞選現在分詞 (B) examining。"}, {"id": 8, "question": "Contractual guidelines require departing commercial tenants to ________ the office suites by month-end.", "options": {"A": "vacate", "B": "vacant", "C": "vacantly", "D": "vacancy"}, "answer": "A", "trap_point": "to + [動詞原形] + the office suites！", "analysis": "不定詞後接動詞原形，vacate（騰空/搬出物業）。vacant 為形容詞；vacancy 為名詞職缺。"}, {"id": 9, "question": "Full-time personnel who have completed three years of service are ________ for subsidized tuition grants.", "options": {"A": "eligible", "B": "entitled", "C": "exempted", "D": "compatible"}, "answer": "A", "trap_point": "eligible 固定接 for（符合資格）；entitled 需接 to！看到後方介系詞 for 秒選 eligible！", "analysis": "後方接介系詞 for，符合語塊 be eligible for sth.（符合…資格）。entitled 須接 to；exempted 須接 from；compatible 須接 with。", "translation": "任職滿三年的全職員工符合申請學費補助金的資格。"}, {"id": 10, "question": "The marine logistics insurer agreed to compensate the client in full for any ________ to the shipped cargo.", "options": {"A": "damage", "B": "damages", "C": "damaging", "D": "damaged"}, "answer": "A", "trap_point": "damage 表物品實體損壞為不可數名詞，絕不可加 -s！damages 表法律損害賠償金。", "analysis": "句意是賠償貨物的實體受損，不可數名詞選 (A) damage。damages 加 -s 是法律損害賠償金，此處不合。", "translation": "海運保險公司同意就運送貨物所遭受的任何損害向客戶進行全額賠償。"}, {"id": 11, "question": "Most beta testers found the cloud accounting portal remarkably ________ to navigate.", "options": {"A": "intuitive", "B": "intuitively", "C": "intuition", "D": "intuitiveness"}, "answer": "A", "trap_point": "find + O + 形容詞受詞補語！千萬不可被副詞 remarkably 誤導而選副詞 intuitively！", "analysis": "find + the portal (受詞) + [形容詞受詞補語]。選形容詞 (A) intuitive（直覺好用的）。", "translation": "大多數測試者發現該雲端會計網站操作起來非常直覺流暢。"}, {"id": 12, "question": "The three international trade delegates met in Zurich to discuss joint tariff policies with ________.", "options": {"A": "one another", "B": "other", "C": "another", "D": "each other"}, "answer": "A", "trap_point": "三者以上彼此互相用 one another！兩者才用 each other！", "analysis": "主詞明確為 The three delegates（三位代表，大於兩位），互相交流固定選代名詞片語 (A) one another。", "translation": "三位國際貿易代表在蘇黎世會面，共同商討彼此的聯合關稅政策。"}, {"id": 13, "question": "The press conference was abruptly postponed ________ unexpected technical malfunctions in the sound system.", "options": {"A": "owing to", "B": "because", "C": "since", "D": "as"}, "answer": "A", "trap_point": "空格後為 'unexpected technical malfunctions'（名詞片語），無動詞！選介系詞 owing to！", "analysis": "整段無動詞子句，(B)、(C)、(D) 皆為從屬連接詞無法接純名詞片語。故選介系詞片語 (A) owing to。", "translation": "由於音響系統發生未預期的技術故障，新聞發布會突然遭到推遲。"}, {"id": 14, "question": "Ms. Tanaka agreed to ________ as division vice president so she could devote more time to university lecturing.", "options": {"A": "step down", "B": "take over", "C": "hold off", "D": "put off"}, "answer": "A", "trap_point": "step down as + 職位（辭去/卸任職務）。take over 是接管；hold off 接 on；put off 指延期。", "analysis": "田中女士為了投入更多時間於大學講學而決定辭去副總裁職位，選 (A) step down。", "translation": "田中女士同意辭去部門副總裁一職，以便投入更多時間進行大學講學。"}], "part7": {"passages": [{"text_type": "Corporate Benefits Policy Document", "title": "Summit Group — Annual Employee Health & Wellness Subsidy Guidelines", "content": "DOCUMENT ID: HR-POL-2026-088\nISSUING AUTHORITY: Global Human Resources & Wellbeing Directorate\nEFFECTIVE DATE: November 4, 2026\nTARGET AUDIENCE: All Full-Time and Contract Personnel\n\n1. Policy Objective & Scope\nSummit Group is firmly committed to cultivating a healthy, supportive, and ergonomically sound working environment. Under the ongoing direction of our certified workplace wellness specialists, this policy details qualifying criteria, authorized spending limits, and claims verification procedures for the annual health stipend across all regional branch locations.\n\n2. Eligibility & Qualifying Expenditures\nAll permanent employees who have completed at least six months of continuous service under the direction of a certified team lead are eligible for an annual health subsidy of up to $500 per fiscal year. Qualifying claims encompass verified monthly gym memberships, registered fitness classes, or ergonomically approved home-office furniture (such as specialized lumbar task chairs and motorized standing desks). Requests must be submitted via the corporate intranet portal along with itemized merchant payment receipts.\n\n*Note on Temporary Staff: Part-time staff and temporary interns are exempted from the mandatory monthly wellness activity log but are entitled to a modified subsidy of $150, provided that their application is submitted prior to November 15. Reimbursements will be disbursed on the first scheduled bi-weekly payroll cycle following departmental authorization.", "questions": [{"question": "What is required for temporary interns to receive a subsidy?", "options": {"A": "Complete six months of full-time service.", "B": "Maintain a daily workout log.", "C": "Apply before November 15.", "D": "Purchase certified gym equipment."}, "answer": "C", "radar": "🔍 防漏看雷達：看到 *Note 星號附註中的條件句 'provided that their application is submitted prior to November 15'！實習生不必滿 6 個月，但必須在 11/15 前提出申請。", "analysis": "文中星號標記明確指出實習生享有修改後的補助，前提是申請在 11 月 15 日前提出（prior to November 15 = before November 15），故選 (C)。"}, {"question": "What is TRUE about permanent employees regarding the subsidy?", "options": {"A": "They must have at least six months of continuous tenure.", "B": "They can claim up to $1,000 annually.", "C": "They are exempted from submitting wellness receipts.", "D": "They must purchase their own office laptops."}, "answer": "A", "radar": "🔍 防漏看雷達：首句開頭細節 'completed at least six months of service'！", "analysis": "第一句提及 'All permanent employees who have completed at least six months of service... are eligible'，與 (A) 意思完全相符。"}, {"question": "Which item is eligible for reimbursement under this wellness policy?", "options": {"A": "Standard home office stationery supplies.", "B": "Ergonomically certified home-office furniture.", "C": "Monthly public transit commuting cards.", "D": "Uncertified personal recreational items."}, "answer": "B", "radar": "🔍 防漏看雷達：內文具體名詞替換！'applied toward gym memberships or ergonomically approved home-office furniture' ＝ 'Ergonomically certified home-office furniture'！", "analysis": "文中第一段第二句清楚列出補助可用於健身房會籍或人體工學核准家具，故選 (B)。"}]}, {"text_type": "Corporate Travel & Attire Memo", "title": "Summit Logistics: Regional Delegate Conference Logistics & Dress Code", "content": "MEMORANDUM\n\nTO: Regional Sales Representatives and Account Executives\nFROM: Events Planning Directorate & Corporate Travel Services\nDATE: November 4, 2026\nSUBJECT: Annual Chicago Sales Leadership Summit — Accommodations, Attire, and Expense Guidelines\n\nWe look forward to welcoming all regional representatives to our flagship convention held at the Chicago Waterfront Center. To guarantee executive professionalism and seamless operations throughout the three-day itinerary, delegates are requested to adhere to the guidelines outlined below:\n\nHotel Accommodations & Conference Attire:\nAll representatives attending the annual Chicago summit will be provided complimentary accommodation at the Grand Plaza Hotel on Michigan Avenue. Standard business attire (tailored suits, pressed collared shirts, and neckties or professional blazers) is mandatory for all daytime panel sessions and keynote addresses. However, casual garments (such as polo shirts and clean jeans) are permitted exclusively during the Friday evening networking reception in the Skyline Pavilion.\n\nBaggage Allowance & Reimbursement Thresholds:\nRound-trip airline reservations have been secured through our corporate travel partner. When checking baggage at airport ticket counters, travelers should note corporate reimbursement limits.\n\n*Luggage Allowance: The company will reimburse luggage fees for up to two checked bags, provided that luggage receipts are submitted within 7 days of trip conclusion. Claims submitted after this 7-day threshold will be rejected without exception. Excess baggage weight charges remain the personal liability of the delegate.", "questions": [{"question": "What type of clothing is permitted exclusively on Friday evening?", "options": {"A": "Formal evening tuxedos and gowns.", "B": "Casual clothing.", "C": "Branded sports jerseys.", "D": "Traditional ethnic costumes."}, "answer": "B", "radar": "🔍 防漏看雷達：限制副詞 exclusively！'casual garments are permitted exclusively during the Friday evening networking reception'！garments ＝ clothing！", "analysis": "文中指出週五晚間社交酒會唯一允許休閒便服（casual garments = casual clothing），故選 (B)。"}, {"question": "How many checked bags can delegates have reimbursed?", "options": {"A": "One bag only.", "B": "Up to two checked bags.", "C": "Three checked bags.", "D": "Unlimited bags with manager approval."}, "answer": "B", "radar": "🔍 防漏看雷達：具體數字細節 'reimburse luggage fees for up to two checked bags'！", "analysis": "行李補助條款明確載明可報銷至多兩件托運行李（up to two checked bags），故選 (B)。"}, {"question": "Under what condition will a luggage reimbursement claim be denied?", "options": {"A": "If the representative flew on an unapproved airline.", "B": "If receipts are submitted more than 7 days after the trip ends.", "C": "If the delegate traveled alone without a colleague.", "D": "If checked bags weighed over 20 kilograms each."}, "answer": "B", "radar": "🔍 防漏看雷達：星號附註最後一句 'Claims submitted after this 7-day threshold will be rejected without exception'！rejected ＝ denied！", "analysis": "文末星號強調若超過 7 天期限繳交收據，報銷申請將毫無例外地遭到拒絕（rejected = denied），故選 (B)。"}]}]}}}, "2": {"day": 2, "date": "11/05", "phase": 1, "phase_name": "錯題庫清零與語感校正", "topic": "原因與轉折結構 ｜ proceed vs. procedure ｜ 堅持與組成", "morning": {"chunks": [{"chunk": "proceed with caution", "meaning": "謹慎繼續進行", "scenario": "Engineers were advised to proceed with caution during the structural inspection.", "paraphrase": "proceed = continue = go ahead", "alert": "易混淆：proceed (v.) 繼續進行 vs. procedure (n.) 程序步驟！"}, {"chunk": "standard operating procedure", "meaning": "標準作業程序 (SOP)", "scenario": "Employees must adhere to the standard operating procedure when handling toxic chemicals.", "paraphrase": "procedure = protocol = routine", "alert": ""}, {"chunk": "consist of five modules", "meaning": "由五個模組組成", "scenario": "The executive training program consists of five rigorous modules.", "paraphrase": "consist of = be composed of = comprise", "alert": "必考用法：consist of 永遠沒有被動態 (is consisted of ❌)！"}, {"chunk": "persist in efforts", "meaning": "堅持不懈地努力", "scenario": "The sales team persisted in efforts despite facing severe market contraction.", "paraphrase": "persist in = continue steadfastly", "alert": "介系詞搭配：persist 固定接 in！"}, {"chunk": "insist on compliance", "meaning": "堅持要求合規", "scenario": "The safety auditor insisted on immediate compliance with environmental standards.", "paraphrase": "insist on = demand firmly", "alert": "介系詞搭配：insist 固定接 on！"}, {"chunk": "prior to departure", "meaning": "在出發之前", "scenario": "All travelers must submit visa documentation prior to departure.", "paraphrase": "prior to = before = ahead of", "alert": "視覺錨點：prior to 是介系詞片語，後接名詞或 V-ing！"}, {"chunk": "delegate tasks capably", "meaning": "幹練地委派任務", "scenario": "A great supervisor knows how to delegate tasks capably to team members.", "paraphrase": "delegate = assign = entrust; capably = skillfully", "alert": ""}], "visual_anchor": {"title": "原因詞：because vs. owing to 秒殺", "rule_1": "👀 空格後為【S + V (完整句子)】➔ 選 because / since / as", "rule_2": "👀 空格後為【名詞 / 代名詞】➔ 選 owing to / due to / on account of / because of", "golden_rule": "⚡ 教練金句：看到 owing to 後面有逗號沒動詞，千萬不要選 because！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "The flight to Chicago was postponed ________ severe inclement weather across the Midwest.", "options": {"A": "because", "B": "owing to", "C": "since", "D": "as"}, "answer": "B", "analysis": "視覺錨點：空格後為 'severe inclement weather'（名詞片語），沒有任何動詞，屬於介系詞受詞，故秒選介系詞片語 (B) owing to。(A)、(C)、(D) 皆為從屬連接詞，後方必須接完整 S+V 子句。", "translation": "由於中西部遭遇嚴重惡劣天氣，飛往芝加哥的航班已被延誤。"}, {"id": 2, "target_seconds": 15, "question": "Please review the updated safety ________ before operating the factory machinery.", "options": {"A": "proceed", "B": "procedure", "C": "proceedings", "D": "procedural"}, "answer": "B", "analysis": "詞性位置秒殺：空格前為形容詞 'safety'，受詞位置需填入名詞。此處指『安全規程 / 程序』，選名詞 (B) procedure。(A) proceed 為動詞（繼續進行）；(D) procedural 為形容詞。", "translation": "在操作工廠機械之前，請先檢閱最新的安全程序。"}, {"id": 3, "target_seconds": 15, "question": "The steering committee ________ seven senior department heads and two external advisors.", "options": {"A": "consists of", "B": "is consisted of", "C": "persists in", "D": "insists on"}, "answer": "A", "analysis": "核心必考文法：consist of（由……組成）為不及物動詞片語，『絕對沒有被動態』，直接排除 (B)。語意為委員會由七位主管與兩位顧問組成，故選 (A)。(C) persist in 堅持不懈；(D) insist on 堅持要求。", "translation": "指導委員會由七位資深部門主管及兩位外部顧問組成。"}, {"id": 4, "target_seconds": 15, "question": "After addressing initial shareholder concerns, the board decided to ________ with the scheduled acquisition.", "options": {"A": "proceed", "B": "procedure", "C": "procession", "D": "proceeding"}, "answer": "A", "analysis": "看到不定詞符號 'to + [原形動詞]' 搭配介系詞 'with'。proceed with sth.（繼續進行某事）為商務高頻語塊。(B) procedure 為名詞（程序）；(C) procession 為名詞（隊伍行列）。", "translation": "在解決股東最初的疑慮後，董事會決定按原定計畫推進收購案。"}, {"id": 5, "target_seconds": 15, "question": "Despite fierce market competition, the tech startup ________ in developing its proprietary AI algorithm.", "options": {"A": "consisted", "B": "persisted", "C": "insisted", "D": "resisted"}, "answer": "B", "analysis": "介系詞搭配秒殺：看到空格後介系詞 'in'，秒選 persist in（堅持不懈於……）。consist 後接 of；insist 後接 on；resist 為及物動詞直接接受詞。", "translation": "儘管面臨激烈的市場競爭，這家科技新創公司仍堅持不懈地開發其專利 AI 演算法。"}, {"id": 6, "target_seconds": 15, "question": "The regional health inspector firmly ________ on examining the storage facilities without prior notice.", "options": {"A": "persisted", "B": "insisted", "C": "consisted", "D": "assisted"}, "answer": "B", "analysis": "介系詞搭配秒殺：看到空格後介系詞 'on' + V-ing，秒選 insist on（堅持要求 / 硬要……）。persist 搭配 in；consist 搭配 of；assist 搭配 with 或 in。", "translation": "地區衛生稽核員堅持要在未事先通知的情況下檢查倉儲設施。"}, {"id": 7, "target_seconds": 15, "question": "All international participants must submit their passport credentials ________ to boarding the charter flight.", "options": {"A": "prior", "B": "ahead", "C": "previous", "D": "beforehand"}, "answer": "A", "analysis": "介系詞片語秒殺：prior to + N / V-ing（在……之前），相當於 before。ahead 須接 of；previous 與 beforehand 皆為副詞，不能直接接 'to boarding'。", "translation": "所有國際與會者在登上包機前，必須先繳交護照證件。"}, {"id": 8, "target_seconds": 15, "question": "A truly effective manager knows how to delegate complex responsibilities ________ among team members.", "options": {"A": "capable", "B": "capably", "C": "capability", "D": "capacities"}, "answer": "B", "analysis": "詞性秒殺：delegate (動詞) + responsibilities (名詞受詞) + [副詞] 修飾動詞 delegate。故選副詞 (B) capably（幹練地、勝任地）。(A) 為形容詞；(C)、(D) 為名詞。", "translation": "一位真正優秀的經理人懂得如何幹練地將複雜職責委派給團隊成員。"}, {"id": 9, "target_seconds": 15, "question": "________ the laboratory had undergone rigorous sanitization, unauthorized entry remained prohibited.", "options": {"A": "Because", "B": "Even though", "C": "Due to", "D": "Owing to"}, "answer": "B", "analysis": "視覺錨點：空格後為完整句子 'the laboratory (S) + had undergone (V) ...'，排除介系詞 (C)、(D)。依語意前後為轉折關係（雖然已消毒，但仍禁止進入），故選 (B) Even though。(A) Because 表因果，語意不合。", "translation": "即使實驗室已經過嚴格消毒，未經授權的進入仍然受到禁止。"}, {"id": 10, "target_seconds": 20, "question": "Production costs decreased ________ after the manufacturing division installed energy-efficient machinery.", "options": {"A": "drastic", "B": "drastically", "C": "drasticness", "D": "drasticize"}, "answer": "B", "analysis": "詞性秒殺：decreased 為不及物動詞，空格位於句尾修飾動詞，需填入副詞。(B) drastically（大幅度地）為高頻商務副詞。(A) 為形容詞；(C) 為名詞。", "translation": "在製造部門安裝節能機械後，生產成本大幅度下降。"}, {"id": 11, "target_seconds": 15, "question": "The logistics supervisor selected a ________ courier service to guarantee prompt delivery of urgent medical supplies.", "options": {"A": "dependable", "B": "depend", "C": "dependably", "D": "dependence"}, "answer": "A", "analysis": "空格位於冠詞 'a' 與名詞片語 'courier service' 之間，需填入形容詞修飾名詞。(A) dependable（可靠的/值得信賴的）符合語法與語意。(C) 為副詞；(D) 為名詞。", "translation": "物流主管挑選了一家可靠的快遞服務公司，以確保緊急醫療用品能迅速送達。"}, {"id": 12, "target_seconds": 20, "question": "The payroll department will automatically ________ union dues from each monthly paycheck.", "options": {"A": "deduct", "B": "deduction", "C": "deductible", "D": "deducted"}, "answer": "A", "analysis": "助動詞夾心秒殺：will + automatically (adv.) + [原形動詞] + union dues (名詞受詞)。選原形動詞 (A) deduct（扣除）。(B) 為名詞；(C) 為形容詞。", "translation": "薪資部門將會自動從每月的薪資單中扣除工會會費。"}, {"id": 13, "target_seconds": 15, "question": "Because of an unexpected power failure, the factory ________ was extended until 8:00 A.M. tomorrow.", "options": {"A": "close", "B": "closure", "C": "closely", "D": "closing"}, "answer": "B", "analysis": "空格位於主詞位置 'the factory ________'，後接被動動詞 'was extended'，需名詞。closure 表『關閉 / 停工』。(A) 為動詞或形容詞；(C) 為副詞（緊密地）；(D) closing 多指儀式尾聲。", "translation": "由於突發停電，該工廠的關閉停工時間延長至明日上午 8 點。"}, {"id": 14, "target_seconds": 15, "question": "The HR committee interviewed several ________ candidates before selecting the new head of marketing.", "options": {"A": "competent", "B": "competence", "C": "competently", "D": "competition"}, "answer": "A", "analysis": "空格位於限定詞 'several' 與名詞 'candidates' 之間，需填入形容詞修飾人。(A) competent（勝任的/有能力的）符合語意。(B) competence 為名詞；(C) 為副詞。", "translation": "人資委員會在選出新任行銷主管之前，面試了數名稱職優秀的候選人。"}, {"id": 15, "target_seconds": 20, "question": "The financial audit provided a ________ evaluation of the multinational firm's overseas assets.", "options": {"A": "comprehend", "B": "comprehensive", "C": "comprehensively", "D": "comprehension"}, "answer": "B", "analysis": "形容詞修飾名詞：a + [形容詞] + evaluation。comprehensive（全面詳盡的）為多益 860 超高頻形容詞。(A) 為動詞；(C) 為副詞；(D) 為名詞（理解力）。", "translation": "財務稽核對該跨國企業的海外資產提供了全面且詳盡的評估。"}, {"id": 16, "target_seconds": 15, "question": "Supermarket staff members must keep every ________ clear of boxes during peak shopping hours.", "options": {"A": "aisle", "B": "isle", "C": "aisles", "D": "appliance"}, "answer": "A", "analysis": "名詞單複數與拼字：'every' 後方接單數可數名詞。aisle 指走道、通道。isle 為小島；aisles 為複數；appliance 為家電，語意不符。", "translation": "在購物尖峰時段，超市員工必須確保每條走道均無紙箱阻礙。"}, {"id": 17, "target_seconds": 15, "question": "Retailers ________ a substantial surge in consumer demand ahead of the upcoming holiday weekend.", "options": {"A": "anticipate", "B": "anticipation", "C": "anticipatory", "D": "anticipatedly"}, "answer": "A", "analysis": "句子結構分析：Retailers (S) + [及物動詞] + a substantial surge (O)。主詞為複數名詞，時態為現在式，選動詞原形 (A) anticipate（預期/預料）。(B) 為名詞；(C) 為形容詞。", "translation": "零售商預期在即將到來的連假週末前，消費需求將大幅激增。"}, {"id": 18, "target_seconds": 15, "question": "Customer service representatives are expected to provide a ________ response to all client inquiries.", "options": {"A": "prompt", "B": "promptly", "C": "promptness", "D": "prompting"}, "answer": "A", "analysis": "空格位於冠詞 'a' 與名詞 'response' 之間，需填入形容詞。prompt（迅速即時的）為形容詞。(B) promptly 為副詞；(C) promptness 為名詞（敏捷）。", "translation": "客戶服務代表預期應對所有客戶的諮詢提供迅速即時的回覆。"}, {"id": 19, "target_seconds": 20, "question": "The warranty does not apply to any household ________ that has been altered by an unauthorized technician.", "options": {"A": "appliance", "B": "applicant", "C": "application", "D": "applicable"}, "answer": "A", "analysis": "易混淆單字：household appliance 指『家用電器』。applicant 為應徵者；application 為申請書；applicable 為可適用的。故選 (A)。", "translation": "保固不適用於任何曾遭未經授權技師改裝的家用電器。"}, {"id": 20, "target_seconds": 20, "question": "Sales figures dropped slightly in the northern territory ________ rising distribution expenses.", "options": {"A": "because", "B": "in spite of", "C": "due to", "D": "even if"}, "answer": "C", "analysis": "視覺錨點：空格後為 'rising distribution expenses'（名詞片語，rising 為分詞形容詞修飾 expenses）。(A) because 與 (D) even if 只能接句子；(B) in spite of 表讓步（儘管）；(C) due to 表原因（由於）。銷售下滑是因為配銷費用上升，因果關係選 (C)。", "translation": "由於配銷費用上升，北部地區的銷售額微幅下滑。"}]}, "afternoon": {"quick_recall": [{"prompt": "The committee consists ________ [介系詞] eight advisors.", "clue": "由……組成（不及物無被動）", "answer": "of"}, {"prompt": "She persisted ________ [介系詞] completing the audit despite delays.", "clue": "堅持不懈於……", "answer": "in"}, {"prompt": "The manager insisted ________ [介系詞] immediate compliance.", "clue": "堅持要求……", "answer": "on"}, {"prompt": "Prior ________ [介系詞] departure, tickets must be validated.", "clue": "在……之前（等於 before）", "answer": "to"}, {"prompt": "Postponed ________ [介系詞片語，表原因] severe weather.", "clue": "接名詞片語的原因詞（o開頭）", "answer": "owing to (or due to)"}, {"prompt": "The supervisor knows how to delegate tasks ________ [副詞，勝任幹練地].", "clue": "修飾動詞 delegate 的副詞", "answer": "capably"}], "spaced_traps": [{"id": 1, "question": "The newly established division ________ ten bilingual researchers and three technical writers.", "options": {"A": "is consisted of", "B": "consists of", "C": "consisting", "D": "are consisted of"}, "answer": "B", "trap_point": "consist of 絕對沒有被動態！主詞 division 為單數，現在式選 consists of。", "analysis": "許多考生看到中文『由…所組成』就誤選被動態 is consisted of。牢記：consist of 本身即不及物，主動式表包含組成，秒選 (B)。", "translation": "新成立的部門由十位雙語研究人員及三位技術文件撰寫員組成。"}, {"id": 2, "question": "The contractor was instructed not to ________ with the demolition until environmental clearance was issued.", "options": {"A": "proceed", "B": "procedure", "C": "proceedings", "D": "procedural"}, "answer": "A", "trap_point": "to 後接原形動詞 proceed with（繼續進行）。procedure 是名詞（手續/規程）。", "analysis": "助動詞 was instructed not to 後接原形動詞，proceed with sth. 是商務黃金搭配。procedure 為名詞不可接 with。", "translation": "在環境許可令核發之前，承包商接獲指示不得繼續進行拆除作業。"}, {"id": 3, "question": "________ the sudden drop in quarterly revenue, the executive committee approved the planned bonus.", "options": {"A": "Although", "B": "In spite of", "C": "Because", "D": "Owing to"}, "answer": "B", "trap_point": "前後語意為讓步（營收下降卻依然發獎金），且空格後為名詞片語，選介系詞 In spite of。", "analysis": "空格後 'the sudden drop...' 為名詞片語，先排除連接詞 (A) Although 與 (C) Because。語意上營收下降卻批准獎金為轉折讓步，故選 (B) In spite of 而非因果 (D) Owing to。", "translation": "儘管季度營收驟降，執行委員會依然批准了原定的獎金發放。"}, {"id": 4, "question": "All personnel are ________ to an ergonomic workstation assessment upon completing probation.", "options": {"A": "eligible", "B": "entitled", "C": "exempted", "D": "compatible"}, "answer": "B", "trap_point": "be entitled to + 名詞（有權獲得…）；eligible 搭配 for！", "analysis": "空格後為介系詞 'to'，符合語塊 'be entitled to + N'（有權享有人體工學評估）。eligible 後方固定接 for。", "translation": "所有人員在試用期滿後，皆有權享有工作站人體工學評估。"}, {"id": 5, "question": "The flight was canceled ________ severe turbulence across the mountain pass.", "options": {"A": "because", "B": "as", "C": "since", "D": "owing to"}, "answer": "D", "trap_point": "空格後 'severe turbulence' 為名詞片語無動詞，只能選介系詞 owing to！", "analysis": "(A)、(B)、(C) 皆為連接詞，後方須接完整子句 S+V。只有 (D) owing to 為介系詞片語，後接名詞片語。", "translation": "由於通過山口時發生嚴重亂流，該航班已被取消。"}, {"id": 6, "question": "The auditor discovered a significant ________ in the quarterly inventory reports.", "options": {"A": "oversee", "B": "oversight", "C": "overseeing", "D": "overseen"}, "answer": "B", "trap_point": "oversee 是動詞（監督）；oversight 是名詞（疏忽/疏漏）。", "analysis": "冠詞 a + 形容詞 significant + [名詞]。oversight 表『疏漏/失誤』，符合稽核員發現報告有疏漏的語境。故選 (B)。", "translation": "稽核員在季度庫存報告中發現了一項重大疏漏。"}, {"id": 7, "question": "Subscribers may terminate their membership ________ written notice is submitted thirty days in advance.", "options": {"A": "provided that", "B": "prior to", "C": "in spite of", "D": "owing to"}, "answer": "A", "trap_point": "空格後為完整句子 'written notice is submitted' (S + be + p.p.)，需選連接詞 provided that！", "analysis": "(B)、(C)、(D) 全為介系詞片語，後面只能接名詞。只有 (A) provided that 為連接詞（只要……），後接完整條件子句。", "translation": "訂閱會員只要提前 30 天提交書面通知，即可終止會員資格。"}, {"id": 8, "question": "The software engineer is exceptionally ________ in full-stack cloud architecture.", "options": {"A": "proficient", "B": "accustomed", "C": "vulnerable", "D": "exempted"}, "answer": "A", "trap_point": "介系詞搭配：proficient in（精通…）；accustomed 接 to；vulnerable 接 to；exempted 接 from。", "analysis": "看到空格後介系詞 'in'，秒殺選 (A) proficient。這是一道純粹的介系詞搭配題，記憶語塊即可 3 秒拿分。", "translation": "該軟體工程師極度精通全端雲端架構。"}, {"id": 9, "question": "Before authorizing the budget disbursement, the director must ________ with the revised financial protocol.", "options": {"A": "proceed", "B": "procedure", "C": "proceedings", "D": "procedural"}, "answer": "A", "trap_point": "must + 原形動詞 proceed with（繼續進行/依序推進）。procedure 是名詞！", "analysis": "助動詞 must 後接動詞原形，proceed with sth. 是固定高頻搭配，選 (A)。", "translation": "在批准預算撥付之前，總監必須按照修訂後的財務規程繼續進行。"}, {"id": 10, "question": "The international consortium ________ seven telecommunications carriers and three hardware manufacturers.", "options": {"A": "consists of", "B": "is consisted of", "C": "persists in", "D": "insists on"}, "answer": "A", "trap_point": "consist of（由…組成）為不及物動詞，絕無被動態！主詞單數選 consists of。", "analysis": "consist of 永遠用主動態表示組成，排除 (B)。選 (A)。", "translation": "該國際財團由七家電信營運商及三家硬體製造商組成。"}, {"id": 11, "question": "Despite repeated software crashes, the engineering team ________ in optimizing the proprietary algorithm.", "options": {"A": "persisted", "B": "insisted", "C": "consisted", "D": "assisted"}, "answer": "A", "trap_point": "介系詞搭配：persist in（堅持不懈於…）；insist 搭配 on！", "analysis": "看到空格後介系詞 in，秒選 (A) persisted。", "translation": "儘管軟體一再崩潰，工程團隊仍堅持不懈地優化其專利演算法。"}, {"id": 12, "question": "The airline passenger must present a valid boarding pass ________ to passing through the security checkpoint.", "options": {"A": "prior", "B": "ahead", "C": "previous", "D": "beforehand"}, "answer": "A", "trap_point": "prior to + V-ing（在…之前）。ahead 須搭配 of！", "analysis": "空格後接 'to passing'，只有 prior to 能構成介系詞片語，選 (A)。", "translation": "航空旅客在通過安檢站之前，必須出示有效登機證。"}, {"id": 13, "question": "A senior project coordinator must know how to delegate operational assignments ________ among team members.", "options": {"A": "capably", "B": "capable", "C": "capability", "D": "capacities"}, "answer": "A", "trap_point": "delegate assignments + [副詞 -ly] 修飾及物動詞 delegate！", "analysis": "副詞修飾動詞 delegate，capably 表幹練妥善地，選 (A)。", "translation": "資深專案協調員必須懂得如何幹練地將作業任務委派給團隊成員。"}, {"id": 14, "question": "Quarterly net revenue declined slightly in the northern sales sector ________ rising freight rates.", "options": {"A": "owing to", "B": "because", "C": "since", "D": "as"}, "answer": "A", "trap_point": "rising freight rates 為名詞片語（rising 是分詞修飾 rates），無動詞！選介系詞 owing to！", "analysis": "空格後為純名詞片語，不可選從屬連接詞 (B)、(C)、(D)。選介系詞片語 (A) owing to。", "translation": "由於貨運費率上升，北部銷售部門的季度淨營收微幅下滑。"}], "part7": {"passages": [{"text_type": "Executive Memorandum (主管備忘錄)", "title": "BioVance Research — Facility Upgrade & Cleanroom Maintenance Guidelines", "content": "MEMORANDUM: LAB-OPS-2026-11\nTO: Departmental Research Fellows and Clinical Laboratory Staff\nFROM: Operations Directorate, BioVance Pharmaceutical Research Center\nDATE: November 5, 2026\nSUBJECT: Cleanroom 3B Scheduled Maintenance and Workstation Relocation Protocol\n\n1. Facility Maintenance Window\nBioVance Research announces that Cleanroom 3B will undergo urgent physical modifications and specialized decontamination protocols. Specifically, owing to comprehensive ventilation repairs and high-efficiency particulate air (HEPA) filter replacements, Cleanroom 3B will be entirely inaccessible to all project teams from Monday, November 10, through Wednesday, November 12. Normal testing operations are scheduled to resume at 8:00 AM on Thursday, November 13.\n\n2. Protocol for Urgent Chemical Testing\nAll bio-analytical experiments and ongoing cell culture syntheses must be paused or rescheduled accordingly. However, chemical testing may proceed before November 15 exclusively with prior written approval from Laboratory Director Dr. Sandra Bullock. Unapproved entries will trigger automatic security alarms and lead to experimental invalidation.\n\n*Alternative Workspace Arrangements: Research groups with non-negotiable regulatory filing deadlines are strongly encouraged to request temporary bench space in Building C on a first-come, first-served basis. Reallocation request forms are accessible via the internal laboratory intranet under Facility Resource Requests.", "questions": [{"question": "Why is Cleanroom 3B unavailable between November 10 and 12?", "options": {"A": "Owing to comprehensive ventilation repairs.", "B": "Because of annual financial inventory.", "C": "Due to accidental chemical contamination.", "D": "To prepare for an executive board inspection."}, "answer": "A", "radar": "🔍 防漏看雷達：原因連接詞片語 'owing to comprehensive ventilation repairs'！", "analysis": "文中第一段結尾指出：'cleanroom 3B will remain strictly off-limits owing to comprehensive ventilation repairs'，故選 (A)。"}, {"question": "Under what condition may chemical testing proceed before November 15?", "options": {"A": "If conducted exclusively in Cleanroom 3B.", "B": "With prior written approval from Dr. Sandra Bullock.", "C": "Provided that results are filed by November 12.", "D": "If an extra facility technician supervises the lab."}, "answer": "B", "radar": "🔍 防漏看雷達：星號重要除外條款 'unless prior written authorization has been granted by Dr. Sandra Bullock'！", "analysis": "文末星號強調測試必須暫緩，'unless prior written authorization has been granted by Dr. Sandra Bullock'（除非取得事前書面核准），故選 (B)。"}, {"question": "How can researchers secure alternative workspace if their deadline cannot change?", "options": {"A": "By requesting space in Building C on a first-come basis.", "B": "By paying an expedited reservation surcharge.", "C": "By submitting an appeal to the Facilities Director.", "D": "By relocating their equipment to the main auditorium."}, "answer": "A", "radar": "🔍 防漏看雷達：條件句細節 'temporary lab space in Building C will be allocated on a first-come, first-served basis'！", "analysis": "最後一句提到：若時限無法調整，C 棟臨時實驗空間將以先到先得方式分配，故選 (A)。"}]}, {"text_type": "Standard Operating Procedure (標準作業程序手冊)", "title": "Corporate Finance Directive — Standard Operating Procedure: Travel Expense Reimbursements", "content": "FINANCE DIRECTIVE: FIN-SOP-2026-04\nAPPLIES TO: All Global Staff, Field Consultants, and Department Heads\nISSUED BY: Corporate Accounting & Financial Audit Division\nEFFECTIVE: November 5, 2026\n\n1. Purpose and Submission Timelines\nTo standardize international and domestic business travel accounting, the Finance Directorate has established updated expense filing regulations. All employees traveling on company business must file their formal expense reimbursement claims within ten business days following trip conclusion. Late submissions will experience processing delays and may be deferred to the subsequent fiscal quarter.\n\n2. Daily Per Diem Thresholds and Exclusions\nThe standard business travel per diem provides up to $75 per day for meals and personal incidentals while on official travel status. If a daily meal expense surpasses $75 without written consent from a division vice president, the excess amount is deducted from the next paycheck. Alcohol, minibar purchases, and personal laundry services remain strictly non-reimbursable.\n\n*Mandatory Receipt Requirements: Itemized receipts showing payment method and date are mandatory for all transactions exceeding $25. As a minor administrative exemption, small incidentals, such as a taxi fare receipt totaling $18 or parking meter stubs under $20, do not require itemized receipts; standard merchant credit card receipts or terminal printouts are acceptable.", "questions": [{"question": "What is the deadline for filing expense reimbursement claims?", "options": {"A": "Within ten business days following trip conclusion.", "B": "Prior to departing on the business trip.", "C": "Within twenty-four hours of hotel check-out.", "D": "At the final business day of each calendar month."}, "answer": "A", "radar": "🔍 防漏看雷達：時間條件句 'submitted within ten business days following the conclusion of any business trip'！", "analysis": "第一段第二句清楚說明：報銷申請表格必須在出差結束後十個工作天內送出，故選 (A)。"}, {"question": "What happens if a daily meal expense surpasses $75 without written consent?", "options": {"A": "The excess amount is deducted from the next paycheck.", "B": "The entire travel claim is permanently rejected.", "C": "The employee must repeat the training seminar.", "D": "A formal disciplinary reprimand is issued."}, "answer": "A", "radar": "🔍 防漏看雷達：超額懲罰條款 'any amount exceeding this threshold will be deducted from the employee's subsequent paycheck'！", "analysis": "星號小字說明：每日餐費上限 75 美元，超過門檻的金額將從員工隨後的薪資單中扣除，故選 (A)。"}, {"question": "Which expense does NOT require an itemized receipt?", "options": {"A": "A taxi fare receipt totaling $18.", "B": "A client dinner receipt totaling $65.", "C": "A hotel stay receipt totaling $120.", "D": "An airport express train ticket totaling $35."}, "answer": "A", "radar": "🔍 防漏看雷達：金額門檻條件 'receipts exceeding $25 must be itemized and attached'！", "analysis": "文中明確規定只有『超過 25 美元』的單據才需要逐項列出並附上收據。計程車費 18 美元低於 25 美元門檻，不需檢附，故選 (A)。"}]}]}}}, "3": {"day": 3, "date": "11/06", "phase": 1, "phase_name": "錯題庫清零與語感校正", "topic": "條件假設連接詞 ｜ intent vs. intention ｜ 評估與顧問", "morning": {"chunks": [{"chunk": "letter of intent", "meaning": "意向書 (LOI)", "scenario": "Both firms signed a letter of intent to finalize the cross-border merger.", "paraphrase": "intent = commitment / purpose", "alert": "商務固定名詞搭配：letter of intent（意向書），不可用 intention 替換！"}, {"chunk": "without clear intention", "meaning": "缺乏明確的意圖", "scenario": "Investing capital without clear intention frequently leads to poor returns.", "paraphrase": "intention = objective = aim", "alert": "單獨指個人意圖、打算時，通常用 intention。"}, {"chunk": "annual convention center", "meaning": "年度大會中心", "scenario": "Over 3,000 delegates will gather at the annual convention center.", "paraphrase": "convention = conference = assembly", "alert": "多義字：convention 可指『大型會議/年會』或『慣例/傳統』。"}, {"chunk": "assess the damage", "meaning": "評估損失 / 災情", "scenario": "Insurance adjusters arrived early to assess the damage caused by the storm.", "paraphrase": "assess = evaluate = appraise = gauge", "alert": ""}, {"chunk": "evaluate market potential", "meaning": "評估市場潛力", "scenario": "The consulting firm will evaluate market potential before greenlighting the launch.", "paraphrase": "evaluate = estimate = analyze", "alert": ""}, {"chunk": "in the event that", "meaning": "萬一 / 如果發生……", "scenario": "In the event that the server crashes, backup generators will activate instantly.", "paraphrase": "in the event that = if = in case", "alert": "視覺錨點：in the event that 後接完整句子 S+V；in the event of 後接名詞！"}, {"chunk": "provided that terms are met", "meaning": "只要符合條件", "scenario": "The contract will be renewed provided that terms are met satisfactorily.", "paraphrase": "provided that = as long as = on condition that", "alert": ""}], "visual_anchor": {"title": "條件句三劍客：that 尾巴 vs. of 尾巴", "rule_1": "👀 看到 in the event that / provided that / given that ➔ 後面必接【完整句子 (S+V)】", "rule_2": "👀 看到 in the event of / in case of ➔ 後面必接【名詞片語 / V-ing】", "golden_rule": "⚡ 教練金句：字尾帶 that 接句子，字尾帶 of 接名詞！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "The manufacturer will replace defective parts free of charge ________ the warranty claim is filed within one year.", "options": {"A": "provided that", "B": "in the event of", "C": "regardless", "D": "in spite of"}, "answer": "A", "analysis": "視覺錨點：空格後為 'the warranty claim (S) + is filed (V)'（完整子句），秒選連接詞 (A) provided that（只要 / 在……條件下）。(B) 與 (D) 為介系詞片語，只能接名詞；(C) regardless 須搭配 of。", "translation": "只要保固申請在一年內提出，製造商將免費更換瑕疵零件。"}, {"id": 2, "target_seconds": 15, "question": "The CEO signed a formal letter of ________ outlining the preliminary purchase price.", "options": {"A": "intend", "B": "intent", "C": "intentionally", "D": "intended"}, "answer": "B", "analysis": "商務高頻語塊秒殺：letter of intent（意向書，不可數抽象名詞）。(A) 為動詞；(C) 為副詞；(D) 為過去分詞。", "translation": "執行長簽署了一份正式意向書，概述初步收購價格。"}, {"id": 3, "target_seconds": 15, "question": "Before finalizing the budget, the financial director hired an independent analyst to ________ recent revenue projections.", "options": {"A": "advise", "B": "evaluate", "C": "persist", "D": "oversee"}, "answer": "B", "analysis": "空格後接名詞 'recent revenue projections'（營收預測）。evaluate projections 指『評估預測數據』，語意最精準。advise 通常接人或接 on/about；persist 接 in；oversee 指監督流程或人員。", "translation": "在敲定預算之前，財務總監聘請了一位獨立分析師來評估近期的營收預估。"}, {"id": 4, "target_seconds": 15, "question": "________ a severe fire or natural disaster, emergency backup systems will engage within ten seconds.", "options": {"A": "In the event that", "B": "In the event of", "C": "Provided that", "D": "As though"}, "answer": "B", "analysis": "視覺錨點：空格後為 'a severe fire or natural disaster'（純名詞片語無動詞），秒選 of 結尾的介系詞片語 (B) In the event of。(A)、(C)、(D) 全為從屬連接詞，後面必須接 S+V 完整子句。", "translation": "萬一發生嚴重火災或自然災害，緊急備用系統將在 10 秒內啟動。"}, {"id": 5, "target_seconds": 15, "question": "Senior structural engineers were dispatched to ________ structural damage caused by the recent earthquake.", "options": {"A": "assess", "B": "assessment", "C": "assessor", "D": "assessable"}, "answer": "A", "analysis": "不定詞結構秒殺：to + [原形動詞] + damage (名詞受詞)。選動詞 (A) assess（評估/核定）。(B) 為名詞；(C) 為評估員（人）；(D) 為形容詞。", "translation": "資深結構工程師獲派前往評估近期地震所造成的結構損害。"}, {"id": 6, "target_seconds": 15, "question": "Ms. Keller presented the keynote address at the technology symposium on ________ of the executive committee.", "options": {"A": "behalf", "B": "behave", "C": "behavior", "D": "becoming"}, "answer": "A", "analysis": "固定片語秒殺：on behalf of sb.（代表某人 / 代表某機構）。(B) 為動詞（表現）；(C) 為名詞（行為）。", "translation": "Keller 女士代表執行委員會在科技研討會上發表了專題演講。"}, {"id": 7, "target_seconds": 15, "question": "________ that inflation rates remain stable, consumer spending is projected to rebound next quarter.", "options": {"A": "Given", "B": "In spite", "C": "Owing", "D": "Because of"}, "answer": "A", "analysis": "視覺錨點：看到空格後的 'that' + 完整子句 (inflation rates remain stable)，秒選 (A) Given that（考慮到/鑑於……）。(B) 需接 of；(C) 需接 to；(D) 後方不可直接接 that 子句。", "translation": "鑑於通貨膨脹率維持穩定，預計下季度消費者支出將會反彈。"}, {"id": 8, "target_seconds": 15, "question": "The legal department stated that the enterprise had no ________ of infringing on existing copyrights.", "options": {"A": "intend", "B": "intention", "C": "intentional", "D": "intentionally"}, "answer": "B", "analysis": "have no intention of V-ing（毫無意圖做某事）。no 為形容詞修飾名詞 intention。(A) 為動詞；(C) 為形容詞；(D) 為副詞。", "translation": "法務部門聲明該企業絕無侵犯現有著作權之意圖。"}, {"id": 9, "target_seconds": 20, "question": "Management consulted with external advisors to ________ the feasibility of launching a European branch.", "options": {"A": "evaluate", "B": "evaluation", "C": "evaluative", "D": "evaluator"}, "answer": "A", "analysis": "不定詞結構：to + [原形動詞] + the feasibility (名詞受詞)。evaluate the feasibility（評估可行性）為多益黃金搭配。故選 (A)。", "translation": "管理層諮詢了外部顧問，以評估設立歐洲分部的可行性。"}, {"id": 10, "target_seconds": 15, "question": "The commercial lease will renew automatically ________ the tenant submits a written termination letter before October 1.", "options": {"A": "unless", "B": "without", "C": "despite", "D": "in spite of"}, "answer": "A", "analysis": "視覺錨點：空格後為完整句子 'the tenant submits...'。選連接詞 (A) unless（除非……否則）。(B)、(C)、(D) 皆為介系詞，後方不能接動詞子句。", "translation": "商業租約將自動續約，除非承租人在 10 月 1 日前提交書面終止信。"}, {"id": 11, "target_seconds": 15, "question": "Every residential ________ in the complex is required to register their vehicle with the security office.", "options": {"A": "tenant", "B": "tenancy", "C": "tenants", "D": "tenanted"}, "answer": "A", "analysis": "限定詞用法：Every 後接『單數可數名詞』。tenant 指房客/住戶。(B) tenancy 為租賃關係（抽象名詞）；(C) 為複數；(D) 為動詞過去式。", "translation": "該社區的每位住戶都必須向警衛室登記其車輛。"}, {"id": 12, "target_seconds": 20, "question": "The board reached a ________ decision to allocate additional funding to green energy research.", "options": {"A": "unanimous", "B": "unanimously", "C": "unanimity", "D": "unanimousness"}, "answer": "A", "analysis": "形容詞修飾名詞：a + [形容詞] + decision。unanimous（全體一致的/無異議的）為多益 860 關鍵單字。(B) 為副詞；(C) 為名詞。", "translation": "董事會達成全體一致的決定，將提撥額外資金用於綠色能源研究。"}, {"id": 13, "target_seconds": 15, "question": "The hotel's close ________ to the convention center makes it an ideal choice for conference guests.", "options": {"A": "proximity", "B": "approximate", "C": "approximately", "D": "proximities"}, "answer": "A", "analysis": "名詞搭配：close proximity to sth.（鄰近/接近某處）。proximity 為不可數名詞。(B) 為形容詞/動詞；(C) 為副詞（大約）。", "translation": "該飯店鄰近會議中心的優越地理位置，使其成為與會嘉賓的理想選擇。"}, {"id": 14, "target_seconds": 15, "question": "Sales representatives are currently reaching out to ________ clients across the metropolitan region.", "options": {"A": "prospective", "B": "prospectively", "C": "prospects", "D": "prospectus"}, "answer": "A", "analysis": "形容詞修飾名詞：prospective clients 指『潛在客戶 / 準客戶』。(A) prospective 為形容詞。(B) 為副詞；(C) 為名詞；(D) 為公開說明書。", "translation": "業務代表目前正主動接觸大都會區內的潛在客戶。"}, {"id": 15, "target_seconds": 20, "question": "The research team provided ________ evidence demonstrating the efficacy of the new solar cell.", "options": {"A": "tangible", "B": "tangibly", "C": "tangibility", "D": "tangibleness"}, "answer": "A", "analysis": "形容詞修飾名詞：tangible evidence 指『實質具體的證據』。(A) tangible 為形容詞。(B) 為副詞；(C) 為名詞。", "translation": "研究團隊提供了實質具體的證據，證明了新型太陽能電池的功效。"}, {"id": 16, "target_seconds": 15, "question": "For any technical ________ regarding the online software portal, please email support@orbit.com.", "options": {"A": "queries", "B": "queried", "C": "querying", "D": "querulous"}, "answer": "A", "analysis": "名詞受詞：介系詞 For + [名詞]。technical queries 指『技術諮詢/技術問題』。query 為名詞，複數為 queries。(B)、(C) 為動詞變化。", "translation": "若對線上軟體入口網站有任何技術諮詢，請發送電子郵件至 support@orbit.com。"}, {"id": 17, "target_seconds": 15, "question": "The chief executive officer ________ the expansion plan during yesterday's press conference.", "options": {"A": "endorsed", "B": "endorsing", "C": "endorsement", "D": "endorse"}, "answer": "A", "analysis": "時態與主謂一致：主詞 The chief executive officer，時間副詞 yesterday 提示過去式，選過去式動詞 (A) endorsed（背書/支持）。(C) 為名詞；(D) 為現在式原形未加 -s。", "translation": "執行長在昨天的記者會上為擴張計畫公開背書。"}, {"id": 18, "target_seconds": 20, "question": "The restaurant ________ decided to renovate the dining area to accommodate larger banquet parties.", "options": {"A": "proprietor", "B": "proprietary", "C": "propriety", "D": "proprietorship"}, "answer": "A", "analysis": "主詞身分秒殺：空格位於句子主詞位置，且後方動詞為 decided（決定），主詞必須是人。(A) proprietor 指『業主/業主老闆』。(B) proprietary 為專利的/所有權的；(D) 為所有權制度。", "translation": "該餐廳業主決定重新裝修用餐區，以容納更大型的宴會聚餐。"}, {"id": 19, "target_seconds": 15, "question": "A minimum revenue ________ of $500,000 must be achieved before the affiliate branch can qualify for bonuses.", "options": {"A": "threshold", "B": "subtraction", "C": "dues", "D": "aisle"}, "answer": "A", "analysis": "名詞搭配：revenue threshold 指『營收門檻』。subtraction 為減法扣除；dues 為會費；aisle 為走道。故選 (A)。", "translation": "加盟分部在具備領取獎金資格之前，必須達到至少 50 萬美元的營收門檻。"}, {"id": 20, "target_seconds": 15, "question": "________ the original blueprint was lost, the architectural firm reconstructed the floor plan from digital backups.", "options": {"A": "Since", "B": "Owing to", "C": "Prior to", "D": "Regardless of"}, "answer": "A", "analysis": "視覺錨點：空格後為完整句子 'the original blueprint (S) + was lost (V)'，秒選從屬連接詞 (A) Since（因為 / 既然）。(B)、(C)、(D) 全為介系詞片語，後方無法接動詞子句。", "translation": "由於原始藍圖遺失，建築事務所便利用數位備份重建了平面圖。"}]}, "afternoon": {"quick_recall": [{"prompt": "A formal letter of ________ [名詞，意向] outlining terms.", "clue": "意向書（固定搭配 letter of ...）", "answer": "intent"}, {"prompt": "The company has no ________ [名詞，意圖] of terminating staff.", "clue": "have no _____ of V-ing", "answer": "intention"}, {"prompt": "In the event ________ [介系詞] severe turbulence, stay seated.", "clue": "萬一發生……（後面接名詞）", "answer": "of"}, {"prompt": "In the event ________ [連接詞尾巴] flight schedules change, notify us.", "clue": "萬一……（後面接完整句子 S+V）", "answer": "that"}, {"prompt": "The manager spoke on ________ [片語介系詞核心] of the team.", "clue": "代表某人（on _____ of）", "answer": "behalf"}, {"prompt": "Approved ________ [連接詞，只要] all safety requirements are met.", "clue": "只要……（p開頭連接詞）", "answer": "provided that"}], "spaced_traps": [{"id": 1, "question": "________ the contract is officially ratified by legal counsel, no funds will be disbursed.", "options": {"A": "Provided that", "B": "Unless", "C": "In spite of", "D": "Prior to"}, "answer": "B", "trap_point": "語意邏輯轉折：Unless = if not（除非）。Provided that 表只要；Prior to 與 In spite of 為介系詞無法接句子。", "analysis": "空格後為句子。句意為『除非契約正式獲得法務批准，否則不予撥款』。表否定條件選 (B) Unless。(A) Provided that 語意會變成『只要批准了就不撥款』，邏輯相反。", "translation": "除非該合約獲得法務顧問正式批准，否則不會撥付任何款項。"}, {"id": 2, "question": "The acquisition proposal was rejected ________ concerns regarding undisclosed foreign liabilities.", "options": {"A": "because", "B": "due to", "C": "even though", "D": "as"}, "answer": "B", "trap_point": "concerns 在此處為『名詞（疑慮）』，其後 regarding... 為介系詞修飾，整段無動詞！秒選介系詞 due to！", "analysis": "許多考生看到 concerns 誤以為是動詞。在此處 concerns 為複數名詞受詞，整段沒有主要動詞，故不可選連接詞 (A)、(C)、(D)，秒選介系詞 (B) due to。", "translation": "由於對未公開之海外負債存在疑慮，該收購提案遭到否決。"}, {"id": 3, "question": "The two department directors reached an agreement to cooperate with ________ on the marketing campaign.", "options": {"A": "one another", "B": "each other", "C": "other", "D": "another"}, "answer": "B", "trap_point": "雙方（兩者）互相用 each other；三者以上互相用 one another！", "analysis": "主詞明確提到 'The two department directors'（兩位總監）。傳統文法與多益嚴謹考點：兩者之間互相用 each other；三者以上用 one another。故選 (B)。", "translation": "兩位部門總監達成協議，在行銷宣傳活動中彼此通力合作。"}, {"id": 4, "question": "The facility supervisor must ________ all electrical appliances prior to factory closure.", "options": {"A": "inspection", "B": "inspect", "C": "inspecting", "D": "inspected"}, "answer": "B", "trap_point": "助動詞 must + 原形動詞 inspect。不能被長名詞片語拉開距離而誤選名詞。", "analysis": "must 為情態助動詞，後接原形動詞 (B) inspect。inspection 為名詞；inspected 為過去分詞。", "translation": "廠區主管在工廠關閉前必須檢查所有電器設備。"}, {"id": 5, "question": "The firm signed a binding letter of ________ to purchase the waterfront commercial lot.", "options": {"A": "intend", "B": "intent", "C": "intentional", "D": "intentionally"}, "answer": "B", "trap_point": "letter of intent（意向書）為專有商業語塊，不可選動詞 intend 或形容詞 intentional。", "analysis": "letter of intent 為不可變動之商務術語。名詞 of 名詞結構，選 (B) intent。", "translation": "該公司簽署了一份具約束力的意向書，以購買水岸商業用地。"}, {"id": 6, "question": "Emergency medical treatment is provided free of charge ________ the patient has active insurance.", "options": {"A": "regardless", "B": "provided that", "C": "owing to", "D": "in spite of"}, "answer": "B", "trap_point": "空格後為句子 'the patient has active insurance'，選連接詞 provided that！", "analysis": "(C)、(D) 為介系詞片語；(A) regardless 須接 of。只有 (B) provided that（只要……）能連接完整子句。", "translation": "只要病患擁有有效保險，緊急醫療照護便免費提供。"}, {"id": 7, "question": "The committee ________ four regional directors and a certified public accountant.", "options": {"A": "consists of", "B": "is consisted of", "C": "insists on", "D": "persists in"}, "answer": "A", "trap_point": "由……組成用主動態 consists of，絕無被動態 is consisted of！", "analysis": "主詞 committee 為單數集合名詞，現在式不及物片語選 (A) consists of。(C) 是堅持要求；(D) 是堅持不懈。", "translation": "該委員會由四位區域總監及一位執業會計師組成。"}, {"id": 8, "question": "The marketing manager decided to ________ the regional launch until supplier issues are resolved.", "options": {"A": "step down", "B": "put off", "C": "take over", "D": "back down"}, "answer": "B", "trap_point": "動詞片語語意辨析：put off（延期推遲）。step down 辭職；take over 接管；back down 讓步。", "analysis": "句意表示行銷經理決定『延期』該區域的上市發表，直到供應商問題解決。故選 (B) put off（= postpone / delay）。", "translation": "行銷經理決定將該區域的產品上市發表延期，直到供應商問題獲得解決。"}, {"id": 9, "question": "The pharmaceutical company signed a non-binding letter of ________ to acquire the biotech startup.", "options": {"A": "intent", "B": "intend", "C": "intentionally", "D": "intended"}, "answer": "A", "trap_point": "letter of intent（意向書）為固定商業術語，不可選動詞 intend！", "analysis": "letter of intent 為不可更換之專用名詞語塊，選 (A)。", "translation": "該製藥公司簽署了一份不具約束力的意向書，以收購該生技新創公司。"}, {"id": 10, "question": "Emergency water sprinklers will activate automatically in the event ________ a chemical fire in the laboratory.", "options": {"A": "of", "B": "that", "C": "as", "D": "for"}, "answer": "A", "trap_point": "後方接名詞片語 'a chemical fire'，選 of 結尾的介系詞片語 in the event of！", "analysis": "後方無句子，不可選 in the event that。選介系詞 (A) of。", "translation": "萬一實驗室發生化學火災，緊急灑水系統將自動啟動。"}, {"id": 11, "question": "The board will approve the international expansion ________ that all environmental regulations are met.", "options": {"A": "provided", "B": "owing", "C": "in spite", "D": "prior"}, "answer": "A", "trap_point": "provided that + 完整子句（只要……在…條件下）。", "analysis": "看到空格後接 that + 完整句子，秒選 (A) provided that。", "translation": "只要符合所有環境法規，董事會將批准國際擴張計畫。"}, {"id": 12, "question": "The human resources director has no ________ of terminating remote work privileges for staff.", "options": {"A": "intention", "B": "intend", "C": "intentional", "D": "intentionally"}, "answer": "A", "trap_point": "have no intention of V-ing（毫無…意圖）。", "analysis": "no 為形容詞修飾名詞 intention，選 (A)。", "translation": "人資總監絕無終止員工遠距辦公權限的意圖。"}, {"id": 13, "question": "The municipal safety inspector was sent to ________ property damage following the industrial explosion.", "options": {"A": "assess", "B": "assessment", "C": "assessor", "D": "assessable"}, "answer": "A", "trap_point": "sent to + [動詞原形] + damage (名詞受詞)。assess damage（評估損害）。", "analysis": "不定詞後接及物動詞原形，選 (A) assess。", "translation": "市政安全稽查員獲派前往評估工業爆炸後的財產損害。"}, {"id": 14, "question": "The company guarantees replacement parts free of charge ________ the item was bought from an authorized dealer.", "options": {"A": "provided that", "B": "in the event of", "C": "in spite of", "D": "prior to"}, "answer": "A", "trap_point": "空格後為完整句子 'the item was bought...'，選連接詞 provided that！", "analysis": "(B)、(C)、(D) 全為介系詞片語無法接句子。只有 (A) provided that 為連接詞，選 (A)。", "translation": "只要商品是向授權經銷商購買的，該公司保證免費更換零件。"}], "part7": {"passages": [{"text_type": "Commercial Lease Agreement (商業租賃合約)", "title": "Apex Commercial Dining — Equipment Lease and Event Catering Master Agreement", "content": "COMMERCIAL CONTRACT NO: APX-CAT-2026-78\nLESSOR: Apex Commercial Dining & Event Equipment Solutions LLC\nLESSEE: Vanguard Global Hospitality Group\nLOCATION OF SERVICE: Grand Hall Expo Center, Seattle, WA\nEFFECTIVE PERIOD: November 6, 2026 — November 30, 2027\n\nClause 4. Maintenance Standards & Emergency Replacement:\nApex Catering guarantees that all commercial convection ovens, induction cooktops, and refrigeration displays will operate in prime mechanical condition. In the rare event that leased machinery breaks down under normal use, Apex Catering will dispatch emergency replacement units within three hours of receiving phone notification from the on-site event coordinator.\n\nClause 7. Cancellation, Alteration, and Restocking Charges:\nLessee acknowledges that major catering logistics require substantial advance preparation. Event cancellations are permitted without any surcharge if written notice is received at least 48 hours before the event date.\n\n*Late Cancellation Penalty: Cancellations submitted less than 48 hours before the scheduled event will incur a mandatory 25% restocking surcharge calculated from the gross contracted billing amount. This fee covers warehouse re-shelving, vehicle rescheduling, and pre-allocated perishable supplies. Written cancellation notices must be transmitted via email to logistics@apexcatering.com.", "questions": [{"question": "What will Apex Catering do if leased machinery breaks down under normal use?", "options": {"A": "Dispatch emergency replacement units within three hours.", "B": "Refund the entire catering deposit immediately.", "C": "Send a certified technician the following business morning.", "D": "Issue a credit voucher for future equipment rentals."}, "answer": "A", "radar": "🔍 防漏看雷達：定位承諾條件 'emergency replacement units will be dispatched within three hours of notification'！", "analysis": "第一段第二句明確說明：若設備故障非承租人過失，緊急替換設備將在接獲通知後 3 小時內派出，故選 (A)。"}, {"question": "Under what condition is cancellation permitted without any surcharge?", "options": {"A": "If written notice is received at least 48 hours before the event.", "B": "Provided that total equipment cost does not exceed $5,000.", "C": "Whenever severe weather forces the convention to close.", "D": "If an alternative lessee takes over the equipment contract."}, "answer": "A", "radar": "🔍 防漏看雷達：星號免責小字 'provided that written notice is submitted at least 48 hours prior to the event commencement date'！", "analysis": "星號特別註記：承租人若想免受罰款終止合約，條件為至少在活動開始前 48 小時提交書面通知，故選 (A)。"}, {"question": "What penalty applies to cancellations made less than 48 hours before the expo?", "options": {"A": "A mandatory 25% restocking surcharge.", "B": "Permanent forfeiture of all security deposits.", "C": "A flat administrative cancellation fine of $500.", "D": "Suspension from future expo vendor registrations."}, "answer": "A", "radar": "🔍 防漏看雷達：抓逾期罰則 'subject to a mandatory 25% restocking surcharge'！", "analysis": "文中明確寫道：在該門檻之後取消者，必須負擔 25% 的強制重新進貨附加費，故選 (A)。"}]}, {"text_type": "Internal Policy Notice (內部行政通告)", "title": "Metropolitan Operations — Facility Relocation Guidelines for Regional Staff", "content": "FACILITY OPERATIONS BULLETIN: METRO-RELOC-2026\nDATE: November 6, 2026\nTO: Regional Corporate Staff and Resident Contractors\nFROM: Corporate Relocation Task Force & Building Administration\nSUBJECT: Transition to Metropolitan Tower New Headquarters\n\n1. Document Security & Packing Mandates\nIn preparation for our scheduled transition to the newly constructed Metropolitan Tower on November 18, all resident departments must complete preparatory measures. Department heads and project managers must ensure that staff shred or securely lock confidential documents prior to leaving the old office premises. Unsecured sensitive client dossiers left on desks will be confiscated by internal security.\n\n2. Employee Parking Registration & Rates\nSubterranean parking permits at the new Metropolitan Tower are managed through an automated license-plate recognition system. Staff members may secure the subsidized parking rate of $60 per month by registering their license plate online before November 15 through the corporate portal.\n\n*Non-Compliance Consequences: Employees who fail to complete their license plate registration by November 15 will forfeit the corporate subsidy and must pay the full rate of $180 per month. Visitor spaces are reserved strictly for registered external clients and auditors.", "questions": [{"question": "What must department heads complete before leaving the old office?", "options": {"A": "Shred or securely lock confidential documents.", "B": "Distribute new electronic entrance badges to staff.", "C": "Submit quarterly operational expense audits.", "D": "Pay the commercial moving deposit in cash."}, "answer": "A", "radar": "🔍 防漏看雷達：行動要求 'all confidential paperwork is shredded or locked in designated security bins prior to departure'！", "analysis": "第一段最後一句規定：各部門主管出發離開前，必須確保所有機密文件均已銷毀或鎖於指定安全箱內，故選 (A)。"}, {"question": "How can employees secure the subsidized parking rate?", "options": {"A": "By registering their license plate online before November 15.", "B": "By submitting a written request to the Operations Director.", "C": "By paying four months of garage fees upfront.", "D": "By carpooling with at least two other staff members."}, "answer": "A", "radar": "🔍 防漏看雷達：資格條件 'provided that they register their license plate online before November 15'！", "analysis": "星號小字說明補助條件：只要在 11 月 15 日前完成線上車牌登記即可享有補助費率，故選 (A)。"}, {"question": "What happens if an employee misses the November 15 parking deadline?", "options": {"A": "They must pay the full rate of $180 per month.", "B": "Their garage access privileges are revoked permanently.", "C": "They are assigned to park in an off-site overflow lot.", "D": "A $50 late administrative fee will be deducted."}, "answer": "A", "radar": "🔍 防漏看雷達：未符條件後果 'required to pay the standard commercial parking rate of $180 per month'！", "analysis": "文末指出：錯過登記期限者，必須支付每月 180 美元的標準商業費率，故選 (A)。"}]}]}}}, "4": {"day": 4, "date": "11/07", "phase": 1, "phase_name": "錯題庫清零與語感校正", "topic": "分詞修飾名詞 (V-ing vs V-ed) ｜ 召回、庫存與保險範圍", "morning": {"chunks": [{"chunk": "extensive media coverage", "meaning": "廣泛的媒體報導", "scenario": "The tech summit received extensive media coverage across North America.", "paraphrase": "coverage = reporting = broadcast; 多義字：coverage 亦指『保險理賠範圍』！", "alert": ""}, {"chunk": "recall faulty appliances", "meaning": "召回故障家電", "scenario": "The distributor decided to recall faulty appliances to avoid legal liability.", "paraphrase": "recall = withdraw = call back; faulty = defective", "alert": ""}, {"chunk": "under warranty conditions", "meaning": "在保固條件限制下", "scenario": "Repairs are conducted free of charge under warranty conditions.", "paraphrase": "conditions = terms = stipulations", "alert": ""}, {"chunk": "keep items in stock", "meaning": "備有現貨庫存", "scenario": "The warehouse strives to keep high-demand merchandise in stock.", "paraphrase": "in stock = available = on hand", "alert": ""}, {"chunk": "conduct an investigation", "meaning": "執行內部調查", "scenario": "The compliance division was authorized to conduct an investigation into the leak.", "paraphrase": "conduct = carry out = perform = execute", "alert": ""}, {"chunk": "promote brand awareness", "meaning": "提昇品牌知名度", "scenario": "Digital campaigns were launched to promote brand awareness among young professionals.", "paraphrase": "promote = boost = enhance; 多義字：promote 亦指『升遷 / 提拔』！", "alert": ""}, {"chunk": "promising prospective clients", "meaning": "有潛力的潛在客戶", "scenario": "The sales representative scheduled meetings with several promising prospective clients.", "paraphrase": "prospective = potential = future; promising = favorable", "alert": ""}], "visual_anchor": {"title": "分詞當形容詞：看被修飾名詞是「主動發出」還是「被動承受」", "rule_1": "👀 名詞自己能做動作 ➔ 選 V-ing（demanding job 費力的工作, promising future 有前途的未來）", "rule_2": "👀 名詞是被做的 / 承受動作 ➔ 選 V-ed（damaged goods 受損貨品, revised contract 修改後的合約）", "golden_rule": "⚡ 教練金句：主動發光選 -ing，被動受傷選 -ed！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "Customers who purchased ________ appliances are urged to contact customer support immediately for a replacement.", "options": {"A": "faulty", "B": "fault", "C": "faultily", "D": "faulting"}, "answer": "A", "analysis": "形容詞修飾名詞：faulty appliances 指『有缺陷的電器』。(A) faulty 為形容詞；(B) 為名詞；(C) 為副詞。", "translation": "購買到有瑕疵家電的顧客，請立即聯繫客戶支援以獲取更換產品。"}, {"id": 2, "target_seconds": 15, "question": "Warehouse personnel must report any ________ merchandise to the inventory supervisor before signing the freight receipt.", "options": {"A": "damaged", "B": "damaging", "C": "damages", "D": "damage"}, "answer": "A", "analysis": "分詞形容詞秒殺：商品是『被損壞的』，表被動完成狀態用過去分詞 (A) damaged 修飾名詞 merchandise。(B) damaging 為主動造成損害的（如 damaging storm）。", "translation": "倉庫人員在簽收貨運單之前，必須向庫存主管回報任何受損商品。"}, {"id": 3, "target_seconds": 15, "question": "The commercial insurance policy provides extensive ________ against water and earthquake damage.", "options": {"A": "coverage", "B": "cover", "C": "covering", "D": "covered"}, "answer": "A", "analysis": "名詞受詞：provides (及物動詞) + extensive (形容詞) + [名詞受詞]。insurance coverage 表『保險涵蓋範圍/理賠保障』。(B) 為動詞；(D) 為分詞。", "translation": "該商業保單針對水災及地震損害提供了廣泛的理賠保障範圍。"}, {"id": 4, "target_seconds": 15, "question": "Although the vintage desk was manufactured in 1950, it remains in mint ________.", "options": {"A": "condition", "B": "conditionally", "C": "conditional", "D": "conditioner"}, "answer": "A", "analysis": "固定商務片語：in mint condition 指『處於嶄新/完好無損的狀態』。condition 為名詞。(B) 為副詞；(C) 為形容詞。", "translation": "雖然這張古董書桌是在 1950 年製造的，但它依然保持在完好如新的狀態。"}, {"id": 5, "target_seconds": 15, "question": "Due to overwhelming demand during the holiday sale, the wireless headphones are temporarily out of ________.", "options": {"A": "stock", "B": "stocked", "C": "stocking", "D": "stocks"}, "answer": "A", "analysis": "商業高頻片語：out of stock（缺貨）。stock 在此為不可數名詞，指現貨庫存。(B) 為過去分詞；(C) 為現在分詞。", "translation": "由於連假特賣期間需求暴增，該款無線耳機目前暫時缺貨。"}, {"id": 6, "target_seconds": 15, "question": "The human resources committee has identified three ________ candidates for the regional sales director position.", "options": {"A": "promising", "B": "promised", "C": "promise", "D": "promisingly"}, "answer": "A", "analysis": "分詞形容詞秒殺：candidates（候選人）本身具備前途與潛力（主動特質），用現在分詞 (A) promising（有希望的 / 大有可為的）。(B) promised 指被承諾的。", "translation": "人資委員會已鎖定三位大有可為的候選人，以角逐區域銷售總監一職。"}, {"id": 7, "target_seconds": 15, "question": "The automobile manufacturer issued a voluntary ________ of over 50,000 sedans due to an airbag sensor glitch.", "options": {"A": "recall", "B": "recalled", "C": "recalling", "D": "recalls"}, "answer": "A", "analysis": "名詞受詞：冠詞 a + 形容詞 voluntary + [單數名詞]。a voluntary recall 指『自願性召回』。(A) recall 可作名詞（召回）。(B) 為動詞過去式；(C) 為動名詞。", "translation": "由於安全氣囊感應器故障，該汽車製造商對超過 5 萬輛房車發布了自願召回令。"}, {"id": 8, "target_seconds": 15, "question": "Older computer servers are particularly ________ to external security breaches unless patched regularly.", "options": {"A": "vulnerable", "B": "vulnerably", "C": "vulnerability", "D": "vulnerableness"}, "answer": "A", "analysis": "介系詞搭配秒殺：be vulnerable to sth.（易受……傷害/脆弱的）。are 為 be 動詞，副詞 particularly 修飾形容詞 (A) vulnerable。(C) 為名詞。", "translation": "舊型電腦伺服器除非定期修補，否則特別容易遭受外部安全入侵。"}, {"id": 9, "target_seconds": 20, "question": "Clients who upgrade to the premium subscription enjoy ________ access to industry research whitepapers.", "options": {"A": "exclusive", "B": "exclusively", "C": "exclusion", "D": "excluding"}, "answer": "A", "analysis": "形容詞修飾名詞：enjoy (及物動詞) + [形容詞] + access (名詞受詞)。exclusive access 指『獨家專屬使用權』。(A) exclusive 為形容詞。(B) 為副詞；(C) 為名詞。", "translation": "升級至高級會員的客戶可享有取得產業研究白皮書的專屬權限。"}, {"id": 10, "target_seconds": 15, "question": "The logistics department agreed to ________ the shipment of industrial filters to avoid factory downtime.", "options": {"A": "expedite", "B": "expedition", "C": "expeditious", "D": "expedient"}, "answer": "A", "analysis": "不定詞動詞：agreed to + [原形動詞] + the shipment。expedite（加速/迅速處理）為多益 860 必考動詞。(B) 為名詞（考察/探險）；(C) 為形容詞。", "translation": "物流部門同意加快工業濾網的運送，以避免工廠停工。"}, {"id": 11, "target_seconds": 15, "question": "Due to unforeseen architectural complications, the project manager filed for a two-week deadline ________.", "options": {"A": "extension", "B": "extensively", "C": "extensive", "D": "extend"}, "answer": "A", "analysis": "複合名詞：deadline extension 指『截止期限展延』。空格需名詞。(A) extension 為名詞；(C) extensive 為形容詞（廣泛的）；(D) 為動詞。", "translation": "由於不可預見的建築結構問題，專案經理申請了為期兩週的期限展延。"}, {"id": 12, "target_seconds": 20, "question": "Contractors are scheduled to power-wash the building's ________ stone walls this coming weekend.", "options": {"A": "exterior", "B": "externally", "C": "exteriorly", "D": "exteriors"}, "answer": "A", "analysis": "名詞前形容詞修飾：exterior stone walls 指『外部石牆』。(A) exterior 可作形容詞（外部的）。(B) 為副詞；(D) 為名詞複數。", "translation": "承包商預計在即將到來的週末對大樓的外側石牆進行高壓清洗。"}, {"id": 13, "target_seconds": 15, "question": "The marketing firm launched an ________ campaign targeting first-time home buyers in suburban markets.", "options": {"A": "elaborate", "B": "elaborately", "C": "elaboration", "D": "elaborates"}, "answer": "A", "analysis": "冠詞與名詞間修飾：an + [形容詞] + campaign。elaborate（精心策劃的/詳盡的）為形容詞。(B) 為副詞；(C) 為名詞。", "translation": "該行銷公司推出了一項精心策劃的宣傳活動，鎖定郊區市場的首購族。"}, {"id": 14, "target_seconds": 15, "question": "Management emphasized that staff members must wear appropriate corporate ________ during client consultations.", "options": {"A": "attire", "B": "attired", "C": "attiring", "D": "attires"}, "answer": "A", "analysis": "名詞受詞：wear (及物動詞) + appropriate corporate + [不可數名詞]。attire 指『服裝/著裝』，為不可數名詞。(B) 為過去分詞形容詞；(D) 錯誤加 -s。", "translation": "管理層強調，員工在進行客戶諮詢時必須穿著適當的商務正裝。"}, {"id": 15, "target_seconds": 20, "question": "The operations manager will ________ a comprehensive safety audit across all manufacturing plants next week.", "options": {"A": "conduct", "B": "conduction", "C": "conductive", "D": "conductor"}, "answer": "A", "analysis": "助動詞夾心：will + [原形動詞] + a audit (名詞受詞)。conduct an audit（執行/進行稽核）為最高頻商務搭配。(B) 為名詞；(C) 為傳導性形容詞；(D) 為指揮家/導體。", "translation": "營運經理將於下週對所有製造工廠進行全面的安全稽核。"}, {"id": 16, "target_seconds": 15, "question": "All attendees must enclose a copy of their registration confirmation ________ entering the main lecture hall.", "options": {"A": "prior to", "B": "although", "C": "because", "D": "even if"}, "answer": "A", "analysis": "視覺錨點：空格後為動名詞片語 'entering the main lecture hall'，無完整主詞動詞。秒選介系詞片語 (A) prior to（在……之前）。(B)、(C)、(D) 全為從屬連接詞，後需接 S+V。", "translation": "所有參加者在進入大演講廳前，必須出示其報名確認信副本。"}, {"id": 17, "target_seconds": 15, "question": "The updated promotional brochure contains ________ descriptions of our overseas consulting packages.", "options": {"A": "detailed", "B": "detail", "C": "detailing", "D": "details"}, "answer": "A", "analysis": "分詞形容詞秒殺：descriptions（描述）是『被詳細說明的』，用過去分詞形容詞 (A) detailed 修飾名詞。(B) 為名詞/動詞；(D) 為名詞複數。", "translation": "更新後的宣傳手冊包含對我們海外顧問套裝方案的詳細說明。"}, {"id": 18, "target_seconds": 20, "question": "Despite initial budget cutbacks, the tech firm has maintained an ________ reputation for customer service.", "options": {"A": "exceptional", "B": "exceptionally", "C": "exception", "D": "except"}, "answer": "A", "analysis": "形容詞修飾名詞：an + [形容詞] + reputation。exceptional reputation 指『卓越卓越的聲譽』。(A) exceptional 為形容詞。(B) 為副詞；(C) 為名詞；(D) 為介系詞。", "translation": "儘管面臨初期的預算縮減，這家科技公司依然保持著卓越的客戶服務聲譽。"}, {"id": 19, "target_seconds": 15, "question": "Safety regulators are currently investigating whether the factory ________ with regional emission limits.", "options": {"A": "complied", "B": "complaint", "C": "compliant", "D": "compliance"}, "answer": "A", "analysis": "動詞時態與搭配：whether the factory (主詞) + [動詞] + with...。comply with（遵守……）為不及物動詞片語，選過去式動詞 (A) complied。(B) 為名詞抱怨；(C) 為形容詞；(D) 為名詞合規。", "translation": "安全監管機構目前正在調查該工廠是否遵守了當地的排放限制。"}, {"id": 20, "target_seconds": 20, "question": "Before finalizing the agreement, the company insisted on adding a clause to protect its ________ property rights.", "options": {"A": "intellectual", "B": "intellect", "C": "intellectually", "D": "intellectualize"}, "answer": "A", "analysis": "複合名詞修飾：intellectual property rights 指『智慧財產權』。(A) intellectual 為形容詞。(B) 為名詞（智力）；(C) 為副詞。", "translation": "在敲定協議前，該公司堅持加入條款以保護其智慧財產權。"}]}, "afternoon": {"quick_recall": [{"prompt": "The car company issued a safety ________ [名詞，召回] for faulty brakes.", "clue": "召回（動名詞同形）", "answer": "recall"}, {"prompt": "The goods arrived in damaged ________ [名詞，狀態/情況].", "clue": "物品狀態（c開頭）", "answer": "condition"}, {"prompt": "Item out of ________ [名詞，庫存] due to high demand.", "clue": "缺貨（out of ...）", "answer": "stock"}, {"prompt": "Comprehensive insurance ________ [名詞，理賠/涵蓋範圍].", "clue": "保險涵蓋範圍（c開頭）", "answer": "coverage"}, {"prompt": "Elderly patients are vulnerable ________ [介系詞] infections.", "clue": "易受……影響（vulnerable 固定搭配）", "answer": "to"}, {"prompt": "We hired two very ________ [現在分詞形容詞，有前途的] software developers.", "clue": "有希望的/前途大好的（p開頭 -ing）", "answer": "promising"}], "spaced_traps": [{"id": 1, "question": "The supervisor asked warehouse technicians to return all ________ items to the supplier immediately.", "options": {"A": "damaged", "B": "damaging", "C": "damage", "D": "damages"}, "answer": "A", "trap_point": "物品是被破壞的，用被動過去分詞 damaged 修飾名詞 items；damaging 指造成傷害的！", "analysis": "修飾名詞 items，受詞本身承受損害，表被動完成狀態選 (A) damaged。damaging 是主動造成傷害的（例如 damaging effects）。", "translation": "主管要求倉庫技術員立即將所有受損物品退還給供應商。"}, {"id": 2, "question": "The executive committee is searching for ________ candidates to expand operations overseas.", "options": {"A": "promising", "B": "promised", "C": "promises", "D": "promisingly"}, "answer": "A", "trap_point": "人具備優秀潛力，主動散發希望，選現在分詞 promising（有前途的）；promised 是被承諾的！", "analysis": "修飾 candidates，表特質有前途，固定用現在分詞形容詞 (A) promising。promised candidates 語意不通。", "translation": "執行委員會正在尋找有前途的候選人，以拓展海外業務。"}, {"id": 3, "question": "The warranty certificate must be presented ________ receiving complimentary repair service.", "options": {"A": "prior to", "B": "although", "C": "in the event that", "D": "provided that"}, "answer": "A", "trap_point": "空格後為 receiving（動名詞 V-ing），沒有主詞動詞，只能選介系詞 prior to！", "analysis": "(B)、(C)、(D) 全為從屬連接詞，後面必須接完整的子句 S+V。只有 (A) prior to 為介系詞片語，後接 V-ing。", "translation": "在接受免費維修服務之前，必須出示保固證書。"}, {"id": 4, "question": "The research facility was evacuated ________ an unexpected chemical odor in the laboratory hallway.", "options": {"A": "owing to", "B": "because", "C": "as", "D": "since"}, "answer": "A", "trap_point": "空格後為名詞片語 'an unexpected chemical odor'，沒有動詞，秒選介系詞 owing to！", "analysis": "because, as, since 皆為從屬連接詞，後需接完整子句。只有 owing to 為介系詞片語，後接名詞受詞。", "translation": "由於實驗室走廊傳出意外的化學異味，該研究設施已被緊急疏散。"}, {"id": 5, "question": "The technician followed standard operating ________ to reboot the regional power network.", "options": {"A": "procedure", "B": "proceed", "C": "proceeding", "D": "procedural"}, "answer": "A", "trap_point": "operating procedure（作業程序/標準程序）為名詞受詞。proceed 是動詞！", "analysis": "standard operating procedure（SOP）為經典商務名詞片語。選名詞 (A) procedure。", "translation": "技術人員遵循標準作業程序重新啟動了區域電力網路。"}, {"id": 6, "question": "Our customer support team will ________ any concerns submitted through the feedback portal.", "options": {"A": "address", "B": "addressed", "C": "addressing", "D": "addresses"}, "answer": "A", "trap_point": "will + [原形動詞] + any concerns。address 作動詞指『處理/因應』。", "analysis": "助動詞 will 後接原形動詞 (A) address。address 作及物動詞表示因應或處理疑慮。", "translation": "我們的客戶支援團隊將處理透過意見回饋平台提交的任何疑慮。"}, {"id": 7, "question": "The company's cybersecurity infrastructure is ________ to sophisticated phishing attempts.", "options": {"A": "vulnerable", "B": "eligible", "C": "entitled", "D": "exempted"}, "answer": "A", "trap_point": "介系詞搭配：vulnerable to（易遭受…）；eligible 後接 for；exempted 後接 from！", "analysis": "看到空格後為介系詞 'to'，且受詞為網路釣魚攻擊（負面威脅），秒選 (A) vulnerable（脆弱/易受傷害的）。", "translation": "該公司的網路安全架構容易受到精密網路釣魚攻擊的威脅。"}, {"id": 8, "question": "The board reached a consensus to ________ the contract until patent litigation is resolved.", "options": {"A": "hold off on", "B": "step down", "C": "take over", "D": "back down"}, "answer": "A", "trap_point": "hold off on（暫緩/推遲）；step down 辭職；take over 接管。", "analysis": "句意表示董事會達成共識暫緩簽訂合約，直到專利訴訟解決。故選 (A) hold off on。", "translation": "董事會達成共識，在專利訴訟解決前暫緩該合約。"}, {"id": 9, "question": "Warehouse managers ordered all ________ electronics to be quarantined immediately for inspection.", "options": {"A": "damaged", "B": "damaging", "C": "damage", "D": "damages"}, "answer": "A", "trap_point": "electronics 是『被損壞的』，表被動完成狀態用過去分詞 damaged！", "analysis": "受損的電子產品，修飾名詞選過去分詞 (A) damaged。", "translation": "倉庫經理下令立即將所有受損的電子產品隔離檢驗。"}, {"id": 10, "question": "The human resources department is actively interviewing ________ applicants for the regional manager position.", "options": {"A": "promising", "B": "promised", "C": "promise", "D": "promisingly"}, "answer": "A", "trap_point": "人具有發展潛力，用現在分詞 promising（有前途的）；promised 是被承諾的！", "analysis": "修飾 applicants，表前途大有可為選 (A) promising。", "translation": "人資部門目前正積極面試大有可為的應徵者以選拔區域經理。"}, {"id": 11, "question": "The smartphone manufacturer issued a voluntary ________ affecting over thirty thousand units worldwide.", "options": {"A": "recall", "B": "recalled", "C": "recalling", "D": "recalls"}, "answer": "A", "trap_point": "issued a voluntary + [單數名詞]。recall 為動名同形字（召回令）。", "analysis": "選單數名詞 (A) recall（產品召回）。", "translation": "該智慧型手機製造商發布了一項影響全球三萬多台設備的自願召回令。"}, {"id": 12, "question": "Due to overwhelming demand during the flash sale, wireless earbuds are temporarily out of ________.", "options": {"A": "stock", "B": "stocked", "C": "stocking", "D": "stocks"}, "answer": "A", "trap_point": "out of stock（缺貨）為固定片語，stock 為不可數名詞！", "analysis": "out of stock 為商業最高頻片語，選 (A)。", "translation": "由於快閃特賣期間需求暴增，無線耳機目前暫時缺貨。"}, {"id": 13, "question": "The commercial building policy provides extensive ________ against fire and natural disasters.", "options": {"A": "coverage", "B": "cover", "C": "covering", "D": "covered"}, "answer": "A", "trap_point": "provides extensive + [名詞受詞] coverage（理賠保障範圍）。", "analysis": "insurance coverage 指保險涵蓋範圍，選名詞 (A)。", "translation": "該商業建築保單針對火災及自然災害提供了廣泛的理賠保障。"}, {"id": 14, "question": "Legacy server mainframes are extremely ________ to malware incursions unless updated weekly.", "options": {"A": "vulnerable", "B": "vulnerably", "C": "vulnerability", "D": "vulnerableness"}, "answer": "A", "trap_point": "be extremely [形容詞] vulnerable to sth.（易受…傷害的）。", "analysis": "are 為 be 動詞，副詞 extremely 修飾形容詞 (A) vulnerable。", "translation": "舊型大型伺服器主機除非每週更新，否則極易遭受惡意軟體入侵。"}], "part7": {"passages": [{"text_type": "Public Safety Recall Notice (產品安全召回公告)", "title": "Volta Electric Consumer Products — URGENT SAFETY RECALL: Model X-200 Blenders", "content": "CONSUMER PRODUCT SAFETY NOTICE\nISSUING BODY: Volta Electric Quality Assurance Bureau & National Consumer Commission\nRELEASE DATE: November 7, 2026\nPRODUCT LINE: Volta Chef Master High-Speed Blender (Model X-200)\n\n1. Reason for Voluntary Recall\nVolta Electric, in voluntary cooperation with consumer safety regulators, is recalling all Model X-200 high-speed blenders manufactured between March and September 2026. Internal laboratory diagnostics revealed that an internal wiring defect may cause the motor to overheat during extended usage, presenting a potential fire hazard. Consumers are urged to immediately discontinue using the appliance and unplug it from electrical outlets.\n\n2. Refund and Replacement Remedies\nConsumers are entitled to a full cash refund of $149 or a free replacement unit featuring our upgraded brushless motor. To receive a full refund or free replacement, customers must present the original purchase receipt or the serial barcode label affixed to the underside of the blender base.\n\n*Important Program Deadline: All recall claims accompanied by proper documentation must be processed before December 31, 2026. Claims filed after December 31 will be eligible only for store credit redeemable on Volta kitchen appliances. Prepaid shipping return boxes can be ordered at www.voltaelectric.com/recall.", "questions": [{"question": "Why is Volta Electric recalling Model X-200 blenders?", "options": {"A": "A wiring defect may cause the motor to overheat.", "B": "The glass blending pitcher easily shatters.", "C": "The packaging failed international export standards.", "D": "The device does not comply with voltage requirements."}, "answer": "A", "radar": "🔍 防漏看雷達：抓召回原因 'an electrical wiring defect may cause the motor appliance to overheat'！", "analysis": "第一段第二句指出：在重度使用情況下，電線缺陷可能導致馬達過熱並引發火災危險，故選 (A)。"}, {"question": "What is required to receive a full refund or free replacement?", "options": {"A": "Returning the purchase receipt or serial barcode label.", "B": "Bringing the unit to the original retail store in person.", "C": "Purchasing an extended three-year electrical warranty.", "D": "Filing a formal product liability complaint."}, "answer": "A", "radar": "🔍 防漏看雷達：退款必備條件 'provided that the original purchase receipt or serial barcode label is returned'！", "analysis": "星號小字說明補償條件：只要附上原始購買發票或序號條碼標籤寄回，即可獲全額退款或免費換機，故選 (A)。"}, {"question": "What happens if a recall claim is filed after December 31?", "options": {"A": "The customer is eligible only for store credit.", "B": "The claim will be completely rejected.", "C": "A 20% restocking fee will be deducted.", "D": "The replacement unit will take six months to arrive."}, "answer": "A", "radar": "🔍 防漏看雷達：時間截止陷阱 'Claims submitted after December 31 will be eligible only for store credit'！", "analysis": "文末最後一句明確提醒：12 月 31 日之後提出的申請，僅能兌換店內購物金，故選 (A)。"}]}, {"text_type": "Insurance Policy Certificate (商業保險條款手冊)", "title": "Alliance Commercial Underwriters — Property Loss & Casualty Coverage Terms", "content": "POLICY NUMBER: ACU-POL-88402\nUNDERWRITING ENTITY: Alliance Commercial Underwriters Group\nINSURED: Crestview Logistics Enterprises Inc.\nEFFECTIVE DATES: November 7, 2026 — November 6, 2027\n\nSection 3. Claims Filing Protocol & On-Site Inspection:\nIn the event of accidental water damage, fire loss, or catastrophic structural impairment to insured corporate facilities, policyholders must notify Alliance Claims Central within twelve hours of incident discovery. To expedite claim resolutions and assess mitigation efforts, a certified commercial insurance adjuster will visit damaged property within twenty-four hours of an incident report to perform structural photographic analysis and cost estimation.\n\nSection 5. Policy Exclusions & Specific Limitations:\nCoverage under this policy applies strictly to company-owned real estate, architectural fixtures, and commercial inventory. Personal electronic devices belonging to employees (including personal smartphones, tablets, and privately owned laptops) are explicitly excluded from coverage under all standard property schedules.\n\n*Deductible Waiver Rider: All standard claims are subject to a mandatory $1,000 baseline deductible. However, policyholders can waive the $1,000 standard deductible entirely by enrolling in the Executive Commercial Rider before the policy inception start date. Inquiries regarding supplemental riders should be directed to underwriters@alliance-ins.com.", "questions": [{"question": "How quickly will an insurance adjuster visit damaged property?", "options": {"A": "Within twenty-four hours of an incident.", "B": "Within three business days.", "C": "Immediately after repairs are completed.", "D": "At the conclusion of each billing quarter."}, "answer": "A", "radar": "🔍 防漏看雷達：服務時限 'a licensed adjuster will inspect the premises within twenty-four hours'！", "analysis": "第一段最後一句清楚載明：若發生重大財產受損，持證理算師將在 24 小時內到場檢驗，故選 (A)。"}, {"question": "What is explicitly EXCLUDED from coverage under this policy?", "options": {"A": "Personal electronic devices belonging to employees.", "B": "Specialized industrial manufacturing machinery.", "C": "Warehouse inventory damaged by storms.", "D": "Corporate real estate affected by pipe leaks."}, "answer": "A", "radar": "🔍 防漏看雷達：除外條款細節 'Coverage does not extend to personal electronic devices owned by individual employees'！", "analysis": "星號小字除外條款指出：保險範圍不包含個別員工擁有的個人電子設備，故選 (A)。"}, {"question": "How can a policyholder waive the $1,000 standard deductible?", "options": {"A": "By enrolling in the Executive Rider before policy start date.", "B": "By filing their claim online instead of by telephone.", "C": "By paying annual premiums in one lump-sum cash transfer.", "D": "By maintaining no claims for three consecutive years."}, "answer": "A", "radar": "🔍 防漏看雷達：免自負額豁免條件 'unless the policyholder has opted into the Zero-Deductible Executive Rider prior to the policy start date'！", "analysis": "最後一句說明：標準自負額 1000 美元，除非保戶在保單生效日前已選擇加入零自負額主管附加險，故選 (A)。"}]}]}}}, "5": {"day": 5, "date": "11/08", "phase": 1, "phase_name": "錯題庫清零與語感校正", "topic": "減化子句與分詞構句 (while + V-ing) ｜ 政策規範與熟練搭配", "morning": {"chunks": [{"chunk": "proficient in Mandarin", "meaning": "精通中文", "scenario": "Candidates proficient in Mandarin and English are preferred for the regional role.", "paraphrase": "proficient in = skilled in = fluent in", "alert": "必考介系詞：proficient 後方固定搭配 in！"}, {"chunk": "accustomed to changes", "meaning": "習慣於各種變動", "scenario": "Staff members quickly became accustomed to changes in remote work guidelines.", "paraphrase": "accustomed to = used to", "alert": "注意：be accustomed to 後方的 to 是介系詞，接名詞或 V-ing！"}, {"chunk": "resistant to heat", "meaning": "耐熱的 / 抗熱的", "scenario": "The new kitchen apron is made of synthetic fibers highly resistant to heat.", "paraphrase": "resistant to = impervious to", "alert": "介系詞搭配：resistant 固定接 to！"}, {"chunk": "vulnerable to attacks", "meaning": "易遭受攻擊", "scenario": "Unpatched database servers are vulnerable to cyber attacks.", "paraphrase": "vulnerable to = susceptible to = exposed to", "alert": "介系詞搭配：vulnerable 固定接 to！"}, {"chunk": "pertinent to the case", "meaning": "與本案直接相關", "scenario": "Please disclose all files pertinent to the ongoing patent dispute.", "paraphrase": "pertinent to = relevant to = related to", "alert": "介系詞搭配：pertinent 固定接 to！"}, {"chunk": "government mandate", "meaning": "政府的強制命令", "scenario": "The factory complied strictly with the government mandate on emission limits.", "paraphrase": "mandate = directive = order = regulation", "alert": "多義字：mandate 可作名詞（授權/指令）亦可作動詞（強制規定）。"}, {"chunk": "a deliberate attempt", "meaning": "一項蓄意/深思熟慮的企圖", "scenario": "The firm made a deliberate attempt to capture market share in rural regions.", "paraphrase": "deliberate = intentional = calculated", "alert": "多義字：deliberate (adj.) 蓄意的/審慎的；(v.) 仔細考慮/研議。"}], "visual_anchor": {"title": "看到 while / when / once 後面直接接分詞？", "rule_1": "👀 主詞主動做動作 ➔ while + V-ing（while reviewing the file, she found a typo）", "rule_2": "👀 主詞被動被處理 ➔ once / when + V-ed（once approved, the budget will be released）", "golden_rule": "⚡ 教練金句：看到 while 接空格帶受詞，90% 秒選 -ing！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "While ________ the quarterly budget proposal, the finance director discovered an unexpected accounting discrepancy.", "options": {"A": "reviewing", "B": "reviewed", "C": "reviews", "D": "review"}, "answer": "A", "analysis": "分詞構句秒殺：While 後省略主詞 the finance director，動作主體為主動審核預算，故選主動現在分詞 (A) reviewing。(B) reviewed 為被動過去分詞，語法不符。", "translation": "在審查季度預算提案時，財務總監發現了一筆意想不到的會計帳目差異。"}, {"id": 2, "target_seconds": 15, "question": "Candidates applying for the senior analyst role must be highly ________ in database management tools.", "options": {"A": "proficient", "B": "proficiency", "C": "proficiently", "D": "profit"}, "answer": "A", "analysis": "介系詞搭配秒殺：be proficient in sth.（精通某事物）。must be 為 be 動詞結構，副詞 highly 修飾形容詞 (A) proficient。(B) proficiency 為名詞；(C) 為副詞。", "translation": "應徵資深分析師職位的候選人，必須高度精通資料庫管理工具。"}, {"id": 3, "target_seconds": 15, "question": "The software development team is ________ to working under strict deadlines during product sprints.", "options": {"A": "accustomed", "B": "accustom", "C": "accustoming", "D": "accustoms"}, "answer": "A", "analysis": "固定片語秒殺：be accustomed to + V-ing / N（習慣於……）。to 為介系詞，後接 working。(A) accustomed 為過去分詞轉化之形容詞。", "translation": "軟體開發團隊在產品衝刺期間已習慣在嚴格的截止期限下工作。"}, {"id": 4, "target_seconds": 15, "question": "The newly formulated composite coating is remarkably ________ to corrosion and extreme temperatures.", "options": {"A": "resistant", "B": "resistance", "C": "resist", "D": "resistantly"}, "answer": "A", "analysis": "介系詞搭配秒殺：be resistant to sth.（對……具有抵抗力的 / 耐……的）。is 為 be 動詞，remarkably 為副詞修飾形容詞 (A) resistant。(B) 為名詞；(C) 為動詞。", "translation": "新配方複合塗層對腐蝕與極端溫度具有顯著的耐受性。"}, {"id": 5, "target_seconds": 15, "question": "The legal advisor requested all documentation ________ to the ongoing merger negotiations.", "options": {"A": "pertinent", "B": "pertinently", "C": "pertinence", "D": "pertain"}, "answer": "A", "analysis": "形容詞後置修飾：documentation [pertinent to sth.]（與某事切身相關的文件）。pertinent 固定搭配介系詞 to。(B) 為副詞；(C) 為名詞；(D) pertain 為動詞。", "translation": "法律顧問要求提供所有與當前合併談判切身相關的文件。"}, {"id": 6, "target_seconds": 20, "question": "Before entering the production facility, all visitors must ________ a rigorous security screening.", "options": {"A": "undergo", "B": "undergone", "C": "undergoing", "D": "undergoes"}, "answer": "A", "analysis": "助動詞後接原形動詞：must + [原形動詞] + a screening (受詞)。undergo a screening/inspection 指『接受審查/檢驗』。(B) 為過去分詞；(C) 為現在分詞。", "translation": "在進入生產設施之前，所有訪客必須接受嚴格的安全審查。"}, {"id": 7, "target_seconds": 15, "question": "The municipal safety council will ________ employee training in fire evacuation procedures twice a year.", "options": {"A": "mandate", "B": "mandatorily", "C": "mandatory", "D": "mandated"}, "answer": "A", "analysis": "助動詞後接及物動詞：will + [原形動詞] + training (名詞受詞)。mandate 可作動詞表示『強制規定 / 要求』。(C) mandatory 為形容詞；(B) 為副詞。", "translation": "市政安全委員會將強制規定每年進行兩次員工火災疏散培訓。"}, {"id": 8, "target_seconds": 15, "question": "The tenant was legally required to ________ the commercial property before midnight on June 30.", "options": {"A": "vacate", "B": "vacation", "C": "vacant", "D": "vacated"}, "answer": "A", "analysis": "不定詞動詞：required to + [原形動詞] + the commercial property (受詞)。vacate 指『騰出/搬離』空間。(B) 為假期；(C) vacant 為形容詞空置的。", "translation": "承租人在法律上被要求於 6 月 30 日午夜前騰空並搬離該商業不動產。"}, {"id": 9, "target_seconds": 15, "question": "Please ensure that you present a ________ government-issued passport at the airport customs counter.", "options": {"A": "valid", "B": "validate", "C": "validation", "D": "validity"}, "answer": "A", "analysis": "形容詞修飾名詞：a + [形容詞] + government-issued passport。valid 指『有效的 / 合法的』。(B) 為動詞驗證；(C)、(D) 為名詞。", "translation": "請確保在機場海關櫃台出示有效的政府核發護照。"}, {"id": 10, "target_seconds": 15, "question": "The catering service offers ________ dining options to accommodate attendees with specific dietary restrictions.", "options": {"A": "various", "B": "variously", "C": "variety", "D": "variable"}, "answer": "A", "analysis": "限定修飾名詞：[形容詞] + dining options。various 指『各種各樣的』。(B) 為副詞；(C) a variety of 需搭配 of；(D) variable 為可變動的。", "translation": "外燴服務提供多樣化的餐飲選擇，以迎合有特殊飲食限制的與會者。"}, {"id": 11, "target_seconds": 20, "question": "The procurement team selected an approved external ________ to supply high-grade aluminum sheets.", "options": {"A": "vendor", "B": "vending", "C": "vends", "D": "vended"}, "answer": "A", "analysis": "名詞受詞：selected an approved external + [單數名詞]。vendor 指『供應商/廠商』。(B) 為動名詞；(C) 為動詞單數現在式。", "translation": "採購團隊挑選了一家核准的外部供應商，以供應高等級的鋁板。"}, {"id": 12, "target_seconds": 15, "question": "Conference participants are politely requested to refrain ________ taking flash photography during the keynote.", "options": {"A": "from", "B": "to", "C": "with", "D": "at"}, "answer": "A", "analysis": "介系詞搭配秒殺：refrain from + V-ing（克制/避免做某事）。refrain 固定搭配介系詞 from。(B)、(C)、(D) 皆不可與 refrain 搭配。", "translation": "懇請與會嘉賓在專題演講進行期間克制不要使用閃光燈拍照。"}, {"id": 13, "target_seconds": 15, "question": "All laboratory scientists must adhere strictly ________ environmental safety regulations at all times.", "options": {"A": "to", "B": "for", "C": "in", "D": "by"}, "answer": "A", "analysis": "介系詞搭配秒殺：adhere strictly to sth.（嚴格遵守某法規）。adhere 固定搭配 to。abide 才是搭配 by！", "translation": "所有實驗室科學家必須隨時嚴格遵守環境安全法規。"}, {"id": 14, "target_seconds": 15, "question": "Before ________ the final architectural blueprint, the head designer requested a peer review.", "options": {"A": "submitting", "B": "submit", "C": "submitted", "D": "submits"}, "answer": "A", "analysis": "介系詞/分詞省略結構：Before + [V-ing] + 受詞。主詞 the head designer 主動提交藍圖，故選動名詞 (A) submitting。", "translation": "在提交最終建築藍圖之前，首席設計師要求進行同儕審查。"}, {"id": 15, "target_seconds": 15, "question": "Unless ________ instructed by the chief physician, patients should continue taking their prescribed medication.", "options": {"A": "otherwise", "B": "other", "C": "another", "D": "others"}, "answer": "A", "analysis": "副詞修飾分詞：unless otherwise instructed 指『除非另有指示』，為商務與多益絕對必考慣用語塊！(B)、(C)、(D) 皆為代名詞/形容詞，無法修飾分詞 instructed。", "translation": "除非主治醫師另有指示，否則病患應繼續服用其處方藥物。"}, {"id": 16, "target_seconds": 20, "question": "Upon ________ at the convention hotel, please collect your badge at the hospitality registration desk.", "options": {"A": "arriving", "B": "arrived", "C": "arrival", "D": "arrive"}, "answer": "A", "analysis": "介系詞後接 V-ing：Upon arriving at... 指『一抵達……就……』。arrival 雖為名詞但不及物通常需加介系詞短語修飾，此處接地點介系詞片語 'at the convention hotel'，用動名詞 (A) arriving 最標準且流暢。", "translation": "一抵達會議飯店，請至接待報到處領取您的名牌。"}, {"id": 17, "target_seconds": 15, "question": "Once ________ by the executive committee, the revised marketing strategy will take effect immediately.", "options": {"A": "approved", "B": "approving", "C": "approves", "D": "approval"}, "answer": "A", "analysis": "減化子句秒殺：Once [it is] approved... 行銷策略是『被批准』，被動減化子句選過去分詞 (A) approved。(D) approval 為名詞。", "translation": "一旦獲得執行委員會批准，修改後的行銷策略將立即生效。"}, {"id": 18, "target_seconds": 15, "question": "Full-time employees who enroll in evening graduate courses are eligible ________ tuition assistance.", "options": {"A": "for", "B": "to", "C": "with", "D": "from"}, "answer": "A", "analysis": "介系詞搭配秒殺：be eligible for + 名詞（符合領取……的資格）。tuition assistance 為名詞受詞，秒選 (A) for。", "translation": "報名夜間研究所課程的全職員工，符合申請學費補助的資格。"}, {"id": 19, "target_seconds": 20, "question": "The manufacturing company made a ________ attempt to lower carbon emissions across all its supply lines.", "options": {"A": "deliberate", "B": "deliberately", "C": "deliberation", "D": "deliberating"}, "answer": "A", "analysis": "形容詞修飾名詞：a + [形容詞] + attempt。deliberate attempt 指『深思熟慮且刻意的嘗試』。(A) deliberate 為形容詞。(B) 為副詞；(C) 為名詞。", "translation": "該製造公司做出了深思熟慮的努力，以降低其所有供應鏈的碳排放量。"}, {"id": 20, "target_seconds": 15, "question": "The technical report was revised several times to make the operating guidelines ________ understood by new recruits.", "options": {"A": "easily", "B": "ease", "C": "easier", "D": "easiness"}, "answer": "A", "analysis": "副詞修飾過去分詞：副詞 (A) easily 修飾過去分詞形容詞 understood。(B) ease 為名詞/動詞；(C) easier 為比較級形容詞。", "translation": "該技術報告經過數次修改，以便新進員工能輕易理解操作指南。"}]}, "afternoon": {"quick_recall": [{"prompt": "While ________ [分詞，審核] the report, she found a typo.", "clue": "While + 主動 V-ing", "answer": "reviewing"}, {"prompt": "She is proficient ________ [介系詞] data analysis.", "clue": "精通某領域（proficient 固定搭配）", "answer": "in"}, {"prompt": "We are accustomed ________ [介系詞] tight deadlines.", "clue": "習慣於某事（accustomed 固定搭配）", "answer": "to"}, {"prompt": "The material is resistant ________ [介系詞] water and heat.", "clue": "耐……受性的（resistant 固定搭配）", "answer": "to"}, {"prompt": "Please refrain ________ [介系詞] smoking in the lobby.", "clue": "克制/避免做某事（refrain 固定搭配）", "answer": "from"}, {"prompt": "Adhere strictly ________ [介系詞] safety rules.", "clue": "嚴格遵守（adhere 固定搭配）", "answer": "to"}], "spaced_traps": [{"id": 1, "question": "While ________ the laboratory facilities, inspectors noted two minor safety violations.", "options": {"A": "touring", "B": "toured", "C": "tours", "D": "tour"}, "answer": "A", "trap_point": "減化子句：主詞是稽查員 (inspectors)，主動參觀實驗室，選主動現在分詞 touring；被動 toured 邏輯不通！", "analysis": "While 後省略主詞與 be 動詞，動作主體 inspectors 是主動參觀設施，故選 (A) touring。", "translation": "在巡視實驗室設施時，稽核員注意到了兩項微小的安全違規情事。"}, {"id": 2, "question": "Unless ________ stated in the warranty contract, shipping fees are the responsibility of the purchaser.", "options": {"A": "otherwise", "B": "other", "C": "another", "D": "others"}, "answer": "A", "trap_point": "固定必考語塊：unless otherwise stated/noted/specified（除非另有說明）。", "analysis": "otherwise 為副詞，用來修飾過去分詞 stated。意為『除非另有說明』。這是多益金色證書秒殺送分題，選 (A)。", "translation": "除非保固合約中另有說明，否則運費均由買方自行負擔。"}, {"id": 3, "question": "Candidates must be fluent in English and proficient ________ statistical modeling.", "options": {"A": "in", "B": "at", "C": "for", "D": "with"}, "answer": "A", "trap_point": "proficient 固定搭配 in（精通某專業科目）；good 才接 at！", "analysis": "看到 proficient，立刻聯想介系詞 in。故選 (A)。", "translation": "候選人必須英語流利，並精通統計建模。"}, {"id": 4, "question": "The executive committee decided to ________ the regional marketing launch until supply chain bottlenecks clear.", "options": {"A": "put off", "B": "step down", "C": "take over", "D": "back down"}, "answer": "A", "trap_point": "put off = delay / postpone（延期推遲）。step down 辭職；take over 接管。", "analysis": "依據句意，委員會決定推遲行銷活動直到供應鏈瓶頸消除。故選 (A) put off。", "translation": "執行委員會決定將區域行銷發表推遲，直到供應鏈瓶頸解除。"}, {"id": 5, "question": "All visitors must present proper identification ________ to being admitted into the high-security server room.", "options": {"A": "prior", "B": "previous", "C": "beforehand", "D": "ahead"}, "answer": "A", "trap_point": "prior to + V-ing（在…之前）。ahead 須搭配 of！", "analysis": "空格後接 'to being admitted'，只有 prior to 能構成介系詞片語。故選 (A)。", "translation": "所有訪客在獲准進入高安全等級伺服器機房前，必須出示有效身分證件。"}, {"id": 6, "question": "The contractor was penalized for failing to adhere strictly ________ building code specifications.", "options": {"A": "to", "B": "with", "C": "by", "D": "for"}, "answer": "A", "trap_point": "adhere strictly to（嚴格遵守）。注意 abide 才接 by！", "analysis": "adhere 必須固定搭配介系詞 to，秒殺選 (A)。", "translation": "該承包商因未能嚴格遵守建築法規規範而遭到懲處。"}, {"id": 7, "question": "The research article provided ________ evidence substantiating the environmental advantages of solar roofing.", "options": {"A": "conclusive", "B": "conclude", "C": "conclusion", "D": "conclusively"}, "answer": "A", "trap_point": "conclusive evidence（決定性的/確鑿的證據）。修飾名詞 evidence 需用形容詞！", "analysis": "provided (動詞) + [形容詞] + evidence (名詞)。conclusive（決定性的/令人信服的）為形容詞，選 (A)。", "translation": "該研究論文提供了確鑿的證據，證實了太陽能屋頂的環境優勢。"}, {"id": 8, "question": "The tenant promised to ________ the apartment by 5:00 P.M. on the final day of the lease.", "options": {"A": "vacate", "B": "vacation", "C": "vacant", "D": "vacating"}, "answer": "A", "trap_point": "to 後接原形動詞 vacate（騰空撤出）。vacant 是形容詞！", "analysis": "promised to + [原形動詞] + the apartment (受詞)。選及物動詞 (A) vacate。", "translation": "房客承諾在租約最後一天的下午 5 點前騰空公寓並遷出。"}, {"id": 9, "question": "While ________ the warehouse inventory, the logistics clerk discovered several misplaced crates.", "options": {"A": "auditing", "B": "audited", "C": "audits", "D": "audit"}, "answer": "A", "trap_point": "While 後省略主詞，動作主體 the clerk 主動審查庫存，選現在分詞 auditing！", "analysis": "主動分詞構句選 (A) auditing。", "translation": "在清點倉庫庫存時，物流職員發現了數個放錯位置的貨箱。"}, {"id": 10, "question": "Candidates applying for the bioinformatics post must be highly ________ in Python and R programming.", "options": {"A": "proficient", "B": "proficiency", "C": "proficiently", "D": "profit"}, "answer": "A", "trap_point": "be highly [形容詞] proficient in sth.（精通…）。", "analysis": "must be 後接形容詞，proficient 固定搭配 in，選 (A)。", "translation": "應聘生物資訊職位的候選人必須高度精通 Python 與 R 程式語言。"}, {"id": 11, "question": "The production team is ________ to working double shifts during annual product rollouts.", "options": {"A": "accustomed", "B": "accustom", "C": "accustoming", "D": "accustoms"}, "answer": "A", "trap_point": "be accustomed to + V-ing（習慣於…）。to 為介系詞！", "analysis": "選轉化為形容詞之過去分詞 (A) accustomed。", "translation": "生產團隊已習慣在年度產品發布期間輪值雙班。"}, {"id": 12, "question": "The newly engineered ceramic tile is exceptionally ________ to thermal shock and moisture.", "options": {"A": "resistant", "B": "resistance", "C": "resist", "D": "resistantly"}, "answer": "A", "trap_point": "be exceptionally [形容詞] resistant to sth.（耐…的）。", "analysis": "選形容詞 (A) resistant，固定搭配 to。", "translation": "這款新研發的陶瓷磚對熱震與濕氣具有極佳的耐受力。"}, {"id": 13, "question": "Unless ________ stated in the purchase contract, all shipping fees are non-refundable.", "options": {"A": "otherwise", "B": "other", "C": "another", "D": "others"}, "answer": "A", "trap_point": "unless otherwise stated（除非另有說明）。副詞修飾過去分詞！", "analysis": "商務黃金搭配 unless otherwise stated，選副詞 (A)。", "translation": "除非採購合約中另有說明，否則所有運費概不退還。"}, {"id": 14, "question": "Conference participants are asked to refrain ________ recording audio during executive keynote presentations.", "options": {"A": "from", "B": "to", "C": "with", "D": "at"}, "answer": "A", "trap_point": "refrain from + V-ing（克制/避免做某事）。", "analysis": "refrain 永遠搭配 from，選 (A)。", "translation": "與會者受請在主管專題演講期間克制切勿進行錄音。"}], "part7": {"passages": [{"text_type": "Chemical Safety Bulletin (化學安全作業規範)", "title": "Zenith Chemicals — Standard Protocols for Chemical Handling & Protective Gear", "content": "SAFETY COMPLIANCE CIRCULAR: ZC-HSE-2026-05\nISSUED BY: Environmental Health & Safety Division, Zenith Chemicals Inc.\nEFFECTIVE DATE: November 8, 2026\nMANDATORY FOR: All Laboratory Technicians, Production Chemists, and Plant Supervisors\n\n1. Mandatory Personal Protective Equipment (PPE)\nZenith Chemicals maintains uncompromising zero-tolerance safety standards regarding hazardous workplace chemical exposure. When handling volatile organic solvents, corrosive acids, or pressurized catalysts in Synthesis Hall B, laboratory personnel are required to wear chemical-resistant aprons and eye goggles at all times. Standard cotton lab coats and prescription spectacles do not meet safety compliance specifications and are strictly prohibited in active chemical handling zones.\n\n2. Emergency Decontamination Stations & Eyewashes\nIn accordance with international occupational safety regulations and chemical hazard containment directives, emergency wash stations and high-flow eyewash units are situated in every corridor throughout the chemical processing facility. These life-safety stations undergo automated pressure testing every Monday morning by facility engineers.\n\n*Accidental Exposure Protocol: In the event of skin contact or chemical spillage, affected staff must vacate the contaminated area immediately and rinse the exposed body part for a minimum of fifteen minutes, unless medically advised otherwise by emergency health responders. Unreported exposure incidents will result in formal disciplinary review.", "questions": [{"question": "What equipment is required when handling volatile solvents?", "options": {"A": "Chemical-resistant aprons and eye goggles.", "B": "Steel-toed boots and heavy leather gloves.", "C": "Disposable plastic coats and noise-canceling headsets.", "D": "Thermal protective suits and insulated masks."}, "answer": "A", "radar": "🔍 防漏看雷達：配備要求 'mandated to wear certified chemical-resistant aprons and eye goggles'！", "analysis": "第一段最後一句明確規定：處理揮發性溶劑時，必須隨時穿戴認證的防化學圍裙與護目鏡，故選 (A)。"}, {"question": "Where are emergency wash stations situated?", "options": {"A": "In every corridor.", "B": "Exclusively inside Cleanroom 2.", "C": "Next to the main reception entrance.", "D": "In the chemical storage basement."}, "answer": "A", "radar": "🔍 防漏看雷達：地點細節 'located in every corridor'！", "analysis": "星號小字說明：緊急清洗站設置在『每一條走廊（in every corridor）』，故選 (A)。"}, {"question": "What must affected staff do unless medically advised otherwise?", "options": {"A": "Vacate the contaminated area immediately.", "B": "Neutralize the spilled solvent with water.", "C": "Contact external news agencies.", "D": "Shut down all central server electrical feeds."}, "answer": "A", "radar": "🔍 防漏看雷達：除外條款 'Unless otherwise instructed by on-site medical officers, all affected individuals must vacate the area immediately'！", "analysis": "文末明確指出：除非現場醫護人員另有指示，否則所有受影響人員必須立即撤離該區域，故選 (A)。"}]}, {"text_type": "Human Resources Policy Notice (人力資源進修補助通知)", "title": "Corporate Workforce Directorate — Employee Professional Development & Tuition Subsidy", "content": "POLICY BULLETIN: HR-DEV-2026-14\nTO: All Full-Time Personnel Across Regional Operating Divisions\nFROM: Workforce Development Committee & Chief People Officer\nDATE: November 8, 2026\nSUBJECT: 2027 Academic Year Continuing Education & Professional Certification Grant\n\n1. Annual Grant Allocation & Approved Programs\nSummit Corporation is proud to foster continuous intellectual and vocational advancement across our global business teams. Under the updated Continuing Education Program, the maximum annual education subsidy per eligible employee is $3,000 per academic calendar year. Approved courses include accredited university degree modules, data science bootcamps, and professional project management certifications relevant to the employee's corporate function.\n\n2. Grade Thresholds & Reimbursement Verification\nTo receive reimbursement, applicants must complete their courses with a grade of 'B' or higher (or equivalent 'Pass' in pass/fail certification exams). Official transcripts and bursar payment receipts must be transmitted to Human Resources within 30 days of course completion.\n\n*Grant Repayment Covenant: In return for corporate educational sponsorship, recipients agree to a retention commitment. If an employee voluntarily resigns within twelve months of receiving funds, they must repay the educational grant in full via deduction from their final severance or compensation settlement.", "questions": [{"question": "What is the maximum annual education subsidy per eligible employee?", "options": {"A": "$3,000.", "B": "$1,000.", "C": "$5,000.", "D": "$7,500."}, "answer": "A", "radar": "🔍 防漏看雷達：金額上限 'entitled to up to $3,000 annually'！", "analysis": "第一段第二句明確說明補助上限為每年最高 3,000 美元，故選 (A)。"}, {"question": "What minimum academic grade is required to receive reimbursement?", "options": {"A": "A grade of 'B' or higher.", "B": "A passing grade of 'C' or above.", "C": "Perfect attendance with no grade requirement.", "D": "An overall grade point average above 3.8."}, "answer": "A", "radar": "🔍 防漏看雷達：學業成績門檻 'demonstrating a grade of B or higher'！", "analysis": "星號小字第二句指出：報銷款項僅在收到正式成績單且成績為 B 或以上時才會撥付，故選 (A)。"}, {"question": "Under what circumstance must an employee repay the educational grant?", "options": {"A": "If they voluntarily resign within twelve months of receiving funds.", "B": "Whenever their annual department sales quota is missed.", "C": "If they enroll in an online distance-learning program.", "D": "In the event that the company changes ownership."}, "answer": "A", "radar": "🔍 防漏看雷達：返還條款 'Employees who voluntarily resign within twelve months of receiving reimbursement are required to repay the grant in full'！", "analysis": "最後一句強調：領取補助款後 12 個月內自願離職者，必須全額返還該筆補助金，故選 (A)。"}]}]}}}, "6": {"day": 6, "date": "11/09", "phase": 1, "phase_name": "錯題庫清零與語感校正", "topic": "詞性秒殺 (will + adv. + V) ｜ 職務交接與承擔", "morning": {"chunks": [{"chunk": "in charge of logistics", "meaning": "負責物流營運", "scenario": "Mr. Chen was placed in charge of logistics for the Asia-Pacific territory.", "paraphrase": "in charge of = responsible for = overseeing", "alert": ""}, {"chunk": "on behalf of the committee", "meaning": "代表委員會全體", "scenario": "The spokesperson spoke on behalf of the committee during the press briefing.", "paraphrase": "on behalf of = representing", "alert": ""}, {"chunk": "in addition to bonuses", "meaning": "除績效獎金之外（還有）", "scenario": "In addition to bonuses, employees receive subsidized commuting passes.", "paraphrase": "in addition to = besides = as well as", "alert": "視覺錨點：in addition to 後接名詞 / V-ing，表『除了…還有…』！"}, {"chunk": "step down from the board", "meaning": "辭去董事會職位", "scenario": "The founder announced plans to step down from the board next spring.", "paraphrase": "step down = resign = retire from", "alert": ""}, {"chunk": "take over the department", "meaning": "接管該部門業務", "scenario": "A veteran manager will take over the department following the restructuring.", "paraphrase": "take over = assume control of", "alert": ""}, {"chunk": "hold off on hiring", "meaning": "暫緩招聘新進人員", "scenario": "Management decided to hold off on hiring until third-quarter forecasts improve.", "paraphrase": "hold off on = delay = defer = postpone", "alert": ""}, {"chunk": "put off the negotiation", "meaning": "推遲雙邊談判會議", "scenario": "Both parties agreed to put off the negotiation until legal reviews are complete.", "paraphrase": "put off = postpone = defer", "alert": ""}], "visual_anchor": {"title": "助動詞與動詞中間的「夾心餅乾」位置？", "rule_1": "👀 看到 will ________ [動詞原形] ➔ 夾心位置 100% 填入「副詞 (-ly)」！", "rule_2": "👀 同樣適用：has/have ________ [V-en]、be ________ [V-ed / V-ing] ➔ 通通塞副詞！", "golden_rule": "⚡ 教練金句：看到動詞前後有破洞，抓 -ly 副詞填補！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "The board announced that Dr. Vance will ________ step down from his post as chief scientific officer.", "options": {"A": "official", "B": "officially", "C": "officials", "D": "officiate"}, "answer": "B", "analysis": "助動詞夾心秒殺：will + [副詞 -ly] + step down (原形動詞片語)。副詞修飾動詞片語，秒選 (B) officially。(A) 為形容詞；(C) 為名詞複數；(D) 為動詞。", "translation": "董事會宣布 Vance 博士將正式辭去其首席科學官一職。"}, {"id": 2, "target_seconds": 15, "question": "Following the merger, the international consortium will ________ take over regional logistics operations.", "options": {"A": "eventually", "B": "eventual", "C": "eventuality", "D": "events"}, "answer": "A", "analysis": "助動詞夾心秒殺：will + [副詞 -ly] + take over (原形動詞片語)。秒選副詞 (A) eventually（最終地/終究）。(B) 為形容詞；(C) 為名詞。", "translation": "在合併之後，該國際財團最終將接管區域物流業務。"}, {"id": 3, "target_seconds": 15, "question": "Due to unexpected supply chain disruptions, the manufacturer decided to ________ on constructing the new facility.", "options": {"A": "hold off", "B": "step down", "C": "take over", "D": "back down"}, "answer": "A", "analysis": "動詞片語搭配秒殺：hold off on sth. / V-ing（推遲/暫緩某事）。(B) step down 為辭職；(C) take over 為接管；(D) back down 為退縮讓步。", "translation": "由於未預見的供應鏈中斷，製造商決定暫緩興建新設施。"}, {"id": 4, "target_seconds": 15, "question": "The executive committee voted to ________ the annual shareholders' meeting until financial audits are finalized.", "options": {"A": "put off", "B": "take over", "C": "step down", "D": "refrain from"}, "answer": "A", "analysis": "動詞片語語意秒殺：put off = postpone = delay（推遲/延期）。put off the meeting 指推遲會議。故選 (A)。", "translation": "執行委員會投票決定推遲年度股東大會，直到財務稽核完成。"}, {"id": 5, "target_seconds": 15, "question": "Labor representatives refused to ________ from their demand for higher hazard compensation.", "options": {"A": "back down", "B": "step down", "C": "take over", "D": "hold off"}, "answer": "A", "analysis": "動詞片語搭配：back down from sth. 指『從……中讓步/退縮』。句意表示勞方代表拒絕從其提高危險津貼的要求中讓步，選 (A)。", "translation": "勞方代表拒絕就提高危險津貼的訴求做出讓步。"}, {"id": 6, "target_seconds": 20, "question": "The newly installed robotic sorting system will ________ enhance factory processing speeds.", "options": {"A": "substantially", "B": "substantial", "C": "substantiate", "D": "substantiality"}, "answer": "A", "analysis": "助動詞夾心秒殺：will + [副詞 -ly] + enhance (動詞原形)。substantially 表『大幅度地/顯著地』，修飾動詞 enhance。故選 (A)。", "translation": "新安裝的機器人分揀系統將顯著提升工廠的處理速度。"}, {"id": 7, "target_seconds": 15, "question": "Overhead expenditures decreased ________ after all departments transitioned to digital document archives.", "options": {"A": "drastically", "B": "drastic", "C": "drasticness", "D": "drasticize"}, "answer": "A", "analysis": "副詞修飾不及物動詞：decreased (動詞) + [副詞]。drastically（急劇地/大幅度地）修飾 decreased。故選 (A)。", "translation": "在所有部門轉向數位文件歸檔後，經常性開支大幅度下降。"}, {"id": 8, "target_seconds": 15, "question": "The public relations department ________ handled client concerns during the product recall crisis.", "options": {"A": "capably", "B": "capable", "C": "capability", "D": "capacities"}, "answer": "A", "analysis": "副詞修飾動詞：[副詞] + handled (過去式及物動詞)。capably 指『能幹地 / 幹練地』修飾 handled。故選 (A)。", "translation": "公關部門在產品召回危機期間幹練妥善地處理了客戶的疑慮。"}, {"id": 9, "target_seconds": 15, "question": "Ms. Gomez has ________ proven herself to be an indispensable asset to the international trade division.", "options": {"A": "consistently", "B": "consistent", "C": "consistency", "D": "consist"}, "answer": "A", "analysis": "完成式夾心秒殺：has + [副詞 -ly] + proven (p.p.)。consistently 表『一貫地/始終如一地』。故選 (A)。", "translation": "Gomez 女士始終證明自己是國際貿易部門不可或缺的得力資產。"}, {"id": 10, "target_seconds": 15, "question": "The technical helpline is ________ recommended by prominent consumer electronics review blogs.", "options": {"A": "highly", "B": "high", "C": "height", "D": "heighten"}, "answer": "A", "analysis": "被動態夾心秒殺：is + [副詞 -ly] + recommended (p.p.)。highly recommended（極力推薦）為商務最高頻片語。故選 (A)。", "translation": "該技術諮詢專線受到各大知名消費電子評論部落格的極力推薦。"}, {"id": 11, "target_seconds": 20, "question": "Contract negotiations were ________ delayed due to disagreements over intellectual property rights.", "options": {"A": "temporarily", "B": "temporary", "C": "temporariness", "D": "temporal"}, "answer": "A", "analysis": "被動態夾心秒殺：were + [副詞 -ly] + delayed (p.p.)。temporarily delayed 指『暫時受阻/被延誤』。故選 (A)。", "translation": "由於對智慧財產權的爭議，合約談判暫時遭到延誤。"}, {"id": 12, "target_seconds": 15, "question": "Management announced that bonuses would be distributed ________ among all administrative branches.", "options": {"A": "equitably", "B": "equitable", "C": "equity", "D": "equitableness"}, "answer": "A", "analysis": "被動態副詞修飾：distributed (p.p.) + [副詞 -ly]。equitably 表『公平公正地』。故選 (A)。", "translation": "管理層宣布獎金將公平地分配給所有行政分部。"}, {"id": 13, "target_seconds": 15, "question": "The municipal council ________ approved the zoning permit for the commercial shopping plaza.", "options": {"A": "unanimously", "B": "unanimous", "C": "unanimity", "D": "unanimousness"}, "answer": "A", "analysis": "副詞修飾及物動詞：[副詞 -ly] + approved (動詞)。unanimously approved 指『全體一致無異議通過』。故選 (A)。", "translation": "市政委員會全體一致通過了該商業購物廣場的分區建築許可。"}, {"id": 14, "target_seconds": 15, "question": "The chief financial officer will ________ outline the fourth-quarter revenue projections at tomorrow's briefing.", "options": {"A": "briefly", "B": "brief", "C": "brevity", "D": "briefing"}, "answer": "A", "analysis": "助動詞夾心秒殺：will + [副詞 -ly] + outline (原形動詞)。briefly（簡要地）修飾動詞 outline。故選 (A)。", "translation": "財務長將在明天的簡報會上簡要概述第四季度的營收預測。"}, {"id": 15, "target_seconds": 20, "question": "The warranty certificate ________ states that water damage is exempt from coverage.", "options": {"A": "explicitly", "B": "explicit", "C": "explication", "D": "explicitness"}, "answer": "A", "analysis": "副詞修飾動詞：[副詞 -ly] + states (及物動詞)。explicitly states 指『明確載明』。故選 (A)。", "translation": "保固證書明確載明水損不在保固涵蓋範圍之內。"}, {"id": 16, "target_seconds": 15, "question": "The corporate legal counsel ________ advised the CEO to refrain from issuing public comments.", "options": {"A": "strongly", "B": "strength", "C": "strong", "D": "strengthen"}, "answer": "A", "analysis": "副詞修飾動詞：[副詞 -ly] + advised (動詞)。strongly advised 指『強烈建議』。故選 (A)。", "translation": "企業法律顧問強烈建議執行長克制切勿發表公開評論。"}, {"id": 17, "target_seconds": 15, "question": "Employees are ________ reminded that all identification badges must be visible at security checkpoints.", "options": {"A": "periodically", "B": "periodic", "C": "period", "D": "periodical"}, "answer": "A", "analysis": "被動態夾心秒殺：are + [副詞 -ly] + reminded (p.p.)。periodically 表『定期地 / 週期性地』。故選 (A)。", "translation": "員工定期受到提醒，在安全檢查站必須出示並佩戴其識別證。"}, {"id": 18, "target_seconds": 20, "question": "The new software update will ________ resolve compatibility issues experienced on older operating systems.", "options": {"A": "effectively", "B": "effective", "C": "effectiveness", "D": "effect"}, "answer": "A", "analysis": "助動詞夾心秒殺：will + [副詞 -ly] + resolve (動詞原形)。effectively resolve 指『有效解決』。故選 (A)。", "translation": "新的軟體更新將有效解決舊版作業系統上所遇到的相容性問題。"}, {"id": 19, "target_seconds": 15, "question": "Due to hazardous road icing, highway authorities ________ restricted commercial truck traffic.", "options": {"A": "severely", "B": "severe", "C": "severity", "D": "severeness"}, "answer": "A", "analysis": "副詞修飾動詞：[副詞 -ly] + restricted (及物動詞)。severely restricted 指『嚴格限制』。故選 (A)。", "translation": "由於路面危險結冰，公路主管機關嚴格限制了商業貨車的通行。"}, {"id": 20, "target_seconds": 20, "question": "The pharmaceutical board must ________ verify test results before submitting the drug for federal approval.", "options": {"A": "rigorously", "B": "rigorous", "C": "rigor", "D": "rigorousness"}, "answer": "A", "analysis": "情態助動詞夾心：must + [副詞 -ly] + verify (原形動詞)。rigorously verify 指『嚴謹徹底驗證』。故選 (A)。", "translation": "藥物委員會在將藥品送交聯邦審批之前，必須嚴謹徹底地驗證測試結果。"}]}, "afternoon": {"quick_recall": [{"prompt": "The director decided to ________ [片語動詞，辭去職位] after ten years of service.", "clue": "辭去職務（step ...）", "answer": "step down"}, {"prompt": "The new management team will ________ [片語動詞，接管] the overseas facility.", "clue": "接管業務（take ...）", "answer": "take over"}, {"prompt": "We had to ________ [片語動詞，暫緩推遲] on the expansion until next spring.", "clue": "暫緩推遲（hold ...）", "answer": "hold off (on)"}, {"prompt": "The meeting was ________ [片語動詞，延期] until next Monday.", "clue": "延遲/推遲（put ...）", "answer": "put off"}, {"prompt": "Seeing 'will _____ enhance', immediately fill in an ________ [詞性].", "clue": "夾心餅乾位置（副詞 -ly）", "answer": "Adverb (-ly)"}, {"prompt": "Seeing 'has _____ proven', immediately fill in an ________ [詞性].", "clue": "完成式夾心位置", "answer": "Adverb (-ly)"}], "spaced_traps": [{"id": 1, "question": "The engineering department will ________ finish evaluating the structural integrity report.", "options": {"A": "promptly", "B": "prompt", "C": "promptness", "D": "prompted"}, "answer": "A", "trap_point": "will + [副詞 -ly] + finish (原形動詞)。不可選形容詞 prompt！", "analysis": "will 與動詞 finish 之間的夾心位置，只能填入副詞 (A) promptly（迅速地）修飾 finish。", "translation": "工程部門將迅速完成結構完整性報告的評估。"}, {"id": 2, "question": "Mr. Sterling has agreed to ________ as senior partner at the end of the fiscal year.", "options": {"A": "step down", "B": "take over", "C": "hold off", "D": "put off"}, "answer": "A", "trap_point": "step down as + 職位（辭職/退下）；take over 指接管；hold off 接 on；put off 指推遲事物。", "analysis": "句意搭配 'as senior partner'，指從資深合夥人職位退休或卸任，故選 (A) step down。", "translation": "Sterling 先生已同意在該會計年度結束時辭去資深合夥人職務。"}, {"id": 3, "question": "The company's innovative manufacturing process is ________ recognized across the automobile industry.", "options": {"A": "widely", "B": "wide", "C": "widen", "D": "width"}, "answer": "A", "trap_point": "is + [副詞 -ly] + recognized (p.p.)。widely recognized 為高頻商務搭配（廣泛認可）。", "analysis": "be 動詞與過去分詞之間塞入副詞修飾，widely recognized 指『受到廣泛認可』，秒選 (A)。", "translation": "該公司創新的製造流程在整個汽車產業中受到廣泛認可。"}, {"id": 4, "question": "The project coordinator decided to ________ the meeting because several key stakeholders were traveling.", "options": {"A": "put off", "B": "step down", "C": "take over", "D": "back down"}, "answer": "A", "trap_point": "put off the meeting = postpone the meeting（推遲會議）。", "analysis": "受詞為 the meeting，因利益關係人出差而決定『延期推遲』會議，故選 (A) put off。", "translation": "由於數位關鍵利益相關者出差在途，專案協調員決定推遲會議。"}, {"id": 5, "question": "The software is ________ compatible with the newest mobile operating system.", "options": {"A": "fully", "B": "full", "C": "fullness", "D": "fulfilling"}, "answer": "A", "trap_point": "is + [副詞 -ly] + compatible (形容詞)。fully compatible（完全相容）。", "analysis": "be 動詞與形容詞 compatible 之間，需填入副詞 (A) fully 修飾形容詞。", "translation": "該軟體與最新的行動作業系統完全相容。"}, {"id": 6, "question": "Applicants must submit their tax records ________ to scheduling an in-person loan interview.", "options": {"A": "prior", "B": "beforehand", "C": "previous", "D": "ahead"}, "answer": "A", "trap_point": "prior to + V-ing（在…之前）。ahead 須搭配 of！", "analysis": "看到空格後接 'to scheduling'，秒選固定介系詞片語 (A) prior to。", "translation": "申請人在安排實體貸款面談之前，必須繳交其稅務紀錄。"}, {"id": 7, "question": "Management was forced to issue a nationwide ________ of its popular smart thermostat.", "options": {"A": "recall", "B": "recalling", "C": "recalled", "D": "recalls"}, "answer": "A", "trap_point": "issue a nationwide + [單數名詞]。recall 為動名同形字（召回令）。", "analysis": "冠詞 a + 形容詞 nationwide + [單數名詞]。recall 可作名詞指產品召回，故選 (A)。", "translation": "管理層被迫對其熱銷智慧溫控器發布全國召回令。"}, {"id": 8, "question": "The auditor identified several ________ that led to substantial accounting errors.", "options": {"A": "oversights", "B": "oversees", "C": "overseeing", "D": "overseen"}, "answer": "A", "trap_point": "several 後接可數複數名詞 oversights（疏漏/疏失）。oversee 是動詞（監督）！", "analysis": "限定詞 several 後接複數名詞。oversights 指疏忽疏漏，導致重大會計錯誤，選名詞 (A)。", "translation": "稽核員指出了導致重大會計錯誤的數項疏漏。"}, {"id": 9, "question": "The executive committee will ________ review quarterly performance targets at tomorrow's meeting.", "options": {"A": "thoroughly", "B": "thorough", "C": "thoroughness", "D": "through"}, "answer": "A", "trap_point": "will + [副詞 -ly] + review (原形動詞)！夾心餅乾秒殺！", "analysis": "will 與動詞 review 之間填入副詞 (A) thoroughly 修飾動詞。", "translation": "執行委員會將在明天的會議上徹底檢視季度績效目標。"}, {"id": 10, "question": "Dr. Aris agreed to ________ as laboratory director after fifteen years of dedicated service.", "options": {"A": "step down", "B": "take over", "C": "hold off", "D": "put off"}, "answer": "A", "trap_point": "step down as + 職位（辭職/卸任）。", "analysis": "句意表示卸任實驗室總監一職，選 (A) step down。", "translation": "Aris 博士在奉獻服務了 15 年後，同意辭去實驗室總監一職。"}, {"id": 11, "question": "Management decided to ________ on constructing the testing annex until municipal permits are cleared.", "options": {"A": "hold off", "B": "step down", "C": "take over", "D": "back down"}, "answer": "A", "trap_point": "hold off on + V-ing（推遲/暫緩）。", "analysis": "受詞為 on constructing，表示暫緩擴建工程，選 (A) hold off。", "translation": "管理層決定暫緩興建測試附屬建築，直到市府許可獲准。"}, {"id": 12, "question": "The project supervisor decided to ________ the staff conference because three team leaders were ill.", "options": {"A": "put off", "B": "step down", "C": "take over", "D": "back down"}, "answer": "A", "trap_point": "put off the conference = postpone the conference（延期會議）。", "analysis": "因幹部生病而決定延後會議，選 (A) put off。", "translation": "專案主管因三位組長生病而決定延後員工會議。"}, {"id": 13, "question": "The automated packaging system has ________ enhanced distribution speeds across the regional network.", "options": {"A": "substantially", "B": "substantial", "C": "substantiate", "D": "substantiality"}, "answer": "A", "trap_point": "has + [副詞 -ly] + enhanced (p.p.)！完成式夾心秒殺！", "analysis": "has 與過去分詞 enhanced 之間填入副詞 (A) substantially（大幅度地）。", "translation": "自動化包裝系統大幅提升了全區網路的配送速度。"}, {"id": 14, "question": "Labor negotiators refused to ________ from their demand for comprehensive health coverage.", "options": {"A": "back down", "B": "step down", "C": "take over", "D": "hold off"}, "answer": "A", "trap_point": "back down from sth.（退讓/妥協）。", "analysis": "拒絕就健保訴求退讓，選 (A) back down。", "translation": "勞方談判代表拒絕就其全額健保涵蓋範圍的訴求做出讓步。"}], "part7": {"passages": [{"text_type": "Executive Press Release (企業新聞稿與交接公告)", "title": "Aura Logistics International — Executive Board Succession & Leadership Transition", "content": "PRESS RELEASE: AURA-CORP-2026-11\nFOR IMMEDIATE RELEASE: November 9, 2026\nISSUED BY: Office of the Board of Directors, Aura Logistics International\n\n1. Executive Leadership Announcement\nAura Logistics International announces that Founder and Chief Executive Officer Arthur Pendelton will officially step down from his executive duties after twenty-five years of dedicated service. The Board of Directors has unanimously designated Executive Vice President Elena Rostova as the incoming Chief Executive Officer, effective January 1, 2027. Ms. Rostova has spearheaded our Asian supply chain expansion and digital logistics transformation for the past seven years.\n\n2. Advisory Role and Strategic Focus\nFollowing his retirement from active day-to-day administrative operations, Mr. Pendelton will retain the prestigious role of Senior Advisor to the Board. In this continuing capacity, he will focus on long-term corporate governance, shareholder relations, and strategic cross-border mergers and acquisitions, ensuring continuity in corporate client partnerships.\n\n*Transition Town Hall: A global virtual town hall will be held on December 15 to introduce Ms. Rostova's executive leadership team. Departmental directors are invited to submit strategic transition questions to board-secretariat@auralogistics.com prior to December 1.", "questions": [{"question": "When will Elena Rostova assume the role of Chief Executive Officer?", "options": {"A": "Effective January 1.", "B": "On December 31.", "C": "After a twelve-month advisory leave.", "D": "Upon completion of the international merger."}, "answer": "A", "radar": "🔍 防漏看雷達：生效時間細節 'effective January 1'！", "analysis": "第一段第二句明確說明：Elena Rostova 將於 1 月 1 日起接管所有執行長職責，故選 (A)。"}, {"question": "What role will Arthur Pendelton retain following his retirement?", "options": {"A": "Senior Advisor to the Board.", "B": "Chief Operations Supervisor.", "C": "Director of Human Resources.", "D": "Regional Compliance Officer."}, "answer": "A", "radar": "🔍 防漏看雷達：新職位名稱 'Senior Advisor to the Board for a twelve-month consultative period'！", "analysis": "星號小字第一句指出：Pendelton 先生將留任擔任董事會資深顧問為期 12 個月，故選 (A)。"}, {"question": "What duty will Mr. Pendelton continue to supervise?", "options": {"A": "Strategic cross-border mergers and acquisitions.", "B": "Day-to-day administrative personnel matters.", "C": "Quarterly regional warehouse logistics audits.", "D": "Annual IT cybersecurity infrastructure reviews."}, "answer": "A", "radar": "🔍 防漏看雷達：保留督導業務 'continue overseeing strategic cross-border mergers and acquisitions'！", "analysis": "文末最後一句清楚載明：他免除日常行政職責，但將繼續監督策略性跨國併購業務，故選 (A)。"}]}, {"text_type": "Conference Organizing Memorandum (大型科技峰會調度通知)", "title": "Global Tech Summit: Session Schedule, Room Relocations, and Badge Replacement", "content": "CONFERENCE MEMORANDUM\nTO: All Registered Conference Delegates, Panelists, and Corporate Exhibitors\nFROM: Summit Planning Committee & Technical Operations Directorate\nDATE: November 9, 2026\nSUBJECT: Program Adjustments, Room Reassignments, and Security Credentials\n\n1. Keynote Room Relocation & Schedule Update\nWelcome to the 12th Annual Global Tech Summit. Due to unprecedented attendance demand surpassing initial venue projections, the opening panel discussion on Artificial Intelligence in Enterprise Logistics has been relocated from Salon C to the Grand Ballroom on Level 2. To ensure that all delegates can pass through security screening and locate their seats comfortably, the start time was put off by thirty minutes, now commencing promptly at 9:30 AM.\n\n2. Badge Replacement & Identification Requirements\nAll attendees must wear their personalized radio-frequency identification (RFID) conference badges visibly at all times to access exhibition halls, breakout sessions, and catering lounges.\n\n*Badge Replacement Policy: If an attendee misplaces their conference badge, an administrative fee of $20 will be charged for issuing an encrypted replacement badge at the Registration Concierge desk. Lost badges must be reported immediately to security to prevent unauthorized venue entry.", "questions": [{"question": "Why was the opening panel discussion relocated?", "options": {"A": "Due to unprecedented attendance demand.", "B": "Because of sudden electrical repairs in Room 204.", "C": "Owing to the late arrival of international panelists.", "D": "To facilitate professional live video recording."}, "answer": "A", "radar": "🔍 防漏看雷達：原因資訊 'Due to unprecedented attendance demand'！", "analysis": "第一段第一句明確指出：由於出席需求空前熱烈，開幕座談會移至一樓大禮堂，故選 (A)。"}, {"question": "What adjustment was made to the opening panel's schedule?", "options": {"A": "The start time was put off by thirty minutes.", "B": "The duration of the discussion was cut in half.", "C": "The session was rescheduled to the following afternoon.", "D": "The audience Q&A portion was completely eliminated."}, "answer": "A", "radar": "🔍 防漏看雷達：時間變更陷阱 'start time has been put off by thirty minutes'！", "analysis": "第一段第二句指出：開始時間推遲了 30 分鐘，以便與會代表有充裕時間移動，故選 (A)。"}, {"question": "How much is the administrative fee for replacing a lost conference badge?", "options": {"A": "$20.", "B": "Free of charge.", "C": "$50.", "D": "$10."}, "answer": "A", "radar": "🔍 防漏看雷達：星號末端規費細節 'replaced at the registration desk for a $20 processing fee'！", "analysis": "星號小字最後一句指出：遺失名牌可在報到處補發，工本手續費為 20 美元，故選 (A)。"}]}]}}}, "7": {"day": 7, "date": "11/10", "phase": 1, "phase_name": "錯題庫清零與語感校正", "topic": "不完全及物動詞 (find + O + OC) ｜ 規章遵守與超時加班", "morning": {"chunks": [{"chunk": "putting in overtime", "meaning": "持續加班工作", "scenario": "Staff members were putting in overtime to meet the rigorous software rollout date.", "paraphrase": "putting in overtime = working extra hours", "alert": ""}, {"chunk": "refrain from smoking", "meaning": "請勿抽煙 / 克制避免", "scenario": "Guests are kindly requested to refrain from smoking on the outdoor terrace.", "paraphrase": "refrain from = abstain from = avoid", "alert": "必考介系詞：refrain 固定搭配 from + V-ing/N！"}, {"chunk": "adhere to guidelines", "meaning": "遵守各項準則", "scenario": "All laboratory personnel must adhere to guidelines set by the safety commission.", "paraphrase": "adhere to = comply with = abide by = follow", "alert": "必考介系詞：adhere 固定搭配 to！"}, {"chunk": "be bound to happen", "meaning": "必然會發生", "scenario": "With market volatility at record highs, price fluctuations are bound to happen.", "paraphrase": "be bound to = be certain to = inevitable", "alert": ""}, {"chunk": "back down from demands", "meaning": "從訴求中退讓妥協", "scenario": "Neither negotiating team was willing to back down from demands.", "paraphrase": "back down = yield = concede", "alert": ""}, {"chunk": "throughout the day", "meaning": "一整天持續不斷", "scenario": "Refreshments and snacks will be served in the foyer throughout the day.", "paraphrase": "throughout the day = all day long", "alert": ""}, {"chunk": "and vice versa", "meaning": "反之亦然", "scenario": "A successful marketing campaign benefits sales figures, and vice versa.", "paraphrase": "vice versa = the reverse is also true", "alert": ""}], "visual_anchor": {"title": "看到 find / keep / make / deem + 受詞 ➔ 後面接什麼？", "rule_1": "👀 看到 find + 受詞 + ________ ➔ 80% 考「形容詞 (OC 受詞補語)」！", "rule_2": "👀 例：find the manual ________ ➔ 選 helpful / useful（覺得手冊很實用）！", "golden_rule": "⚡ 教練金句：find/keep/make 後面帶受詞，補語秒挑形容詞！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "Most survey participants found the new mobile banking interface remarkably ________ to navigate.", "options": {"A": "easy", "B": "easily", "C": "ease", "D": "easiness"}, "answer": "A", "analysis": "不完全及物動詞秒殺：find + 受詞 (the interface) + [受詞補語 OC]。受詞補語必須用形容詞，副詞 remarkably 修飾形容詞 (A) easy。絕不能選副詞 easily！", "translation": "大多數受訪者發現新的行動網銀介面操作起來非常簡單。"}, {"id": 2, "target_seconds": 15, "question": "Senior management deemed the proposed environmental sustainability initiative ________ for corporate reputation.", "options": {"A": "beneficial", "B": "beneficially", "C": "benefit", "D": "benefiting"}, "answer": "A", "analysis": "不完全及物動詞秒殺：deem + 受詞 (the initiative) + [形容詞受詞補語]。deem sth. beneficial（認為某事有益）。故選形容詞 (A)。", "translation": "高層管理人員認為提議的環境永續倡議對企業聲譽大有助益。"}, {"id": 3, "target_seconds": 15, "question": "Warehouse supervisors must keep all emergency fire exit routes ________ at all times.", "options": {"A": "clear", "B": "clearly", "C": "clearness", "D": "clearing"}, "answer": "A", "analysis": "keep + 受詞 + [形容詞受詞補語]：keep all routes clear（保持所有通道暢通）。形容詞作補語，秒選 (A) clear。(B) clearly 為副詞不可作補語。", "translation": "倉庫主管必須隨時確保所有緊急火災逃生路線保持暢通。"}, {"id": 4, "target_seconds": 15, "question": "The software update made the enterprise resource system significantly more ________ for remote workers.", "options": {"A": "reliable", "B": "reliably", "C": "reliance", "D": "relying"}, "answer": "A", "analysis": "make + 受詞 + [形容詞受詞補語]：more reliable（更可靠）。受詞補語選形容詞 (A)。(B) reliably 為副詞；(C) reliance 為名詞。", "translation": "該軟體更新使得企業資源系統對遠端工作者而言變得顯著更加可靠。"}, {"id": 5, "target_seconds": 20, "question": "Employees who are putting ________ overtime to meet the audit deadline will receive compensatory leave.", "options": {"A": "in", "B": "on", "C": "at", "D": "out"}, "answer": "A", "analysis": "商務高頻片語秒殺：put in overtime 指『加班 / 投入超時工作』。put in 後接時間或努力。故選 (A)。", "translation": "為了趕上稽核截止期限而加班的員工，將獲得補休假期。"}, {"id": 6, "target_seconds": 15, "question": "Office personnel are requested to refrain ________ using speakerphones in shared workspace areas.", "options": {"A": "from", "B": "to", "C": "for", "D": "at"}, "answer": "A", "analysis": "介系詞搭配秒殺：refrain from + V-ing（克制/避免做某事）。refrain 固定搭配 from。故選 (A)。", "translation": "懇請辦公室同仁在共用工作區域克制切勿使用擴音通話。"}, {"id": 7, "target_seconds": 15, "question": "All clinical researchers must strictly adhere ________ established laboratory safety guidelines.", "options": {"A": "to", "B": "with", "C": "in", "D": "by"}, "answer": "A", "analysis": "介系詞搭配秒殺：adhere strictly to...（嚴格遵守……）。adhere 固定搭配 to。故選 (A)。", "translation": "所有臨床研究員必須嚴格遵守既定的實驗室安全準則。"}, {"id": 8, "target_seconds": 15, "question": "With crude oil prices fluctuating wildly, airline ticket prices are ________ to increase next month.", "options": {"A": "bound", "B": "binding", "C": "boundless", "D": "boundary"}, "answer": "A", "analysis": "固定片語秒殺：be bound to + 原形動詞（必然會…… / 注定會……）。故選 (A) bound。", "translation": "隨著原油價格劇烈波動，下個月機票價格必然會上漲。"}, {"id": 9, "target_seconds": 15, "question": "Despite fierce shareholder opposition, the CEO refused to back ________ from the corporate merger.", "options": {"A": "down", "B": "out", "C": "off", "D": "away"}, "answer": "A", "analysis": "片語搭配：back down (from) 指『退讓/妥協』。back down from the merger 指從合併案中讓步。故選 (A)。", "translation": "儘管面臨股東的激烈反對，執行長依然拒絕在企業合併案上做出讓步。"}, {"id": 10, "target_seconds": 15, "question": "Air conditioning in the corporate headquarters operates continuously ________ the day during summer months.", "options": {"A": "throughout", "B": "across", "C": "along", "D": "between"}, "answer": "A", "analysis": "時間介系詞：throughout the day 指『整天 / 一整天貫穿始終』。across 指跨越空間；along 沿著；between 兩者之間。故選 (A)。", "translation": "在夏季期間，企業總部的大樓空調整天持續運轉。"}, {"id": 11, "target_seconds": 15, "question": "Sales managers can view marketing analytics, and ________ versa, ensuring mutual operational alignment.", "options": {"A": "vice", "B": "voice", "C": "visa", "D": "vivid"}, "answer": "A", "analysis": "拉丁商務成語秒殺：and vice versa（反之亦然）。副詞片語固定拼寫為 vice versa，選 (A)。", "translation": "銷售經理可以檢視行銷數據分析，反之亦然，以確保雙方的營運目標一致。"}, {"id": 12, "target_seconds": 20, "question": "The executive board found the financial audit results ________ satisfactory to warrant the dividend payout.", "options": {"A": "sufficiently", "B": "sufficient", "C": "sufficiency", "D": "suffice"}, "answer": "A", "analysis": "副詞修飾形容詞：find + the results (受詞) + [副詞] + satisfactory (形容詞補語)。副詞 (A) sufficiently 修飾補語 satisfactory。故選 (A)。", "translation": "執行董事會認為財務稽核結果令人滿意，足以支撐股利發放。"}, {"id": 13, "target_seconds": 15, "question": "Staff members working the night shift must leave the server room doors ________ at all times for ventilation.", "options": {"A": "unlocked", "B": "unlocking", "C": "unlock", "D": "unlocks"}, "answer": "A", "analysis": "leave + 受詞 + [受詞補語]：門是被開鎖的狀態，表被動完成用過去分詞形容詞 (A) unlocked。(C) 為原形動詞。", "translation": "值夜班的人員必須隨時保持伺服器機房大門不鎖，以利通風。"}, {"id": 14, "target_seconds": 15, "question": "The newly hired compliance officer considers strict safety adherence ________ to organizational success.", "options": {"A": "vital", "B": "vitally", "C": "vitality", "D": "vitalize"}, "answer": "A", "analysis": "consider + 受詞 + [形容詞補語]：considers strict adherence vital（認為嚴格遵守極為重要）。受詞補語用形容詞 (A) vital。(B) 為副詞。", "translation": "新聘的合規主管認為嚴格遵守安全規章對組織的成功至關重要。"}, {"id": 15, "target_seconds": 20, "question": "The marketing department's proactive outreach proved ________ in attracting international sponsors.", "options": {"A": "instrumental", "B": "instrumentally", "C": "instrument", "D": "instrumentality"}, "answer": "A", "analysis": "連繫動詞 prove + [形容詞主詞補語]：prove instrumental in sth.（在某事中起關鍵作用）。選形容詞 (A) instrumental。(B) 為副詞。", "translation": "行銷部門積極主動的推廣，在吸引國際贊助商方面發揮了關鍵作用。"}, {"id": 16, "target_seconds": 15, "question": "The revised cafeteria layout makes lunch queueing significantly ________ for factory workers.", "options": {"A": "faster", "B": "fastest", "C": "fasten", "D": "fastness"}, "answer": "A", "analysis": "make + 受詞 + [形容詞補語]：significantly 為程度副詞修飾比較級形容詞 (A) faster。fasten 為動詞；fastest 為最高級。", "translation": "修改後的餐廳動線讓工廠工人的午餐排隊速度顯著變快。"}, {"id": 17, "target_seconds": 15, "question": "The software developers found the cloud API documentation ________ organized and easy to integrate.", "options": {"A": "neatly", "B": "neat", "C": "neatness", "D": "neater"}, "answer": "A", "analysis": "副詞修飾過去分詞：organized 為過去分詞形容詞，副詞 (A) neatly 修飾 organized（整齊有條理地組織）。故選 (A)。", "translation": "軟體開發人員發現雲端 API 文件組織得非常有條理且易於整合。"}, {"id": 18, "target_seconds": 20, "question": "Factory workers must wear protective goggles to keep their eyes ________ from chemical splashes.", "options": {"A": "safe", "B": "safely", "C": "safety", "D": "safeguard"}, "answer": "A", "analysis": "keep + their eyes (受詞) + [形容詞受詞補語]：keep eyes safe from...（保護眼睛不受傷害）。受詞補語選形容詞 (A) safe。(B) safely 為副詞。", "translation": "工廠工人必須佩戴護目鏡，以保護眼睛免受化學液體飛濺。"}, {"id": 19, "target_seconds": 15, "question": "The chief executive considers the current financial quarter an ________ moment to expand into South America.", "options": {"A": "ideal", "B": "ideally", "C": "idealize", "D": "idealism"}, "answer": "A", "analysis": "名詞前形容詞修飾：an + [形容詞] + moment。ideal moment 指『理想時機』。選形容詞 (A)。", "translation": "執行長認為當前會計季度是向南美洲擴張的理想時機。"}, {"id": 20, "target_seconds": 15, "question": "To prevent unauthorized access, the IT division keeps database credentials ________ confidential.", "options": {"A": "strictly", "B": "strict", "C": "strictness", "D": "stricter"}, "answer": "A", "analysis": "副詞修飾形容詞受詞補語：keep + credentials (受詞) + [副詞] + confidential (形容詞補語)。副詞 (A) strictly 修飾 confidential。故選 (A)。", "translation": "為防止未經授權的存取，IT 部門對資料庫認證資訊嚴格保密。"}]}, "afternoon": {"quick_recall": [{"prompt": "We found the manual very ________ [形容詞，容易的] to follow.", "clue": "find + O + 形容詞補語（不可填 easily）", "answer": "easy"}, {"prompt": "He is putting ________ [介系詞] overtime this week.", "clue": "加班（put ___ overtime）", "answer": "in"}, {"prompt": "Please refrain ________ [介系詞] making personal calls.", "clue": "克制/避免（refrain 固定搭配）", "answer": "from"}, {"prompt": "Adhere ________ [介系詞] the company handbook.", "clue": "遵守規定（adhere 固定搭配）", "answer": "to"}, {"prompt": "The flight is ________ [形容詞，注定/必然] to be delayed.", "clue": "注定會（be _____ to + V）", "answer": "bound"}, {"prompt": "She helps him, and ________ [拉丁成語前字] versa.", "clue": "反之亦然（_____ versa）", "answer": "vice"}], "spaced_traps": [{"id": 1, "question": "The focus group found the prototype mobile app remarkably ________ to operate.", "options": {"A": "simple", "B": "simply", "C": "simplicity", "D": "simplify"}, "answer": "A", "trap_point": "find + O + 形容詞受詞補語！千萬不要被副詞 remarkably 誤導而選副詞 simply！", "analysis": "受詞為 the prototype mobile app，後方需要受詞補語 (OC)，補語必須用形容詞 (A) simple。remarkably 為副詞，修飾形容詞 simple。", "translation": "焦點訪談小組發現該原型行動應用程式操作起來格外簡單。"}, {"id": 2, "question": "All employees working in the chemical laboratory must keep the ventilation fans ________ at all times.", "options": {"A": "running", "B": "ran", "C": "run", "D": "runs"}, "answer": "A", "trap_point": "keep + O + V-ing（保持受詞持續運轉）。", "analysis": "通風扇持續運轉，表主動進行狀態用現在分詞 (A) running 作受詞補語。", "translation": "在化學實驗室工作的所有員工必須隨時保持通風扇運轉。"}, {"id": 3, "question": "Production line workers who put ________ overtime during the holiday rush are compensated at double rates.", "options": {"A": "in", "B": "on", "C": "out", "D": "up"}, "answer": "A", "trap_point": "put in overtime 為商務固定片語（加班）。", "analysis": "put in + 時間/努力。put in overtime 意指超時加班，秒選 (A)。", "translation": "在連假趕工期間加班的產線工人，將獲得雙倍工資補償。"}, {"id": 4, "question": "The board of directors considers the revised merger agreement ________ to both corporations.", "options": {"A": "advantageous", "B": "advantageously", "C": "advantage", "D": "advantaged"}, "answer": "A", "trap_point": "consider + O + 形容詞受詞補語！", "analysis": "consider + the agreement (受詞) + [形容詞受詞補語]。選形容詞 (A) advantageous（有利的）。", "translation": "董事會認為修改後的合併協議對兩家公司均屬有利。"}, {"id": 5, "question": "Passengers are reminded to refrain ________ talking loudly while onboard the quiet car.", "options": {"A": "from", "B": "to", "C": "at", "D": "by"}, "answer": "A", "trap_point": "refrain from + V-ing（克制避免）。", "analysis": "看到 refrain，秒配介系詞 from，選 (A)。", "translation": "乘客受到提醒，在寧靜車廂內應克制勿大聲說話。"}, {"id": 6, "question": "The logistics director declared that transportation delays were ________ to occur during the winter storm.", "options": {"A": "bound", "B": "binding", "C": "bounds", "D": "boundary"}, "answer": "A", "trap_point": "be bound to + 原形動詞（必然會發生）。", "analysis": "be bound to + V 是多益必考片語，表『注定/必然發生』，選 (A) bound。", "translation": "物流總監表示在冬季暴風雪期間，交通運輸延誤勢必無可避免。"}, {"id": 7, "question": "Contractors must adhere strictly ________ environmental zoning guidelines established by the municipal council.", "options": {"A": "to", "B": "for", "C": "in", "D": "by"}, "answer": "A", "trap_point": "adhere strictly to（嚴格遵守）。abide 才接 by！", "analysis": "adhere 固定搭配介系詞 to，選 (A)。", "translation": "承包商必須嚴格遵守市政委員會制定的環境分區指引。"}, {"id": 8, "question": "The factory manager insisted on inspecting the assembly line ________ prior to signing off on daily production.", "options": {"A": "personally", "B": "personal", "C": "personality", "D": "person"}, "answer": "A", "trap_point": "inspected the line + [副詞] 修飾動詞 inspect！", "analysis": "空格修飾動詞片語 inspecting the assembly line，需用副詞 (A) personally（親自地）。", "translation": "工廠經理堅持在簽署每日生產確認書之前，必須親自檢查裝配線。"}, {"id": 9, "question": "Focus group evaluators found the updated website design remarkably ________ to navigate.", "options": {"A": "easy", "B": "easily", "C": "easiness", "D": "ease"}, "answer": "A", "trap_point": "find + O + 形容詞受詞補語！絕不選副詞 easily！", "analysis": "find + the design (受詞) + [形容詞受詞補語]。選形容詞 (A) easy。", "translation": "焦點評估小組發現更新後的網站設計操作起來非常簡單。"}, {"id": 10, "question": "Staff members putting ________ overtime to meet the audit deadline will be granted compensatory leave.", "options": {"A": "in", "B": "on", "C": "at", "D": "up"}, "answer": "A", "trap_point": "put in overtime（超時加班）。", "analysis": "put in overtime 為商務固定語塊，選 (A)。", "translation": "為趕上稽核截止期限而加班的同仁將獲得補休假。"}, {"id": 11, "question": "All personnel must adhere strictly ________ environmental containment safety regulations.", "options": {"A": "to", "B": "with", "C": "in", "D": "for"}, "answer": "A", "trap_point": "adhere strictly to（嚴格遵守）。", "analysis": "adhere 固定搭配介系詞 to，選 (A)。", "translation": "所有人員必須嚴格遵守環境圍阻安全規章。"}, {"id": 12, "question": "Transportation fares are ________ to rise following the surge in petroleum market prices.", "options": {"A": "bound", "B": "binding", "C": "bounds", "D": "boundary"}, "answer": "A", "trap_point": "be bound to + 原形動詞（必然會發生）。", "analysis": "be bound to + V 表必然會發生，選 (A)。", "translation": "隨著石油市場價格暴漲，交通運輸票價勢必會上漲。"}, {"id": 13, "question": "Conference delegates are politely asked to refrain ________ using mobile phones during panel speeches.", "options": {"A": "from", "B": "to", "C": "with", "D": "at"}, "answer": "A", "trap_point": "refrain from + V-ing（克制避免）。", "analysis": "refrain 搭配 from，選 (A)。", "translation": "與會代表懇請在座談演講期間克制勿使用手機。"}, {"id": 14, "question": "Accounting department heads can view project expenses, and ________ versa, ensuring mutual oversight.", "options": {"A": "vice", "B": "voice", "C": "visa", "D": "vivid"}, "answer": "A", "trap_point": "vice versa（反之亦然）。", "analysis": "拉丁商務成語 vice versa，選 (A)。", "translation": "會計部門主管可以檢視專案費用，反之亦然，以確保相互監督。"}], "part7": {"passages": [{"text_type": "Corporate Compensation Circular (企業加班與津貼規範)", "title": "Vertex Technologies — Corporate Overtime Compensation & Shift Allocation Policy", "content": "CIRCULAR NO: VERTEX-PAY-2026-07\nISSUING AUTHORITY: Compensation & Benefits Committee, Vertex Technologies\nEFFECTIVE DATE: November 10, 2026\nAPPLICABILITY: All Non-Exempt Operations, Logistics, and Manufacturing Personnel\n\n1. Overtime Compensation Multipliers\nTo maintain fair workforce compensation and ensure compliance with regional labor laws, Vertex Technologies has updated its overtime framework. Non-exempt hourly employees who perform authorized work in excess of forty hours per calendar week will receive overtime compensation at 1.5 times the regular base rate for each supplemental hour worked. Weekend and public holiday shifts will continue to follow statutory holiday premiums and differential hourly allowances.\n\n2. Mandatory Supervisory Pre-Approval\nTo control departmental operational budgets and prevent workplace exhaustion, all overtime shifts must be scheduled and verified in advance. Prior written authorization from a department head is strictly required before an employee begins an overtime shift.\n\n*Unapproved Hours Policy: If an employee works overtime without written consent from their departmental supervisor, the recorded hours do not qualify for premium pay rates and will be reimbursed solely at standard base pay, accompanied by formal supervisory counseling. Timecard dispute forms must be lodged within five business days.", "questions": [{"question": "What compensation rate applies to approved overtime hours beyond forty hours?", "options": {"A": "1.5 times the regular base rate.", "B": "Double the standard base wage.", "C": "A flat bonus of $200 per extra shift.", "D": "Tripled base rate plus dinner stipends."}, "answer": "A", "radar": "🔍 防漏看雷達：加班費率 'receive 1.5 times their regular base rate'！", "analysis": "第一段最後一句明確說明：每週超過 40 小時的加班工時，將獲得正常底薪的 1.5 倍工資，故選 (A)。"}, {"question": "What is required before an employee begins an overtime shift?", "options": {"A": "Prior written authorization from a department head.", "B": "A comprehensive annual medical wellness check.", "C": "Submitting a digital timecard via email.", "D": "Completing forty-eight hours of safety webinars."}, "answer": "A", "radar": "🔍 防漏看雷達：星號事前審批細節 'pre-authorized in writing by a department head prior to the commencement of extra hours'！", "analysis": "星號小字第一句指出：所有加班必須在開始前由部門主管書面事前核准，故選 (A)。"}, {"question": "What happens if an employee works overtime without written consent?", "options": {"A": "The hours do not qualify for premium pay rates.", "B": "The employee is permanently dismissed immediately.", "C": "The entire weekly base paycheck is frozen.", "D": "They must pay an administrative processing fee."}, "answer": "A", "radar": "🔍 防漏看雷達：未依規定之後果 'will not qualify for premium pay rates and may result in administrative review'！", "analysis": "文中第二句清楚註記：未經事先書面同意而記錄的加班工時，將無法享有加成工資費率，故選 (A)。"}]}, {"text_type": "Workplace Etiquette Directive (辦公室環境與工位守則)", "title": "Apex Commercial Tower — Open-Plan Workstation Protocols and Etiquette", "content": "FACILITY DIRECTIVE: METRO-OFFICE-2026-02\nTO: All Personnel Operating Within Open-Plan Floors (Floors 3–7)\nFROM: Corporate Workplace Experience Committee & Facility Operations\nDATE: November 10, 2026\nSUBJECT: Noise Mitigation, Clean-Desk Standards, and Flexible Hot-Desk Allocation\n\n1. Sound Control & Dedicated Call Zones\nTo cultivate a professional, productive, and acoustically comfortable working environment in our newly renovated headquarters, staff members are reminded to maintain conversational mindfulness at all times. When conducting mobile voice calls or participating in video conferences, employees must take phone calls in dedicated soundproof phone booths on Floor 3 rather than speaking at open workstations.\n\n2. Clean-Desk Mandate & Nightly Storage\nTo safeguard sensitive business intelligence and facilitate nighttime commercial cleaning, employees must keep their workstations completely clear of paperwork and personal belongings at the end of each day. Document shredders, confidential recycling bins, and individual locked credenzas are provided along every main corridor aisle.\n\n*Hot-Desk Allocation: Hot desks are allocated to agile staff on a first-come, first-served basis each morning via our digital check-in tablets. Reserving unoccupied desks with personal coats, laptop bags, or notebooks is strictly prohibited across all floors.", "questions": [{"question": "Where should employees take phone calls to avoid disturbing coworkers?", "options": {"A": "In dedicated soundproof phone booths on Floor 3.", "B": "At their assigned individual workstations.", "C": "In the open cafeteria on Floor 1.", "D": "Outside the front main building entrance."}, "answer": "A", "radar": "🔍 防漏看雷達：地點指引 'dedicated soundproof phone booths are available on Floor 3'！", "analysis": "星號小字第一點明確說明：個人座位禁止使用擴音通話，3 樓設有專用隔音電話亭，故選 (A)。"}, {"question": "What must staff do with their workstations at the end of each day?", "options": {"A": "Keep them completely clear of paperwork and personal belongings.", "B": "Lock the office door with physical security keys.", "C": "Spray sanitizing solution on all computer keyboards.", "D": "Power off all emergency overhead ceiling lights."}, "answer": "A", "radar": "🔍 防漏看雷達：收工規範 'kept completely clear of paperwork and personal items at the conclusion of each workday'！", "analysis": "第二點指出：每日工作結束時，工作站必須完全清理乾淨，不留文件或私人物品，故選 (A)。"}, {"question": "How are hot desks allocated to employees?", "options": {"A": "On a first-come, first-served basis.", "B": "According to senior employee rank.", "C": "By monthly online reservations.", "D": "Through annual employee lottery."}, "answer": "A", "radar": "🔍 防漏看雷達：分配原則 'implemented on a first-come, first-served basis'！", "analysis": "文末最後一句明確說明：流動辦公桌採先到先得的方式分配，故選 (A)。"}]}]}}}, "8": {"day": 8, "date": "11/11", "phase": 1, "phase_name": "錯題庫清零與語感校正", "topic": "名詞動詞同形誤判 (damage) ｜ 差旅與服裝規範", "morning": {"chunks": [{"chunk": "compensate for damage", "meaning": "賠償所造成的損失", "scenario": "The courier promised to compensate for damage sustained during transit.", "paraphrase": "damage = harm = destruction; 多義字：damage (n.) 損害; damage (v.) 破壞", "alert": "文法陷阱：damage 當『損害』時為不可數名詞！damages 複數時指『法律賠償金』！"}, {"chunk": "book luxury accommodation", "meaning": "預訂奢華住宿設施", "scenario": "Travel coordinators booked luxury accommodation for the visiting delegates.", "paraphrase": "accommodation = lodging = housing", "alert": "不可數名詞：accommodation（住宿）多益常考不可數！"}, {"chunk": "walking down the aisle", "meaning": "沿著走道走過去", "scenario": "Please keep luggage clear while walking down the aircraft aisle.", "paraphrase": "aisle = walkway = corridor = passageway", "alert": ""}, {"chunk": "anticipate the demand", "meaning": "預先掌握市場需求", "scenario": "Retailers must anticipate the demand for winter coats before the freeze.", "paraphrase": "anticipate = foresee = expect = predict", "alert": ""}, {"chunk": "wear professional attire", "meaning": "穿著專業商務服飾", "scenario": "Consultants are expected to wear professional attire during client presentations.", "paraphrase": "attire = clothing = garments = apparel", "alert": "不可數名詞：attire 為不可數；attired (adj.) 穿著……服裝的。"}, {"chunk": "commercial kitchen appliance", "meaning": "商用廚房家電器具", "scenario": "The restaurant replaced its outdated commercial kitchen appliance.", "paraphrase": "appliance = device = machine = equipment", "alert": ""}, {"chunk": "attired in business suits", "meaning": "身著商務套裝", "scenario": "All convention attendees were neatly attired in business suits.", "paraphrase": "attired in = dressed in", "alert": ""}], "visual_anchor": {"title": "看到 damage / access / schedule / contact ➔ 先看位置定詞性！", "rule_1": "👀 前面有 a / the / cause / assess ➔ 它是「名詞」受詞！（assess the damage）", "rule_2": "👀 前面有 will / could / to ➔ 它是「動詞」原形！（will damage the engine）", "golden_rule": "⚡ 教練金句：不要先入為主背死詞性，看前看後判斷它是動還是名！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "The logistics carrier agreed to compensate the client in full for any ________ to the shipped fragile electronics.", "options": {"A": "damage", "B": "damages", "C": "damaging", "D": "damaged"}, "answer": "A", "analysis": "動名同形與不可數名詞：compensate for [不可數名詞] damage（損害/損壞）。damage 表損壞時為不可數名詞，不可加 -s。(B) damages 在法律上是複數名詞『賠償金』，此處是賠償貨物的損害，故選 (A)。", "translation": "物流承運商同意就運送之易碎電子產品所受的任何損壞，向客戶進行全額賠償。"}, {"id": 2, "target_seconds": 15, "question": "A severe thunderstorm may ________ the satellite communications array if protective shields are not engaged.", "options": {"A": "damage", "B": "damages", "C": "damaging", "D": "damaged"}, "answer": "A", "analysis": "情態助動詞後接及物動詞：may + [原形動詞] + the array (受詞)。此處 damage 作動詞使用，表示『破壞/使受損』。選原形動詞 (A)。", "translation": "若未啟動防護罩，猛烈的雷雨可能會損壞衛星通訊陣列。"}, {"id": 3, "target_seconds": 15, "question": "The conference organizers arranged complimentary hotel ________ for all international keynote speakers.", "options": {"A": "accommodations", "B": "accommodating", "C": "accommodate", "D": "accommodated"}, "answer": "A", "analysis": "名詞受詞：hotel accommodations 指『飯店住宿』。選名詞 (A)。(C) 為動詞；(B) 為分詞形容詞樂於助人的。", "translation": "大會籌辦方為所有國際專題演講者安排了免費的飯店住宿。"}, {"id": 4, "target_seconds": 15, "question": "Passengers must ensure that their carry-on luggage does not obstruct the aircraft ________ during taxiing.", "options": {"A": "aisle", "B": "isle", "C": "aisles", "D": "appliance"}, "answer": "A", "analysis": "名詞拼字與單複數：obstruct the aircraft aisle 指『阻礙飛機走道』。(A) aisle 為走道/通道。(B) isle 為島嶼；(D) appliance 為電器。", "translation": "乘客必須確保其隨身行李在飛機滑行期間不會阻礙機艙走道。"}, {"id": 5, "target_seconds": 15, "question": "Marketing directors ________ a considerable rise in e-commerce orders prior to Black Friday.", "options": {"A": "anticipate", "B": "anticipation", "C": "anticipatory", "D": "anticipatedly"}, "answer": "A", "analysis": "句子動詞秒殺：Marketing directors (主詞) + [及物動詞] + a rise (受詞)。選現在式原形動詞 (A) anticipate（預期/預估）。(B) 為名詞；(C) 為形容詞。", "translation": "行銷總監預期在黑色星期五之前，電子商務訂單將大幅增長。"}, {"id": 6, "target_seconds": 15, "question": "Delegates attending the annual gala dinner are requested to wear formal business ________.", "options": {"A": "attire", "B": "attired", "C": "attiring", "D": "attires"}, "answer": "A", "analysis": "名詞受詞：wear (及物動詞) + formal business + [不可數名詞]。attire 表『正裝/服裝』，為不可數名詞。選 (A)。", "translation": "出席年度晚宴的嘉賓懇請穿著正式商務正裝。"}, {"id": 7, "target_seconds": 15, "question": "All kitchen ________ installed in the commercial cafeteria are covered under a three-year manufacturer warranty.", "options": {"A": "appliances", "B": "applicants", "C": "applications", "D": "applicability"}, "answer": "A", "analysis": "易混淆字名詞辨析：kitchen appliances 指『廚房家電/廚房器具』。(B) applicants 為應徵者；(C) applications 為申請書；(D) applicability 為適用性。選 (A)。", "translation": "商業員工餐廳內安裝的所有廚房電器，均享有為期三年的製造商保固。"}, {"id": 8, "target_seconds": 20, "question": "The executive board was ________ attired in bespoke dark suits for the press briefing.", "options": {"A": "immaculately", "B": "immaculate", "C": "immaculateness", "D": "immaculation"}, "answer": "A", "analysis": "副詞修飾過去分詞形容詞：was + [副詞 -ly] + attired (p.p. 形容詞)。immaculately attired 指『衣冠楚楚/穿著無可挑剔』。選副詞 (A)。", "translation": "執行董事會成員身穿訂製深色西裝，衣著無可挑剔地出席了新聞簡報會。"}, {"id": 9, "target_seconds": 15, "question": "Customer service representatives must respond ________ to all inquiries submitted via the web chat.", "options": {"A": "promptly", "B": "prompt", "C": "promptness", "D": "prompted"}, "answer": "A", "analysis": "副詞修飾動詞：respond (動詞) + [副詞]。promptly 指『迅速地 / 即時地』修飾動詞 respond。故選 (A)。", "translation": "客戶服務代表必須對透過線上即時通訊提交的所有諮詢做出迅速回覆。"}, {"id": 10, "target_seconds": 15, "question": "The real estate developer plans to ________ its commercial holdings across the Pacific Rim.", "options": {"A": "broaden", "B": "broad", "C": "broadly", "D": "broadness"}, "answer": "A", "analysis": "不定詞後接動詞：plans to + [原形動詞] + its commercial holdings (受詞)。broaden 指『擴展/拓寬』。(B) broad 為形容詞；(D) 為名詞。選 (A)。", "translation": "該房地產開發商計畫擴展其在環太平洋地區的商業資產組合。"}, {"id": 11, "target_seconds": 15, "question": "The promotional ________ distributed at the entrance summarizes our new retirement investment plans.", "options": {"A": "brochure", "B": "canvas", "C": "dues", "D": "closure"}, "answer": "A", "analysis": "商務名詞辨析：promotional brochure 指『宣傳手冊/小冊子』。(B) canvas 為帆布；(C) dues 為會費；(D) closure 為停工關閉。選 (A)。", "translation": "在入口處發放的宣傳小手冊概述了我們最新的退休投資計畫。"}, {"id": 12, "target_seconds": 20, "question": "The renovated grand ballroom has a maximum seating ________ of five hundred attendees.", "options": {"A": "capacity", "B": "capacitance", "C": "capably", "D": "capable"}, "answer": "A", "analysis": "複合名詞：seating capacity 指『容納座位人數 / 座位容量』。capacity 為名詞。選 (A)。", "translation": "翻新後的大宴會廳最大座位容納量為 500 位賓客。"}, {"id": 13, "target_seconds": 15, "question": "Ms. Delgado managed the logistics budget ________, saving the department over ten percent in freight costs.", "options": {"A": "capably", "B": "capable", "C": "capability", "D": "capacities"}, "answer": "A", "analysis": "副詞修飾及物動詞：managed the budget + [副詞]。capably 指『能幹勝任地』。選副詞 (A)。", "translation": "Delgado 女士幹練妥善地管理了物流預算，為該部門節省了超過 10% 的貨運費用。"}, {"id": 14, "target_seconds": 15, "question": "The event coordinator hired an upscale ________ to provide gourmet refreshments for the gallery opening.", "options": {"A": "caterer", "B": "catering", "C": "catered", "D": "caters"}, "answer": "A", "analysis": "名詞受詞（職業指人）：hired an upscale + [可數名詞指人]。caterer 指『外燴承辦商 / 外燴業者』。(B) catering 為外燴服務（不可數事業）。選 (A)。", "translation": "活動協調員聘請了一家高級外燴廠商，為畫廊開幕式提供精緻茶點。"}, {"id": 15, "target_seconds": 15, "question": "A temporary highway ________ was ordered to permit municipal workers to repair damaged water pipes.", "options": {"A": "closure", "B": "close", "C": "closely", "D": "closing"}, "answer": "A", "analysis": "名詞主詞：highway closure 指『公路封閉』。closure 為名詞。(B) 為動詞/形容詞；(C) 為副詞。選 (A)。", "translation": "當局下令暫時封閉高速公路，以便市政工人修復受損的水管。"}, {"id": 16, "target_seconds": 20, "question": "The department chair took time during the ceremony to ________ team members for their exceptional dedication.", "options": {"A": "commend", "B": "command", "C": "comment", "D": "commence"}, "answer": "A", "analysis": "易混淆動詞辨析：commend sb. for sth. 指『因某事表揚/稱讚某人』。(B) command 為命令/指揮；(C) comment 為評論；(D) commence 為開始。選 (A)。", "translation": "系主任在典禮上特別抽出時間，表揚團隊成員的傑出奉獻精神。"}, {"id": 17, "target_seconds": 15, "question": "The advisory board consists ________ five distinguished industry professionals and two university scholars.", "options": {"A": "of", "B": "in", "C": "with", "D": "at"}, "answer": "A", "analysis": "介系詞搭配秒殺：consist of（由……組成）。consist 固定搭配 of，不及物無被動態。選 (A)。", "translation": "該顧問委員會由五位傑出的業界專家及兩位大學學者組成。"}, {"id": 18, "target_seconds": 15, "question": "Employees must submit all official travel receipts ________ to requesting expense reimbursements.", "options": {"A": "prior", "B": "previous", "C": "beforehand", "D": "ahead"}, "answer": "A", "analysis": "介系詞片語秒殺：prior to + V-ing（在……之前）。ahead 須接 of。選 (A)。", "translation": "員工在申請差旅費報銷之前，必須提交所有正式差旅收據。"}, {"id": 19, "target_seconds": 20, "question": "The company's new line of commercial appliances is known for its rugged ________ under heavy kitchen use.", "options": {"A": "durability", "B": "durable", "C": "durably", "D": "duration"}, "answer": "A", "analysis": "名詞受詞：its rugged (形容詞) + [名詞]。durability 指『耐用性/耐久度』。(B) 為形容詞；(C) 為副詞；(D) duration 為持續時間。選 (A)。", "translation": "該公司新推出的商用電器系列，以在重度廚房使用環境下的堅固耐用性而著稱。"}, {"id": 20, "target_seconds": 15, "question": "The facilities manager must ________ scheduled maintenance on all central cooling units before summer.", "options": {"A": "conduct", "B": "conduction", "C": "conductive", "D": "conductor"}, "answer": "A", "analysis": "情態助動詞後接及物動詞：must + [原形動詞] + maintenance (受詞)。conduct maintenance 指『執行維護保養』。選 (A)。", "translation": "設施經理必須在夏季來臨前，對所有中央冷卻設備執行定期維護保養。"}]}, "afternoon": {"quick_recall": [{"prompt": "The storm caused extensive ________ [不可數名詞，損害] to roofs.", "clue": "損害（不可加 -s）", "answer": "damage"}, {"prompt": "The storm might ________ [及物動詞，使損害] the antennae.", "clue": "破壞/使受損（動詞原形）", "answer": "damage"}, {"prompt": "Luxury hotel ________ [名詞，住宿/住處] for delegates.", "clue": "住宿設施（a開頭複數名詞）", "answer": "accommodations"}, {"prompt": "Keep carry-on luggage out of the ________ [名詞，走道].", "clue": "機艙走道（a開頭）", "answer": "aisle"}, {"prompt": "Employees must wear formal business ________ [名詞，服裝/著裝].", "clue": "服裝正裝（a開頭不可數）", "answer": "attire"}, {"prompt": "The CEO took time to ________ [動詞，表揚稱讚] the sales team.", "clue": "表揚（c開頭動詞）", "answer": "commend"}], "spaced_traps": [{"id": 1, "question": "The airline will compensate travelers for any ________ sustained by checked baggage during transit.", "options": {"A": "damage", "B": "damages", "C": "damaging", "D": "damaged"}, "answer": "A", "trap_point": "damage 表『物品實體受損』為不可數名詞，不可加 -s！damages 加 -s 是法律賠償金！", "analysis": "句意是託運行李在運送過程中所遭受的『損壞』，表受損之不可數名詞選 (A) damage。damages 是複數法律名詞『損害賠償金』，此處不符。", "translation": "航空公司將對託運行李在運送途中所遭受的任何損壞向旅客進行賠償。"}, {"id": 2, "question": "A sudden electrical power surge could severely ________ sensitive laboratory equipment.", "options": {"A": "damage", "B": "damages", "C": "damaged", "D": "damaging"}, "answer": "A", "trap_point": "could + [副詞 -ly] + 原形動詞 damage！", "analysis": "情態助動詞 could 與及物動詞 damage 之間夾入副詞 severely，空格需填入及物動詞原形 (A) damage。", "translation": "突發的突波電壓可能會嚴重損壞精密的實驗室設備。"}, {"id": 3, "question": "Conference organizers arranged five-star hotel ________ for all visiting dignitaries.", "options": {"A": "accommodations", "B": "accommodate", "C": "accommodating", "D": "accommodated"}, "answer": "A", "trap_point": "名詞受詞選 accommodations（住宿）。accommodate 是動詞！", "analysis": "arranged + hotel [名詞受詞]，表示提供住宿，需用名詞 (A) accommodations。", "translation": "大會籌辦方為所有來訪貴賓安排了五星級飯店住宿。"}, {"id": 4, "question": "All personnel attending the awards gala are required to wear formal evening ________.", "options": {"A": "attire", "B": "attires", "C": "attired", "D": "attiring"}, "answer": "A", "trap_point": "attire（服裝）為不可數名詞，絕對不能加 -s！", "analysis": "attire 泛指正式服裝，為不可數名詞，不可選 (B) attires。選 (A) attire。", "translation": "出席頒獎晚宴的所有人員均需穿著正式晚禮服。"}, {"id": 5, "question": "The marketing department published a full-color ________ detailing new investment products.", "options": {"A": "brochure", "B": "aisle", "C": "canvas", "D": "closure"}, "answer": "A", "trap_point": "名詞字義：brochure 指介紹產品的宣傳手冊。", "analysis": "句意修飾 published a full-color... 介紹投資產品，選名詞 (A) brochure（小冊子）。", "translation": "行銷部門發行了一份全彩小冊子，詳細介紹了新投資產品。"}, {"id": 6, "question": "The renovated concert hall has a maximum audience ________ of two thousand guests.", "options": {"A": "capacity", "B": "capably", "C": "capable", "D": "capacitance"}, "answer": "A", "trap_point": "audience capacity 指觀眾容量/容納人數，選名詞 capacity！", "analysis": "複合名詞結構，修飾容納人數需用名詞 (A) capacity。", "translation": "翻新後的音樂廳最大觀眾容納量為 2,000 位賓客。"}, {"id": 7, "question": "The executive committee voted to ________ the quarterly performance review until next week.", "options": {"A": "put off", "B": "step down", "C": "take over", "D": "back down"}, "answer": "A", "trap_point": "put off = postpone / delay（推遲延期）。", "analysis": "受詞為 quarterly performance review，時間延至下週，選 (A) put off。", "translation": "執行委員會投票決定將季度績效考核推遲到下週進行。"}, {"id": 8, "question": "Customer service representatives must respond ________ to all online warranty inquiries.", "options": {"A": "promptly", "B": "prompt", "C": "promptness", "D": "prompting"}, "answer": "A", "trap_point": "respond (不及物動詞) + [副詞 -ly]！", "analysis": "修飾動詞 respond 必須填入副詞 (A) promptly（迅速地）。", "translation": "客戶服務代表必須迅速回覆所有線上保固諮詢。"}, {"id": 9, "question": "The airline promised to compensate the passenger in full for any ________ to personal property.", "options": {"A": "damage", "B": "damages", "C": "damaging", "D": "damaged"}, "answer": "A", "trap_point": "damage 表損害為不可數名詞！damages 是法律賠償金！", "analysis": "選不可數名詞 (A) damage。", "translation": "航空公司承諾就個人財產所受的任何損害向旅客進行全額賠償。"}, {"id": 10, "question": "The international convention organizers booked five-star hotel ________ for all visiting dignitaries.", "options": {"A": "accommodations", "B": "accommodate", "C": "accommodating", "D": "accommodated"}, "answer": "A", "trap_point": "hotel accommodations 指飯店住宿，選名詞 accommodations！", "analysis": "名詞受詞選 (A) accommodations。", "translation": "國際大會籌辦方為所有來訪貴賓預訂了五星級飯店住宿。"}, {"id": 11, "question": "Flight attendants reminded travelers not to leave bags in the center ________ during landing.", "options": {"A": "aisle", "B": "isle", "C": "canvas", "D": "appliance"}, "answer": "A", "trap_point": "aisle 指走道通道；isle 是小島！", "analysis": "走道選 (A) aisle。", "translation": "空服員提醒旅客降落期間勿將行李留在中央走道上。"}, {"id": 12, "question": "All personnel attending the gala dinner are expected to wear formal business ________.", "options": {"A": "attire", "B": "attires", "C": "attired", "D": "attiring"}, "answer": "A", "trap_point": "attire（服裝）為不可數名詞，不可加 -s！", "analysis": "不可數名詞選 (A) attire。", "translation": "出席晚宴的所有人員預期應穿著正式商務正裝。"}, {"id": 13, "question": "The marketing division published an informative ________ detailing overseas investment opportunities.", "options": {"A": "brochure", "B": "closure", "C": "aisle", "D": "canvas"}, "answer": "A", "trap_point": "brochure（宣傳手冊/小冊子）。", "analysis": "選名詞 (A) brochure。", "translation": "行銷部門發行了一份詳細介紹海外投資機會的宣傳手冊。"}, {"id": 14, "question": "The chief executive officer took time during the annual briefing to ________ top sales performers.", "options": {"A": "commend", "B": "comment", "C": "command", "D": "commence"}, "answer": "A", "trap_point": "commend sb.（表揚某人）。", "analysis": "表揚銷售拔尖人員，選 (A) commend。", "translation": "執行長在年度簡報會上特別抽出時間表揚優秀銷售同仁。"}], "part7": {"passages": [{"text_type": "Airline Passenger Notice (航空公司行李與客艙規範手冊)", "title": "Meridian Airlines — Luggage Allowance, Aisle Regulations & Damage Compensation", "content": "PASSENGER SERVICE BULLETIN: MA-CABIN-2026-08\nISSUED BY: In-Flight Safety & Customer Service Directorate, Meridian Airlines\nDATE: November 11, 2026\nMANDATORY FOR: All Gate Agents, Flight Crews, and Traveling Passengers\n\n1. Cabin Baggage Safety & Aisle Clearance\nTo ensure passenger safety during boarding and rapid emergency evacuation procedures, flight attendants must ensure that carry-on baggage is placed entirely under seats or inside overhead compartments, keeping the main aircraft aisle completely unobstructed at all times during taxi, takeoff, and landing operations.\n\n2. Checked Baggage Damage Claims Procedure\nMeridian Airlines handles checked baggage with extreme care throughout our automated baggage handling facilities. In the unfortunate event that luggage sustains physical damage during transit, passengers must file a formal claim at the baggage service counter prior to exiting the airport customs hall. Meridian Airlines will compensate travelers up to $1,500 for documented structural damage.\n\n*Exclusion Clause: Normal cosmetic wear and tear resulting from standard automated baggage handling systems—such as minor scratches and cosmetic scuffs, small fabric tears, or missing zipper pulls—is explicitly excluded from baggage damage compensation. Inspect luggage thoroughly before customs exit.", "questions": [{"question": "Why must the main aircraft aisle remain clear during boarding?", "options": {"A": "To ensure passenger safety.", "B": "To allow meal cart preparation.", "C": "To facilitate ticket re-examinations.", "D": "To accommodate first-class luggage."}, "answer": "A", "radar": "🔍 防漏看雷達：目的說明 'To ensure passenger safety during boarding'！", "analysis": "第一段第一句明確指出：保持主走道暢通是為了確保旅客登機時的安全，故選 (A)。"}, {"question": "When must a passenger file a checked baggage damage claim?", "options": {"A": "Prior to exiting the airport customs hall.", "B": "Within seven business days via email.", "C": "Before checking into their hotel.", "D": "Upon purchasing their initial boarding pass."}, "answer": "A", "radar": "🔍 防漏看雷達：申報時限條件 'prior to exiting the customs hall'！", "analysis": "星號小字第一句指出：行李受損必須在走出海關大廳之前向行李服務櫃台提出申報，故選 (A)。"}, {"question": "What is explicitly EXCLUDED from baggage damage compensation?", "options": {"A": "Minor scratches and cosmetic scuffs.", "B": "Broken suitcase wheels and handles.", "C": "Water leakage from exterior storms.", "D": "Lost electronic travel adapters."}, "answer": "A", "radar": "🔍 防漏看雷達：除外條款細節 'Normal cosmetic wear and tear, including minor scratches and scuffs, is strictly exempted'！", "analysis": "文末最後一句明確載明：輕微刮痕與磨損等外觀正常損耗，嚴格排除在賠償範圍之外，故選 (A)。"}]}, {"text_type": "Corporate Symposium Guidelines (國際研討會差旅與服儀規範)", "title": "Global Operations Office — Executive Travel Accommodations & Attire Standards", "content": "MEMORANDUM: GLOBAL-SYMP-2026-08\nTO: Senior Regional Representatives and Market Analysts\nFROM: Global Operations Office & Executive Hospitality Committee\nDATE: November 11, 2026\nSUBJECT: International Business Symposium — Lodging, Attire Standards, and Credentials\n\n1. Official Conference Hotel Accommodations\nCorporate travel coordinators have finalized all delegate bookings for the upcoming Annual International Business Symposium. All invited senior regional representatives will stay at the Grand Plaza hotel, located adjacent to the downtown convention center. Hotel check-in commences at 3:00 PM on Wednesday, with room, tax, and high-speed internet direct-billed to corporate headquarters.\n\n2. Professional Dress Code Standards\nDaytime conference sessions, executive roundtables, and formal dinners require standard professional business attire (business suits, collared shirts, blazers, and dress shoes). As an exception to our corporate dress standard, business casual attire is acceptable solely during Thursday evening's welcome mixer in the hotel courtyard.\n\n*Prohibition on Athletic Wear: Delegates are reminded that athletic clothing, including sportswear, hoodies, running shoes, and denim, is strictly forbidden during all official event sessions. Individuals who wear athletic clothing will be barred from conference proceedings by event marshals at venue checkpoints.", "questions": [{"question": "Where will regional representatives stay during the symposium?", "options": {"A": "At the Grand Plaza hotel.", "B": "In university dormitories.", "C": "At suburban vacation suites.", "D": "Inside the trade venue apartments."}, "answer": "A", "radar": "🔍 防漏看雷達：住宿地點 'finalized hotel accommodations at the Grand Plaza'！", "analysis": "第一段第一句明確指出：所有與會者的飯店住宿安排在 Grand Plaza，故選 (A)。"}, {"question": "When is business casual attire acceptable?", "options": {"A": "Solely during Thursday evening's welcome mixer.", "B": "Throughout all afternoon panel debates.", "C": "During Friday morning breakfast briefings.", "D": "Whenever traveling on corporate shuttles."}, "answer": "A", "radar": "🔍 防漏看雷達：唯一除外時段 'permissible solely during the informal welcome mixer on Thursday evening'！", "analysis": "星號小字第二句指出：商務休閒服裝僅在週四晚間的非正式迎賓聚會中被允許，故選 (A)。"}, {"question": "What will happen to individuals who wear athletic clothing?", "options": {"A": "They will be barred from conference proceedings.", "B": "They must pay an attire violation fine of $50.", "C": "They are required to purchase official gala robes.", "D": "Their hotel reservations will be canceled."}, "answer": "A", "radar": "🔍 防漏看雷達：嚴格罰則 'Attendees arriving in athletic wear will be barred from conference proceedings'！", "analysis": "文末最後一句明確規定：穿著運動服裝的人員將被禁止參加會議議程，故選 (A)。"}]}]}}}, "9": {"day": 9, "date": "11/12", "phase": 1, "phase_name": "錯題庫清零與語感校正", "topic": "不定代名詞範圍判定 ｜ 文宣手冊與容量承載", "morning": {"chunks": [{"chunk": "one another in the team", "meaning": "團隊彼此互相（三人以上）", "scenario": "Colleagues are encouraged to assist one another in the team during peak hours.", "paraphrase": "one another = each other", "alert": "文法考點：one another 與 each other 是代名詞，通常當受詞，不能直接當主詞！"}, {"chunk": "broaden client outreach", "meaning": "拓展客戶觸及範圍", "scenario": "The marketing team launched campaigns to broaden client outreach in suburban districts.", "paraphrase": "broaden = expand = widen", "alert": ""}, {"chunk": "promotional brochure or flier", "meaning": "宣傳小冊或傳單", "scenario": "Volunteers distributed a promotional brochure or flier at the subway exit.", "paraphrase": "brochure = pamphlet = booklet = flier / flyer", "alert": "多益常考三胞胎：brochure / pamphlet / flier 通通是文宣小冊子！"}, {"chunk": "reach maximum capacity", "meaning": "達到最大容納量 / 產能", "scenario": "The auditorium reached maximum capacity minutes before the keynote address.", "paraphrase": "capacity = volume = maximum occupancy", "alert": ""}, {"chunk": "perform tasks capably", "meaning": "幹練稱職地執行任務", "scenario": "Despite her young age, she performed tasks capably under intense deadline pressure.", "paraphrase": "capably = competently = adeptly", "alert": ""}, {"chunk": "hire a local caterer", "meaning": "聘請當地外燴廠商", "scenario": "The event coordinator decided to hire a local caterer for the banquet dinner.", "paraphrase": "caterer = food service provider", "alert": ""}, {"chunk": "temporary road closure", "meaning": "臨時道路封閉", "scenario": "Commuters were alerted to a temporary road closure along Main Street.", "paraphrase": "closure = shutdown = blockage", "alert": ""}], "visual_anchor": {"title": "不定代名詞秒殺：看後面有沒有名詞，以及是單數還是複數？", "rule_1": "👀 空格後有【單數名詞】➔ 選 another（another branch 另一家分行）", "rule_2": "👀 空格後有【複數名詞】➔ 選 other（other branches 其他分行）", "rule_3": "👀 空格後【沒有名詞，自己獨立站著】➔ 選 others（其他的人事物）或 the others（剩下的全部）", "golden_rule": "⚡ 教練金句：後有單數選 another，後有複數選 other，後無名詞選 others！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "The five regional project directors hold weekly virtual briefings to coordinate with ________.", "options": {"A": "one another", "B": "other", "C": "another", "D": "every other"}, "answer": "A", "analysis": "不定代名詞秒殺：主詞明確為 'The five regional directors'（五位總監，三者以上）。三者以上彼此互相用代名詞片語 (A) one another。兩者互相用 each other；other 為形容詞不能單獨作受詞。", "translation": "五位區域專案總監每週舉行線上簡報會，以便相互協調合作。"}, {"id": 2, "target_seconds": 15, "question": "One of the factory generators is undergoing routine repairs, while ________ is operating at full capacity.", "options": {"A": "the other", "B": "other", "C": "another", "D": "others"}, "answer": "A", "analysis": "不定代名詞對比秒殺：兩台發電機中的一台與另一台，結構為 'One ..., while the other ...'。特指剩下的那另一個用 (A) the other。(C) another 指三者以上未特指的另一個；(B) other 不能單獨作主詞。", "translation": "其中一台工廠發電機正在進行定期維修，而另一台則在滿載運轉。"}, {"id": 3, "target_seconds": 15, "question": "Several members preferred the morning flight, while ________ opted to travel on the afternoon express train.", "options": {"A": "others", "B": "other", "C": "another", "D": "the another"}, "answer": "A", "analysis": "不定代名詞秒殺：Some / Several ..., while others ...（一些人……，而其他人……）。others 為代名詞複數，指其他的人，直接作主詞。(B) other 為形容詞，後需接複數名詞。", "translation": "幾位成員偏好搭乘早班機，而其他人則選擇搭乘下午的特快列車。"}, {"id": 4, "target_seconds": 15, "question": "The executive committee is scheduled to reconvene for ________ round of contract negotiations next Tuesday.", "options": {"A": "another", "B": "other", "C": "others", "D": "the others"}, "answer": "A", "analysis": "不定代名詞修飾單數名詞：another + [單數可數名詞 round]。another round of 指『另一輪……』。(B) other 後需接複數名詞；(C) 為代名詞。", "translation": "執行委員會預計於下週二再次開會，進行另一輪合約談判。"}, {"id": 5, "target_seconds": 15, "question": "The university library plans to ________ its collection of digital trade publications next year.", "options": {"A": "broaden", "B": "broad", "C": "broadly", "D": "broadness"}, "answer": "A", "analysis": "不定詞後接動詞原形：plans to + [動詞] + its collection (受詞)。broaden 指『擴充/擴展』。(B) 為形容詞；(C) 為副詞。選 (A)。", "translation": "大學圖書館計畫明年擴充其數位貿易出版品的館藏。"}, {"id": 6, "target_seconds": 15, "question": "Please review the informational ________ enclosed in the welcome packet for workshop schedules.", "options": {"A": "pamphlet", "B": "canvas", "C": "dues", "D": "threshold"}, "answer": "A", "analysis": "商務名詞辨析：informational pamphlet 指『資訊手冊/小冊子』。(B) canvas 為帆布；(C) dues 為會費；(D) threshold 為門檻。選 (A)。", "translation": "請檢閱歡迎資料袋內附的資訊小手冊，以了解工作坊的時程表。"}, {"id": 7, "target_seconds": 20, "question": "The newly constructed data warehouse has the ________ to store over fifty petabytes of encrypted analytics.", "options": {"A": "capacity", "B": "capacitance", "C": "capably", "D": "capable"}, "answer": "A", "analysis": "名詞受詞：has the + [名詞] + to store...。capacity to do sth. 指『做某事的能力/容量』。選名詞 (A)。", "translation": "新建立的資料倉儲具備儲存超過 50PB 加密分析數據的容量。"}, {"id": 8, "target_seconds": 15, "question": "The newly promoted logistics supervisor performed all warehousing duties ________ during the seasonal surge.", "options": {"A": "capably", "B": "capable", "C": "capability", "D": "capacities"}, "answer": "A", "analysis": "副詞修飾動詞：performed all duties + [副詞]。capably 指『能幹勝任地』。選副詞 (A)。", "translation": "新升任的物流主管在旺季暴增期間幹練妥善地執行了所有倉儲職責。"}, {"id": 9, "target_seconds": 15, "question": "The event coordinator signed a formal contract with an approved ________ for the annual luncheon banquet.", "options": {"A": "caterer", "B": "catering", "C": "catered", "D": "caters"}, "answer": "A", "analysis": "名詞受詞（指人）：with an approved + [單數名詞指人]。caterer 指『外燴廠商』。選 (A)。", "translation": "活動協調員與一家核准的外燴廠商簽署了年度午宴的正式合約。"}, {"id": 10, "target_seconds": 15, "question": "Commuters experienced significant travel delays owing to the unexpected ________ of the suspension bridge.", "options": {"A": "closure", "B": "close", "C": "closely", "D": "closing"}, "answer": "A", "analysis": "名詞受詞：the unexpected + [名詞] + of the bridge。closure 指『封閉 / 關閉』。選 (A)。", "translation": "由於吊橋意外封閉，通勤族遭遇了嚴重的交通延誤。"}, {"id": 11, "target_seconds": 15, "question": "The municipal planning ________ voted unanimously to approve the waterfront redevelopment initiative.", "options": {"A": "council", "B": "counsel", "C": "counselor", "D": "counseling"}, "answer": "A", "analysis": "易混淆字名詞辨析：planning council 指『規劃委員會 / 市議會』。(B) counsel 為法律顧問/勸告；(C) counselor 為心理諮商師。選 (A)。", "translation": "市政規劃委員會全體一致投票通過了水岸再開發計畫。"}, {"id": 12, "target_seconds": 20, "question": "A prominent culinary ________ praised the restaurant for its innovative seasonal tasting menu.", "options": {"A": "critic", "B": "criticism", "C": "critical", "D": "critically"}, "answer": "A", "analysis": "主詞身分指人：A prominent culinary + [名詞指人] + praised (動詞)。critic 指『評論家/美食家』。(B) criticism 為批評（抽象名詞）；(C) critical 為形容詞批判的。選 (A)。", "translation": "一位知名美食評論家稱讚了該餐廳創新的季節品嘗套餐。"}, {"id": 13, "target_seconds": 15, "question": "The midtown commercial district is ________ populated with financial technology corporations.", "options": {"A": "densely", "B": "dense", "C": "density", "D": "denseness"}, "answer": "A", "analysis": "副詞修飾過去分詞：is + [副詞 -ly] + populated (p.p.)。densely populated 指『密集分佈的/人口稠密的』。選副詞 (A)。", "translation": "市中心商業區密集分佈著金融科技公司。"}, {"id": 14, "target_seconds": 15, "question": "Tenants are required to pay a non-refundable security ________ of $500 prior to receiving their apartment keys.", "options": {"A": "deposit", "B": "deposited", "C": "depositing", "D": "depositor"}, "answer": "A", "analysis": "商務複合名詞：security deposit 指『押金 / 保證金』。deposit 為名詞。選 (A)。", "translation": "房客在領取公寓鑰匙之前，必須支付 500 美元的不可退還保證金。"}, {"id": 15, "target_seconds": 15, "question": "The facility manager will ________ two parking bays exclusively for electric delivery vans.", "options": {"A": "designate", "B": "designation", "C": "designated", "D": "designative"}, "answer": "A", "analysis": "助動詞後接及物動詞：will + [原形動詞] + two bays (受詞)。designate 指『指定/指派』。(B) designation 為名詞。選 (A)。", "translation": "廠區經理將專門指定兩個停車位供電動貨車專用。"}, {"id": 16, "target_seconds": 20, "question": "While one technician checked the wiring, ________ technician calibrated the pressure gauges.", "options": {"A": "the other", "B": "another", "C": "others", "D": "other"}, "answer": "A", "analysis": "兩者對比修飾單數名詞：兩位技術員中的一位與另一位，'While one technician ..., the other technician ...'。特指剩餘的那一位用 (A) the other。(D) other 修飾複數名詞。", "translation": "當其中一位技術員檢查線路時，另一位技術員則校準了壓力表。"}, {"id": 17, "target_seconds": 15, "question": "The software vendor issued a patch to correct glitches, and ________ will be released next month.", "options": {"A": "another", "B": "other", "C": "the other", "D": "others"}, "answer": "A", "analysis": "不定代名詞代稱單數：前面提到 a patch，後面表示『另一個（未限定範圍的修補檔）』將於下月發布，用單數代名詞 (A) another。(B) other 不能單獨作主詞；(C) the other 需在有特定兩者時使用。", "translation": "該軟體廠商發布了修正錯誤的修補檔，且下個月還將發布另一個。"}, {"id": 18, "target_seconds": 15, "question": "Some board members voted in favor of the proposal, but ________ voiced strong reservations.", "options": {"A": "others", "B": "other", "C": "another", "D": "each other"}, "answer": "A", "analysis": "Some ..., but others ...（一些人……，但其他人……）。others 為複數代名詞獨立作主詞。選 (A)。", "translation": "一些董事會成員投票贊成該提案，但其他人則表達了強烈保留意見。"}, {"id": 19, "target_seconds": 20, "question": "Before finalizing the brochure layout, the graphic designer consulted with ________ team members.", "options": {"A": "other", "B": "others", "C": "another", "D": "the others"}, "answer": "A", "analysis": "形容詞修飾複數名詞：[形容詞] + team members (複數名詞)。other 修飾複數名詞，指『其他團隊成員』。others 本身為代名詞不可再修飾名詞。選 (A)。", "translation": "在敲定宣傳手冊版面之前，平面設計師諮詢了其他團隊成員。"}, {"id": 20, "target_seconds": 15, "question": "International trade delegates exchanged business cards and contact information with ________ at the reception.", "options": {"A": "one another", "B": "another", "C": "other", "D": "every other"}, "answer": "A", "analysis": "代名詞片語秒殺：with [one another]（彼此互相交換）。delegates 為眾多與會代表（三者以上），互通有無選 (A) one another。", "translation": "國際貿易代表在接待酒會上彼此交換了名片與聯絡方式。"}]}, "afternoon": {"quick_recall": [{"prompt": "The three directors cooperate with ________ [彼此互相，三者以上].", "clue": "三者以上彼此（o開頭）", "answer": "one another"}, {"prompt": "Two partners respect ________ [彼此互相，兩者].", "clue": "兩者互相（e開頭）", "answer": "each other"}, {"prompt": "One is red; ________ [特指剩下的那一個] is blue.", "clue": "特指另一個（t開頭兩個字）", "answer": "the other"}, {"prompt": "Some left early, while ________ [其他人，複數代名詞] stayed.", "clue": "其他人（o開頭代名詞複數）", "answer": "others"}, {"prompt": "Consulted with ________ [形容詞，其他的] team members.", "clue": "修飾複數名詞的形容詞", "answer": "other"}, {"prompt": "Would you like ________ [代名詞/形容詞，另一個] cup of coffee?", "clue": "另一個（a開頭單數）", "answer": "another"}], "spaced_traps": [{"id": 1, "question": "The four division supervisors regularly consult with ________ to resolve operational bottlenecks.", "options": {"A": "one another", "B": "other", "C": "another", "D": "the other"}, "answer": "A", "trap_point": "三者以上互相用 one another！兩者互相用 each other！", "analysis": "主詞明確為 'The four division supervisors'（四位主管，大於兩位），表示群體之間彼此相互諮詢，固定選代名詞 (A) one another。", "translation": "四位部門主管定期相互諮詢，以解決營運瓶頸。"}, {"id": 2, "question": "The company operates two factories in Asia; one produces microchips, and ________ manufactures display monitors.", "options": {"A": "the other", "B": "another", "C": "other", "D": "others"}, "answer": "A", "trap_point": "明確設定兩者 (two factories)！one ... and the other ...！", "analysis": "開頭明確說明只有兩家工廠 (two factories)。兩者對比中，特指剩下的另一家必定用 (A) the other。another 用於三者以上未限定之另一個。", "translation": "該公司在亞洲經營兩家工廠；一家生產微晶片，另一家則製造顯示螢幕。"}, {"id": 3, "question": "Some attendees preferred the printed agenda, while ________ downloaded the mobile event app.", "options": {"A": "others", "B": "other", "C": "another", "D": "the other"}, "answer": "A", "trap_point": "Some ..., while others ...（代名詞複數主詞）！", "analysis": "空格位於 while 子句的主詞位置，後接動詞 downloaded。指『其他的人們』，需用代名詞複數 (A) others。other 只是形容詞，不能單獨作主詞。", "translation": "一些與會者偏好紙本議程，而其他人則下載了活動的手機應用程式。"}, {"id": 4, "question": "The human resources manager requested ________ copy of the revised employment contract.", "options": {"A": "another", "B": "other", "C": "others", "D": "the others"}, "answer": "A", "trap_point": "another + 單數可數名詞 copy！other 需接複數名詞！", "analysis": "空格後接單數名詞 'copy'。another copy 指『另一份複本』，選 (A)。(B) other 後接複數名詞。", "translation": "人資經理要求再提供一份修改後僱用合約的複本。"}, {"id": 5, "question": "The marketing department published an informational ________ explaining the benefits of clean energy.", "options": {"A": "brochure", "B": "closure", "C": "aisle", "D": "canvas"}, "answer": "A", "trap_point": "brochure 指介紹產品或議題的文宣小冊子。", "analysis": "修飾 published an informational... 選名詞 (A) brochure（宣傳冊）。", "translation": "行銷部門發布了一份說明乾淨能源效益的宣傳手冊。"}, {"id": 6, "question": "The main auditorium has a maximum seated ________ of eight hundred delegates.", "options": {"A": "capacity", "B": "capably", "C": "capable", "D": "capacities"}, "answer": "A", "trap_point": "seated capacity 指座位容量/席位。", "analysis": "複合名詞修飾容納數量，選名詞 (A) capacity。", "translation": "大禮堂的最大席位容量為 800 位與會代表。"}, {"id": 7, "question": "The city council ordered an immediate ________ of the downtown tunnel for emergency drainage repairs.", "options": {"A": "closure", "B": "close", "C": "closely", "D": "closing"}, "answer": "A", "trap_point": "ordered an immediate + [名詞] closure（封閉/關閉）。", "analysis": "冠詞 an + 形容詞 immediate + [名詞]。tunnel closure 指隧道封閉，選 (A)。", "translation": "市議會下令立即封閉市中心隧道，以進行緊急排水維修。"}, {"id": 8, "question": "The catering manager hired ten temporary servers to ensure that banquet guests were served ________.", "options": {"A": "promptly", "B": "prompt", "C": "promptness", "D": "prompting"}, "answer": "A", "trap_point": "were served (被動動詞) + [副詞 -ly]！", "analysis": "副詞修飾動詞短語 were served，promptly 表迅速及時地，選 (A)。", "translation": "外燴經理聘請了十位臨時服務生，以確保宴會賓客獲得迅速即時的服務。"}, {"id": 9, "question": "The five regional branch directors cooperate closely with ________ to optimize supply chain delivery.", "options": {"A": "one another", "B": "other", "C": "another", "D": "each other"}, "answer": "A", "trap_point": "五位總監（三者以上）彼此互相用 one another！", "analysis": "三者以上互相選 (A) one another。", "translation": "五位區域分部總監彼此密切合作，以優化供應鏈配送。"}, {"id": 10, "question": "The corporation operates two warehouses; one is in Chicago, and ________ is located in Dallas.", "options": {"A": "the other", "B": "another", "C": "others", "D": "other"}, "answer": "A", "trap_point": "兩者限定（two warehouses）！one ... the other ...！", "analysis": "特指剩下的另一座倉庫，選 (A) the other。", "translation": "該公司經營兩座倉庫；一座在芝加哥，另一座則位於達拉斯。"}, {"id": 11, "question": "Some delegates stayed for the evening banquet, while ________ returned to their hotel rooms.", "options": {"A": "others", "B": "other", "C": "another", "D": "each other"}, "answer": "A", "trap_point": "Some ..., while others ...（代名詞複數主詞）！", "analysis": "代名詞複數主詞選 (A) others。", "translation": "一些代表留下來參加晚宴，而其他人則返回了飯店房間。"}, {"id": 12, "question": "The graphic designer requested ________ copy of the promotional brochure before printing.", "options": {"A": "another", "B": "other", "C": "others", "D": "the others"}, "answer": "A", "trap_point": "another + 單數名詞 copy！", "analysis": "修飾單數名詞 copy，選 (A) another。", "translation": "平面設計師在印刷前要求再提供一份宣傳手冊的複本。"}, {"id": 13, "question": "The main amphitheater has a maximum seating ________ of one thousand delegates.", "options": {"A": "capacity", "B": "capably", "C": "capable", "D": "capacities"}, "answer": "A", "trap_point": "seating capacity 指座位容量，選名詞 capacity！", "analysis": "名詞選 (A) capacity。", "translation": "主露天劇場的最大席位容量為 1,000 位代表。"}, {"id": 14, "question": "Municipal authorities ordered an immediate bridge ________ to conduct seismic structural inspections.", "options": {"A": "closure", "B": "close", "C": "closely", "D": "closing"}, "answer": "A", "trap_point": "bridge closure（大橋封閉）為複合名詞！", "analysis": "選名詞 (A) closure。", "translation": "市政當局下令立即封閉大橋，以進行抗震結構檢測。"}], "part7": {"passages": [{"text_type": "Event Facility Rental Brochure (活動場地租賃規範與手冊)", "title": "Riverside Arts Center — Facility Rentals, Capacity Limits & Catering Protocols", "content": "EVENT VENUE CHARTER: RAC-RENT-2026-09\nVENUE LOCATION: Riverside Arts & Convention Center, Waterfront Plaza\nISSUED BY: Commercial Events & Banquet Booking Bureau\nDATE: November 12, 2026\n\n1. Room Specifications & Banquet Capacities\nThe Riverside Arts Center offers modern event spaces for corporate banquets, product exhibitions, and executive conferences. The premier Grand Pavilion can accommodate up to 350 guests for seated dinner banquets and up to 500 attendees for standing cocktail receptions. Smaller presentation suites and executive boardrooms are available on the second mezzanine.\n\n2. Exclusive Catering & Food Safety Standards\nTo comply with municipal hygiene codes and liquor licensing statutes, outside food and beverage are strictly prohibited within all venue facilities. All banquet catering, meal services, and refreshment bars must be provided by licensed partner caterers selected from the facility's certified culinary registry. Special dietary accommodations must be finalized ten business days in advance.\n\n*Payment Terms and Booking Confirmation: A non-refundable 25% deposit is required at reservation signing to secure the date. The remaining venue rental balance must be paid thirty days prior to the event date. Late payments will incur a 5% monthly compounding administrative penalty and may result in immediate cancellation of facility reservations.", "questions": [{"question": "What is the maximum banquet capacity of the Grand Pavilion?", "options": {"A": "350 guests.", "B": "500 guests.", "C": "200 guests.", "D": "1,000 guests."}, "answer": "A", "radar": "🔍 防漏看雷達：容納人數細節 'maximum banquet seating capacity of 350 guests'！", "analysis": "第一段第二句清楚說明：大廳的宴會最大座位容納量為 350 人，故選 (A)。"}, {"question": "What catering restriction applies to all booked events?", "options": {"A": "Food must be provided by licensed partner caterers.", "B": "Clients must cook their own meals on-site.", "C": "All beverages must be brought in by guests.", "D": "External restaurants are allowed on weekends."}, "answer": "A", "radar": "🔍 防漏看雷達：供應商限制 'must be coordinated through our list of licensed partner caterers'！", "analysis": "星號小字第一句指出：所有餐飲必須由名冊上的持證合作外燴廠商提供，嚴禁外部廠商，故選 (A)。"}, {"question": "When must the remaining venue rental balance be paid?", "options": {"A": "Thirty days prior to the event date.", "B": "Upon initial booking confirmation.", "C": "At the conclusion of the banquet evening.", "D": "Within twenty-four hours after booking."}, "answer": "A", "radar": "🔍 防漏看雷達：結清尾款期限 'remaining rental balance must be settled thirty days prior to the event date'！", "analysis": "文末最後一句明確載明：剩餘租金尾款必須在活動日期前 30 天結清，故選 (A)。"}]}, {"text_type": "Municipal Transit Notice (市政交通封路與公車接駁通告)", "title": "Metropolitan Transportation Council — Bridge Closure and Commuter Detour Guidelines", "content": "CIVIC INFRASTRUCTURE ADVISORY: MTC-TRAF-2026-44\nISSUING AGENCY: Metropolitan Transportation Council & Department of Public Works\nDATE: November 12, 2026\nIMPACT ZONE: West Harbor Crossing Corridor\n\n1. Scheduled Weekend Bridge Closure\nThe Metropolitan Transportation Council announces that the West Harbor Suspension Bridge will undergo a complete vehicular and cycling closure this weekend, commencing Friday at 10:00 PM and concluding Monday at 5:00 AM. This closure is necessary to install seismic reinforcement braces and repair structural joint dampeners, following our triennial seismic safety assessment.\n\n2. Alternative Routing & Tunnel Toll Waiver\nMotorists traveling between downtown and the western districts are advised to utilize the Midtown Tunnel as the primary detour route. To alleviate traffic congestion and expedite weekend journeys, toll fees will be temporarily exempted at all Midtown Tunnel toll plazas for the duration of the bridge closure.\n\n*Public Transit & Pedestrian Shuttle Services: Harbor ferry services will operate on an expanded weekend schedule with boats departing every twenty minutes. Furthermore, cross-bay pedestrian shuttle buses will run every fifteen minutes between the north and south transit centers. Detailed detour diagrams and real-time travel alerts are accessible at www.metrotransit.gov/harbor-repair.", "questions": [{"question": "Why is the West Harbor Suspension Bridge closing this weekend?", "options": {"A": "To install seismic reinforcement braces.", "B": "To prepare for an annual road marathon.", "C": "Because of severe river water contamination.", "D": "To repaint the exterior steel pedestrian railings."}, "answer": "A", "radar": "🔍 防漏看雷達：施工原因 'install seismic reinforcement braces throughout the central span'！", "analysis": "第一段第二句明確指出：封閉是為了在中央跨度安裝抗震加固支撐，故選 (A)。"}, {"question": "What special accommodation is offered at the Midtown Tunnel during the closure?", "options": {"A": "Toll fees will be temporarily exempted.", "B": "Speed limits will be doubled for safety.", "C": "Heavy freight trucks are strictly banned.", "D": "Drivers receive free gasoline vouchers."}, "answer": "A", "radar": "🔍 防漏看雷達：通融優惠 'toll fees will be temporarily exempted throughout the closure'！", "analysis": "星號小字第一句指出：建議改道行駛中城隧道，該隧道在封閉期間暫時免收通行費，故選 (A)。"}, {"question": "How often will cross-bay pedestrian shuttle buses run?", "options": {"A": "Every fifteen minutes.", "B": "Every half hour.", "C": "Once per hour.", "D": "Continuously without fixed schedules."}, "answer": "A", "radar": "🔍 防漏看雷達：接駁車班距 'Shuttle buses will operate every fifteen minutes'！", "analysis": "文末指出：接駁巴士每 15 分鐘一班往返於南北海港廣場之間，免費接駁行人與單車客，故選 (A)。"}]}]}}}, "10": {"day": 10, "date": "11/13", "phase": 1, "phase_name": "錯題庫清零與語感校正", "topic": "Phase 1 綜合驗收 ｜ 表揚、全面與當代商務", "morning": {"chunks": [{"chunk": "commend the staff", "meaning": "大力表揚全體員工", "scenario": "The regional director commended the staff for exceeding quarterly sales benchmarks.", "paraphrase": "commend = praise = applaud = compliment", "alert": "易混淆：commend (v.) 表揚讚賞 vs. comment (v./n.) 評論！"}, {"chunk": "a competent manager", "meaning": "一位能幹稱職的經理", "scenario": "Hiring a competent manager helped stabilize the company's manufacturing unit.", "paraphrase": "competent = capable = skilled = proficient", "alert": ""}, {"chunk": "comprehensive training guide", "meaning": "詳盡全面的培訓手冊", "scenario": "The human resources department compiled a comprehensive training guide.", "paraphrase": "comprehensive = thorough = complete = exhaustive", "alert": "易混淆：comprehensive (adj.) 全面的 vs. comprehensible (adj.) 可理解的！"}, {"chunk": "conclusive laboratory evidence", "meaning": "決定性的實驗室證據", "scenario": "Researchers presented conclusive laboratory evidence supporting the new formula.", "paraphrase": "conclusive = definitive = decisive", "alert": ""}, {"chunk": "considerable growth", "meaning": "相當可觀的成長幅度", "scenario": "The pharmaceutical sector achieved considerable growth over the past two quarters.", "paraphrase": "considerable = substantial = significant", "alert": "易混淆：considerable (adj.) 相當多的/可觀的 vs. considerate (adj.) 體貼的！"}, {"chunk": "contemporary office design", "meaning": "當代現代化辦公室設計", "scenario": "The architecture firm specializes in sustainable and contemporary office design.", "paraphrase": "contemporary = modern = current", "alert": ""}, {"chunk": "corridor leading to", "meaning": "通往……的走廊通道", "scenario": "Exit signs are installed along the corridor leading to the emergency stairwell.", "paraphrase": "corridor = hallway = passageway", "alert": ""}], "visual_anchor": {"title": "Phase 1 四大陷阱終極合體雷達", "rule_1": "1️⃣ 看到空格後無動詞 ➔ 介系詞（despite, in spite of, owing to, prior to）", "rule_2": "2️⃣ 看到 while/once 帶受詞 ➔ 主動 -ing，被動 -ed", "rule_3": "3️⃣ 看到 will / has + 空格 + 動詞 ➔ 夾心塞副詞 -ly", "golden_rule": "⚡ 教練金句：秒殺題靠位置，語意題靠語塊搭配！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "The CEO took time during the quarterly meeting to ________ the engineering division for exceeding performance targets.", "options": {"A": "commend", "B": "comment", "C": "command", "D": "commence"}, "answer": "A", "analysis": "動詞語意辨析：commend sb. for sth. 指『因某事表揚/稱讚某人』。(B) comment 需接 on；(C) command 為命令；(D) commence 為開始。選 (A)。", "translation": "執行長在季度會議上特別抽出時間，表揚工程部門超越績效目標。"}, {"id": 2, "target_seconds": 15, "question": "Human resources hired a highly ________ logistics supervisor to oversee distribution operations.", "options": {"A": "competent", "B": "competence", "C": "competently", "D": "competition"}, "answer": "A", "analysis": "形容詞修飾名詞：a highly (副詞) + [形容詞] + supervisor (名詞)。competent 指『稱職有能力的』。(B) 為名詞；(C) 為副詞。選 (A)。", "translation": "人資部門聘請了一位極為稱職優秀的物流主管來監督配銷作業。"}, {"id": 3, "target_seconds": 15, "question": "The new employee orientation handbook provides a ________ overview of company safety policies.", "options": {"A": "comprehensive", "B": "comprehend", "C": "comprehensively", "D": "comprehension"}, "answer": "A", "analysis": "形容詞修飾名詞：a + [形容詞] + overview。comprehensive overview 指『全方位且詳盡的概述』。選形容詞 (A)。", "translation": "新進員工到職手冊對公司的安全政策提供了全面詳盡的概述。"}, {"id": 4, "target_seconds": 15, "question": "Independent lab trials provided ________ proof that the newly formulated battery retains charge twice as long.", "options": {"A": "conclusive", "B": "conclude", "C": "conclusion", "D": "conclusively"}, "answer": "A", "analysis": "形容詞修飾名詞：conclusive proof 指『決定性的/確鑿的證據』。選形容詞 (A)。(D) 為副詞；(C) 為名詞。", "translation": "獨立實驗室的試驗提供了確鑿的證據，證明新配方電池的蓄電時間延長了一倍。"}, {"id": 5, "target_seconds": 20, "question": "The pharmaceutical company invested a ________ amount of capital in researching rare pediatric illnesses.", "options": {"A": "considerable", "B": "considerate", "C": "considerably", "D": "consideration"}, "answer": "A", "analysis": "易混淆形容詞辨析：a considerable amount 指『相當可觀的數量/金額』。(B) considerate 指體貼有同理心的（修飾人）。選 (A)。", "translation": "這家製藥公司投入了相當可觀的資金用於研究罕見兒童疾病。"}, {"id": 6, "target_seconds": 15, "question": "The architecture firm transformed the historic brick warehouse into a stylish, ________ workspace.", "options": {"A": "contemporary", "B": "contemporaneously", "C": "contemplate", "D": "contempt"}, "answer": "A", "analysis": "形容詞修飾名詞：contemporary workspace 指『當代現代風格的工作空間』。contemporary 為多益高頻形容詞。選 (A)。", "translation": "該建築事務所將這座歷史悠久的磚造倉庫改建為時尚現代的工作空間。"}, {"id": 7, "target_seconds": 15, "question": "Emergency lighting fixtures are installed along every ________ to guide employees during evacuations.", "options": {"A": "corridor", "B": "council", "C": "critic", "D": "canvas"}, "answer": "A", "analysis": "名詞受詞辨析：along every corridor 指『沿著每條走廊』。(B) council 為委員會；(C) critic 為評論家；(D) canvas 為畫布。選 (A)。", "translation": "每條走廊沿途均裝有緊急照明設備，以在疏散期間引導員工。"}, {"id": 8, "target_seconds": 15, "question": "Accounting will automatically ________ health insurance premiums from each monthly paycheck.", "options": {"A": "deduct", "B": "deduction", "C": "deductible", "D": "deducted"}, "answer": "A", "analysis": "助動詞夾心：will + automatically (副詞) + [原形動詞] + premiums (受詞)。deduct 指『扣除』。選原形動詞 (A)。", "translation": "會計部門將自動從每月的薪資單中扣除健保費。"}, {"id": 9, "target_seconds": 15, "question": "The logistics director chosen by the board is known for offering ________ delivery schedules.", "options": {"A": "dependable", "B": "dependably", "C": "dependence", "D": "depend"}, "answer": "A", "analysis": "形容詞修飾名詞：dependable delivery schedules 指『可靠準時的運送時程』。選形容詞 (A)。(B) 為副詞；(C) 為名詞。", "translation": "董事會挑選的物流總監以提供值得信賴的交貨時程而聞名。"}, {"id": 10, "target_seconds": 20, "question": "A certified network technician was dispatched to ________ the chronic server connectivity issues.", "options": {"A": "diagnose", "B": "diagnosis", "C": "diagnostic", "D": "diagnostician"}, "answer": "A", "analysis": "不定詞後接動詞：dispatched to + [原形動詞] + issues (受詞)。diagnose 指『診斷/查明故障』。(B) diagnosis 為名詞。選 (A)。", "translation": "一名認證網路技術員獲派前往診斷伺服器長期的連線問題。"}, {"id": 11, "target_seconds": 15, "question": "Thanks to ________ research by the market analytics team, the new product captured fifteen percent market share.", "options": {"A": "diligent", "B": "diligently", "C": "diligence", "D": "diligentness"}, "answer": "A", "analysis": "形容詞修飾名詞：diligent research 指『勤勉細緻的研究』。選形容詞 (A)。(B) 為副詞；(C) 為名詞。", "translation": "多虧市場分析團隊勤勉細緻的研究，新產品奪得了 15% 的市場份額。"}, {"id": 12, "target_seconds": 15, "question": "The plant manager chose to ________ the safety violation as an isolated administrative error.", "options": {"A": "dismiss", "B": "dismissal", "C": "dismissive", "D": "dismissively"}, "answer": "A", "analysis": "不定詞後接動詞：chose to + [原形動詞] + the violation (受詞) + as...。dismiss sth. as... 指『將某事視為……而不予理會』。選 (A)。", "translation": "廠長選擇將該起安全違規視為單純的行政失誤而不予深究。"}, {"id": 13, "target_seconds": 15, "question": "________ the severe blizzard conditions, the maintenance crew kept airport runways clear throughout the night.", "options": {"A": "In spite of", "B": "Although", "C": "Even if", "D": "Because"}, "answer": "A", "analysis": "視覺錨點：空格後為 'the severe blizzard conditions'（名詞片語無動詞）。秒選介系詞 (A) In spite of。(B)、(C)、(D) 皆為從屬連接詞，後需接 S+V。", "translation": "儘管面臨嚴重的暴風雪天候，維護人員整夜依然維持機場跑道暢通。"}, {"id": 14, "target_seconds": 15, "question": "The international flight was redirected to Boston ________ mechanical failure in the hydraulic system.", "options": {"A": "owing to", "B": "because", "C": "since", "D": "as"}, "answer": "A", "analysis": "視覺錨點：空格後為 'mechanical failure in the hydraulic system'（名詞片語）。秒選介系詞片語 (A) owing to。(B)、(C)、(D) 為連接詞需接句子。", "translation": "由於液壓系統發生機械故障，該國際航班改降波士頓。"}, {"id": 15, "target_seconds": 15, "question": "The contractor guarantees delivery within ten days, ________ that construction materials arrive on schedule.", "options": {"A": "provided", "B": "in spite", "C": "owing", "D": "prior"}, "answer": "A", "analysis": "視覺錨點：看到空格後的 'that' + 完整子句 (materials arrive on schedule)，秒選 (A) provided that（只要……）。", "translation": "只要建築材料如期送達，承包商保證在 10 天內完工交付。"}, {"id": 16, "target_seconds": 20, "question": "While ________ the quarterly balance sheet, the auditor discovered an unrecorded offshore transaction.", "options": {"A": "examining", "B": "examined", "C": "examines", "D": "examination"}, "answer": "A", "analysis": "分詞構句秒殺：While 後主詞 the auditor 主動檢查資產負債表，選主動現在分詞 (A) examining。(B) examined 為被動 past participle。", "translation": "在審閱季度資產負債表時，稽核員發現了一筆未記錄的境外交易。"}, {"id": 17, "target_seconds": 15, "question": "All personnel must wear protective hard hats unless ________ instructed by the safety supervisor.", "options": {"A": "otherwise", "B": "other", "C": "another", "D": "others"}, "answer": "A", "analysis": "固定減化子句語塊：unless otherwise instructed（除非另有指示）。選副詞 (A) otherwise。", "translation": "除非安全主管另有指示，否則所有人員均必須佩戴防護安全帽。"}, {"id": 18, "target_seconds": 15, "question": "The executive board found the proposed telecommuting policy remarkably ________ to employee retention.", "options": {"A": "beneficial", "B": "beneficially", "C": "benefit", "D": "benefited"}, "answer": "A", "analysis": "不完全及物動詞：find + the policy (受詞) + [形容詞受詞補語]。選形容詞 (A) beneficial。絕不可選副詞 beneficially！", "translation": "執行董事會發現提議的遠距辦公政策對於留住員工極為有利。"}, {"id": 19, "target_seconds": 20, "question": "The newly upgraded cybersecurity protocol will ________ minimize the threat of ransomware infiltration.", "options": {"A": "significantly", "B": "significant", "C": "significance", "D": "significative"}, "answer": "A", "analysis": "助動詞夾心秒殺：will + [副詞 -ly] + minimize (原形動詞)。副詞 (A) significantly 修飾動詞 minimize。選 (A)。", "translation": "新升級的網路安全協定將顯著降低勒索軟體入侵的威脅。"}, {"id": 20, "target_seconds": 15, "question": "One regional branch achieved its quota, while ________ branch fell slightly below expectations.", "options": {"A": "the other", "B": "another", "C": "others", "D": "other"}, "answer": "A", "analysis": "兩者特指對比修飾單數名詞：'One branch ..., while the other branch ...'。特指剩餘的那一個分部，用 (A) the other 修飾單數名詞 branch。", "translation": "其中一家區域分部達成了配額，而另一家分部則微幅低於預期。"}]}, "afternoon": {"quick_recall": [{"prompt": "The CEO took time to ________ [動詞，表揚稱讚] the team.", "clue": "表揚（c開頭動詞）", "answer": "commend"}, {"prompt": "A highly ________ [形容詞，勝任稱職的] supervisor.", "clue": "有能力的/稱職的（c開頭）", "answer": "competent"}, {"prompt": "A ________ [形容詞，全面詳盡的] overview of policies.", "clue": "詳盡全方位的（c開頭）", "answer": "comprehensive"}, {"prompt": "The lab provided ________ [形容詞，確鑿決定性的] proof.", "clue": "決定性的/有說服力的（c開頭）", "answer": "conclusive"}, {"prompt": "Invested a ________ [形容詞，相當可觀的] amount of capital.", "clue": "相當多的（c開頭）", "answer": "considerable"}, {"prompt": "A stylish, ________ [形容詞，現代當代的] office layout.", "clue": "當代的（c開頭）", "answer": "contemporary"}], "spaced_traps": [{"id": 1, "question": "The company decided to compensate clients for any ________ to personal electronics during transit.", "options": {"A": "damage", "B": "damages", "C": "damaging", "D": "damaged"}, "answer": "A", "trap_point": "damage 表物品實體損壞為不可數名詞，不可加 -s！", "analysis": "句意是賠償運輸途中電子產品的實體損壞，不可數名詞選 (A) damage。damages 加 -s 是法律賠償金。", "translation": "該公司決定就運送過程中個人電子產品所受的任何損壞向客戶進行賠償。"}, {"id": 2, "question": "The CEO and the COO promised to support ________ during upcoming parliamentary hearings.", "options": {"A": "each other", "B": "one another", "C": "other", "D": "another"}, "answer": "A", "trap_point": "兩者互相用 each other！三者以上互相用 one another！", "analysis": "主詞為 The CEO and the COO（兩個人），雙方彼此互相用 (A) each other。", "translation": "執行長與營運長承諾在即將舉行的國會聽證會中相互支持。"}, {"id": 3, "question": "All personnel must adhere strictly ________ environmental compliance protocols.", "options": {"A": "to", "B": "with", "C": "for", "D": "by"}, "answer": "A", "trap_point": "adhere strictly to（嚴格遵守）。abide 才接 by！", "analysis": "adhere 固定搭配介系詞 to，選 (A)。", "translation": "所有人員必須嚴格遵守環境合規手冊。"}, {"id": 4, "question": "The customer found the online checkout procedure remarkably ________ to finish.", "options": {"A": "simple", "B": "simply", "C": "simplicity", "D": "simplification"}, "answer": "A", "trap_point": "find + O + 形容詞受詞補語！絕不選副詞 simply！", "analysis": "find + the procedure (受詞) + [形容詞受詞補語]。選形容詞 (A) simple。", "translation": "客戶發現線上結帳程序操作起來非常簡單。"}, {"id": 5, "question": "Employees who put ________ overtime during the weekend will receive compensatory holiday time.", "options": {"A": "in", "B": "on", "C": "out", "D": "at"}, "answer": "A", "trap_point": "put in overtime（超時加班）。", "analysis": "put in overtime 為商務核心語塊，選 (A)。", "translation": "在週末加班的員工將獲得補休時數。"}, {"id": 6, "question": "The pharmaceutical lab will ________ conduct quality verification on the new vaccine lot.", "options": {"A": "rigorously", "B": "rigorous", "C": "rigor", "D": "rigorousness"}, "answer": "A", "trap_point": "will + [副詞 -ly] + conduct (原形動詞)！", "analysis": "will 與動詞 conduct 之間的夾心位置，需用副詞 (A) rigorously（嚴格徹底地）。", "translation": "製藥實驗室將對新批次疫苗嚴格進行品質驗證。"}, {"id": 7, "question": "The retail chain will replace defective merchandise ________ that the original sales receipt is enclosed.", "options": {"A": "provided", "B": "owing", "C": "in spite", "D": "prior"}, "answer": "A", "trap_point": "provided that + 完整子句（只要……）。", "analysis": "看到空格後接 that + 完整句子，秒選 (A) provided that。", "translation": "只要隨附原始發票收據，該零售連鎖店將為瑕疵商品提供更換。"}, {"id": 8, "question": "The senior engineer was instructed to ________ as project lead due to health considerations.", "options": {"A": "step down", "B": "take over", "C": "hold off", "D": "put off"}, "answer": "A", "trap_point": "step down as + 職位（辭去/退下職務）。", "analysis": "依據句意因健康因素而『卸任』專案負責人一職，選 (A) step down。", "translation": "資深工程師因健康考量獲准辭去專案負責人職務。"}, {"id": 9, "question": "The board unanimously voted to ________ the software development division for their record-breaking release.", "options": {"A": "commend", "B": "comment", "C": "command", "D": "commence"}, "answer": "A", "trap_point": "commend sb. for sth.（因某事表揚某人）。", "analysis": "表揚團隊選 (A) commend。", "translation": "董事會一致投票表揚軟體開發部門破紀錄的產品發布。"}, {"id": 10, "question": "The logistics firm hired an exceptionally ________ supervisor to oversee international air freight.", "options": {"A": "competent", "B": "competence", "C": "competently", "D": "competition"}, "answer": "A", "trap_point": "an exceptionally [形容詞] supervisor。competent 指稱職有能力的。", "analysis": "選形容詞 (A) competent 修飾 supervisor。", "translation": "該物流公司聘請了一位極為稱職的主管來監督國際航空貨運。"}, {"id": 11, "question": "The newly published guide offers a ________ explanation of commercial real estate zoning laws.", "options": {"A": "comprehensive", "B": "comprehend", "C": "comprehensively", "D": "comprehension"}, "answer": "A", "trap_point": "a comprehensive explanation（全面詳盡的說明）。", "analysis": "選形容詞 (A) comprehensive。", "translation": "新出版的指南對商業不動產分區法規提供了全面詳盡的說明。"}, {"id": 12, "question": "The independent scientific panel produced ________ evidence verifying the safety of the pharmaceutical product.", "options": {"A": "conclusive", "B": "conclude", "C": "conclusion", "D": "conclusively"}, "answer": "A", "trap_point": "conclusive evidence（確鑿決定性的證據）。", "analysis": "選形容詞 (A) conclusive。", "translation": "獨立科學專家小組提供了確鑿的證據，證實了該藥品的安全性。"}, {"id": 13, "question": "The company invested a ________ portion of its annual profits into renewable energy development.", "options": {"A": "considerable", "B": "considerate", "C": "considerably", "D": "consideration"}, "answer": "A", "trap_point": "a considerable portion 指相當大的一部分；considerate 是指人體貼的！", "analysis": "修飾金額或比例相當可觀，選 (A) considerable。", "translation": "該公司將其年度利潤中相當可觀的一部分投入到了再生能源開發中。"}, {"id": 14, "question": "The commercial interior designer transformed the empty space into a sleek, ________ corporate office.", "options": {"A": "contemporary", "B": "contemporaneously", "C": "contemplate", "D": "contempt"}, "answer": "A", "trap_point": "contemporary corporate office 指現代當代風格的辦公室。", "analysis": "選形容詞 (A) contemporary。", "translation": "商業室內設計師將空置空間改造成時尚現代的企業辦公室。"}], "part7": {"passages": [{"text_type": "Corporate Commendation Memo (企業年度表彰與主管備忘錄)", "title": "Executive Committee — Annual Leadership Awards & Department Excellence Commendation", "content": "MEMORANDUM: EXEC-AWRD-2026-10\nTO: All Global Corporate Personnel and Regional Directors\nFROM: Executive Committee & Office of the Chief Executive\nDATE: November 13, 2026\nSUBJECT: 2026 Departmental Excellence Awards and Special Project Bonuses\n\n1. Department of the Year Recognition\nThe Board of Directors is pleased to formally announce that the Global Software Engineering Division has been awarded the prestigious Department of the Year honor. The engineering team received this distinguished commendation for modernizing the global logistics platform ahead of schedule, reducing transactional latency across thirty-five country gateways and significantly improving customer satisfaction metrics.\n\n2. Overtime Project Stipends and Bonus Disbursement\nIn recognition of their exceptional dedication during critical deployment milestones, a performance stipend of $1,200 is granted to team members who worked overtime during October. This one-time reward will be disbursed in the November end-of-month compensation package.\n\n*Supervisor Endorsement Requirement: To receive their bonus disbursement, all eligible personnel must submit their supervisor's sign-off through the HR rewards portal before November 25. Unconfirmed submissions will be held until the December payroll reconciliation cycle. Inquiries should be addressed to awards@enterprise-global.com.", "questions": [{"question": "Why is the Software Engineering division being commended?", "options": {"A": "For modernizing the global logistics platform ahead of schedule.", "B": "For negotiating a multi-million-dollar overseas contract.", "C": "Because of their successful corporate legal defense.", "D": "To acknowledge their relocation to the new downtown plaza."}, "answer": "A", "radar": "🔍 防漏看雷達：表揚原因 'diligent efforts in modernizing our global logistics platform... two weeks ahead of schedule'！", "analysis": "第一段第一、二句明確說明：軟體工程團隊因提前兩週完成全球物流平台的現代化改建而受到表揚，故選 (A)。"}, {"question": "What award is granted to team members who worked overtime during October?", "options": {"A": "A performance stipend of $1,200.", "B": "Four additional weeks of paid vacation.", "C": "An immediate promotion to division director.", "D": "A voucher for complimentary airline tickets."}, "answer": "A", "radar": "🔍 防漏看雷達：獎勵金額 'entitled to an executive performance stipend of $1,200'！", "analysis": "星號小字第一句指出：在 10 月上線期間加班的全員有權獲得 1,200 美元的特別績效津貼，故選 (A)。"}, {"question": "What must eligible personnel do before November 25 to receive their bonus?", "options": {"A": "Submit their supervisor's sign-off.", "B": "Enroll in the advanced coding seminar.", "C": "Register their bank credentials in person.", "D": "Complete forty hours of client evaluations."}, "answer": "A", "radar": "🔍 防漏看雷達：領取條件期限 'submit their department supervisor sign-off prior to November 25'！", "analysis": "文末最後一句明確指出：符合資格者必須在 11 月 25 日前繳交主管簽核文件，方能於月底發放薪資時領取，故選 (A)。"}]}, {"text_type": "Facility Renovation Circular (總部大樓整修施工安全通告)", "title": "Facilities Management Division — Corporate Headquarters Interior Renovation & Access", "content": "FACILITY OPERATIONS ADVISORY: FAC-RENOV-2026-10\nTO: All Corporate Headquarters Building Occupants\nFROM: Facilities Management Division & Workplace Safety Taskforce\nDATE: November 13, 2026\nSUBJECT: Phase II Structural Interior Renovation and Corridor Access Restrictions\n\n1. Construction Schedule & Nighttime Working Hours\nStarting Monday, interior contractors will begin remodeling the third-floor executive conference suites, restrooms, and main administrative corridors. To minimize noise and prevent operational interruptions to daytime business tasks, all heavy interior renovation work will take place between 6:00 P.M. and 6:00 A.M. Nighttime custodial teams will vacuum and sanitize all shared corridors prior to 7:30 AM each morning.\n\n2. Evening Access & Freight Elevator Routing\nDuring nighttime renovation hours, the central passenger elevators will bypass Floor 3 entirely. Evening staff and security personnel requiring urgent access to the third floor must travel via the exterior freight elevator in Sector B, presenting their digital clearance credentials to the night security warden.\n\n*Strict Zone Enforcement: Unauthorized personnel are strictly forbidden from entering active construction zones. Entering the construction zone without authorization will result in immediate suspension of building security credentials and formal departmental review. For emergency building inquiries, call extension 4410.", "questions": [{"question": "During what hours will interior renovation work take place?", "options": {"A": "Between 6:00 P.M. and 6:00 A.M.", "B": "From 8:00 A.M. to 5:00 P.M.", "C": "Continuously throughout the entire weekend.", "D": "Solely during the lunch hour between noon and 1:00 P.M."}, "answer": "A", "radar": "🔍 防漏看雷達：施工時段 'restricted between 6:00 P.M. and 6:00 A.M.'！", "analysis": "第一段最後一句明確說明：施工活動限制在晚間 6 點至清晨 6 點之間進行，以減少日間干擾，故選 (A)。"}, {"question": "How should evening staff access the third floor during renovations?", "options": {"A": "Via the exterior freight elevator in Sector B.", "B": "Through the main central reception staircase.", "C": "By requesting an escort from the CEO.", "D": "Using the subterranean parking ramp."}, "answer": "A", "radar": "🔍 防漏看雷達：進出通道指定 'enter via the exterior freight elevator in Sector B'！", "analysis": "星號小字第二句指出：持有夜間通行證的員工必須從 B 區的外部貨梯進出，故選 (A)。"}, {"question": "What is the consequence of entering the construction zone without authorization?", "options": {"A": "Suspension of building security credentials.", "B": "A fine of $250 deducted from payroll.", "C": "Mandatory reassignment to another branch.", "D": "Immediate confiscation of laptop computers."}, "answer": "A", "radar": "🔍 防漏看雷達：罰則細節 'will have their building security credentials suspended'！", "analysis": "文末最後一句明確指出：未經授權進入施工區域者，其大樓門禁安全證件將被暫停使用，故選 (A)。"}]}]}}}, "11": {"day": 11, "date": "11/14", "phase": 2, "phase_name": "860 突破與同義代換", "topic": "轉折副詞秒殺 (otherwise / therefore / however) ｜ 扣除、分派與可靠性", "morning": {"chunks": [{"chunk": "deduct from payroll", "meaning": "從薪資中扣除", "scenario": "Health insurance premiums are automatically deducted from monthly payroll.", "paraphrase": "deduct = subtract = withhold", "alert": "注意：deduct 後方固定接 from！"}, {"chunk": "allocate resources to", "meaning": "將資源分配給", "scenario": "The executive board agreed to allocate additional resources to the AI research lab.", "paraphrase": "allocate = assign = distribute", "alert": "allocate 固定搭配 to + 受詞！"}, {"chunk": "reliable vendor", "meaning": "可靠的供應商", "scenario": "Apex Supplies has proven to be a highly reliable vendor over the past decade.", "paraphrase": "reliable = dependable = trustworthy", "alert": "名詞形式為 reliability！"}, {"chunk": "contingent upon approval", "meaning": "取決於／視核准而定", "scenario": "The property acquisition is contingent upon approval from the municipal zoning board.", "paraphrase": "contingent upon = dependent on = subject to", "alert": "contingent 固定搭配 upon / on！"}, {"chunk": "otherwise noted", "meaning": "除非另有說明", "scenario": "All team members must attend the weekly briefing unless otherwise noted.", "paraphrase": "otherwise noted = unless stated differently", "alert": "otherwise 為副詞，常出現在 unless otherwise [V-ed]！"}, {"chunk": "therefore required to", "meaning": "因此被要求……", "scenario": "Contractors are therefore required to wear safety helmets in active zones.", "paraphrase": "therefore = consequently = as a result", "alert": "therefore 為副詞，不可直接連接兩個獨立子句（須用分號或句號）！"}, {"chunk": "however difficult", "meaning": "無論多麼困難", "scenario": "However difficult the negotiations may seem, both parties remain committed to finding common ground.", "paraphrase": "however difficult = no matter how difficult", "alert": "however + 形容詞/副詞 + S + V 表示『無論多麼……』！"}], "visual_anchor": {"title": "句首或分號後面的轉折詞性秒殺？", "rule_1": "👀 看到 [S+V ; ________ , S+V] ➔ 填入「轉折副詞」（therefore, however, otherwise, nevertheless）！", "rule_2": "👀 看到 unless ________ [V-en] ➔ 100% 秒選 otherwise（unless otherwise specified/noted）！", "golden_rule": "⚡ 教練金句：分號隔開選副詞，逗號連接選連詞！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "All travel reimbursement forms must be submitted by Friday; ________, payments will be delayed until the next billing cycle.", "options": {"A": "otherwise", "B": "although", "C": "despite", "D": "unless"}, "answer": "A", "analysis": "分號與逗號夾心結構 [; ________ , S+V]，此處表示『否則』，秒選副詞 (A) otherwise。(B) although 與 (D) unless 為從屬連接詞，不可在分號後加逗號獨立使用；(C) despite 為介系詞。", "translation": "所有差旅報銷單必須在週五前提交；否則，款項將延遲至下一個結算週期發放。"}, {"id": 2, "target_seconds": 15, "question": "The budget deficit was greater than anticipated; ________, the planned expansion of the overseas warehouse had to be deferred.", "options": {"A": "consequently", "B": "in spite of", "C": "because", "D": "whereas"}, "answer": "A", "analysis": "分號後轉折副詞：看到分號 [; ________ , S+V]，表因果推論『因此/結果』，選轉折副詞 (A) consequently。(B) 為介系詞；(C) 為從屬連接詞；(D) 為對比連接詞。", "translation": "預算赤字超出預期；因此，海外倉庫的擴建計畫不得不延後。"}, {"id": 3, "target_seconds": 15, "question": "Unless ________ stated in the warranty agreement, customer service hotlines are operational twenty-four hours a day.", "options": {"A": "otherwise", "B": "other", "C": "another", "D": "others"}, "answer": "A", "analysis": "固定副詞搭配：unless otherwise stated / noted（除非另有說明）。otherwise 修飾過去分詞 stated，秒選 (A)。", "translation": "除非保固協議中另有說明，否則客戶服務熱線全天 24 小時運作。"}, {"id": 4, "target_seconds": 15, "question": "Monthly parking fees will be automatically ________ from each participating employee's paycheck.", "options": {"A": "deduct", "B": "deducted", "C": "deduction", "D": "deductible"}, "answer": "B", "analysis": "被動語態：will be automatically + [V-en]。空格處需要過去分詞形成被動，選 (B) deducted。(A) 為原形；(C) 為名詞；(D) 為形容詞。", "translation": "每月的停車費將自動從每位參與員工的薪資中扣除。"}, {"id": 5, "target_seconds": 15, "question": "The financial committee decided to ________ twenty percent of surplus revenue to infrastructure modernization.", "options": {"A": "allocate", "B": "allocation", "C": "allocated", "D": "allocating"}, "answer": "A", "analysis": "不定詞片語：decided to + [原形動詞]。allocate resources to...（分配資源給……），秒選原形動詞 (A) allocate。", "translation": "財務委員會決定將 20% 的盈餘資金分配給基礎設施現代化工程。"}, {"id": 6, "target_seconds": 15, "question": "The delivery schedule remains ________ upon prompt clearance of customs documents at the harbor.", "options": {"A": "contingent", "B": "contingency", "C": "contingently", "D": "contingents"}, "answer": "A", "analysis": "連綴動詞 + 形容詞：remains 為連綴動詞，後接形容詞主詞補語。be/remain contingent upon（取決於……），選形容詞 (A) contingent。(B) 為名詞；(C) 為副詞。", "translation": "交貨時間表仍取決於港口海關文件的及時清關。"}, {"id": 7, "target_seconds": 15, "question": "Supplier evaluations indicate that Orion Logistics is the most ________ partner for refrigerated shipping.", "options": {"A": "rely", "B": "reliable", "C": "reliably", "D": "reliability"}, "answer": "B", "analysis": "最高級形容詞：the most + [形容詞] + partner (名詞)。選形容詞 (B) reliable（可靠的）。(A) 為動詞；(C) 為副詞；(D) 為名詞。", "translation": "供應商評估顯示，Orion 物流是冷藏運輸方面最可靠的合作夥伴。"}, {"id": 8, "target_seconds": 15, "question": "Staff may work remotely up to two days per week unless ________ directed by their immediate supervisor.", "options": {"A": "otherwise", "B": "instead", "C": "seldom", "D": "hardly"}, "answer": "A", "analysis": "固定片語：unless otherwise directed（除非另有指示）。秒選 (A) otherwise。", "translation": "員工每週最多可遠端工作兩天，除非其直屬主管另有指示。"}, {"id": 9, "target_seconds": 15, "question": "The prototype showed remarkable speed; ________, power consumption exceeded current factory specifications.", "options": {"A": "however", "B": "although", "C": "despite", "D": "in spite"}, "answer": "A", "analysis": "分號轉折副詞：看到 [; ________ , S+V]，表示對比轉折，選轉折副詞 (A) however。(B) although 不能在分號後帶逗號；(C) despite 與 (D) in spite 後接名詞。", "translation": "原型機展現了卓越的速度；然而，其功耗超出了現行工廠規格。"}, {"id": 10, "target_seconds": 15, "question": "Voluntary contributions will be ________ directly from employee compensation on the fifteenth of each month.", "options": {"A": "deducting", "B": "deducted", "C": "deduct", "D": "deductions"}, "answer": "B", "analysis": "被動語態：will be + [V-en]。捐款是被扣除，選過去分詞 (B) deducted。", "translation": "自願捐款將在每月 15 日直接從員工薪資中扣除。"}, {"id": 11, "target_seconds": 15, "question": "The city council voted to ________ additional funding for the revitalization of the historic downtown district.", "options": {"A": "allocate", "B": "allocating", "C": "allocation", "D": "allocates"}, "answer": "A", "analysis": "不定詞結構：voted to + [原形動詞]。選 (A) allocate。", "translation": "市議會投票通過為歷史街區的復興工程撥配額外資金。"}, {"id": 12, "target_seconds": 15, "question": "Final execution of the commercial lease is strictly ________ on municipal permit issuance.", "options": {"A": "contingent", "B": "contingency", "C": "contingently", "D": "contingencies"}, "answer": "A", "analysis": "be strictly contingent on...（嚴格取決於……）。選形容詞 (A) contingent。", "translation": "該商業租約的最終簽署嚴格取決於市政許可證的核發。"}, {"id": 13, "target_seconds": 15, "question": "Because of its exceptional ________, the robotic packaging system reduced sorting downtime by half.", "options": {"A": "reliable", "B": "reliability", "C": "reliably", "D": "relies"}, "answer": "B", "analysis": "所有格/形容詞後接名詞：its exceptional + [名詞]。選名詞 (B) reliability（可靠性）。", "translation": "由於其卓越的可靠性，這套機器人包裝系統將分揀停機時間縮短了一半。"}, {"id": 14, "target_seconds": 15, "question": "All laboratory tests must adhere to national protocols unless ________ indicated by the chief researcher.", "options": {"A": "otherwise", "B": "anyway", "C": "likewise", "D": "besides"}, "answer": "A", "analysis": "高頻語塊：unless otherwise indicated（除非另有指示）。選 (A) otherwise。", "translation": "所有實驗室測試均須遵守國家法規，除非首席研究員另有指示。"}, {"id": 15, "target_seconds": 15, "question": "Conference participants may park in Lot B; ________, vehicles lacking permits will be ticketed immediately.", "options": {"A": "nevertheless", "B": "even though", "C": "because of", "D": "in order that"}, "answer": "A", "analysis": "分號副詞：看到 [; ________ , S+V]，選轉折副詞 (A) nevertheless（然而/儘管如此）。其餘選項均不能在分號逗號中作副詞使用。", "translation": "會議與會者可停泊在 B 停車場；然而，無停車證的車輛將立即被開罰單。"}, {"id": 16, "target_seconds": 15, "question": "The manufacturing plant operated at full capacity; ________, orders placed this week can be fulfilled without delay.", "options": {"A": "therefore", "B": "although", "C": "despite", "D": "unless"}, "answer": "A", "analysis": "因果轉折副詞：[; therefore , S+V]，表示『因此』，選 (A) therefore。", "translation": "製造工廠全負荷運轉；因此，本週下的訂單可以毫無延誤地完成交付。"}, {"id": 17, "target_seconds": 15, "question": "The payroll department will ________ five percent of each paycheck for the employee stock purchase plan.", "options": {"A": "deduct", "B": "deduction", "C": "deducting", "D": "deducted"}, "answer": "A", "analysis": "助動詞後接原形動詞：will + [原形動詞] + 受詞。選原形動詞 (A) deduct。", "translation": "薪資部門將從每期薪水扣除 5% 用於員工購股計畫。"}, {"id": 18, "target_seconds": 15, "question": "Management intends to ________ substantial computing capacity to the new automated translation engine.", "options": {"A": "allocate", "B": "allocates", "C": "allocation", "D": "allocating"}, "answer": "A", "analysis": "不定詞片語：intends to + [原形動詞]。選 (A) allocate。", "translation": "管理層打算將大量運算能力分配給新的自動翻譯引擎。"}, {"id": 19, "target_seconds": 15, "question": "The company's expansion into South America is ________ on signing a distribution agreement before December.", "options": {"A": "contingent", "B": "contingently", "C": "contingency", "D": "contingents"}, "answer": "A", "analysis": "be contingent on（取決於……）。選形容詞 (A) contingent。", "translation": "公司進軍南美的擴張計畫取決於 12 月前簽署經銷協議。"}, {"id": 20, "target_seconds": 15, "question": "Regular server maintenance will take place at midnight on Sunday unless ________ announced by IT support.", "options": {"A": "otherwise", "B": "moreover", "C": "furthermore", "D": "wherever"}, "answer": "A", "analysis": "高頻慣用語句型：unless otherwise announced（除非另有宣布）。選 (A) otherwise。", "translation": "定期伺服器維護將於週日午夜進行，除非 IT 支援部門另有公告。"}]}, "afternoon": {"quick_recall": [{"prompt": "unless ________ [副詞] noted / specified / instructed.", "clue": "除非另有說明", "answer": "otherwise"}, {"prompt": "Health contributions are ________ [動詞，扣除] from gross salary.", "clue": "從薪資扣除", "answer": "deducted"}, {"prompt": "The budget was approved; ________ [副詞，因此], we can proceed.", "clue": "轉折副詞因此", "answer": "therefore / consequently"}, {"prompt": "Funding is ________ [形容詞，取決於] upon regional approval.", "clue": "取決於 (contingent ...)", "answer": "contingent upon / on"}, {"prompt": "The server showed exceptional ________ [名詞，可靠性].", "clue": "可靠度名詞", "answer": "reliability"}, {"prompt": "The board decided to ________ [動詞，分配] resources to cybersecurity.", "clue": "分配資源", "answer": "allocate"}], "spaced_traps": [{"id": 1, "question": "Submit your travel itinerary by noon; ________, the agency cannot guarantee hotel room availability.", "options": {"A": "otherwise", "B": "unless", "C": "despite", "D": "although"}, "answer": "A", "trap_point": "看到分號加逗號 [; ___ ,]，是副詞 otherwise，非連接詞 unless！", "analysis": "分號接轉折副詞表『否則』，選 (A) otherwise。(B) unless 為連接詞，不能在分號後帶逗號隔開。", "translation": "請在中午前提交您的旅行行程；否則，旅行社無法保證飯店客房供應。"}, {"id": 2, "question": "The conference venue is booked for August 15 unless ________ indicated by the committee.", "options": {"A": "otherwise", "B": "other", "C": "another", "D": "others"}, "answer": "A", "trap_point": "固定片語 unless otherwise indicated，不可選形容詞 other！", "analysis": "修飾過去分詞 indicated，需用副詞 otherwise。選 (A)。", "translation": "除非委員會另有指示，否則會議場地已預訂於 8 月 15 日舉行。"}, {"id": 3, "question": "Mandatory pension contributions are ________ directly from employee payroll accounts.", "options": {"A": "deducting", "B": "deducted", "C": "deduction", "D": "deduct"}, "answer": "B", "trap_point": "are + deducted（被動扣除），非主動 deducting！", "analysis": "退休金『被扣除』，需用過去分詞形成被動語態，選 (B) deducted。", "translation": "強制性退休金自提款直接從員工薪資帳戶中扣除。"}, {"id": 4, "question": "The city planning division will ________ additional manpower to road repairs throughout the summer.", "options": {"A": "allocate", "B": "allocating", "C": "allocated", "D": "allocation"}, "answer": "A", "trap_point": "will 後接原形動詞 allocate！", "analysis": "助動詞 will 後接原形動詞 (A) allocate。", "translation": "都市規劃部門將在整個夏季為道路維修調配額外人力。"}, {"id": 5, "question": "The final bonus payout is ________ on achieving fourth-quarter sales quotas.", "options": {"A": "contingent", "B": "contingently", "C": "contingency", "D": "contingents"}, "answer": "A", "trap_point": "is + contingent on（取決於），選形容詞！", "analysis": "be contingent on 為固定搭配，形容詞作主詞補語，選 (A) contingent。", "translation": "年終獎金的最終發放取決於第四季度銷售配額的達成情況。"}, {"id": 6, "question": "Customers value Vertex Cloud services for their remarkable stability and ________.", "options": {"A": "reliable", "B": "reliability", "C": "reliably", "D": "relying"}, "answer": "B", "trap_point": "stability (名詞) and ________ (需同為名詞)！", "analysis": "對等連接詞 and 連接名詞 stability 與 (B) reliability（可靠性）。", "translation": "客戶看重 Vertex 雲端服務顯著的穩定性與可靠度。"}, {"id": 7, "question": "All personnel must wear protective goggles; ________, entry into the chemical lab will be denied.", "options": {"A": "otherwise", "B": "although", "C": "because", "D": "despite"}, "answer": "A", "trap_point": "分號逗號結構 [; ___ ,]，秒選副詞 otherwise！", "analysis": "表示『否則』的轉折副詞，選 (A) otherwise。", "translation": "所有人員必須佩戴護目鏡；否則，將被拒絕進入化學實驗室。"}, {"id": 8, "question": "The quarterly earnings met market expectations; ________, investment analysts upgraded the stock.", "options": {"A": "therefore", "B": "even if", "C": "owing to", "D": "in spite of"}, "answer": "A", "trap_point": "分號接轉折副詞 therefore 表因果推論！", "analysis": "[; therefore , S+V]，選轉折副詞 (A) therefore。", "translation": "季度營收符合市場預期；因此，投資分析師調高了該股票的評級。"}, {"id": 9, "question": "Unless ________ instructed by the physician, patients should take this medication after meals.", "options": {"A": "otherwise", "B": "seldom", "C": "hardly", "D": "never"}, "answer": "A", "trap_point": "unless otherwise instructed 高頻語塊！", "analysis": "固定片語搭配，選 (A) otherwise（除非另有指示）。", "translation": "除非醫生另有醫囑，病患應在飯後服用此藥物。"}, {"id": 10, "question": "Taxes will be ________ from the total severance package prior to disbursement.", "options": {"A": "deducted", "B": "deduct", "C": "deducting", "D": "deduction"}, "answer": "A", "trap_point": "will be + deducted (被動)！", "analysis": "稅金將被扣除，選過去分詞 (A) deducted。", "translation": "稅款將在發放前從總遣散補償金中扣除。"}, {"id": 11, "question": "The steering committee will ________ thirty percent of the grant to renewable energy projects.", "options": {"A": "allocate", "B": "allocation", "C": "allocated", "D": "allocates"}, "answer": "A", "trap_point": "will 後接原形動詞！", "analysis": "助動詞 will + 原形動詞 (A) allocate。", "translation": "指導委員會將把 30% 的補助金分配給再生能源項目。"}, {"id": 12, "question": "Completion of the runway extension is strictly ________ upon dry weather conditions.", "options": {"A": "contingent", "B": "contingency", "C": "contingently", "D": "contingents"}, "answer": "A", "trap_point": "strictly contingent upon 表取決於！", "analysis": "is strictly contingent upon，選形容詞 (A) contingent。", "translation": "跑道擴建工程的竣工嚴格取決於乾燥的天氣條件。"}, {"id": 13, "question": "The software vendor has earned an international reputation for high product ________.", "options": {"A": "reliability", "B": "reliable", "C": "reliably", "D": "relying"}, "answer": "A", "trap_point": "high product + reliability (名詞)！", "analysis": "形容詞 high product 修飾名詞，選 (A) reliability。", "translation": "該軟體供應商因產品極高的可靠性而享譽國際。"}, {"id": 14, "question": "All visitors must sign in at the security desk; ________, an escort will not be provided.", "options": {"A": "otherwise", "B": "unless", "C": "despite", "D": "although"}, "answer": "A", "trap_point": "分號轉折副詞 otherwise（否則）！", "analysis": "分號後轉折副詞表否則，選 (A) otherwise。", "translation": "所有訪客必須在警衛處登記；否則，將不安排專人陪同引導。"}], "part7": {"passages": [{"text_type": "Corporate Benefits Bulletin (公司福利與薪資代扣通知)", "title": "Lexington Financial Corp — Corporate Payroll Deductions and Benefits Allocation", "content": "POLICY BULLETIN: LEX-BEN-2026-11\nISSUED BY: Global Compensation & Human Resources Bureau, Lexington Financial Corp\nDATE: November 14, 2026\nDISTRIBUTION: All Full-Time Corporate Staff and Regional Analysts\n\n1. Flexible Benefits Election & Pre-Tax Deductions\nLexington Financial Corp provides all permanent full-time personnel with pre-tax payroll deduction elections for retirement contributions, medical premiums, and municipal transit passes. Personnel wishing to enroll in the subsidized monthly transit program must complete their digital enrollment forms by the deadline of November 25.\n\n2. Monthly Public Transportation Deduction\nUnder our subsidized municipal commuter program, a fixed sum of $85 will be deducted monthly from the employee's payroll, while the corporation funds the remaining 50% of the unlimited regional transit pass. Passes will be distributed digitally to corporate mobile wallets on the first calendar day of each operating month.\n\n*Fitness Center Wellness Subsidy: Staff members are also entitled to a 40% corporate discount at partner athletic centers. To qualify for the fitness discount, employees must complete an annual health assessment through the digital health portal before December 10. Completed assessment forms are automatically transmitted to human resources.", "questions": [{"question": "What is the deadline for submitting the commuter subsidy form?", "options": {"A": "November 14", "B": "November 25", "C": "December 1", "D": "December 15"}, "answer": "B", "radar": "🔍 防漏看雷達：定位具體日期 'must submit form HR-204 before November 25'！", "analysis": "文中明確指示通勤補助表單 HR-204 必須在 11 月 25 日之前提交，故選 (B)。"}, {"question": "How much will be deducted monthly for the transit program?", "options": {"A": "$25", "B": "$50", "C": "$85", "D": "$204"}, "answer": "C", "radar": "🔍 防漏看雷達：鎖定金額數字 'transit deductions of $85 will be automatically deducted'！", "analysis": "文中說明每月將自動扣除 85 美元，故選 (C)。"}, {"question": "What must employees do to qualify for the fitness discount?", "options": {"A": "Work for at least three consecutive years", "B": "Complete an annual health assessment", "C": "Pay an additional administrative fee", "D": "Register with the local community center"}, "answer": "B", "radar": "🔍 防漏看雷達：星號條件條款 'contingent upon completion of an annual health assessment*'！", "analysis": "星號小字前文強調：健身折扣取決於是否完成年度健康評估，故選 (B)。"}]}, {"text_type": "Service Level Agreement (雲端服務水準協定 SLA)", "title": "Lexington Cloud Solutions — Service Level Standards & Performance Guarantees", "content": "SERVICE LEVEL AGREEMENT: SLA-CORP-2026-99\nPROVIDER: Lexington Cloud Solutions LLC\nCLIENT: Enterprise Financial & Analytics Partners\nEFFECTIVE DATE: November 14, 2026\nMONITORING CYCLE: 24/7/365 Automated Server Telemetry & Performance Auditing\n\n1. System Reliability & Availability Commitment\nLexington Cloud Solutions guarantees that our high-performance cloud hosting infrastructure and distributed database clusters will maintain an availability threshold of 99.95% uptime across each calendar billing quarter. Network latency, packet delivery rates, and server ping metrics are publicly reported via our customer status dashboard every sixty seconds, ensuring total operational transparency for institutional clients across North America and Europe.\n\n2. Downtime Service Credits and Penalties\nIn the unforeseen event that unplanned service outages or hardware failures cause platform reliability to fall below this guaranteed standard, Lexington Cloud Solutions provides a 15% billing credit on the next monthly service invoice upon client submission of an incident ticket.\n\n*Exclusion Window: Downtime calculations expressly exclude planned system upgrades performed during our recurring maintenance window on Sunday mornings between 1:00 AM and 4:00 AM Eastern Time. Clients are notified forty-eight hours in advance of any non-standard maintenance operations requiring temporary service degradation.", "questions": [{"question": "What uptime percentage does Lexington Cloud Solutions guarantee?", "options": {"A": "95.0%", "B": "98.5%", "C": "99.0%", "D": "99.95%"}, "answer": "D", "radar": "🔍 防漏看雷達：首段關鍵規格 'warrants 99.95% system uptime'！", "analysis": "首段首句明確保證 99.95% 的伺服器在線率，故選 (D)。"}, {"question": "What compensation is provided if reliability drops below the guaranteed level?", "options": {"A": "A replacement server at no charge", "B": "A 15% billing credit on the next invoice", "C": "A complete refund of annual fees", "D": "Free technical consulting for one month"}, "answer": "B", "radar": "🔍 防漏看雷達：補償條件 'receive an automatic 15% billing credit applied to the subsequent invoice'！", "analysis": "內文說明若在線率低於標準，客戶將在下期帳單獲得 15% 抵扣，故選 (B)。"}, {"question": "When is scheduled maintenance excluded from downtime calculations?", "options": {"A": "Sunday mornings between 1:00 AM and 4:00 AM", "B": "Every weekday evening after 6:00 PM", "C": "The first business day of each quarter", "D": "National public holidays only"}, "answer": "A", "radar": "🔍 防漏看雷達：星號除外條款 '*Note: System maintenance performed between 1:00 AM and 4:00 AM on Sundays'！", "analysis": "星號附註條款特別註明週日凌晨 1:00 至 4:00 的維護不計入停機時間，故選 (A)。"}]}]}}}, "12": {"day": 12, "date": "11/15", "phase": 2, "phase_name": "860 突破與同義代換", "topic": "同義字大替換 ｜ 翻新、改善與急件處理", "morning": {"chunks": [{"chunk": "renovate the facility", "meaning": "翻新整修設施", "scenario": "Management authorized funds to renovate the historical training facility.", "paraphrase": "renovate = remodel = refurbish = restore", "alert": "名詞形式為 renovation！"}, {"chunk": "expedite the shipment", "meaning": "加速出貨處理", "scenario": "The logistics team agreed to expedite the shipment for our premier client.", "paraphrase": "expedite = accelerate = hasten = speed up", "alert": "形容詞形式為 expeditious！"}, {"chunk": "streamline the workflow", "meaning": "精簡工作流程", "scenario": "Digital invoicing has helped streamline the workflow across departments.", "paraphrase": "streamline = simplify = optimize", "alert": "過去分詞 streamlined 可作形容詞『精簡流線型的』！"}, {"chunk": "enhance performance", "meaning": "提升績效表現", "scenario": "Regular feedback sessions substantially enhance team performance.", "paraphrase": "enhance = improve = boost = augment", "alert": "名詞形式為 enhancement！"}, {"chunk": "a major revamp", "meaning": "大規模改版翻新", "scenario": "The corporate website underwent a major revamp this quarter.", "paraphrase": "revamp = overhaul = restructure", "alert": "revamp 可作動詞也可直接作名詞！"}, {"chunk": "refurbish old equipment", "meaning": "重新整修舊設備", "scenario": "The company chose to refurbish old equipment rather than purchase new units.", "paraphrase": "refurbish = recondition = upgrade", "alert": "refurbished 常指出廠翻新良品！"}, {"chunk": "prioritize urgent tasks", "meaning": "優先處理緊急任務", "scenario": "Project managers must prioritize urgent tasks to meet critical milestones.", "paraphrase": "prioritize = give precedence to", "alert": "名詞形式為 priority！"}], "visual_anchor": {"title": "商務同義詞替換 (Paraphrase) 視覺秒殺錨點", "rule_1": "👀 看到 renovate ➔ 原文或選項秒對應 remodel, refurbish, overhaul！", "rule_2": "👀 看到 expedite ➔ 原文或選項秒對應 accelerate, speed up, rush, priority！", "golden_rule": "⚡ 教練金句：看到精簡選 streamline，看到加速選 expedite！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "The contractor was hired to ________ the executive conference room before the annual summit.", "options": {"A": "renovate", "B": "renovation", "C": "renovated", "D": "renovating"}, "answer": "A", "analysis": "不定詞後接原形動詞：to + [原形動詞]。renovate 表示『翻新/整修』。故選 (A)。", "translation": "該承包商被聘請在年度高峰會之前整修主管會議室。"}, {"id": 2, "target_seconds": 15, "question": "To ________ shipping during the holiday rush, the warehouse activated two auxiliary conveyor belts.", "options": {"A": "expedite", "B": "expedition", "C": "expedient", "D": "expedited"}, "answer": "A", "analysis": "in order to / to + [原形動詞] 表目的。expedite（加速/急件處理）。選 (A)。", "translation": "為在節慶高峰期加快出貨速度，倉庫啟動了兩條輔助輸送帶。"}, {"id": 3, "target_seconds": 15, "question": "The new software is designed to ________ accounting workflows and eliminate duplicate data entry.", "options": {"A": "streamline", "B": "streamlined", "C": "streamlines", "D": "streamlining"}, "answer": "A", "analysis": "to + [原形動詞] 並由 and 連接 eliminate。streamline（簡化流程）。選 (A)。", "translation": "該新軟體旨在精簡會計工作流程並消除重複的資料輸入。"}, {"id": 4, "target_seconds": 15, "question": "The culinary team made adjustments to the recipe to ________ the subtle flavor of the organic ingredients.", "options": {"A": "enhance", "B": "enhancement", "C": "enhanced", "D": "enhancing"}, "answer": "A", "analysis": "不定詞結構：to + [原形動詞] enhance（提升/增強）。選 (A)。", "translation": "烹飪團隊對食譜進行調整以提升有機食材的微妙風味。"}, {"id": 5, "target_seconds": 15, "question": "Management plans to ________ the corporate website to improve mobile accessibility.", "options": {"A": "revamp", "B": "revamping", "C": "revamped", "D": "revamps"}, "answer": "A", "analysis": "plans to + [原形動詞]。revamp（徹底改版/翻新）。選 (A)。", "translation": "管理層計畫對企業網站進行徹底改版，以改善行動裝置的易用性。"}, {"id": 6, "target_seconds": 15, "question": "Please mark urgent client orders as 'priority' so that processing can be ________.", "options": {"A": "expedited", "B": "expediting", "C": "expedite", "D": "expedites"}, "answer": "A", "analysis": "被動語態：can be + [V-en]。訂單被加速處理，選 (A) expedited。", "translation": "請將客戶緊急訂單標記為『優先』，以使處理程序能夠獲得加速。"}, {"id": 7, "target_seconds": 15, "question": "The extensive ________ of the downtown branch required temporary relocation of retail staff.", "options": {"A": "renovation", "B": "renovate", "C": "renovating", "D": "renovated"}, "answer": "A", "analysis": "形容詞 extensive 後接名詞。選 (A) renovation（裝修/翻新工程）。", "translation": "市中心分行的大規模裝修需要零售員工暫時調遷。"}, {"id": 8, "target_seconds": 15, "question": "The operations team introduced new guidelines that significantly ________ supply chain logistics.", "options": {"A": "streamlined", "B": "streamline", "C": "streamlining", "D": "streamlines"}, "answer": "A", "analysis": "子句動詞：introduced 與過去式動詞 (A) streamlined 對齊時態。", "translation": "營運團隊推出了新準則，大幅精簡了供應鏈物流。"}, {"id": 9, "target_seconds": 15, "question": "Subscribers will receive a complimentary feature ________ upon renewing their annual membership.", "options": {"A": "enhancement", "B": "enhance", "C": "enhancing", "D": "enhanced"}, "answer": "A", "analysis": "複合名詞結構：feature enhancement（功能提升）。選名詞 (A)。", "translation": "訂閱者在續約年度會員資格時將免費獲得功能升級。"}, {"id": 10, "target_seconds": 15, "question": "After the comprehensive ________, hotel occupancy rates surged by thirty percent.", "options": {"A": "revamp", "B": "revamping", "C": "revamped", "D": "revamps"}, "answer": "A", "analysis": "冠詞與形容詞後接名詞：comprehensive + [名詞] revamp。選 (A)。", "translation": "全面翻新後，飯店住房率飆升了 30%。"}, {"id": 11, "target_seconds": 15, "question": "Express couriers charge an extra fee to ________ delivery of sensitive legal contracts.", "options": {"A": "expedite", "B": "expedited", "C": "expedition", "D": "expeditious"}, "answer": "A", "analysis": "to + [原形動詞] + delivery。選 (A) expedite。", "translation": "快遞公司加收額外費用以加快敏感法律合約的交付。"}, {"id": 12, "target_seconds": 15, "question": "The museum will be temporarily closed while technicians ________ the historical galleries.", "options": {"A": "renovate", "B": "renovation", "C": "renovated", "D": "renovating"}, "answer": "A", "analysis": "連接詞 while 引導子句：主詞 technicians + 動詞原形 (A) renovate。", "translation": "博物館在技術人員翻新歷史展廳期間將暫時關閉。"}, {"id": 13, "target_seconds": 15, "question": "Automating payroll tasks will effectively ________ administrative procedures across all branches.", "options": {"A": "streamline", "B": "streamlines", "C": "streamlined", "D": "streamlining"}, "answer": "A", "analysis": "助動詞 will + 副詞 + [原形動詞]。選 (A) streamline。", "translation": "薪資任務的自動化將有效精簡所有分行的行政手續。"}, {"id": 14, "target_seconds": 15, "question": "Advanced thermal insulation will substantially ________ the building's energy efficiency.", "options": {"A": "enhance", "B": "enhances", "C": "enhanced", "D": "enhancing"}, "answer": "A", "analysis": "will + 副詞 + [原形動詞]。選 (A) enhance（提升）。", "translation": "先進的隔熱材料將大幅提升大樓的能源效率。"}, {"id": 15, "target_seconds": 15, "question": "The marketing department undertook a total ________ of their corporate branding strategy.", "options": {"A": "revamp", "B": "revamping", "C": "revamped", "D": "revamps"}, "answer": "A", "analysis": "名詞位置：a total + [名詞] revamp。選 (A)。", "translation": "行銷部門對其企業品牌策略進行了徹底重塑。"}, {"id": 16, "target_seconds": 15, "question": "All overseas shipments requiring special customs permits cannot be ________ without manager sign-off.", "options": {"A": "expedited", "B": "expedite", "C": "expediting", "D": "expedites"}, "answer": "A", "analysis": "助動詞被動：cannot be + [V-en]。選 (A) expedited。", "translation": "所有需要特殊海關許可的海外貨物，未經主管簽署不得加速處理。"}, {"id": 17, "target_seconds": 15, "question": "The municipal theater reopened yesterday following months of structural ________.", "options": {"A": "renovation", "B": "renovate", "C": "renovated", "D": "renovating"}, "answer": "A", "analysis": "介系詞 of 後接名詞。選 (A) renovation。", "translation": "市立劇院在經歷數月的結構翻修後於昨日重新開放。"}, {"id": 18, "target_seconds": 15, "question": "Standardized digital forms have successfully ________ client onboarding times.", "options": {"A": "streamlined", "B": "streamline", "C": "streamlines", "D": "streamlining"}, "answer": "A", "analysis": "現在完成式：have + [V-en]。選 (A) streamlined。", "translation": "標準化數位表單成功精簡了客戶入職導入時間。"}, {"id": 19, "target_seconds": 15, "question": "Customer feedback was reviewed thoroughly to ________ future product designs.", "options": {"A": "enhance", "B": "enhances", "C": "enhanced", "D": "enhancing"}, "answer": "A", "analysis": "to + [原形動詞]。選 (A) enhance。", "translation": "客戶回饋獲得徹底審查，以改進未來的產品設計。"}, {"id": 20, "target_seconds": 15, "question": "Management authorized a complete design ________ for the upcoming flagship smartphone.", "options": {"A": "revamp", "B": "revamping", "C": "revamped", "D": "revamps"}, "answer": "A", "analysis": "名詞位置：design revamp（設計翻新）。選 (A)。", "translation": "管理層授權對即將推出的旗艦智慧型手機進行全面外觀翻新。"}]}, "afternoon": {"quick_recall": [{"prompt": "to ________ [動詞，加速處理] shipping and delivery.", "clue": "急件加速處理", "answer": "expedite"}, {"prompt": "to ________ [動詞，翻新] the historic property.", "clue": "裝潢翻新", "answer": "renovate"}, {"prompt": "to ________ [動詞，精簡簡化] corporate workflows.", "clue": "精簡流程", "answer": "streamline"}, {"prompt": "to ________ [動詞，增強提升] employee safety standards.", "clue": "增強提升", "answer": "enhance"}, {"prompt": "The marketing department initiated a total brand ________ [名詞，改版重塑].", "clue": "改版翻新", "answer": "revamp"}, {"prompt": "Mark urgent freight as priority to ensure it is ________ [過去分詞，被加速處理].", "clue": "被加速", "answer": "expedited"}], "spaced_traps": [{"id": 1, "target_seconds": 20, "question": "The executive committee decided to ________ the downtown headquarters rather than construct a new facility.", "options": {"A": "renovate", "B": "renovation", "C": "renovating", "D": "renovated"}, "answer": "A", "trap_point": "decided to + 原形動詞 renovate！", "analysis": "decide to 後接原形動詞，選 (A) renovate。", "translation": "執行委員會決定翻修市中心總部，而不是興建新設施。"}, {"id": 2, "target_seconds": 20, "question": "Customer representatives may ________ delivery requests only with authorization from a shift supervisor.", "options": {"A": "expedite", "B": "expedited", "C": "expediting", "D": "expedition"}, "answer": "A", "trap_point": "may + 原形動詞 expedite！", "analysis": "助動詞 may 後接原形動詞，選 (A) expedite。", "translation": "客服代表只有在取得值班主管授權後才可加速交貨請求。"}, {"id": 3, "target_seconds": 20, "question": "The chief operating officer proposed a comprehensive plan to ________ inter-departmental communication.", "options": {"A": "streamline", "B": "streamlined", "C": "streamlines", "D": "streamlining"}, "answer": "A", "trap_point": "plan to + 原形動詞 streamline！", "analysis": "不定詞結構接原形動詞，選 (A) streamline。", "translation": "營運長提出了一項全面精簡跨部門溝通的計畫。"}, {"id": 4, "target_seconds": 20, "question": "High-definition video monitors were installed in the auditorium to ________ viewer engagement.", "options": {"A": "enhance", "B": "enhancement", "C": "enhanced", "D": "enhancing"}, "answer": "A", "trap_point": "to + 原形動詞 enhance！", "analysis": "表目的的不定詞接原形動詞，選 (A) enhance。", "translation": "禮堂安裝了高畫質視訊螢幕以提升觀眾的參與感。"}, {"id": 5, "target_seconds": 20, "question": "Following a multi-million-dollar ________, the waterfront luxury resort welcomed its first guests.", "options": {"A": "revamp", "B": "revamping", "C": "revamped", "D": "revamps"}, "answer": "A", "trap_point": "冠詞 a 後接名詞 revamp！", "analysis": "介系詞與冠詞後接名詞，選 (A) revamp。", "translation": "在經歷數百萬美元的翻新工程後，濱海豪華度假村迎來了第一批住客。"}, {"id": 6, "target_seconds": 20, "question": "Freight tracking updates confirmed that the delivery of critical components has been ________.", "options": {"A": "expedited", "B": "expedite", "C": "expediting", "D": "expedition"}, "answer": "A", "trap_point": "has been + expedited (現在完成被動)！", "analysis": "零件交付被加速，選過去分詞 (A) expedited。", "translation": "貨物追蹤更新證實關鍵零件的交付已經被加速處理。"}, {"id": 7, "target_seconds": 20, "question": "The museum announced the scheduled ________ of its modern art pavilion starting next quarter.", "options": {"A": "renovation", "B": "renovate", "C": "renovating", "D": "renovated"}, "answer": "A", "trap_point": "the scheduled + 名詞 renovation！", "analysis": "形容詞修飾名詞，選 (A) renovation。", "translation": "博物館宣布其現代藝術展館預定於下個季度開始進行整修。"}, {"id": 8, "target_seconds": 20, "question": "The newly adopted enterprise software successfully ________ customer account reconciliation.", "options": {"A": "streamlined", "B": "streamline", "C": "streamlining", "D": "streamlines"}, "answer": "A", "trap_point": "副詞 successfully 後接過去式動詞 streamlined！", "analysis": "動詞時態一致，選過去式 (A) streamlined。", "translation": "新採用的企業軟體成功精簡了客戶帳戶核對流程。"}, {"id": 9, "target_seconds": 20, "question": "Digital sound dampening panels provide substantial acoustic ________ for recording studios.", "options": {"A": "enhancement", "B": "enhance", "C": "enhancing", "D": "enhanced"}, "answer": "A", "trap_point": "形容詞 acoustic 修飾名詞 enhancement！", "analysis": "選名詞 (A) enhancement（提升/改善）。", "translation": "數位吸音板為錄音室提供了顯著的聲學效果改善。"}, {"id": 10, "target_seconds": 20, "question": "A strategic website ________ is expected to reduce bounce rates and boost online conversions.", "options": {"A": "revamp", "B": "revamping", "C": "revamped", "D": "revamps"}, "answer": "A", "trap_point": "形容詞 strategic 修飾名詞 revamp！", "analysis": "複合名詞結構，選名詞 (A) revamp。", "translation": "預計網站的策略性改版將降低跳出率並提升線上轉換率。"}, {"id": 11, "target_seconds": 20, "question": "Express shipping fees are applied whenever customers request to ________ order dispatch.", "options": {"A": "expedite", "B": "expedited", "C": "expediting", "D": "expedition"}, "answer": "A", "trap_point": "request to + 原形動詞 expedite！", "analysis": "不定詞後接原形動詞，選 (A) expedite。", "translation": "每當客戶要求加急訂單出貨時，均會收取特快快遞費。"}, {"id": 12, "target_seconds": 20, "question": "Funding for the complete library ________ was secured through private corporate donations.", "options": {"A": "renovation", "B": "renovate", "C": "renovated", "D": "renovating"}, "answer": "A", "trap_point": "library renovation（圖書館整修）名詞片語！", "analysis": "名詞修飾名詞，選 (A) renovation。", "translation": "圖書館全面翻修工程的資金是透過民間企業捐款籌集的。"}, {"id": 13, "target_seconds": 20, "question": "Automated barcode scanners ________ inventory intake by thirty-five percent.", "options": {"A": "streamlined", "B": "streamline", "C": "streamlines", "D": "streamlining"}, "answer": "A", "trap_point": "句中需要主要動詞過去式 streamlined！", "analysis": "主詞 scanners 接過去式動詞 (A) streamlined。", "translation": "自動條碼掃描器將庫存入庫流程精簡了 35%。"}, {"id": 14, "target_seconds": 20, "question": "Customer loyalty rewards were upgraded to ________ long-term client retention.", "options": {"A": "enhance", "B": "enhancement", "C": "enhanced", "D": "enhancing"}, "answer": "A", "trap_point": "to + 原形動詞 enhance！", "analysis": "表目的的不定詞接原形動詞，選 (A) enhance。", "translation": "客戶忠誠度獎勵經過升級以提高長期客戶留存率。"}], "part7": {"passages": [{"text_type": "Corporate Relocation Memo (辦公室內部裝修與搬遷備忘錄)", "title": "Meridian Property Management — Corporate Headquarters Renovation & Relocation Notice", "content": "OPERATIONS MEMORANDUM: MPM-RELOC-2026-12\nTO: Headquarters Staff, Department Managers, and Resident Vendors\nFROM: Meridian Property Management & Corporate Space Planning Taskforce\nDATE: November 15, 2026\nSUBJECT: Phased Floor Renovations, Division Relocation, and Courier Deliveries\n\n1. Phased Renovation Schedule and Division Move\nMeridian Property Management announces that extensive architectural and electrical remodeling of Headquarters Building A will commence on December 1. To accommodate structural acoustic ceiling replacements, fiber-optic cable rerouting, and energy-efficient LED installations, all marketing, finance, and human resources personnel currently working on Floors 4 through 6 will temporarily relocate to Building C for four months.\n\n2. Temporary Workstation Setup & Equipment Migration\nAll modular desktop equipment, dual monitors, and telephony units will be transferred over the final weekend of November by professional movers. Staff need only transport their laptops and secure personal effects.\n\n*Expedited Courier & Package Deliveries: During the four-month renovation cycle, all commercial mail, client documents, and expedited courier deliveries must be directed to the temporary reception kiosk at Entrance 2. Standard courier vans will not be permitted into the subterranean delivery dock without prior security clearance.", "questions": [{"question": "When will the floor renovations begin?", "options": {"A": "November 15", "B": "December 1", "C": "December 15", "D": "January 1"}, "answer": "B", "radar": "🔍 防漏看雷達：首段日期 'will commence on December 1'！", "analysis": "內文明確指明翻修工程將於 12 月 1 日展開，故選 (B)。"}, {"question": "Where will affected departments relocate?", "options": {"A": "Building A", "B": "Building B", "C": "Building C", "D": "Building D"}, "answer": "C", "radar": "🔍 防漏看雷達：地點定位 'relocated to Building C'！", "analysis": "文中說明受影響部門將暫時遷移至 C 棟，故選 (C)。"}, {"question": "Where should expedited courier deliveries be directed?", "options": {"A": "The main loading dock", "B": "The temporary reception kiosk at Entrance 2", "C": "The security office on the first floor", "D": "The central mailroom"}, "answer": "B", "radar": "🔍 防漏看雷達：星號附註 '*Important: Courier drop-offs requiring expedited processing should be routed to the temporary reception kiosk at Entrance 2'！", "analysis": "星號條款特別強調緊急加急快件應送往 2 號入口的臨時接待處，故選 (B)。"}]}, {"text_type": "Software Release Announcement (軟體系統升級與改版公告)", "title": "CoreNet Solutions — System Upgrades and Platform Revamp Announcement", "content": "PRODUCT RELEASE BULLETIN: CNS-VER-4.2\nISSUING ENTITY: CoreNet Solutions Product Engineering & Enterprise Services\nDATE: November 15, 2026\nDISTRIBUTION: All Enterprise License Holders and Database Administrators\n\n1. Architectural Enhancements & Speed Optimizations\nCoreNet Solutions is excited to announce the deployment of Platform Version 4.2 across our global cloud architecture. The primary purpose of this comprehensive system revamp is to enhance server speed and streamline data export procedures for massive corporate reporting datasets. Automated benchmark testing demonstrates a 40% reduction in query processing times, optimized memory caching, and instantaneous cloud backup replication for enterprise customers.\n\n2. Official Launch Date & Transition Schedule\nThe new platform interface will officially launch on Monday, November 18, at 6:00 AM UTC. System access will remain fully functional throughout the rollout, and existing account credentials will carry over seamlessly without requiring password resets.\n\n*Accelerated Administrator Training: To help corporate IT teams master our upgraded REST APIs and analytical charting tools, system administrators can accelerate user training by requesting complimentary access to certification modules through our Customer Success Helpdesk before November 30. Live interactive Q&A webinars will be held daily throughout launch week.", "questions": [{"question": "What is the primary purpose of the platform revamp?", "options": {"A": "To raise subscription pricing", "B": "To enhance server speed and streamline data export", "C": "To terminate legacy accounts", "D": "To eliminate mobile app access"}, "answer": "B", "radar": "🔍 防漏看雷達：核心目標 'engineered to enhance server speed and streamline data export procedures'！", "analysis": "首段說明改版核心在於提升伺服器速度與簡化數據匯出程序，故選 (B)。"}, {"question": "When will the new platform interface officially launch?", "options": {"A": "Monday, November 18", "B": "Friday, November 22", "C": "December 1", "D": "December 31"}, "answer": "A", "radar": "🔍 防漏看雷達：上線日期 'launch on Monday, November 18'！", "analysis": "文中指示新介面於 11 月 18 日週一正式上線，故選 (A)。"}, {"question": "How can administrators accelerate user training according to the note?", "options": {"A": "By hiring an external consultant", "B": "By requesting complimentary access to certification modules", "C": "By purchasing additional software licenses", "D": "By extending the implementation deadline"}, "answer": "B", "radar": "🔍 防漏看雷達：星號小字 'request complimentary access to our self-paced interactive certification modules'！", "analysis": "星號附註說明可申請免費取得認證培訓模組，故選 (B)。"}]}]}}}, "13": {"day": 13, "date": "11/16", "phase": 2, "phase_name": "860 突破與同義代換", "topic": "條件讓步結構 (even if vs as though) ｜ 強化、專屬與高層決策", "morning": {"chunks": [{"chunk": "provided that receipts are", "meaning": "只要附有收據（前提是）", "scenario": "Reimbursement will be honored provided that receipts are submitted.", "paraphrase": "provided that = only if = on the condition that", "alert": "provided that 等同 providing that，後接完整子句！"}, {"chunk": "even if delays occur", "meaning": "即使發生延誤（讓步）", "scenario": "We will deliver the shipment even if minor delays occur at customs.", "paraphrase": "even if = even though = despite the fact that", "alert": "even if 表縱使/即使！"}, {"chunk": "as though it were", "meaning": "彷彿宛如", "scenario": "He spoke as though it were an established fact.", "paraphrase": "as though = as if", "alert": "as though 常接虛擬語氣 were！"}, {"chunk": "reinforce the foundation", "meaning": "加固基礎結構", "scenario": "Concrete pillars were added to reinforce the foundation.", "paraphrase": "reinforce = strengthen = bolster", "alert": "名詞形式為 reinforcement！"}, {"chunk": "exclusive access to", "meaning": "專屬使用權", "scenario": "Club members have exclusive access to the executive fitness center.", "paraphrase": "exclusive to = restricted to", "alert": "副詞形式為 exclusively！"}, {"chunk": "use one's discretion", "meaning": "行使自身裁量權", "scenario": "Managers are instructed to use their discretion in customer disputes.", "paraphrase": "discretion = judgment = authority", "alert": "形容詞形式為 discretionary（自由裁量的）！"}, {"chunk": "at the discretion of", "meaning": "由……自行斟酌決定", "scenario": "Overtime approvals are granted at the discretion of the director.", "paraphrase": "at the discretion of = determined by", "alert": "固定商務片語！"}], "visual_anchor": {"title": "條件 vs. 讓步連接詞視覺秒殺錨點", "rule_1": "👀 語意為『只要 / 前提是』➔ 秒選 provided that / assuming that！", "rule_2": "👀 語意為『即使 / 縱使』➔ 秒選 even if / even though！", "golden_rule": "⚡ 教練金句：只要前提選 provided，即使讓步選 even if！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "The conference keynote will begin promptly at 9:00 AM ________ rain delays outdoor registration.", "options": {"A": "even if", "B": "as though", "C": "so that", "D": "in order to"}, "answer": "A", "analysis": "從屬連接詞引導條件讓步：even if 表『即使/縱使』，後接完整子句 rain delays outdoor registration。故選 (A)。", "translation": "即使降雨延誤了戶外報到，會議主題演講仍將於上午 9:00 準時開始。"}, {"id": 2, "target_seconds": 15, "question": "The CEO spoke ________ the corporate merger had already received full antitrust regulatory approval.", "options": {"A": "as though", "B": "even if", "C": "provided that", "D": "in case of"}, "answer": "A", "analysis": "假設語氣連接詞：as though / as if 表『彷彿/好像』。故選 (A)。", "translation": "執行長說話的口吻彷彿該企業合併案已獲得反壟斷監管機構的全面批准。"}, {"id": 3, "target_seconds": 15, "question": "Travel expense claims will be processed ________ receipts are attached to the digital submission.", "options": {"A": "provided that", "B": "even if", "C": "as though", "D": "barring"}, "answer": "A", "analysis": "條件連接詞：provided that = providing that = only if（只要/前提是）。選 (A)。", "translation": "只要數位送審中附有收據，差旅費報銷申請即可獲得處理。"}, {"id": 4, "target_seconds": 15, "question": "The engineering department conducted structural stress tests to ________ the bridge foundation.", "options": {"A": "reinforce", "B": "reinforcement", "C": "reinforced", "D": "reinforcing"}, "answer": "A", "analysis": "不定詞結構：to + [原形動詞]。reinforce（強化/加固）。故選 (A)。", "translation": "工程部門進行了結構應力測試以加固橋樑基礎。"}, {"id": 5, "target_seconds": 15, "question": "Gold cardholders enjoy ________ access to the airport business lounge across international hubs.", "options": {"A": "exclusive", "B": "exclusively", "C": "exclusivity", "D": "exclude"}, "answer": "A", "analysis": "形容詞修飾名詞：enjoy + [形容詞] + access。選 (A) exclusive（專屬的）。", "translation": "金卡會員享有跨國際樞紐機場貴賓室的專屬使用權。"}, {"id": 6, "target_seconds": 15, "question": "The board of directors granted the managing director full ________ regarding marketing budget allocation.", "options": {"A": "discretion", "B": "discreet", "C": "discreetly", "D": "discretionary"}, "answer": "A", "analysis": "形容詞 full 修飾名詞。full discretion 表『完全裁量權』。故選 (A)。", "translation": "董事會授予常務董事有關行銷預算分配的完全裁量權。"}, {"id": 7, "target_seconds": 15, "question": "The warranty covers all mechanical defects ________ proper maintenance records are provided.", "options": {"A": "assuming that", "B": "even if", "C": "as though", "D": "in spite of"}, "answer": "A", "analysis": "條件連接詞：assuming that = provided that（假設/只要）。故選 (A)。", "translation": "只要提供適當的保養紀錄，保固即涵蓋所有機械故障。"}, {"id": 8, "target_seconds": 15, "question": "The spokesperson addressed media inquiries ________ the acquisition were already concluded.", "options": {"A": "as if", "B": "even if", "C": "provided", "D": "because of"}, "answer": "A", "analysis": "as if + 假設語氣：彷彿/宛如。選 (A)。", "translation": "發言人在回答媒體詢問時，彷彿這起收購案已經敲定一般。"}, {"id": 9, "target_seconds": 15, "question": "Subscribers may cancel their service without penalty ________ they give thirty days' notice.", "options": {"A": "provided that", "B": "even if", "C": "as though", "D": "owing to"}, "answer": "A", "analysis": "條件連接詞：provided that 表『前提是/只要』。選 (A)。", "translation": "訂閱者只要提前 30 天發出通知，即可取消其服務而免受罰款。"}, {"id": 10, "target_seconds": 15, "question": "Steel girders were installed to ________ the integrity of the historic facade.", "options": {"A": "reinforce", "B": "reinforcing", "C": "reinforcement", "D": "reinforces"}, "answer": "A", "analysis": "to + [原形動詞] reinforce。選 (A)。", "translation": "安裝了鋼樑以加固這棟歷史建築外牆的結構完整性。"}, {"id": 11, "target_seconds": 15, "question": "Orion Media holds ________ broadcasting rights for the upcoming international athletics tournament.", "options": {"A": "exclusive", "B": "exclusively", "C": "exclusivity", "D": "excludes"}, "answer": "A", "analysis": "形容詞修飾名詞 rights。選 (A) exclusive（獨家的）。", "translation": "Orion 媒體擁有即將舉行的國際田徑錦標賽的獨家轉播權。"}, {"id": 12, "target_seconds": 15, "question": "Branch managers are permitted to use their own ________ when handling client disputes.", "options": {"A": "discretion", "B": "discreet", "C": "discreetly", "D": "discretionary"}, "answer": "A", "analysis": "所有格 their own 後接名詞 discretion（裁量權）。選 (A)。", "translation": "分行經理在處理客戶爭端時獲准行使自身的裁量權。"}, {"id": 13, "target_seconds": 15, "question": "Shipments will arrive within forty-eight hours ________ the order is confirmed before noon.", "options": {"A": "provided that", "B": "even if", "C": "as though", "D": "despite"}, "answer": "A", "analysis": "條件子句：provided that（只要……）。選 (A)。", "translation": "只要訂單在中午前確認，貨物將在 48 小時內送達。"}, {"id": 14, "target_seconds": 15, "question": "He managed the regional sales team ________ he had decades of corporate leadership experience.", "options": {"A": "as though", "B": "even if", "C": "in case", "D": "barring"}, "answer": "A", "analysis": "as though + S+V 表『彷彿』。選 (A)。", "translation": "他管理區域銷售團隊的方式，彷彿擁有數十年的企業領導經驗。"}, {"id": 15, "target_seconds": 15, "question": "The company will proceed with the product launch ________ international trade tariffs increase.", "options": {"A": "even if", "B": "as though", "C": "provided", "D": "so as to"}, "answer": "A", "analysis": "讓步連接詞：even if 表『即使』。選 (A)。", "translation": "即使國際貿易關稅上調，該公司仍將推進產品發布。"}, {"id": 16, "target_seconds": 15, "question": "Special concrete admixtures were chosen to ________ the marine pilings against saltwater erosion.", "options": {"A": "reinforce", "B": "reinforcement", "C": "reinforced", "D": "reinforcing"}, "answer": "A", "analysis": "to + [原形動詞] reinforce。選 (A)。", "translation": "選用了特殊混凝土添加劑以加固海洋樁柱以抵禦鹽水侵蝕。"}, {"id": 17, "target_seconds": 15, "question": "The boutique hotel offers ________ perks to frequent business travelers.", "options": {"A": "exclusive", "B": "exclusively", "C": "exclusiveness", "D": "exclude"}, "answer": "A", "analysis": "形容詞修飾名詞 perks。選 (A) exclusive。", "translation": "這家精品飯店為頻繁出差的商務旅客提供專屬禮遇。"}, {"id": 18, "target_seconds": 15, "question": "Supervisors must exercise sound ________ when evaluating employee performance appeals.", "options": {"A": "discretion", "B": "discreet", "C": "discreetly", "D": "discretionary"}, "answer": "A", "analysis": "形容詞 sound 修飾名詞 (A) discretion（明智的裁量判斷）。", "translation": "主管在評估員工績效申訴時必須行使明智的裁量權。"}, {"id": 19, "target_seconds": 15, "question": "Vendors are eligible for rapid payment discounts ________ invoices are submitted electronically.", "options": {"A": "provided that", "B": "even if", "C": "as though", "D": "regardless"}, "answer": "A", "analysis": "條件連接詞：provided that（前提是/只要）。選 (A)。", "translation": "只要電子提交發票，供應商即符合快速付款折扣的資格。"}, {"id": 20, "target_seconds": 15, "question": "Management treated the minor software glitch ________ it were a major national security threat.", "options": {"A": "as though", "B": "even if", "C": "provided", "D": "in spite"}, "answer": "A", "analysis": "as though + 虛擬語氣 were 表『彷彿』。選 (A)。", "translation": "管理層對待這個微小的軟體故障，彷彿它是重大的國家安全威脅一般。"}]}, "afternoon": {"quick_recall": [{"prompt": "The contract is valid ________ [連接詞，前提是/只要] both parties sign.", "clue": "前提是只要 (provided ...)", "answer": "provided that"}, {"prompt": "He spoke ________ [連接詞，彷彿/宛如] he owned the corporation.", "clue": "彷彿宛如 (as ...)", "answer": "as though / as if"}, {"prompt": "We will proceed ________ [連接詞，即使/縱使] budget is reduced.", "clue": "即使縱使 (even ...)", "answer": "even if"}, {"prompt": "Steel beams were added to ________ [動詞，加固強化] the roof.", "clue": "加固強化", "answer": "reinforce"}, {"prompt": "VIP guests enjoy ________ [形容詞，專屬獨家的] club access.", "clue": "專屬獨家的", "answer": "exclusive"}, {"prompt": "Department heads have full ________ [名詞，裁量權/斟酌決定權].", "clue": "自由裁量權", "answer": "discretion"}], "spaced_traps": [{"id": 1, "target_seconds": 20, "question": "The airline will maintain scheduled flights ________ weather conditions deteriorate slightly.", "options": {"A": "even if", "B": "as though", "C": "provided", "D": "in case of"}, "answer": "A", "trap_point": "even if（即使）引導讓步子句，非條件 provided！", "analysis": "依句意表即使惡劣天氣稍微惡化仍將維持航班，選 (A) even if。", "translation": "即使天氣狀況稍微惡化，航空公司仍將維持既定航班。"}, {"id": 2, "target_seconds": 20, "question": "The junior executive acted ________ he were authorized to make binding corporate decisions.", "options": {"A": "as though", "B": "even if", "C": "provided that", "D": "because of"}, "answer": "A", "trap_point": "as though + were（虛擬語氣彷彿）！", "analysis": "as though 後接虛擬語氣 were，選 (A) as though。", "translation": "該初階主管舉止行事彷彿他已被授權做出具約束力的企業決策。"}, {"id": 3, "target_seconds": 20, "question": "Equipment rentals are approved ________ a valid credit guarantee is provided on file.", "options": {"A": "provided that", "B": "even if", "C": "as though", "D": "despite"}, "answer": "A", "trap_point": "provided that 表只要/前提是！", "analysis": "表示前提條件，選 (A) provided that。", "translation": "只要檔案中附有有效的信用擔保，設備租賃即獲批准。"}, {"id": 4, "target_seconds": 20, "question": "The building inspector recommended extra carbon fiber wraps to ________ load-bearing columns.", "options": {"A": "reinforce", "B": "reinforcement", "C": "reinforced", "D": "reinforcing"}, "answer": "A", "trap_point": "to + 原形動詞 reinforce！", "analysis": "不定詞接原形動詞，選 (A) reinforce。", "translation": "建築檢驗員建議使用額外的碳纖維裹層來加固承重柱。"}, {"id": 5, "target_seconds": 20, "question": "Members receive ________ invitations to our annual private investment gala.", "options": {"A": "exclusive", "B": "exclusively", "C": "exclusivity", "D": "exclude"}, "answer": "A", "trap_point": "exclusive invitations（專屬邀請函）形容詞！", "analysis": "形容詞修飾名詞 invitations，選 (A) exclusive。", "translation": "會員將收到參加我們年度私人投資晚會的專屬邀請。"}, {"id": 6, "target_seconds": 20, "question": "Store managers may use their own ________ in issuing refunds exceeding fifty dollars.", "options": {"A": "discretion", "B": "discreet", "C": "discreetly", "D": "discretionary"}, "answer": "A", "trap_point": "their own + 名詞 discretion！", "analysis": "所有格修飾名詞，選 (A) discretion（裁量權）。", "translation": "店經理在簽發超過 50 美元的退款時可行使自己的裁量權。"}, {"id": 7, "target_seconds": 20, "question": "The shipment will depart on time ________ minor mechanical adjustments are completed by 3 PM.", "options": {"A": "provided that", "B": "even if", "C": "as though", "D": "owing to"}, "answer": "A", "trap_point": "provided that 表前提條件只要！", "analysis": "只要機械調整在下午 3 點前完成即可出發，選 (A) provided that。", "translation": "只要在下午 3 點前完成微小的機械調整，貨物將按時啟運。"}, {"id": 8, "target_seconds": 20, "question": "The candidate answered technical questions ________ she had developed the proprietary algorithm herself.", "options": {"A": "as though", "B": "even if", "C": "provided", "D": "due to"}, "answer": "A", "trap_point": "as though 表彷彿！", "analysis": "表現得好像自己親自開發了演算法，選 (A) as though。", "translation": "該應徵者回答技術問題時，彷彿自己親自開發了該專利演算法。"}, {"id": 9, "target_seconds": 20, "question": "Management pledged to honor the severance agreements ________ the company changes ownership.", "options": {"A": "even if", "B": "as though", "C": "provided", "D": "in spite"}, "answer": "A", "trap_point": "even if 表即使！", "analysis": "即使公司易主仍將履行協議，選 (A) even if。", "translation": "管理層承諾即使公司所有權發生變更，仍將履行遣散協議。"}, {"id": 10, "target_seconds": 20, "question": "Engineers added internal steel struts to ________ structural resilience against wind shear.", "options": {"A": "reinforce", "B": "reinforcing", "C": "reinforcement", "D": "reinforces"}, "answer": "A", "trap_point": "to + 原形動詞 reinforce！", "analysis": "不定詞接原形動詞，選 (A) reinforce。", "translation": "工程師添加了內部鋼支柱以強化抗風切變的結構韌性。"}, {"id": 11, "target_seconds": 20, "question": "The executive lounge provides an ________ dining environment for corporate suite guests.", "options": {"A": "exclusive", "B": "exclusively", "C": "exclusivity", "D": "exclude"}, "answer": "A", "trap_point": "exclusive dining environment（專屬餐飲環境）！", "analysis": "冠詞 an 後接母音開頭的形容詞 (A) exclusive。", "translation": "行政貴賓室為企業套房賓客提供專屬用餐環境。"}, {"id": 12, "target_seconds": 20, "question": "Discretionary spending requests remain subject to executive ________.", "options": {"A": "discretion", "B": "discreet", "C": "discreetly", "D": "discretionary"}, "answer": "A", "trap_point": "executive discretion（高層裁量）名詞片語！", "analysis": "形容詞 executive 修飾名詞 (A) discretion。", "translation": "非必要支出請求仍須由高層自行斟酌裁量。"}, {"id": 13, "target_seconds": 20, "question": "Discounts will remain active ________ accounts are settled within thirty days of invoicing.", "options": {"A": "provided that", "B": "even if", "C": "as though", "D": "barring"}, "answer": "A", "trap_point": "provided that 表只要！", "analysis": "只要在 30 天內結清帳戶即可享有折扣，選 (A) provided that。", "translation": "只要在開立發票後 30 天內結清帳戶，折扣即持續有效。"}, {"id": 14, "target_seconds": 20, "question": "The spokesperson smiled ________ the hostile takeover bid were completely insignificant.", "options": {"A": "as if", "B": "even if", "C": "provided", "D": "because of"}, "answer": "A", "trap_point": "as if + were（宛如彷彿）！", "analysis": "選 (A) as if 表宛如彷彿。", "translation": "發言人面帶微笑，宛如這起惡意收購要約微不足道一般。"}], "part7": {"passages": [{"text_type": "Corporate Finance Policy (企業財務支出與差旅規範手冊)", "title": "Pinnacle International — Corporate Discretionary Spending & Travel Benefits", "content": "FINANCIAL POLICY DIRECTIVE: PIN-FIN-2026-13\nTO: Regional Directors, Division Heads, and Senior Financial Controllers\nFROM: Corporate Governance Bureau & Office of the Chief Financial Officer\nDATE: November 16, 2026\nSUBJECT: Updated Discretionary Spending Caps and Premium Travel Authorization\n\n1. Discretionary Spending Allowances\nTo ensure prudent fiscal governance while empowering regional leadership to cultivate strategic client partnerships, Pinnacle International has updated its global spending schedules. The quarterly discretionary spending limit for Regional Directors is set at $10,000 per financial quarter. These funds may be allocated toward regional marketing events, client entertainment dinners, and local staff recognition milestones.\n\n2. Executive Approval Thresholds\nAll business expenditures exceeding the authorized quarterly cap require prior written approval from the Chief Financial Officer before financial commitments are incurred. Expense claims submitted without executive authorization will be rejected by corporate accounting without appeal.\n\n*Premium Flight Travel Regulations: International business travel must adhere to standardized corporate cabin policies. Premium business class travel is authorized exclusively provided that flights exceed six hours in continuous duration. Shorter international flights and all domestic journeys must be booked in standard economy class.", "questions": [{"question": "What is the quarterly discretionary spending limit for Regional Directors?", "options": {"A": "$5,000", "B": "$10,000", "C": "$25,000", "D": "$50,000"}, "answer": "B", "radar": "🔍 防漏看雷達：定位具體金額 'allocate discretionary funds up to $10,000 per fiscal quarter'！", "analysis": "文中明確規定每季度自由裁量資金上限為 10,000 美元，故選 (B)。"}, {"question": "Who must approve expenditures exceeding the specified limit?", "options": {"A": "The Managing Director", "B": "The Chief Financial Officer", "C": "The Human Resources Director", "D": "The Internal Auditor"}, "answer": "B", "radar": "🔍 防漏看雷達：審批對象 'require prior authorization from the Chief Financial Officer'！", "analysis": "文中指出超出額度須取得財務長（CFO）事先核准，故選 (B)。"}, {"question": "Under what condition is exclusive business class travel authorized?", "options": {"A": "For all domestic trips", "B": "Provided that flights exceed six hours in continuous duration", "C": "Whenever traveling with a client", "D": "During peak holiday seasons only"}, "answer": "B", "radar": "🔍 防漏看雷達：星號條件條款 '*Important Condition: ... provided that flights exceed six hours in continuous duration'！", "analysis": "星號條款特別強調連續飛行超過 6 小時方可享受商務艙，故選 (B)。"}]}, {"text_type": "Engineering Inspection Notice (建築結構補強與保固條款公告)", "title": "Pinnacle Towers — Structural Reinforcement & Long-Term Warranty Terms", "content": "ENGINEERING DIRECTIVE: PT-STR-2026-88\nISSUED BY: Apex Structural Engineering Consultants & Facility Oversight Directorate\nDATE: November 16, 2026\nAUDIENCE: Commercial Tenants, Retail Lessees, and Property Management Staff\n\n1. Subterranean Structural Reinforcement Works\nApex Structural Engineering announces the successful completion of foundational seismic bracing and concrete reinforcement across Pinnacle Towers commercial complex. In accordance with updated municipal civil codes and high-rise structural safety standards, subterranean levels P1 and P2 have been fitted with carbon-fiber reinforced polymer brackets, heavy structural steel cross-beams, and automated moisture mitigation pumps to guard against subterranean hydrostatic pressure and foundation settlement.\n\n2. Fifteen-Year Warranty Coverage & Maintenance Mandates\nFollowing rigorous load testing, Apex Engineering certifies that the structural integrity warranty will remain valid for fifteen years from the completion date. This comprehensive warranty protects the property against subterranean wall cracks, seismic joint displacement, and foundational water seepage.\n\n*Mandatory Warranty Operational Conditions: To maintain the operational validity of the fifteen-year warranty coverage, property management must comply with mandatory preventative maintenance covenants. Building administration is required to submit annual inspection logs electronically by December 31 each year to the municipal engineering archives.", "questions": [{"question": "Which parking levels will receive structural reinforcement?", "options": {"A": "Levels 1 and 2", "B": "Levels 3 and 4", "C": "Subterranean levels P1 and P2", "D": "Rooftop observation decks"}, "answer": "C", "radar": "🔍 防漏看雷達：施工位置 'subterranean levels P1 and P2'！", "analysis": "首段指明在地下 P1 與 P2 層進行結構加固，故選 (C)。"}, {"question": "How long is the structural integrity warranty valid?", "options": {"A": "5 years", "B": "10 years", "C": "15 years", "D": "20 years"}, "answer": "C", "radar": "🔍 防漏看雷達：保固年限 'guarantees structural integrity for fifteen years'！", "analysis": "文中明確載明保固期為 15 年，故選 (C)。"}, {"question": "What requirement must be met to keep the warranty operational?", "options": {"A": "Submitting annual inspection logs electronically by December 31", "B": "Paying an annual renewal premium", "C": "Replacing support beams every five years", "D": "Allowing monthly tenant walkthroughs"}, "answer": "A", "radar": "🔍 防漏看雷達：星號但書條件 '*Clause 8.4: ... provided that annual inspection logs are submitted electronically to Pinnacle by December 31'！", "analysis": "星號條款載明必須在 12 月 31 日前電子提交年度檢查日誌，故選 (A)。"}]}]}}}, "14": {"day": 14, "date": "11/17", "phase": 2, "phase_name": "860 突破與同義代換", "topic": "關係子句簡化 ｜ 履行承諾、加盟與迫切情勢", "morning": {"chunks": [{"chunk": "fulfill the obligation", "meaning": "履行義務/達成承諾", "scenario": "The vendor worked tirelessly to fulfill the obligation on time.", "paraphrase": "fulfill = execute = satisfy = meet", "alert": "名詞形式為 fulfillment！"}, {"chunk": "an affiliate of", "meaning": "……的附屬機構/子公司", "scenario": "Our branch is a regional affiliate of the parent holding company.", "paraphrase": "affiliate = subsidiary = partner entity", "alert": "動詞形式為 be affiliated with！"}, {"chunk": "pressing matters", "meaning": "迫切事項", "scenario": "Management met behind closed doors to discuss pressing matters.", "paraphrase": "pressing = urgent = critical = acute", "alert": "pressing 是形容詞！"}, {"chunk": "it is imperative that", "meaning": "勢在必行/極為重要", "scenario": "It is imperative that safety protocols be followed strictly.", "paraphrase": "imperative = essential = vital = crucial", "alert": "後面接 (should) + 原形動詞！"}, {"chunk": "those attending the event", "meaning": "參加該活動的人員", "scenario": "Those attending the event must wear identification badges.", "paraphrase": "those attending = participants = attendees", "alert": "those who attend 簡化為 those attending！"}, {"chunk": "anyone wishing to", "meaning": "任何希望……的人", "scenario": "Anyone wishing to apply should submit a resume online.", "paraphrase": "anyone wishing to = any candidate who wishes to", "alert": "分詞簡化句型！"}, {"chunk": "pressing deadlines", "meaning": "緊迫的截止時間", "scenario": "The team worked over the weekend due to pressing deadlines.", "paraphrase": "pressing deadlines = tight schedules", "alert": "商業情境高頻語塊！"}], "visual_anchor": {"title": "關係代名詞子句簡化 (Participle Reduction) 視覺錨點", "rule_1": "👀 主格關代 + 主動動詞 [Those who attend] ➔ 簡化為「V-ing」[Those attending]！", "rule_2": "👀 主格關代 + 被動動詞 [Items that were ordered] ➔ 簡化為「V-en」[Items ordered]！", "golden_rule": "⚡ 教練金句：省掉 who/which，主動留 -ing，被動留 -ed！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "The supplier worked overtime to ________ all contractual obligations before the deadline.", "options": {"A": "fulfill", "B": "fulfillment", "C": "fulfilling", "D": "fulfilled"}, "answer": "A", "analysis": "不定詞片語：to + [原形動詞] fulfill contractual obligations（履行合約義務）。選 (A)。", "translation": "該供應商加班工作以在截止期限前履行所有合約義務。"}, {"id": 2, "target_seconds": 15, "question": "Apex Logistics is an ________ of the international maritime shipping conglomerate.", "options": {"A": "affiliate", "B": "affiliated", "C": "affiliation", "D": "affiliating"}, "answer": "A", "analysis": "冠詞 an 後接名詞。an affiliate of...（……的附屬機構/子公司）。選 (A)。", "translation": "Apex 物流是這家國際海運企業集團的附屬公司。"}, {"id": 3, "target_seconds": 15, "question": "The executive board held an emergency session to address the most ________ operational concerns.", "options": {"A": "pressing", "B": "press", "C": "pressed", "D": "pressure"}, "answer": "A", "analysis": "形容詞修飾名詞 concerns。pressing concerns 表『迫切的疑慮/迫切問題』。選 (A)。", "translation": "執行董事會召開緊急會議以處理最迫切的營運疑慮。"}, {"id": 4, "target_seconds": 15, "question": "It is ________ that all factory workers inspect their protective gear before starting machinery.", "options": {"A": "imperative", "B": "imperatively", "C": "imperativeness", "D": "imperatives"}, "answer": "A", "analysis": "虛主詞句型：It is imperative that + S + (should) 原形動詞。imperative 表『極為重要的/勢在必行的』。選 (A)。", "translation": "工廠所有工人在啟動機械前檢查防護裝備，這是勢在必行的。"}, {"id": 5, "target_seconds": 15, "question": "Employees ________ in the advanced leadership seminars must complete prerequisite reading.", "options": {"A": "participating", "B": "participate", "C": "participated", "D": "participation"}, "answer": "A", "analysis": "分詞後位修飾主詞 Employees：[who participate] 簡化為主動分詞 participating。選 (A)。", "translation": "參加高階領導研討會的員工必須完成先修閱讀材料。"}, {"id": 6, "target_seconds": 15, "question": "The warranty will ________ replacement requests provided proof of purchase is furnished.", "options": {"A": "fulfill", "B": "fulfillment", "C": "fulfills", "D": "fulfilling"}, "answer": "A", "analysis": "助動詞 will 後接原形動詞 (A) fulfill。", "translation": "只要提供購買證明，保固即將履行更換申請。"}, {"id": 7, "target_seconds": 15, "question": "The local medical clinic has officially ________ with the university teaching hospital.", "options": {"A": "affiliated", "B": "affiliate", "C": "affiliation", "D": "affiliating"}, "answer": "A", "analysis": "現在完成式：has officially + [V-en]。be affiliated with（與……結盟/隸屬於）。選 (A)。", "translation": "該地方醫療診所已正式隸屬於大學教學醫院。"}, {"id": 8, "target_seconds": 15, "question": "Due to ________ budget constraints, non-essential travel has been suspended until next quarter.", "options": {"A": "pressing", "B": "press", "C": "pressure", "D": "presses"}, "answer": "A", "analysis": "形容詞修飾名詞 constraints。pressing 表『緊迫的』，選 (A)。", "translation": "由於緊迫的預算限制，非必要的差旅已暫停至下一季度。"}, {"id": 9, "target_seconds": 15, "question": "It is absolutely ________ that confidential client files remain secured under encryption.", "options": {"A": "imperative", "B": "imperatively", "C": "imperatives", "D": "imperativeness"}, "answer": "A", "analysis": "It is + [形容詞] that... 選 (A) imperative。", "translation": "機密客戶檔案在加密保護下保持安全，這是絕對不可或缺的。"}, {"id": 10, "target_seconds": 15, "question": "Anyone ________ to submit the survey by Friday will receive a gift voucher.", "options": {"A": "choosing", "B": "choose", "C": "chose", "D": "chosen"}, "answer": "A", "analysis": "主詞 Anyone 後接主動分詞 choosing [who chooses] 修飾。選 (A)。", "translation": "任何選擇在週五前提交問卷者均將獲得禮品券。"}, {"id": 11, "target_seconds": 15, "question": "The warehouse manager promised to ________ the outstanding backorders by tomorrow evening.", "options": {"A": "fulfill", "B": "fulfilled", "C": "fulfilling", "D": "fulfillment"}, "answer": "A", "analysis": "promised to + [原形動詞] fulfill。選 (A)。", "translation": "倉庫經理承諾在明晚之前履行所有積壓訂單。"}, {"id": 12, "target_seconds": 15, "question": "Our regional marketing firm is a proud ________ of the Global Communications Network.", "options": {"A": "affiliate", "B": "affiliated", "C": "affiliating", "D": "affiliation"}, "answer": "A", "analysis": "冠詞 a 後接名詞 affiliate。選 (A)。", "translation": "我們的區域行銷公司是全球傳播網絡引以為傲的加盟機構。"}, {"id": 13, "target_seconds": 15, "question": "Senior leaders met yesterday to deliberate on ________ matters regarding labor negotiations.", "options": {"A": "pressing", "B": "press", "C": "pressed", "D": "pressure"}, "answer": "A", "analysis": "形容詞修飾 matters。pressing matters（緊急事務）。選 (A)。", "translation": "資深領導層昨日會面，商議有關勞工談判的緊急事項。"}, {"id": 14, "target_seconds": 15, "question": "It is ________ that audit teams receive unrestricted access to accounting ledgers.", "options": {"A": "imperative", "B": "imperatively", "C": "imperativeness", "D": "imperatives"}, "answer": "A", "analysis": "It is imperative that + S + 原形動詞。選 (A)。", "translation": "稽核團隊獲得不受限制地查閱會計帳冊的權限，這是至關重要的。"}, {"id": 15, "target_seconds": 15, "question": "Those ________ for the position must submit three letters of professional recommendation.", "options": {"A": "applying", "B": "apply", "C": "applied", "D": "application"}, "answer": "A", "analysis": "Those [who are applying] 簡化為主動分詞 applying。選 (A)。", "translation": "申請該職位者必須提交三封專業推薦信。"}, {"id": 16, "target_seconds": 15, "question": "The courier service failed to ________ its guarantee of morning package delivery.", "options": {"A": "fulfill", "B": "fulfillment", "C": "fulfilled", "D": "fulfills"}, "answer": "A", "analysis": "failed to + [原形動詞] fulfill。選 (A)。", "translation": "快遞服務未能履行其早間包裹交付的保證。"}, {"id": 17, "target_seconds": 15, "question": "Several domestic regional banks are ________ with the National Clearinghouse.", "options": {"A": "affiliated", "B": "affiliate", "C": "affiliation", "D": "affiliates"}, "answer": "A", "analysis": "be affiliated with（隸屬於/加盟）。選 (A) affiliated。", "translation": "幾家國內區域性銀行隸屬於國家結算所。"}, {"id": 18, "target_seconds": 15, "question": "The director emphasized the ________ need for updated computer security infrastructure.", "options": {"A": "pressing", "B": "press", "C": "pressed", "D": "pressure"}, "answer": "A", "analysis": "形容詞修飾 need。pressing need（迫切需求）。選 (A)。", "translation": "處長強調了對更新電腦安全基礎設施的迫切需求。"}, {"id": 19, "target_seconds": 15, "question": "It is ________ for project leads to document any changes in client project scope.", "options": {"A": "imperative", "B": "imperatively", "C": "imperatives", "D": "imperativeness"}, "answer": "A", "analysis": "It is imperative for sb to do sth。選 (A)。", "translation": "專案負責人記錄客戶專案範圍的任何變更，這是極為重要的。"}, {"id": 20, "target_seconds": 15, "question": "Contractors ________ the safety guidelines will be subject to immediate site removal.", "options": {"A": "violating", "B": "violate", "C": "violated", "D": "violation"}, "answer": "A", "analysis": "Contractors [who violate] 簡化為主動分詞 violating。選 (A)。", "translation": "違反安全準則的承包商將立即被移離現場。"}]}, "afternoon": {"quick_recall": [{"prompt": "to ________ [動詞，履行/達成] contractual requirements.", "clue": "履行合約", "answer": "fulfill"}, {"prompt": "The local agency is an ________ [名詞，附屬機構/子公司] of ABC Corp.", "clue": "附屬分支機構", "answer": "affiliate"}, {"prompt": "The committee addressed several ________ [形容詞，迫切的] problems.", "clue": "迫切緊迫的", "answer": "pressing"}, {"prompt": "It is ________ [形容詞，勢在必行的/極為重要的] that all staff attend.", "clue": "勢在必行的", "answer": "imperative"}, {"prompt": "Those ________ [分詞，申請...] for the grant must submit forms.", "clue": "那些申請的人 (Those ...)", "answer": "applying"}, {"prompt": "be ________ [過去分詞，隸屬於] with the medical society.", "clue": "隸屬於結盟", "answer": "affiliated with"}], "spaced_traps": [{"id": 1, "target_seconds": 20, "question": "The vendor promised to ________ all wholesale orders within three business days.", "options": {"A": "fulfill", "B": "fulfillment", "C": "fulfilling", "D": "fulfilled"}, "answer": "A", "trap_point": "promised to + 原形動詞 fulfill！", "analysis": "to 後接原形動詞，選 (A) fulfill。", "translation": "該供應商承諾在三個工作日內履行所有批發訂單。"}, {"id": 2, "target_seconds": 20, "question": "The regional research center is a recognized ________ of the national institute.", "options": {"A": "affiliate", "B": "affiliated", "C": "affiliation", "D": "affiliating"}, "answer": "A", "trap_point": "a recognized + 名詞 affiliate！", "analysis": "形容詞修飾名詞，選 (A) affiliate（附屬機構）。", "translation": "該區域研究中心是國家學院公認的附屬機構。"}, {"id": 3, "target_seconds": 20, "question": "The board will convene this afternoon to review several ________ personnel matters.", "options": {"A": "pressing", "B": "press", "C": "pressed", "D": "pressure"}, "answer": "A", "trap_point": "pressing personnel matters（迫切的人事問題）！", "analysis": "形容詞修飾名詞 matters，選 (A) pressing。", "translation": "董事會將於今天下午召開會議，以審查幾項迫切的人事問題。"}, {"id": 4, "target_seconds": 20, "question": "It is ________ that all financial records be kept strictly confidential.", "options": {"A": "imperative", "B": "imperatively", "C": "imperativeness", "D": "imperatives"}, "answer": "A", "trap_point": "It is imperative that + S + 原形動詞！", "analysis": "虛主詞句型選形容詞 (A) imperative。", "translation": "所有財務記錄嚴格保密，這是極為重要的。"}, {"id": 5, "target_seconds": 20, "question": "Employees ________ additional certifications will be considered for salary increases.", "options": {"A": "earning", "B": "earn", "C": "earned", "D": "earns"}, "answer": "A", "trap_point": "Employees [who earn] 簡化為主動分詞 earning！", "analysis": "主動分詞修飾先行詞，選 (A) earning。", "translation": "獲得額外認證的員工將被考慮加薪。"}, {"id": 6, "target_seconds": 20, "question": "Failure to ________ warranty conditions will nullify the customer service agreement.", "options": {"A": "fulfill", "B": "fulfillment", "C": "fulfills", "D": "fulfilling"}, "answer": "A", "trap_point": "Failure to + 原形動詞 fulfill！", "analysis": "to 接原形動詞，選 (A) fulfill。", "translation": "未能履行保固條件將使客戶服務協議失效。"}, {"id": 7, "target_seconds": 20, "question": "All regional chapters are ________ with the national professional association.", "options": {"A": "affiliated", "B": "affiliate", "C": "affiliation", "D": "affiliates"}, "answer": "A", "trap_point": "are affiliated with 表隸屬於！", "analysis": "被動搭配選過去分詞 (A) affiliated。", "translation": "所有地方分會均隸屬於國家專業協會。"}, {"id": 8, "target_seconds": 20, "question": "Rising shipping rates have created a ________ need for domestic warehouse space.", "options": {"A": "pressing", "B": "press", "C": "pressed", "D": "pressure"}, "answer": "A", "trap_point": "a pressing need 表迫切需求！", "analysis": "形容詞修飾 need，選 (A) pressing。", "translation": "飆升的運輸費率催生了對國內倉庫空間的迫切需求。"}, {"id": 9, "target_seconds": 20, "question": "It is ________ that contractors follow all OSHA safety protocols on the job site.", "options": {"A": "imperative", "B": "imperatively", "C": "imperatives", "D": "imperativeness"}, "answer": "A", "trap_point": "It is imperative that 句型！", "analysis": "選形容詞 (A) imperative。", "translation": "承包商在工地上遵守所有 OSHA 安全法規是勢在必行的。"}, {"id": 10, "target_seconds": 20, "question": "Applicants ________ previous experience in database administration will be prioritized.", "options": {"A": "possessing", "B": "possess", "C": "possessed", "D": "possession"}, "answer": "A", "trap_point": "Applicants [who possess] 簡化為主動分詞 possessing！", "analysis": "主動分詞修飾，選 (A) possessing。", "translation": "具有資料庫管理先前經驗的應徵者將獲優先考慮。"}, {"id": 11, "target_seconds": 20, "question": "The airline was unable to ________ passenger rebooking requests following the blizzard.", "options": {"A": "fulfill", "B": "fulfilled", "C": "fulfilling", "D": "fulfillment"}, "answer": "A", "trap_point": "unable to + 原形動詞 fulfill！", "analysis": "to 後接原形動詞，選 (A) fulfill。", "translation": "暴風雪過後，航空公司無法滿足乘客的重新訂位要求。"}, {"id": 12, "target_seconds": 20, "question": "Horizon Media and its digital ________ announced a joint content partnership.", "options": {"A": "affiliates", "B": "affiliated", "C": "affiliation", "D": "affiliating"}, "answer": "A", "trap_point": "its digital + 名詞複數 affiliates！", "analysis": "名詞作受詞，選 (A) affiliates（附屬機構）。", "translation": "Horizon 媒體及其數位附屬機構宣布了一項聯合內容合作夥伴關係。"}, {"id": 13, "target_seconds": 20, "question": "The steering committee will prioritize the most ________ issues regarding facility safety.", "options": {"A": "pressing", "B": "press", "C": "pressed", "D": "pressure"}, "answer": "A", "trap_point": "the most pressing issues（最緊迫的問題）！", "analysis": "最高級修飾形容詞，選 (A) pressing。", "translation": "指導委員會將優先考慮有關設施安全的最緊迫問題。"}, {"id": 14, "target_seconds": 20, "question": "It is ________ that visitors wear designated security identification badges at all times.", "options": {"A": "imperative", "B": "imperatively", "C": "imperatives", "D": "imperativeness"}, "answer": "A", "trap_point": "It is imperative that 結構！", "analysis": "選形容詞 (A) imperative。", "translation": "訪客始終佩戴指定的安全識別證是極為必要的。"}], "part7": {"passages": [{"text_type": "Corporate Press Release (物流戰略合作夥伴新聞稿)", "title": "Global Logistics Network (GLN) — Strategic Affiliate Partnership with Apex Cargo", "content": "GLOBAL LOGISTICS NETWORK MEDIA RELEASE\nFOR IMMEDIATE RELEASE: November 17, 2026\nHEADQUARTERS: Singapore & Brussels Logistics Hub\nCONTACT: media@globallogistics.org | Corporate Relations Desk\n\n1. Strategic Alliance and Air Cargo Expansion\nGlobal Logistics Network (GLN) proudly announces that Apex Cargo has officially joined its global freight consortium as an accredited affiliate member. This landmark partnership connects GLN's extensive European rail and marine network with Apex Cargo's advanced trans-Pacific air freight infrastructure, opening faster expedited shipping lanes between Southeast Asia and Western Europe for time-sensitive commercial shipments.\n\n2. Dedicated Regional Hub Operations\nUnder the terms of this long-term commercial agreement, Apex Cargo will directly oversee air freight operations connecting through Changi International Airport in Singapore. Dedicated cold-chain pharmaceutical cargo facilities, high-capacity customs inspection sorting bays, and specialized aerospace parts staging terminals will operate twenty-four hours daily under certified logistics supervisors and temperature-controlled monitoring protocols.\n\n*Mandatory Quality & Environmental Standards: In order to maintain active consortium credentials, all affiliated partners must comply with ISO-9001 environmental standards and carbon monitoring protocols by December 31, 2026. Non-compliant affiliates will be subject to operational suspension and mandatory audits.", "questions": [{"question": "In what capacity has Apex Cargo joined GLN?", "options": {"A": "As an independent competitor", "B": "As an accredited affiliate member", "C": "As an external auditor", "D": "As a temporary seasonal contractor"}, "answer": "B", "radar": "🔍 防漏看雷達：定位身份 'joined the organization as an accredited affiliate member'！", "analysis": "文中明確說明作為認證附屬成員加入，故選 (B)。"}, {"question": "What specific operations will Apex Cargo oversee?", "options": {"A": "Maritime terminal security", "B": "Air freight operations connecting through Changi International Airport", "C": "Automated warehousing in Europe", "D": "Passenger ticketing systems"}, "answer": "B", "radar": "🔍 防漏看雷達：業務範圍 'manage air freight operations ... connecting through Changi International Airport'！", "analysis": "內文指明負責經由樟宜機場轉運的航空貨運業務，故選 (B)。"}, {"question": "What requirement must affiliated partners satisfy by December 31?", "options": {"A": "Upgrade to supersonic aircraft", "B": "Comply with ISO-9001 environmental standards", "C": "Establish offices in five countries", "D": "Double their corporate share capital"}, "answer": "B", "radar": "🔍 防漏看雷達：星號但書條件 '*Special Provision: Affiliated partners must comply with ISO-9001 environmental standards by December 31'！", "analysis": "星號條款特別強調必須在 12 月 31 日前遵守 ISO-9001 環境標準，故選 (B)。"}]}, {"text_type": "Information Security Bulletin (資訊安全緊急通報與筆電出境規範)", "title": "Information Security Office — Mandatory Workstation Encryption & Data Safeguards", "content": "SECURITY MANDATE: SEC-URG-2026-14\nTO: All Corporate Personnel, Subcontractors, and Remote Operators\nISSUED BY: Global Information Security Office & Chief Technology Officer\nDATE: November 17, 2026\nURGENCY LEVEL: CRITICAL — IMMEDIATE ACTION REQUIRED ACROSS ALL NETWORKS\n\n1. Mandatory Workstation Encryption Upgrade\nFollowing recent international cyber threats targeting corporate finance networks, the Information Security Office has issued an urgent directive. All staff members must upgrade their workstation encryption software by Friday at 5:00 PM without exception. Workstations failing to install Security Patch 9.4 by the deadline will face automatic network isolation, certificate revocation, and suspension of corporate email access until verified by desktop technicians.\n\n2. Dedicated Technical Support Stations\nTo facilitate a seamless software migration and assist staff with encryption key generation, technical support specialists will be stationed in the main lobby and on Floor 4 from 8:00 AM to 6:00 PM daily through Friday.\n\n*International Travel with Corporate Laptops: In accordance with global export control and cyber defense laws, employees must obtain explicit clearance from IT Security before traveling internationally with company laptops. Unregistered corporate hardware detected crossing international borders will trigger immediate remote device erasure.", "questions": [{"question": "What urgent action must all personnel complete by Friday at 5:00 PM?", "options": {"A": "Submit their annual leave requests", "B": "Upgrade their workstation encryption", "C": "Return corporate mobile phones", "D": "Relocate to secondary office spaces"}, "answer": "B", "radar": "🔍 防漏看雷達：緊急指示 'it is imperative that all personnel upgrade their workstation encryption by Friday'！", "analysis": "文中明確規定週五下午 5:00 前必須升級工作站加密系統，故選 (B)。"}, {"question": "Where will technical support specialists be stationed?", "options": {"A": "In the executive conference room", "B": "In the main lobby", "C": "In the parking garage", "D": "At the airport terminal"}, "answer": "B", "radar": "🔍 防漏看雷達：支援地點 'stationed in the main lobby'！", "analysis": "內文指出技術專家將駐守在大廳提供協助，故選 (B)。"}, {"question": "What must employees do before traveling internationally with company laptops?", "options": {"A": "Obtain explicit clearance from IT Security", "B": "Purchase supplementary luggage insurance", "C": "Back up files to personal flash drives", "D": "Reinstall their operating system"}, "answer": "A", "radar": "🔍 防漏看雷達：星號出國筆電附註 '*Notice: ... must obtain explicit clearance from IT Security prior to departure'！", "analysis": "星號小字要求攜帶筆電出國前必須獲得 IT 安全部門的明確許可，故選 (A)。"}]}]}}}, "15": {"day": 15, "date": "11/18", "phase": 2, "phase_name": "860 突破與同義代換", "topic": "隱藏除外條款 ｜ 發起、親密與高利潤法規", "morning": {"chunks": [{"chunk": "initiate the investigation", "meaning": "發起調查/啟動審查", "scenario": "Internal auditors decided to initiate the investigation immediately.", "paraphrase": "initiate = commence = launch = trigger", "alert": "名詞形式為 initiation 或 initiative！"}, {"chunk": "lucrative contract", "meaning": "利潤豐厚的合約", "scenario": "The firm landed a lucrative contract with a multinational telecommunications provider.", "paraphrase": "lucrative = profitable = high-yield", "alert": "常修飾 contract, deal, market！"}, {"chunk": "regulatory compliance", "meaning": "法規遵從/符合監管", "scenario": "Companies must ensure regulatory compliance to avoid punitive fines.", "paraphrase": "regulatory compliance = statutory adherence", "alert": "動詞為 regulate，名詞為 regulation！"}, {"chunk": "rigorous testing", "meaning": "嚴密嚴格的測試", "scenario": "All medical software undergoes rigorous testing before hospital deployment.", "paraphrase": "rigorous = thorough = stringent = meticulous", "alert": "副詞為 rigorously！"}, {"chunk": "barring any delays", "meaning": "除非有任何延誤", "scenario": "Barring any delays, the new office wing will open in October.", "paraphrase": "barring = except for = unless there is", "alert": "barring 為介系詞，後接名詞！"}, {"chunk": "aside from the fee", "meaning": "除了該費用之外", "scenario": "Aside from the initial registration fee, participation is free.", "paraphrase": "aside from = apart from = in addition to = except for", "alert": "常考除外或包含語意！"}, {"chunk": "without prior notice", "meaning": "未經事先通知", "scenario": "Prices are subject to adjustment without prior notice.", "paraphrase": "without prior notice = without advance warning", "alert": "商業合約必備語塊！"}], "visual_anchor": {"title": "商務除外介系詞 (Exclusionary Prepositions) 視覺秒殺錨點", "rule_1": "👀 空格後為名詞片語 [________ any unexpected delays] ➔ 秒選介系詞「Barring」或「Without」！", "rule_2": "👀 看到 [________ for 名詞] ➔ 秒選「Except for」；看到 [________ from 名詞] ➔ 秒選「Aside from」！", "golden_rule": "⚡ 教練金句：看到 for 配 except，看到 from 配 aside，看到純名詞選 barring！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "The pharmaceutical firm plans to ________ a comprehensive clinical evaluation next month.", "options": {"A": "initiate", "B": "initiating", "C": "initiation", "D": "initiative"}, "answer": "A", "analysis": "不定詞後接原形動詞：to + [原形動詞] initiate（發起/啟動）。選 (A)。", "translation": "該製藥公司計畫下個月啟動一項全面的臨床評估。"}, {"id": 2, "target_seconds": 15, "question": "The consulting firm secured a highly ________ contract with the state transportation authority.", "options": {"A": "lucrative", "B": "lucratively", "C": "lucrativeness", "D": "lucre"}, "answer": "A", "analysis": "形容詞修飾名詞 contract。lucrative（利潤豐厚的/獲利甚多的）。選 (A)。", "translation": "這家諮詢公司獲得了與州交通局的一份利潤豐厚的合約。"}, {"id": 3, "target_seconds": 15, "question": "All medical devices must adhere to strict ________ compliance guidelines established by the FDA.", "options": {"A": "regulatory", "B": "regularly", "C": "regulate", "D": "regulation"}, "answer": "A", "analysis": "形容詞修飾名詞 compliance：regulatory compliance 表『法規遵循』。選 (A)。", "translation": "所有醫療器材必須遵守 FDA 制定的嚴格法規遵循準則。"}, {"id": 4, "target_seconds": 15, "question": "The engineering laboratory subjects all aviation components to ________ stress testing.", "options": {"A": "rigorous", "B": "rigorously", "C": "rigor", "D": "rigorousness"}, "answer": "A", "analysis": "形容詞修飾名詞 stress testing。rigorous 表『嚴格縝密的』。選 (A)。", "translation": "工程實驗室對所有航空零件進行嚴格縝密的應力測試。"}, {"id": 5, "target_seconds": 15, "question": "________ unforeseen inclement weather, the charity marathon will take place on Saturday morning as scheduled.", "options": {"A": "Barring", "B": "Unless", "C": "Although", "D": "Without"}, "answer": "A", "analysis": "介系詞表除外條件：Barring + 名詞（除非有/若非……）。Barring unforeseen inclement weather 表『除非有無法預見的惡劣天氣』。選 (A)。", "translation": "除非有無法預見的惡劣天氣，否則慈善馬拉松將按既定計畫於週六上午舉行。"}, {"id": 6, "target_seconds": 15, "question": "The factory passed the safety audit ________ any minor citations from federal inspectors.", "options": {"A": "without", "B": "except", "C": "unless", "D": "barring"}, "answer": "A", "analysis": "介系詞 without + 名詞片語：表『沒有……』。選 (A)。", "translation": "該工廠通過了安全審查，未受到聯邦檢查員的任何輕微處罰。"}, {"id": 7, "target_seconds": 15, "question": "The newly appointed CEO intends to ________ a series of cost-reduction initiatives.", "options": {"A": "initiate", "B": "initiation", "C": "initiated", "D": "initiating"}, "answer": "A", "analysis": "intends to + [原形動詞] initiate。選 (A)。", "translation": "新任命的執行長打算發起一系列成本削減計畫。"}, {"id": 8, "target_seconds": 15, "question": "Commercial real estate developers regard the waterfront district as a ________ investment zone.", "options": {"A": "lucrative", "B": "lucratively", "C": "lucrativeness", "D": "lucre"}, "answer": "A", "analysis": "形容詞修飾名詞 investment zone。選 (A) lucrative（高收益的）。", "translation": "商用不動產開發商將濱海區視為一個利潤豐厚的投資區。"}, {"id": 9, "target_seconds": 15, "question": "Corporate auditors verified that the accounting protocols conform to ________ standards.", "options": {"A": "regulatory", "B": "regularly", "C": "regulations", "D": "regulate"}, "answer": "A", "analysis": "regulatory standards（法規標準）。選 (A)。", "translation": "企業查核員核實會計規程符合法規標準。"}, {"id": 10, "target_seconds": 15, "question": "Aviation technicians conducted ________ inspections on the aircraft's hydraulic systems.", "options": {"A": "rigorous", "B": "rigorously", "C": "rigor", "D": "rigors"}, "answer": "A", "analysis": "形容詞修飾名詞 inspections。選 (A) rigorous（嚴密檢查）。", "translation": "航空技術人員對飛機的液壓系統進行了嚴密檢查。"}, {"id": 11, "target_seconds": 15, "question": "________ any last-minute amendments, the trade pact will be formally signed tomorrow.", "options": {"A": "Barring", "B": "Unless", "C": "Although", "D": "Even if"}, "answer": "A", "analysis": "介系詞 Barring + 名詞（若無/除非有）。選 (A)。", "translation": "除非最後一刻有修正案，否則該貿易條約將於明日正式簽署。"}, {"id": 12, "target_seconds": 15, "question": "________ for a brief delay in baggage handling, the inaugural international flight was flawless.", "options": {"A": "Except", "B": "Aside", "C": "Barring", "D": "Without"}, "answer": "A", "analysis": "固定除外介系詞片語：Except for + 名詞。選 (A)。", "translation": "除行李處理稍有延遲外，該首航國際航班完美無瑕。"}, {"id": 13, "target_seconds": 15, "question": "Senior partners voted to ________ a search committee for the new chief compliance officer.", "options": {"A": "initiate", "B": "initiates", "C": "initiated", "D": "initiating"}, "answer": "A", "analysis": "voted to + [原形動詞] initiate。選 (A)。", "translation": "資深合夥人投票決定為新任首席法遵官成立遴選委員會。"}, {"id": 14, "target_seconds": 15, "question": "The joint venture proved exceptionally ________ for both participating technology corporations.", "options": {"A": "lucrative", "B": "lucratively", "C": "lucrativeness", "D": "lucre"}, "answer": "A", "analysis": "連綴動詞 proved 後接形容詞主詞補語 (A) lucrative。", "translation": "這項合資企業對雙方參與的科技公司而言都被證實獲利豐厚。"}, {"id": 15, "target_seconds": 15, "question": "Banks must follow stringent ________ requirements regarding international fund transfers.", "options": {"A": "regulatory", "B": "regulate", "C": "regular", "D": "regularly"}, "answer": "A", "analysis": "形容詞修飾 requirements。regulatory requirements 表『法規監管要求』。選 (A)。", "translation": "銀行在國際資金轉帳方面必須遵守嚴格的法規監管要求。"}, {"id": 16, "target_seconds": 15, "question": "All candidate medicines undergo ________ preclinical trials prior to human administration.", "options": {"A": "rigorous", "B": "rigorously", "C": "rigor", "D": "rigors"}, "answer": "A", "analysis": "形容詞修飾 trials。rigorous preclinical trials。選 (A)。", "translation": "所有候選藥物在人體給藥前均須經歷嚴密的臨床前試驗。"}, {"id": 17, "target_seconds": 15, "question": "________ a written recommendation from a department director, transfer requests will not be processed.", "options": {"A": "Without", "B": "Unless", "C": "Except", "D": "Barring"}, "answer": "A", "analysis": "介系詞 Without + 名詞片語。選 (A)。", "translation": "若無部門處長的書面推薦，調職申請將不予受理。"}, {"id": 18, "target_seconds": 15, "question": "________ from the executive board members, all company employees received the annual survey.", "options": {"A": "Aside", "B": "Except", "C": "Barring", "D": "Without"}, "answer": "A", "analysis": "固定片語：Aside from（除了……之外）。選 (A)。", "translation": "除了執行董事會成員外，公司所有員工都收到了年度問卷。"}, {"id": 19, "target_seconds": 15, "question": "The software startup is seeking to ________ partnerships with major retail banks.", "options": {"A": "initiate", "B": "initiating", "C": "initiated", "D": "initiator"}, "answer": "A", "analysis": "seeking to + [原形動詞] initiate。選 (A)。", "translation": "該軟體新創公司正尋求與大型零售銀行建立合作夥伴關係。"}, {"id": 20, "target_seconds": 15, "question": "Securing distribution rights in East Asia generated a highly ________ income stream for the label.", "options": {"A": "lucrative", "B": "lucratively", "C": "lucrativeness", "D": "lucre"}, "answer": "A", "analysis": "形容詞修飾 income stream。選 (A) lucrative。", "translation": "獲得東亞經銷權為該品牌帶來了利潤豐厚的收入流。"}]}, "afternoon": {"quick_recall": [{"prompt": "to ________ [動詞，發起/啟動] a formal inquiry.", "clue": "發起啟動", "answer": "initiate"}, {"prompt": "The contract was extremely ________ [形容詞，利潤豐厚的].", "clue": "利潤豐厚賺錢的", "answer": "lucrative"}, {"prompt": "to satisfy all ________ [形容詞，法規監管的] standards.", "clue": "法規的", "answer": "regulatory"}, {"prompt": "The research underwent ________ [形容詞，嚴謹嚴密的] testing.", "clue": "嚴格嚴密的", "answer": "rigorous"}, {"prompt": "________ [介系詞，除非有/若非...] unexpected delays, we finish today.", "clue": "除非有... (Barring ...)", "answer": "Barring"}, {"prompt": "________ [介系詞，除了...之外] from the shipping fee, the item is free.", "clue": "除了...之外 (Aside ...)", "answer": "Aside from"}], "spaced_traps": [{"id": 1, "target_seconds": 20, "question": "The pharmaceutical conglomerate plans to ________ research collaboration with premier universities.", "options": {"A": "initiate", "B": "initiating", "C": "initiation", "D": "initiative"}, "answer": "A", "trap_point": "to + 原形動詞 initiate！", "analysis": "to 接原形動詞，選 (A) initiate。", "translation": "該製藥集團計畫啟動與頂尖大學的研究合作。"}, {"id": 2, "target_seconds": 20, "question": "Winning the municipal transit contract proved to be exceptionally ________ for the firm.", "options": {"A": "lucrative", "B": "lucratively", "C": "lucrativeness", "D": "lucre"}, "answer": "A", "trap_point": "proved to be + 形容詞 lucrative！", "analysis": "連綴動詞後接形容詞，選 (A) lucrative（利潤豐厚的）。", "translation": "贏得市政交通合約被證實對該公司而言獲利極為豐厚。"}, {"id": 3, "target_seconds": 20, "question": "The financial institution maintains strict compliance with all federal ________ guidelines.", "options": {"A": "regulatory", "B": "regularly", "C": "regulate", "D": "regulation"}, "answer": "A", "trap_point": "federal regulatory guidelines（聯邦法規準則）！", "analysis": "形容詞修飾名詞，選 (A) regulatory。", "translation": "該金融機構嚴格遵守所有聯邦法規監管準則。"}, {"id": 4, "target_seconds": 20, "question": "Before mass manufacturing, all prototypes must undergo ________ structural quality assessments.", "options": {"A": "rigorous", "B": "rigorously", "C": "rigor", "D": "rigorousness"}, "answer": "A", "trap_point": "rigorous quality assessments（嚴格的品質評估）！", "analysis": "形容詞修飾名詞 assessments，選 (A) rigorous。", "translation": "在大規模製造之前，所有原型機都必須接受嚴格的結構品質評估。"}, {"id": 5, "target_seconds": 20, "question": "________ unforeseen hardware failures, the database server migration will be finalized tonight.", "options": {"A": "Barring", "B": "Unless", "C": "Although", "D": "Without"}, "answer": "A", "trap_point": "介系詞 Barring 後接名詞片語！", "analysis": "表除外條件『除非有』，後接名詞，選 (A) Barring。", "translation": "除非發生未預見的硬體故障，否則資料庫伺服器遷移將於今晚完成。"}, {"id": 6, "target_seconds": 20, "question": "The audit concluded ________ any findings of non-compliance with international labor laws.", "options": {"A": "without", "B": "except", "C": "unless", "D": "barring"}, "answer": "A", "trap_point": "concluded without any findings 表沒有任何缺失！", "analysis": "介系詞 without + 名詞，選 (A) without。", "translation": "稽核結束，未發現任何違反國際勞工法的缺失。"}, {"id": 7, "target_seconds": 20, "question": "The newly appointed division head will ________ an internal review of client billing procedures.", "options": {"A": "initiate", "B": "initiation", "C": "initiating", "D": "initiated"}, "answer": "A", "trap_point": "will + 原形動詞 initiate！", "analysis": "助動詞 will 接原形動詞，選 (A) initiate。", "translation": "新任部門主管將啟動對客戶帳單程序的內部審查。"}, {"id": 8, "target_seconds": 20, "question": "Real estate investors targeted the tech district due to its ________ rental yields.", "options": {"A": "lucrative", "B": "lucratively", "C": "lucrativeness", "D": "lucre"}, "answer": "A", "trap_point": "its lucrative rental yields（其利潤豐厚的租金收益）！", "analysis": "形容詞修飾名詞 yields，選 (A) lucrative。", "translation": "房地產投資人看中該科技區利潤豐厚的租金收益。"}, {"id": 9, "target_seconds": 20, "question": "The legal team reviewed the contract to ensure full alignment with current ________ frameworks.", "options": {"A": "regulatory", "B": "regularly", "C": "regulate", "D": "regulation"}, "answer": "A", "trap_point": "regulatory frameworks（法規架構）！", "analysis": "形容詞修飾名詞 frameworks，選 (A) regulatory。", "translation": "法律團隊審查了合約，以確保完全符合現行法規架構。"}, {"id": 10, "target_seconds": 20, "question": "Automotive safety components are subjected to ________ impact crash tests.", "options": {"A": "rigorous", "B": "rigorously", "C": "rigor", "D": "rigors"}, "answer": "A", "trap_point": "subjected to + 形容詞 + 名詞！", "analysis": "形容詞修飾 impact crash tests，選 (A) rigorous。", "translation": "汽車安全零件受到嚴格的衝撞碰撞測試。"}, {"id": 11, "target_seconds": 20, "question": "________ adverse sea conditions, the container vessel will berth at the terminal by dawn.", "options": {"A": "Barring", "B": "Unless", "C": "Although", "D": "Even if"}, "answer": "A", "trap_point": "Barring + 名詞（除非有…惡劣海況）！", "analysis": "介系詞表除外條件，選 (A) Barring。", "translation": "除非海況惡劣，集裝箱船將於黎明前停泊在碼頭。"}, {"id": 12, "target_seconds": 20, "question": "________ for a few minor formatting errors, the technical manual was completely approved.", "options": {"A": "Except", "B": "Aside", "C": "Barring", "D": "Without"}, "answer": "A", "trap_point": "Except for + 名詞！", "analysis": "固定片語 Except for 表除了……之外，選 (A)。", "translation": "除幾處微小的格式錯誤外，該技術手冊已獲完全批准。"}, {"id": 13, "target_seconds": 20, "question": "Senior management resolved to ________ an extensive corporate restructuring program.", "options": {"A": "initiate", "B": "initiates", "C": "initiated", "D": "initiating"}, "answer": "A", "trap_point": "resolved to + 原形動詞 initiate！", "analysis": "不定詞後接原形動詞，選 (A) initiate。", "translation": "資深管理層決議啟動大規模的企業重組計畫。"}, {"id": 14, "target_seconds": 20, "question": "Overseas patent licensing represents the company's single most ________ business division.", "options": {"A": "lucrative", "B": "lucratively", "C": "lucrativeness", "D": "lucre"}, "answer": "A", "trap_point": "the most lucrative business division！", "analysis": "最高級修飾形容詞，選 (A) lucrative。", "translation": "海外專利授權代表著該公司利潤最豐厚的單一業務部門。"}], "part7": {"passages": [{"text_type": "Biotech Regulatory Press Release (生技新藥監管核准新聞稿)", "title": "BioVance Therapeutics — Phase III Clinical Authorization & Market Projection", "content": "PRESS RELEASE: BV-REG-2026-15\nFOR IMMEDIATE RELEASE: November 18, 2026\nISSUING ENTITY: BioVance Therapeutics Investor Relations & Corporate Communications\nSTOCK TICKER: NASDAQ: BVTC | Global Headquarters: Cambridge, MA\n\n1. Regulatory Milestone Achievement\nBioVance Therapeutics, a clinical-stage biotechnology pioneer in targeted oncology treatments, is delighted to announce that it has received formal regulatory authorization to initiate Phase III evaluations for its proprietary immunotherapy compound, BV-709. This landmark regulatory milestone follows comprehensive Phase II clinical trials demonstrating a 78% overall response rate with zero adverse cardiac events across all evaluated patient cohorts and multi-center testing facilities.\n\n2. Commercial Market Projections\nIndustry financial analysts and healthcare economists forecast substantial global adoption for BV-709 upon final licensing. The drug is projected to generate $1.4 billion in annual revenue within its first three years on the market, addressing critical unmet needs in global oncology treatment regimens.\n\n*Commercial Distribution Timeline: Under the terms approved by the regulatory commission, commercial distribution will begin within 90 days of final regulatory clearance, barring supply disruptions in raw active pharmaceutical ingredient sourcing. BioVance will host an investor briefing this Thursday at 2:00 PM EST.", "questions": [{"question": "What official milestone did BioVance Therapeutics achieve?", "options": {"A": "Merger with a retail drugstore chain", "B": "Regulatory authorization to initiate Phase III evaluations", "C": "Approval to construct a new European factory", "D": "Settlement of an intellectual property lawsuit"}, "answer": "B", "radar": "🔍 防漏看雷達：首段成就 'granted regulatory authorization to initiate global Phase III clinical evaluations'！", "analysis": "文中明確指出獲得啟動三期臨床評估的監管授權，故選 (B)。"}, {"question": "What is the projected annual revenue for the breakthrough medication?", "options": {"A": "$140 million", "B": "$500 million", "C": "$1.2 billion", "D": "$1.4 billion"}, "answer": "D", "radar": "🔍 防漏看雷達：營收數字定位 'annual revenues estimated at $1.4 billion'！", "analysis": "內文明確預估年營收為 14 億美元，故選 (D)。"}, {"question": "When will commercial distribution begin according to the clause?", "options": {"A": "Within 30 days of filing", "B": "Within 90 days of final regulatory clearance, barring supply disruptions", "C": "Six months after clinical trial completion", "D": "Immediately following packaging redesign"}, "answer": "B", "radar": "🔍 防漏看雷達：星號除外條款 '*Exclusionary Clause 4.2: Barring unforeseen supply disruptions ... within ninety days'！", "analysis": "星號條款說明在沒有原料供應中斷的前提下，於最終核准後 90 天內上市，故選 (B)。"}]}, {"text_type": "Quality Assurance Standard Operating Procedure (航太零件超音波檢驗程序手冊)", "title": "Aerospace Component Manufacturing — Rigorous Ultrasonic Testing Mandates", "content": "MANUFACTURING QUALITY DIRECTIVE: ACM-QA-2026-92\nISSUED BY: Aerospace Component Manufacturing Quality Assurance Directorate\nDATE: November 18, 2026\nMANDATORY FOR: All Fastener Fabrication Units, NDT Technicians, and Plant Inspectors\n\n1. Ultrasonic Inspection Protocol\nTo guarantee structural integrity at supersonic flight velocities and withstand extreme thermal variations, all commercial airframe fasteners fabricated in Facilities A and B must undergo rigorous ultrasonic scanning prior to packaging. High-frequency acoustic sensors evaluate internal titanium density, microscopic grain boundaries, and detect sub-surface stress fractures before delivery to commercial aircraft assemblers and international defense contractors across the aviation industry.\n\n2. Precision Tolerance Thresholds\nFabrication tolerances are calibrated to micrometer precision. Any structural deviation or surface irregularity exceeding 0.02 millimeters will trigger immediate product quarantine and initiate automated batch containment investigations. Quarantined batches must undergo destructive metallurgical testing before final disposition.\n\n*Defense Priority Contract Exceptions: In accordance with National Aerospace Standards, emergency defense contracts holding Priority One clearance are exempted from secondary acoustic validation, provided that primary laser measurement scans pass full calibration checks. All validation documentation must be retained for thirty years in electronic compliance vaults.", "questions": [{"question": "What mandatory scanning procedure must all airframe fasteners undergo?", "options": {"A": "Magnetic resonance imaging", "B": "Rigorous ultrasonic scanning", "C": "Manual visual calipers inspection", "D": "X-ray spectral diffraction"}, "answer": "B", "radar": "🔍 防漏看雷達：檢測方式 'undergo rigorous ultrasonic scanning prior to inventory dispatch'！", "analysis": "文中明確指示緊固件必須進行超音波掃描，故選 (B)。"}, {"question": "What deviation threshold triggers immediate product quarantine?", "options": {"A": "0.01 millimeters", "B": "0.02 millimeters", "C": "0.05 millimeters", "D": "0.10 millimeters"}, "answer": "B", "radar": "🔍 防漏看雷達：數字門檻 'surface deviations exceeding 0.02 millimeters'！", "analysis": "超過 0.02 毫米的表面偏差必須立即隔離，故選 (B)。"}, {"question": "Which orders are exempted from secondary acoustic validation according to the note?", "options": {"A": "Standard commercial regional orders", "B": "Emergency defense contracts holding Priority One clearance", "C": "Prototypes intended for museum display", "D": "Orders placed during holiday shutdowns"}, "answer": "B", "radar": "🔍 防漏看雷達：星號除外條件 '*Important Protocol Note: Aside from emergency defense contracts holding Priority One clearance'！", "analysis": "星號小字標明僅有一級國防緊急合約可免除此程序，故選 (B)。"}]}]}}}, "16": {"day": 16, "date": "11/19", "phase": 2, "phase_name": "860 突破與同義代換", "topic": "時間軸與變更陷阱 ｜ 取得、佔用與新生訓練", "morning": {"chunks": [{"chunk": "prior to the conference", "meaning": "在會議之前", "scenario": "Please review the agenda prior to the conference.", "paraphrase": "prior to = before = in advance of", "alert": "prior 後固定接 to + 名詞或 V-ing！"}, {"chunk": "subsequent to the merger", "meaning": "在合併之後", "scenario": "Subsequent to the merger, departmental operations were reorganized.", "paraphrase": "subsequent to = following = after", "alert": "subsequent 後接 to！"}, {"chunk": "following the speech", "meaning": "在演講之後", "scenario": "Following the speech, a question-and-answer session took place.", "paraphrase": "following = after = subsequent to", "alert": "following 作介系詞等同 after！"}, {"chunk": "pending board approval", "meaning": "有待董事會批准（在等待批准期間）", "scenario": "The new product launch is pending board approval.", "paraphrase": "pending = awaiting = subject to", "alert": "pending 可作介系詞表『有待/在等待……期間』！"}, {"chunk": "acquire the property", "meaning": "收購該不動產", "scenario": "The developer secured financing to acquire the property.", "paraphrase": "acquire = purchase = take over = buy", "alert": "名詞形式為 acquisition！"}, {"chunk": "occupy the premises", "meaning": "進駐該處所/佔用物業", "scenario": "The tenants will occupy the premises starting January 1.", "paraphrase": "occupy = inhabit = move into = take up", "alert": "名詞形式為 occupancy（進駐率）或 occupant（住戶）！"}, {"chunk": "employee orientation", "meaning": "員工職前培訓/新生訓練", "scenario": "All new hires must attend employee orientation on their first day.", "paraphrase": "orientation = induction = onboarding", "alert": "動詞為 orient！"}], "visual_anchor": {"title": "時間介系詞 (Time Sequencers) 視覺秒殺錨點", "rule_1": "👀 看到 [________ to 名詞] 表『在……之前』➔ 秒選「Prior to」！", "rule_2": "👀 看到 [________ to 名詞] 表『在……之後』➔ 秒選「Subsequent to」！", "golden_rule": "⚡ 教練金句：前選 prior to，後選 subsequent to，等待期間選 pending！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "The pharmaceutical multinational plans to ________ a regional biotech firm next month.", "options": {"A": "acquire", "B": "acquisition", "C": "acquired", "D": "acquiring"}, "answer": "A", "analysis": "plans to + 原形動詞 acquire（收購/取得）。選 (A)。", "translation": "該跨國製藥集團計畫下個月收購一家區域生物技術公司。"}, {"id": 2, "target_seconds": 15, "question": "Tenants are scheduled to ________ the top four floors of the newly constructed commercial tower.", "options": {"A": "occupy", "B": "occupancy", "C": "occupant", "D": "occupied"}, "answer": "A", "analysis": "scheduled to + 原形動詞 occupy（佔用/進駐使用）。選 (A)。", "translation": "租戶預計進駐新建商業大樓的頂部四層。"}, {"id": 3, "target_seconds": 15, "question": "All newly hired software developers must attend the mandatory workplace ________ on Monday.", "options": {"A": "orientation", "B": "orient", "C": "orienting", "D": "oriented"}, "answer": "A", "analysis": "形容詞 workplace 後接名詞 orientation（新生訓練/職前培訓）。選 (A)。", "translation": "所有新進軟體開發人員均須參加週一舉行的強制性職場培訓。"}, {"id": 4, "target_seconds": 15, "question": "During her ten-year ________ as chief financial officer, corporate revenues doubled.", "options": {"A": "tenure", "B": "tenant", "C": "tenuous", "D": "tenets"}, "answer": "A", "analysis": "所有格 her ten-year 後接名詞 tenure（任期/任職期間）。選 (A)。", "translation": "在她擔任財務長的十年任期內，公司營收翻了一倍。"}, {"id": 5, "target_seconds": 15, "question": "________ to the public announcement of the quarterly earnings, stock values rallied.", "options": {"A": "Prior", "B": "Subsequent", "C": "Following", "D": "Pending"}, "answer": "B", "analysis": "Subsequent to = After（在……之後）。選 (B)。", "translation": "在季報公開公布之後，股票價值出現了反彈。"}, {"id": 6, "target_seconds": 15, "question": "________ to the installation of new manufacturing equipment, floor technicians attended training.", "options": {"A": "Prior", "B": "Subsequent", "C": "Following", "D": "Pending"}, "answer": "A", "analysis": "Prior to = Before（在……之前）。選 (A)。", "translation": "在安裝新生產設備之前，現場技術人員參加了培訓。"}, {"id": 7, "target_seconds": 15, "question": "________ the keynote address, participants were invited to network in the main ballroom.", "options": {"A": "Following", "B": "Prior", "C": "Subsequent", "D": "Pending"}, "answer": "A", "analysis": "Following + 名詞 = After（在……之後）。選 (A)。", "translation": "在主題演講之後，與會者受邀在主宴會廳進行交流。"}, {"id": 8, "target_seconds": 15, "question": "The merger approval remains ________ review by the Federal Trade Commission.", "options": {"A": "pending", "B": "prior", "C": "subsequent", "D": "following"}, "answer": "A", "analysis": "remains pending + 名詞（有待審查/在等待審查期間）。選 (A)。", "translation": "該合併案的核准仍有待聯邦貿易委員會的審查。"}, {"id": 9, "target_seconds": 15, "question": "The retail chain successfully ________ three competitor store locations in the metropolitan area.", "options": {"A": "acquired", "B": "acquire", "C": "acquisition", "D": "acquiring"}, "answer": "A", "analysis": "過去式動詞 acquired。選 (A)。", "translation": "這家零售連鎖店在都會區成功收購了三處競爭對手的門市。"}, {"id": 10, "target_seconds": 15, "question": "Office ________ in the suburban business park reached an all-time peak this quarter.", "options": {"A": "occupancy", "B": "occupy", "C": "occupant", "D": "occupied"}, "answer": "A", "analysis": "名詞位置：Office occupancy（辦公室進駐率/住房率）。選 (A)。", "translation": "郊區商業園區的辦公室進駐率在本季度達到了歷史最高峰。"}, {"id": 11, "target_seconds": 15, "question": "The human resources department scheduled an interactive ________ for summer interns.", "options": {"A": "orientation", "B": "orient", "C": "oriented", "D": "orienting"}, "answer": "A", "analysis": "冠詞 an 後接名詞 orientation。選 (A)。", "translation": "人力資源部門為暑期實習生安排了一場互動式職前培訓。"}, {"id": 12, "target_seconds": 15, "question": "The CEO praised Dr. Vance for his exceptional ________ as head of global research.", "options": {"A": "tenure", "B": "tenant", "C": "tenuous", "D": "tenor"}, "answer": "A", "analysis": "所有格 his exceptional 後接名詞 tenure。選 (A)。", "translation": "執行長讚揚 Vance 博士在擔任全球研究主管期間的卓越任期表現。"}, {"id": 13, "target_seconds": 15, "question": "________ to joining the executive board, Mr. Sato directed the Tokyo logistics terminal.", "options": {"A": "Prior", "B": "Subsequent", "C": "Following", "D": "Pending"}, "answer": "A", "analysis": "Prior to + V-ing（在……之前）。選 (A)。", "translation": "在加入執行董事會之前，Sato 先生負責管理東京物流轉運中心。"}, {"id": 14, "target_seconds": 15, "question": "________ to the signing ceremony, the foreign dignitaries visited the automated manufacturing plant.", "options": {"A": "Subsequent", "B": "Prior", "C": "Pending", "D": "During"}, "answer": "A", "analysis": "Subsequent to = After。選 (A)。", "translation": "簽約儀式結束之後，外國貴賓參觀了自動化製造工廠。"}, {"id": 15, "target_seconds": 15, "question": "________ the successful launch of the mobile application, user registrations surged.", "options": {"A": "Following", "B": "Prior", "C": "Pending", "D": "Subsequent"}, "answer": "A", "analysis": "Following + 名詞（在……之後）。選 (A)。", "translation": "在行動應用程式成功上線之後，用戶註冊量激增。"}, {"id": 16, "target_seconds": 15, "question": "Building construction has been temporarily halted ________ zoning board approval.", "options": {"A": "pending", "B": "prior", "C": "subsequent", "D": "following"}, "answer": "A", "analysis": "pending + 名詞（在等待……期間）。選 (A)。", "translation": "大樓建設工程在等待分區委員會批准期間已暫時停工。"}, {"id": 17, "target_seconds": 15, "question": "The media corporation hopes to ________ exclusive streaming rights for the film festival.", "options": {"A": "acquire", "B": "acquisition", "C": "acquired", "D": "acquires"}, "answer": "A", "analysis": "hopes to + 原形動詞 acquire。選 (A)。", "translation": "這家媒體公司希望能取得該電影節的獨家串流播放權。"}, {"id": 18, "target_seconds": 15, "question": "Only authorized engineering personnel may ________ the cleanroom laboratory.", "options": {"A": "occupy", "B": "occupancy", "C": "occupant", "D": "occupied"}, "answer": "A", "analysis": "助動詞 may + 原形動詞 occupy。選 (A)。", "translation": "只有獲得授權的工程人員才可進駐無塵實驗室。"}, {"id": 19, "target_seconds": 15, "question": "New staff members will receive health insurance enrollment forms during employee ________.", "options": {"A": "orientation", "B": "orient", "C": "orienting", "D": "oriented"}, "answer": "A", "analysis": "名詞片語：employee orientation（員工新生訓練）。選 (A)。", "translation": "新進員工將在員工職前訓練期間領取健保投保表單。"}, {"id": 20, "target_seconds": 15, "question": "Under the ________ of the outgoing director, company share value rose by forty percent.", "options": {"A": "tenure", "B": "tenant", "C": "tenuous", "D": "tenor"}, "answer": "A", "analysis": "the tenure of...（……的任期）。選 (A)。", "translation": "在即將離任處長的任期內，公司股票價值上漲了 40%。"}]}, "afternoon": {"quick_recall": [{"prompt": "to ________ [動詞，收購/取得] another business.", "clue": "收購併購", "answer": "acquire"}, {"prompt": "to ________ [動詞，進駐佔用] the top floor of the tower.", "clue": "進駐佔用", "answer": "occupy"}, {"prompt": "All new hires must attend workplace ________ [名詞，職前培訓/新生訓練].", "clue": "職前培訓", "answer": "orientation"}, {"prompt": "During his ten-year ________ [名詞，任期] as CEO.", "clue": "任期", "answer": "tenure"}, {"prompt": "________ [介系詞，在...之前 (Prior...)] to the meeting, read the brief.", "clue": "在...之前", "answer": "Prior to"}, {"prompt": "Final permits are ________ [介系詞，有待/等待審批期間] regulatory clearance.", "clue": "有待審核 (pending ...)", "answer": "pending"}], "spaced_traps": [{"id": 1, "target_seconds": 20, "question": "The investment syndicate plans to ________ three major commercial real estate assets.", "options": {"A": "acquire", "B": "acquisition", "C": "acquired", "D": "acquiring"}, "answer": "A", "trap_point": "plans to + 原形動詞 acquire！", "analysis": "to 後接原形動詞，選 (A) acquire。", "translation": "投資團體計畫收購三處主要商業房地產資產。"}, {"id": 2, "target_seconds": 20, "question": "The municipal agency will ________ the fifth and sixth floors of the civic tower.", "options": {"A": "occupy", "B": "occupancy", "C": "occupant", "D": "occupied"}, "answer": "A", "trap_point": "will + 原形動詞 occupy！", "analysis": "助動詞 will 接原形動詞，選 (A) occupy。", "translation": "市政機構將進駐市民大廈的五樓和六樓。"}, {"id": 3, "target_seconds": 20, "question": "All prospective lab assistants must register for laboratory safety ________.", "options": {"A": "orientation", "B": "orient", "C": "orienting", "D": "oriented"}, "answer": "A", "trap_point": "safety orientation（安全培訓）名詞！", "analysis": "複合名詞結構，選 (A) orientation。", "translation": "所有準實驗室助理都必須註冊參加實驗室安全培訓。"}, {"id": 4, "target_seconds": 20, "question": "Throughout her distinguished ________ as managing director, operational errors fell sharply.", "options": {"A": "tenure", "B": "tenant", "C": "tenuous", "D": "tenor"}, "answer": "A", "trap_point": "distinguished tenure（傑出任期）名詞！", "analysis": "形容詞修飾名詞，選 (A) tenure（任期）。", "translation": "在她擔任常務董事的傑出任期內，營運錯誤大幅下降。"}, {"id": 5, "target_seconds": 20, "question": "________ to finalizing the merger agreement, attorneys reviewed all tax liabilities.", "options": {"A": "Prior", "B": "Subsequent", "C": "Following", "D": "Pending"}, "answer": "A", "trap_point": "Prior to + V-ing（在…之前）！", "analysis": "表時間在……之前，選 (A) Prior to。", "translation": "在最終敲定合併協議之前，律師審查了所有稅務負債。"}, {"id": 6, "target_seconds": 20, "question": "________ to the shareholder briefing, the board released an official statement.", "options": {"A": "Subsequent", "B": "Prior", "C": "Pending", "D": "During"}, "answer": "A", "trap_point": "Subsequent to = After（在…之後）！", "analysis": "Subsequent to 後接名詞，選 (A) Subsequent。", "translation": "在股東簡報會之後，董事會發布了官方聲明。"}, {"id": 7, "target_seconds": 20, "question": "________ the conclusion of the product showcase, refreshments will be served in the atrium.", "options": {"A": "Following", "B": "Prior", "C": "Pending", "D": "Subsequent"}, "answer": "A", "trap_point": "Following + 名詞（在…之後）！", "analysis": "Following 後接名詞，選 (A) Following。", "translation": "在產品展示會結束之後，中庭將提供茶點。"}, {"id": 8, "target_seconds": 20, "question": "Construction on the wind farm remains ________ environmental review by the state.", "options": {"A": "pending", "B": "prior", "C": "subsequent", "D": "following"}, "answer": "A", "trap_point": "remains pending + 名詞（有待審查）！", "analysis": "選介系詞 (A) pending 表有待審查中。", "translation": "風力發電廠的建設工程仍有待州政府的環境審查。"}, {"id": 9, "target_seconds": 20, "question": "The technology giant announced the official ________ of an automated drone startup.", "options": {"A": "acquisition", "B": "acquire", "C": "acquired", "D": "acquiring"}, "answer": "A", "trap_point": "the official + 名詞 acquisition！", "analysis": "冠詞與形容詞後接名詞，選 (A) acquisition（收購案）。", "translation": "科技巨頭宣布正式收購一家自動化無人機新創公司。"}, {"id": 10, "target_seconds": 20, "question": "Building ________ permits are issued only after fire safety sprinkler validation.", "options": {"A": "occupancy", "B": "occupy", "C": "occupant", "D": "occupied"}, "answer": "A", "trap_point": "Building occupancy permits（建築使用許可證）！", "analysis": "複合名詞結構，選 (A) occupancy。", "translation": "建築使用許可證只有在消防灑水系統驗證後方能核發。"}, {"id": 11, "target_seconds": 20, "question": "The clinic organized a comprehensive staff ________ regarding new privacy rules.", "options": {"A": "orientation", "B": "orient", "C": "oriented", "D": "orienting"}, "answer": "A", "trap_point": "staff orientation（員工培訓）名詞！", "analysis": "名詞修飾名詞，選 (A) orientation。", "translation": "診所組織了針對新隱私規則的全面員工培訓。"}, {"id": 12, "target_seconds": 20, "question": "The president acknowledged the vice president's long and productive ________.", "options": {"A": "tenure", "B": "tenant", "C": "tenuous", "D": "tenor"}, "answer": "A", "trap_point": "long and productive + 名詞 tenure！", "analysis": "形容詞修飾名詞，選 (A) tenure（任期）。", "translation": "總裁對副總裁漫長而富有成效的任期表示感謝。"}, {"id": 13, "target_seconds": 20, "question": "________ to submitting invoices, vendors must verify that purchase order numbers match.", "options": {"A": "Prior", "B": "Subsequent", "C": "Pending", "D": "Following"}, "answer": "A", "trap_point": "Prior to submitting（在提交之前）！", "analysis": "固定片語 Prior to，選 (A)。", "translation": "在提交發票之前，供應商必須核實採購訂單編號相符。"}, {"id": 14, "target_seconds": 20, "question": "The revised budget is ________ approval by the municipal finance committee.", "options": {"A": "pending", "B": "prior", "C": "subsequent", "D": "following"}, "answer": "A", "trap_point": "is pending approval（有待批准）！", "analysis": "pending 後接名詞 approval，選 (A)。", "translation": "修改後的預算案有待市政財政委員會的批准。"}], "part7": {"passages": [{"text_type": "Commercial Property Move-In Guide (商業金融大樓租戶遷入手冊)", "title": "Lexington Financial Center — Tenant Move-In & Orientation Schedule", "content": "TENANT ONBOARDING CIRCULAR: LFC-OPS-2026-16\nBUILDING LOCATION: Lexington Financial Center, 500 Park Avenue\nISSUING ENTITY: Commercial Leasing Directorate & Building Management\nDATE: November 19, 2026\nAUDIENCE: Incoming Corporate Lessees and Moving Contractors\n\n1. Staged Move-In Schedule & Floor Allocations\nLexington Financial Center warmly welcomes our newest corporate tenants. Move-in operations scheduled for the first week of December will specifically cover Floors 12 through 16. To prevent loading dock bottlenecks and ensure seamless elevator dispatching, each tenant has been allocated a dedicated three-hour freight elevator window accessible between 7:00 PM and 6:00 AM.\n\n2. Mandatory Security Orientation Briefing\nTo ensure tenant familiarity with high-rise life safety systems, emergency stairwell pressurization, and biometric door access, incoming executives and facility managers must attend a mandatory security orientation on Monday, December 2, at 9:00 AM in Conference Auditorium 1A.\n\n*Hallway Clearance & Debris Removal: Fire safety regulations are strictly enforced across all commercial corridors. Tenants must clear commercial crates and cartons from public hallways within four hours subsequent to freight delivery. Items remaining after four hours will be removed by building custodial staff at the tenant's expense.", "questions": [{"question": "Which floors are covered by this move-in schedule?", "options": {"A": "Floors 1 through 5", "B": "Floors 6 through 10", "C": "Floors 12 through 16", "D": "Floors 20 through 25"}, "answer": "C", "radar": "🔍 防漏看雷達：樓層定位 'Floors 12 through 16'！", "analysis": "主旨與首句指明適用於 12 至 16 樓的租戶，故選 (C)。"}, {"question": "When will the mandatory security orientation take place?", "options": {"A": "Friday, November 29", "B": "Monday, December 2, at 9:00 AM", "C": "Wednesday, December 4", "D": "Friday, December 6"}, "answer": "B", "radar": "🔍 防漏看雷達：培訓時間 'held on Monday, December 2, at 9:00 AM'！", "analysis": "內文明確載明於 12 月 2 日週一上午 9:00 舉行，故選 (B)。"}, {"question": "What must tenants do within four hours subsequent to freight delivery?", "options": {"A": "Pay their monthly lease fee", "B": "Clear commercial crates and cartons from public hallways", "C": "Inspect all building elevators", "D": "Submit proof of liability insurance"}, "answer": "B", "radar": "🔍 防漏看雷達：星號附註條款 '*Important Moving Provision: Subsequent to freight delivery, all commercial crates ... must be cleared within four hours'！", "analysis": "星號條款要求在卸貨後 4 小時內清理公共走廊的箱子，故選 (B)。"}]}, {"text_type": "Corporate Media Succession Announcement (企業高層交接與併購公告)", "title": "OmniMedia Holdings — Chief Executive Succession & Pending Acquisition Update", "content": "EXECUTIVE PRESS RELEASE: OMNI-CORP-2026-16\nFOR IMMEDIATE RELEASE: November 19, 2026\nISSUING BODY: Board of Directors, OmniMedia Holdings Global\nCONTACT: investor-relations@omnimediagroup.com | Media Hotline: +1-800-555-0199\n\n1. Chief Executive Officer Transition\nThe Board of Directors of OmniMedia Holdings announces that Margaret Sterling has resolved to retire from her role as Chief Executive Officer after 12 years of transformative leadership. Under her stewardship, OmniMedia expanded from a regional print publication into an international streaming, broadcasting, and digital news conglomerate. Following an extensive international executive search, David Cho has been designated as the incoming Chief Executive Officer, assuming full operational leadership on January 15.\n\n2. Broadcast Media Acquisition Update\nConcurrently, OmniMedia Holdings provides an update regarding its proposed $450 million acquisition of Atlas Broadcast Media. The merger agreement has received unanimous approval from both corporate boards of directors and key institutional stakeholders.\n\n*Regulatory Review Condition: Finalization of the transaction remains pending approval from the Federal Communications Commission and standard anti-trust clearance. A public shareholder town hall with David Cho and Margaret Sterling will be broadcast live on December 12 via the investor relations web portal.", "questions": [{"question": "How long did Margaret Sterling serve as CEO of OmniMedia Holdings?", "options": {"A": "5 years", "B": "8 years", "C": "10 years", "D": "12 years"}, "answer": "D", "radar": "🔍 防漏看雷達：任期年數 'conclude her distinguished twelve-year tenure'！", "analysis": "文中指明其長達 12 年的傑出任期，故選 (D)。"}, {"question": "Who has been designated as the incoming Chief Executive Officer?", "options": {"A": "David Cho", "B": "Margaret Sterling", "C": "Dr. Vance", "D": "Sarah Lin"}, "answer": "A", "radar": "🔍 防漏看雷達：繼任者 'Executive Vice President David Cho has been appointed as her successor'！", "analysis": "執行副總裁 David Cho 被任命為繼任者，故選 (A)。"}, {"question": "What condition affects the proposed acquisition of Atlas Broadcast Media?", "options": {"A": "Pending approval from the Federal Communications Commission", "B": "Securing lower interest bank financing", "C": "Finalizing employee union negotiations", "D": "Relocating broadcast towers overseas"}, "answer": "A", "radar": "🔍 防漏看雷達：星號條款 '*Pending Clause: ... remains pending approval from the Federal Communications Commission'！", "analysis": "星號條款說明收購案仍有待聯邦通信委員會（FCC）核准，故選 (A)。"}]}]}}}, "17": {"day": 17, "date": "11/20", "phase": 2, "phase_name": "860 突破與同義代換", "topic": "星號小字與折扣資格 ｜ 聲望、地緣親近與精確", "morning": {"chunks": [{"chunk": "prestigious award", "meaning": "享譽盛名的獎項", "scenario": "The architect accepted a prestigious award for design excellence.", "paraphrase": "prestigious = distinguished = renowned = acclaimed", "alert": "名詞形式為 prestige！"}, {"chunk": "in close proximity to", "meaning": "緊鄰/與……地緣親近", "scenario": "The logistics center is located in close proximity to the seaport.", "paraphrase": "in close proximity to = near = adjacent to = adjacent to", "alert": "固定搭配 in close proximity to！"}, {"chunk": "precise measurements", "meaning": "精確的測量數據", "scenario": "Engineers took precise measurements before cutting the steel beams.", "paraphrase": "precise = exact = accurate = meticulous", "alert": "名詞為 precision，副詞為 precisely！"}, {"chunk": "eligibility criteria", "meaning": "資格審查條件", "scenario": "Applicants must satisfy all stated eligibility criteria.", "paraphrase": "criteria = standards = requirements = specifications", "alert": "criteria 為複數，單數形為 criterion！"}, {"chunk": "with surgical precision", "meaning": "以極高精密度", "scenario": "The automated arm placed the microchip with surgical precision.", "paraphrase": "precision = exactness = accuracy", "alert": "常修飾工藝或高科技製造！"}, {"chunk": "geographic proximity", "meaning": "地理上的鄰近性", "scenario": "Geographic proximity between suppliers speeds up assembly.", "paraphrase": "proximity = nearness = vicinity", "alert": "名詞作主詞！"}, {"chunk": "satisfy the criterion", "meaning": "符合該項標準", "scenario": "The product failed to satisfy the crucial safety criterion.", "paraphrase": "satisfy the criterion = meet the standard", "alert": "criterion 為單數！"}], "visual_anchor": {"title": "Part 7 星號小字與但書條件 (*Footnotes) 獵殺雷達", "rule_1": "👀 看到文本底部附帶「*Notice / *Note / *Terms」➔ 題目必定至少考一題細節陷阱！", "rule_2": "👀 注意單複數名詞變化：criterion (單數) vs. criteria (複數) ➔ 動詞一致性秒殺！", "golden_rule": "⚡ 教練金句：正文快速瀏覽抓架構，星號但書慢讀抓正解！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "The architect received a ________ international award for sustainable building design.", "options": {"A": "prestigious", "B": "prestige", "C": "prestigiously", "D": "prestigiousness"}, "answer": "A", "analysis": "形容詞修飾名詞 award。prestigious award 表『聲望崇高的獎項』。選 (A)。", "translation": "該建築師因永續建築設計獲得了一項聲譽崇高的國際獎項。"}, {"id": 2, "target_seconds": 15, "question": "The tech incubator was chosen for its close ________ to premier engineering universities.", "options": {"A": "proximity", "B": "proximate", "C": "proximately", "D": "proximities"}, "answer": "A", "analysis": "形容詞 close 後接名詞 proximity。close proximity to... 表『與……極為鄰近』。選 (A)。", "translation": "該科技孵化器之所以入選，是因為它極為鄰近頂尖工程大學。"}, {"id": 3, "target_seconds": 15, "question": "Surveyors must take ________ measurements before concrete foundations can be poured.", "options": {"A": "precise", "B": "precision", "C": "precisely", "D": "preciseness"}, "answer": "A", "analysis": "形容詞修飾名詞 measurements。precise measurements（精確測量）。選 (A)。", "translation": "測量員在澆築混凝土基礎之前必須進行精確的測量。"}, {"id": 4, "target_seconds": 15, "question": "Applicants must meet all selection ________ published on the recruitment portal.", "options": {"A": "criteria", "B": "criterion", "C": "criterias", "D": "criterial"}, "answer": "A", "analysis": "複數名詞 criteria（單數為 criterion）。meet all selection criteria 表『符合所有遴選條件』。選 (A)。", "translation": "應徵者必須符合招募網站上公布的所有遴選條件。"}, {"id": 5, "target_seconds": 15, "question": "The laboratory instruments operate with an extraordinary level of ________.", "options": {"A": "precision", "B": "precise", "C": "precisely", "D": "preciseness"}, "answer": "A", "analysis": "介系詞 of 後接名詞。level of precision 表『精密度水平』。選 (A)。", "translation": "實驗室儀器以極高的精準度運作。"}, {"id": 6, "target_seconds": 15, "question": "Due to its geographical ________ to the harbor, the warehouse commands premium lease rates.", "options": {"A": "proximity", "B": "proximate", "C": "proximately", "D": "proximities"}, "answer": "A", "analysis": "形容詞 geographical 修飾名詞 (A) proximity（地緣鄰近度）。", "translation": "由於其地理位置緊鄰港口，該倉庫享有極高的租金費率。"}, {"id": 7, "target_seconds": 15, "question": "Winning the contract brought immense ________ to the boutique consulting agency.", "options": {"A": "prestige", "B": "prestigious", "C": "prestigiously", "D": "prestigiousness"}, "answer": "A", "analysis": "動詞 brought 後接名詞受詞 (A) prestige（聲望/聲譽）。", "translation": "贏得該合約為這家精品諮詢機構帶來了巨大的聲譽。"}, {"id": 8, "target_seconds": 15, "question": "The scholarship committee established rigorous academic ________ for candidate evaluation.", "options": {"A": "criteria", "B": "criterion", "C": "criterias", "D": "criterial"}, "answer": "A", "analysis": "形容詞 academic 修飾複數名詞 (A) criteria。", "translation": "獎學金委員會建立了嚴格的候選人評估學術標準。"}, {"id": 9, "target_seconds": 15, "question": "Laser cutting equipment enables ________ fabrication of microscopic microchip parts.", "options": {"A": "precise", "B": "precisely", "C": "precision", "D": "preciseness"}, "answer": "A", "analysis": "形容詞修飾名詞 fabrication。選 (A) precise。", "translation": "雷射切割設備實現了微晶片零件的精確製造。"}, {"id": 10, "target_seconds": 15, "question": "The luxury apartment complex advertises its immediate ________ to public transit hubs.", "options": {"A": "proximity", "B": "proximate", "C": "proximately", "D": "proximities"}, "answer": "A", "analysis": "its immediate + 名詞 (A) proximity。", "translation": "這座豪華公寓大樓主打其緊鄰大眾運輸樞紐的地緣優勢。"}, {"id": 11, "target_seconds": 15, "question": "The pharmaceutical researcher was inducted into the ________ National Science Academy.", "options": {"A": "prestigious", "B": "prestige", "C": "prestigiously", "D": "prestigiousness"}, "answer": "A", "analysis": "形容詞修飾 Academy。選 (A) prestigious。", "translation": "該製藥研究員入選了享有崇高聲望的國家科學院。"}, {"id": 12, "target_seconds": 15, "question": "Applicants failing to meet the minimum experience ________ will not be interviewed.", "options": {"A": "criterion", "B": "criteria", "C": "criterias", "D": "criterial"}, "answer": "B", "analysis": "複數名詞 criteria 作主詞受詞。選 (B) criteria。", "translation": "未達到最低經驗標準的申請者將不獲面試機會。"}, {"id": 13, "target_seconds": 15, "question": "Automated robotic arms place computer chips with sub-millimeter ________.", "options": {"A": "precision", "B": "precise", "C": "precisely", "D": "preciseness"}, "answer": "A", "analysis": "介系詞 with + 名詞 (A) precision。", "translation": "自動化機械手臂以亞毫米級的精準度放置電腦晶片。"}, {"id": 14, "target_seconds": 15, "question": "The manufacturing center's close ________ to rail lines reduces raw material freight costs.", "options": {"A": "proximity", "B": "proximate", "C": "proximately", "D": "proximities"}, "answer": "A", "analysis": "close proximity to 表地緣鄰近，選 (A)。", "translation": "製造中心緊鄰鐵路線的地緣優勢降低了原料貨運成本。"}, {"id": 15, "target_seconds": 15, "question": "Admission into the fellowship program is highly ________ and competitive.", "options": {"A": "prestigious", "B": "prestige", "C": "prestigiously", "D": "prestigiousness"}, "answer": "A", "analysis": "形容詞作補語：prestigious and competitive。選 (A)。", "translation": "該研究員項目的錄取極具聲望且競爭激烈。"}, {"id": 16, "target_seconds": 15, "question": "Auditors apply strict financial ________ when examining corporate quarterly accounts.", "options": {"A": "criteria", "B": "criterion", "C": "criterias", "D": "criterial"}, "answer": "A", "analysis": "strict financial criteria。選 (A)。", "translation": "審計人員在審查企業季度帳目時適用嚴格的財務標準。"}, {"id": 17, "target_seconds": 15, "question": "Engineers calibrated the optic sensors to guarantee ________ distance calculations.", "options": {"A": "precise", "B": "precision", "C": "precisely", "D": "preciseness"}, "answer": "A", "analysis": "形容詞修飾名詞 calculations。選 (A) precise。", "translation": "工程師校準了光學傳感器以保證精確的距離計算。"}, {"id": 18, "target_seconds": 15, "question": "Hotels located in close ________ to the convention center enjoy high annual occupancy.", "options": {"A": "proximity", "B": "proximate", "C": "proximately", "D": "proximities"}, "answer": "A", "analysis": "in close proximity to（緊鄰……）。選 (A)。", "translation": "緊鄰會議中心的飯店享有較高的年度住房率。"}, {"id": 19, "target_seconds": 15, "question": "Dr. Kim was invited to deliver the keynote address at a ________ medical conference.", "options": {"A": "prestigious", "B": "prestige", "C": "prestigiously", "D": "prestigiousness"}, "answer": "A", "analysis": "冠詞 a 與名詞 conference 之間填形容詞 (A) prestigious。", "translation": "Kim 博士受邀在一家享有盛譽的醫學會議上發表主題演講。"}, {"id": 20, "target_seconds": 15, "question": "Each evaluation ________ is weighted equally during the annual performance review.", "options": {"A": "criterion", "B": "criteria", "C": "criterias", "D": "criterial"}, "answer": "A", "analysis": "Each 後接單數名詞：Each criterion is...。選單數名詞 (A) criterion。", "translation": "在年度績效考核期間，各項評估標準被賦予同等權重。"}]}, "afternoon": {"quick_recall": [{"prompt": "a ________ [形容詞，聲譽崇高的] international honor.", "clue": "有聲望的", "answer": "prestigious"}, {"prompt": "located in close ________ [名詞，鄰近/地緣親近] to the airport.", "clue": "鄰近親近 (close ...)", "answer": "proximity"}, {"prompt": "to provide ________ [形容詞，精確的] dimensions.", "clue": "精確的", "answer": "precise"}, {"prompt": "Applicants must meet all selection ________ [複數名詞，標準/條件].", "clue": "標準條件複數", "answer": "criteria"}, {"prompt": "The instruments measure with extreme ________ [名詞，精確度].", "clue": "精確度名詞", "answer": "precision"}, {"prompt": "Each individual ________ [單數名詞，單項標準] was evaluated.", "clue": "標準單數形", "answer": "criterion"}], "spaced_traps": [{"id": 1, "target_seconds": 20, "question": "The pharmaceutical founder was recognized with a ________ lifetime achievement trophy.", "options": {"A": "prestigious", "B": "prestige", "C": "prestigiously", "D": "prestigiousness"}, "answer": "A", "trap_point": "prestigious trophy（聲譽崇高的獎盃）形容詞！", "analysis": "冠詞 a 與名詞 trophy 之間填形容詞 (A) prestigious。", "translation": "製藥創辦人獲得了聲譽崇高的終身成就獎盃。"}, {"id": 2, "target_seconds": 20, "question": "The commercial office park highlights its geographical ________ to the seaport.", "options": {"A": "proximity", "B": "proximate", "C": "proximately", "D": "proximities"}, "answer": "A", "trap_point": "its geographical + 名詞 proximity！", "analysis": "形容詞修飾名詞，選 (A) proximity（地緣鄰近度）。", "translation": "商業辦公園區強調其緊鄰海港的地理優勢。"}, {"id": 3, "target_seconds": 20, "question": "The laboratory technician calibrated the scale to ensure ________ chemical measurements.", "options": {"A": "precise", "B": "precision", "C": "precisely", "D": "preciseness"}, "answer": "A", "trap_point": "precise measurements（精確測量）！", "analysis": "形容詞修飾名詞 measurements，選 (A) precise。", "translation": "實驗室技術人員校準了天平以確保化學品測量的精確性。"}, {"id": 4, "target_seconds": 20, "question": "Candidates who fulfill all stated eligibility ________ will advance to panel interviews.", "options": {"A": "criteria", "B": "criterion", "C": "criterias", "D": "criterial"}, "answer": "A", "trap_point": "eligibility criteria（資格條件複數）！", "analysis": "複數名詞作受詞，選 (A) criteria。", "translation": "符合所有規定資格條件的候選人將晉級參加小組面試。"}, {"id": 5, "target_seconds": 20, "question": "High-precision manufacturing demands exceptional dimensional ________ in stamping dies.", "options": {"A": "precision", "B": "precise", "C": "precisely", "D": "preciseness"}, "answer": "A", "trap_point": "exceptional dimensional + 名詞 precision！", "analysis": "形容詞修飾名詞，選 (A) precision。", "translation": "高精準度製造要求沖壓模具具備非凡的尺寸精度。"}, {"id": 6, "target_seconds": 20, "question": "The factory's immediate ________ to major highways facilitates rapid freight dispatch.", "options": {"A": "proximity", "B": "proximate", "C": "proximately", "D": "proximities"}, "answer": "A", "trap_point": "immediate proximity to（緊鄰…）！", "analysis": "名詞位置，選 (A) proximity。", "translation": "工廠緊鄰主要高速公路，有利於快速貨物調配。"}, {"id": 7, "target_seconds": 20, "question": "The firm gained international ________ after developing the proprietary medical software.", "options": {"A": "prestige", "B": "prestigious", "C": "prestigiously", "D": "prestigiousness"}, "answer": "A", "trap_point": "gained international + 名詞 prestige！", "analysis": "動詞 gained 後接名詞受詞 (A) prestige。", "translation": "該公司在開發出該專利醫療軟體後贏得了國際聲譽。"}, {"id": 8, "target_seconds": 20, "question": "The grant evaluation committee established five distinct scoring ________.", "options": {"A": "criteria", "B": "criterion", "C": "criterias", "D": "criterial"}, "answer": "A", "trap_point": "five distinct scoring criteria（複數條件）！", "analysis": "數詞 five 修飾複數名詞 (A) criteria。", "translation": "補助金評估委員會確立了五項不同的評分標準。"}, {"id": 9, "target_seconds": 20, "question": "The aerospace contractor required ________ laser cutting tolerances of 0.005 mm.", "options": {"A": "precise", "B": "precisely", "C": "precision", "D": "preciseness"}, "answer": "A", "trap_point": "precise laser cutting tolerances！", "analysis": "形容詞修飾 tolerances，選 (A) precise。", "translation": "航太承包商要求 0.005 毫米的精確雷射切割公差。"}, {"id": 10, "target_seconds": 20, "question": "Tenants appreciate the luxury building's close ________ to central rail lines.", "options": {"A": "proximity", "B": "proximate", "C": "proximately", "D": "proximities"}, "answer": "A", "trap_point": "close proximity to（鄰近…）！", "analysis": "固定片語選名詞 (A) proximity。", "translation": "租戶讚賞這座豪宅緊鄰中央鐵路線的便利地段。"}, {"id": 11, "target_seconds": 20, "question": "The researcher published her findings in a ________ international scientific journal.", "options": {"A": "prestigious", "B": "prestige", "C": "prestigiously", "D": "prestigiousness"}, "answer": "A", "trap_point": "a prestigious scientific journal！", "analysis": "形容詞修飾期刊名詞，選 (A) prestigious。", "translation": "研究人員將她的研究成果發表在一家享有盛譽的國際科學期刊上。"}, {"id": 12, "target_seconds": 20, "question": "Not every single evaluation ________ must be met for preliminary screening approval.", "options": {"A": "criterion", "B": "criteria", "C": "criterias", "D": "criterial"}, "answer": "A", "trap_point": "every single + 單數名詞 criterion！", "analysis": "every single 後接單數名詞 (A) criterion。", "translation": "並非每個單項評估標準都必須符合方能通過初審。"}, {"id": 13, "target_seconds": 20, "question": "Automated robotics ensure surgical ________ during delicate cardiovascular procedures.", "options": {"A": "precision", "B": "precise", "C": "precisely", "D": "preciseness"}, "answer": "A", "trap_point": "surgical precision（手術精密度）名詞！", "analysis": "形容詞修飾名詞，選 (A) precision。", "translation": "自動化機器人確保了在精細心血管手術過程中的手術精密度。"}, {"id": 14, "target_seconds": 20, "question": "The industrial warehouse's unique ________ to the air cargo terminal attracts global couriers.", "options": {"A": "proximity", "B": "proximate", "C": "proximately", "D": "proximities"}, "answer": "A", "trap_point": "unique proximity to...！", "analysis": "選名詞 (A) proximity。", "translation": "該工業倉庫緊鄰航空貨運站的獨特地段吸引了全球快遞公司。"}], "part7": {"passages": [{"text_type": "Fellowship Program Announcement (企業領導力獎學金徵選公告)", "title": "The Horizon Foundation — Prestigious Annual Leadership Fellowship", "content": "FELLOWSHIP DIRECTIVE: HZF-LEAD-2026-17\nISSUING ORGANIZATION: The Horizon Foundation for Global Business Excellence\nDATE: November 20, 2026\nAPPLICATION WINDOW: November 20 — December 22, 2026\n\n1. Fellowship Scope and Financial Award\nThe Horizon Foundation is pleased to invite formal applications for its prestigious Executive Leadership Fellowship. Selected fellowship recipients receive a non-restrictive monetary award of $75,000 to conduct advanced fieldwork in organizational resilience, corporate sustainability, or digital supply chain optimization. In addition, fellows will be paired with executive mentors from Fortune 100 advisory councils and receive international conference travel stipends.\n\n2. Candidate Eligibility & Experience Standards\nThis competitive fellowship targets mid-career professionals with demonstrated operational impact and visionary leadership across business operations. To be eligible, applicants must possess a minimum of five years of verifiable managerial experience within corporate, governmental, or non-profit enterprises, along with documented supervisory accomplishments.\n\n*Mandatory Fellowship Condition: Fellowship recipients must maintain active full-time employment with their current sponsoring employer throughout their fellowship tenure. If an awardee resigns, transitions to part-time consulting, or takes extended unpaid sabbatical without prior foundation clearance, the stipend will be rescinded immediately. Apply online at www.horizonfellows.org/apply.", "questions": [{"question": "What monetary award do fellowship recipients receive?", "options": {"A": "$25,000", "B": "$50,000", "C": "$75,000", "D": "$100,000"}, "answer": "C", "radar": "🔍 防漏看雷達：金額定位 'receive a $75,000 research stipend'！", "analysis": "文中明確載明獲得 75,000 美元的研究津貼，故選 (C)。"}, {"question": "What minimum managerial experience is required to apply?", "options": {"A": "Two years", "B": "Three years", "C": "Five years", "D": "Seven years"}, "answer": "C", "radar": "🔍 防漏看雷達：年資條件 'Minimum five years of managerial experience'！", "analysis": "資格條件第一點指明需至少五年管理經驗，故選 (C)。"}, {"question": "What must candidates maintain throughout their fellowship tenure?", "options": {"A": "Active full-time employment", "B": "Enrollment in an evening MBA program", "C": "Residency in Geneva", "D": "Monthly newsletter publications"}, "answer": "A", "radar": "🔍 防漏看雷達：星號條件條款 '*Selection Note: ... contingent upon candidates maintaining active full-time employment'！", "analysis": "星號條款特別註明在研究員任期內必須維持全職員工身份，故選 (A)。"}]}, {"text_type": "Commercial Science Park Leasing Brochure (科技園區實驗室租賃型錄)", "title": "Verdant Technology Park — Research Suites, Proximity, and Leasing Terms", "content": "LEASING PROSPECTUS: VTP-RE-2026-04\nDEVELOPER: Verdant Commercial Development Group\nLOCATION: Verdant Technology Park, Silicon Corridor\nAVAILABLE UNITS: Modular Bio-Cleanrooms, Nanotechnology Labs & Spec Suites\n\n1. Proximity to Public Transit & Urban Amenities\nVerdant Technology Park is strategically positioned at the vibrant epicenter of the regional biotechnology corridor. Located in close proximity to Metro Line 4, the facility offers corporate researchers and scientific teams seamless direct transit connectivity to the downtown financial district, international airport terminals, and top regional research universities, drastically reducing daily employee commutes and attracting elite scientific talent from across the metropolitan region.\n\n2. Research Infrastructure & Environmental Controls\nOur custom-built research suites feature specialized vibration isolation flooring, redundant backup diesel generators, and medical-grade vacuum lines. Furthermore, every laboratory module is equipped with advanced automated HVAC systems delivering precise environmental temperature controls (regulated within 0.1 degrees Celsius) and HEPA-filtered laminar airflow for sensitive biomedical syntheses.\n\n*Long-Term Lease Promotional Incentive: Commercial tenants signing a binding five-year lease before December 31 will be granted three months of waived facility rent and complimentary tenant improvement allowances. Contact leasing@verdanttechpark.com for floor plans.", "questions": [{"question": "What transit line is located in close proximity to Verdant Technology Park?", "options": {"A": "Bus Rapid Line 1", "B": "Metro Line 4", "C": "Commuter Rail West", "D": "Airport Express"}, "answer": "B", "radar": "🔍 防漏看雷達：交通線路定位 'Located in close proximity to Metro Line 4'！", "analysis": "首段指明緊鄰捷運 4 號線，故選 (B)。"}, {"question": "What engineering feature do the research suites offer?", "options": {"A": "Rooftop helipads", "B": "Precise environmental temperature controls", "C": "Underground bowling alleys", "D": "On-site commercial bakeries"}, "answer": "B", "radar": "🔍 防漏看雷達：設施特點 'engineered with precise environmental temperature controls'！", "analysis": "文中指明研發套房具有精準的環境溫度控制系統，故選 (B)。"}, {"question": "What incentive is granted to tenants signing a ten-year lease by December 15?", "options": {"A": "A 50% discount on office furniture", "B": "Three months of waived facility management fees", "C": "Free unlimited parking for all staff", "D": "Complimentary daily catering services"}, "answer": "B", "radar": "🔍 防漏看雷達：星號優惠條款 '*Special Incentive Clause: ... entitled to three months of waived facility management fees'！", "analysis": "星號條款說明 12 月 15 日前簽署 10 年租約可免除 3 個月物業管理費，故選 (B)。"}]}]}}}, "18": {"day": 18, "date": "11/21", "phase": 2, "phase_name": "860 突破與同義代換", "topic": "Phase 2 大驗收 ｜ 諮詢、限制與嚴格規範", "morning": {"chunks": [{"chunk": "in compliance with", "meaning": "遵守符合……規章", "scenario": "The facility was designed in compliance with federal guidelines.", "paraphrase": "in compliance with = in accordance with = adhering to", "alert": "固定片語 in compliance with！"}, {"chunk": "schedule a consultation", "meaning": "安排諮詢商談", "scenario": "Clients may schedule a consultation with our senior tax attorneys.", "paraphrase": "consultation = advisory session = conference", "alert": "動詞為 consult，名詞為 consultation！"}, {"chunk": "mandatory attendance", "meaning": "強制出席/必須參加", "scenario": "Mandatory attendance is enforced for all department managers.", "paraphrase": "mandatory = compulsory = obligatory = required", "alert": "反義詞為 optional！"}, {"chunk": "trade restrictions", "meaning": "貿易限制規章", "scenario": "New trade restrictions impacted overseas consumer electronics exports.", "paraphrase": "restrictions = limitations = constraints = caps", "alert": "動詞為 restrict！"}, {"chunk": "remain compliant", "meaning": "始終保持合規", "scenario": "We conduct internal reviews to ensure operations remain compliant.", "paraphrase": "remain compliant = maintain regulatory adherence", "alert": "compliant 為形容詞！"}, {"chunk": "consult with specialists", "meaning": "向專家諮詢", "scenario": "Engineers must consult with specialists before modifying blueprints.", "paraphrase": "consult with = seek advice from = confer with", "alert": "consult with + 專家對象！"}, {"chunk": "impose restrictions on", "meaning": "對……施加限制", "scenario": "The authorities chose to impose restrictions on heavy vehicle traffic.", "paraphrase": "impose restrictions on = place limitations on", "alert": "動詞固定搭配 impose / place！"}], "visual_anchor": {"title": "Phase 2 大驗收：高頻名詞/形容詞秒殺錨點", "rule_1": "👀 看到 in ________ with ➔ 100% 填入名詞「compliance」（in compliance with）！", "rule_2": "👀 看到 is strictly ________ ➔ 填入形容詞「mandatory」（強制的）！", "golden_rule": "⚡ 教練金句：合規遵從選 compliance，強制必須選 mandatory！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "Full ________ with international air safety protocols is required of all carrier personnel.", "options": {"A": "compliance", "B": "compliant", "C": "comply", "D": "compliantly"}, "answer": "A", "analysis": "形容詞 Full 後接名詞 compliance（遵從/法規符合）。選 (A)。", "translation": "所有航空公司人員均須完全遵守國際航空安全協議。"}, {"id": 2, "target_seconds": 15, "question": "Management scheduled a special ________ with external cybersecurity auditors.", "options": {"A": "consultation", "B": "consult", "C": "consulting", "D": "consultant"}, "answer": "A", "analysis": "形容詞 special 後接名詞 (A) consultation（諮詢會/商談）。", "translation": "管理層安排了與外部網路安全審計員的專題諮詢會。"}, {"id": 3, "target_seconds": 15, "question": "Attendance at the workplace health and safety seminar is strictly ________ for factory floor supervisors.", "options": {"A": "mandatory", "B": "mandate", "C": "mandatorily", "D": "mandates"}, "answer": "A", "analysis": "連綴動詞 is strictly + [形容詞補語] mandatory（強制的/必須遵守的）。選 (A)。", "translation": "工廠現場主管必須強制參加工作場所健康與安全研討會。"}, {"id": 4, "target_seconds": 15, "question": "The city council imposed strict ________ on overnight commercial vehicle parking.", "options": {"A": "restrictions", "B": "restrict", "C": "restrictive", "D": "restrictively"}, "answer": "A", "analysis": "形容詞 strict 後接名詞複數 restrictions（限制規章）。選 (A)。", "translation": "市議會對隔夜商用車輛停放實施了嚴格限制。"}, {"id": 5, "target_seconds": 15, "question": "Failure to ________ with data privacy statutes may result in substantial financial penalties.", "options": {"A": "comply", "B": "compliance", "C": "compliant", "D": "complied"}, "answer": "A", "analysis": "不定詞結構：to + [原形動詞] comply with。選 (A)。", "translation": "未能遵守資料隱私法規可能導致巨額罰款。"}, {"id": 6, "target_seconds": 15, "question": "The enterprise legal counsel is available for private ________ every Thursday afternoon.", "options": {"A": "consultation", "B": "consult", "C": "consulted", "D": "consulting"}, "answer": "A", "analysis": "介系詞 for 後接名詞 (A) consultation。", "translation": "企業法律顧問每週四下午均可提供私人諮詢。"}, {"id": 7, "target_seconds": 15, "question": "Wearing reflective safety vests is ________ for all workers operating near heavy cranes.", "options": {"A": "mandatory", "B": "mandate", "C": "mandatorily", "D": "mandating"}, "answer": "A", "analysis": "連綴動詞 is + 形容詞 (A) mandatory。", "translation": "在重型吊車附近作業的所有工人必須強制佩戴反光安全背心。"}, {"id": 8, "target_seconds": 15, "question": "Due to budgetary ________, the marketing department canceled two overseas promotional trips.", "options": {"A": "restrictions", "B": "restrict", "C": "restrictive", "D": "restricting"}, "answer": "A", "analysis": "形容詞 budgetary 後接名詞複數 restrictions（限制）。選 (A)。", "translation": "由於預算限制，行銷部門取消了兩次海外促銷考察。"}, {"id": 9, "target_seconds": 15, "question": "The audit confirmed that all financial ledgers are fully ________ with tax regulations.", "options": {"A": "compliant", "B": "compliance", "C": "comply", "D": "compliantly"}, "answer": "A", "analysis": "be fully + [形容詞] compliant with（符合……規定的）。選 (A)。", "translation": "審計證實所有財務帳冊完全符合稅收法規。"}, {"id": 10, "target_seconds": 15, "question": "After close ________ with union representatives, the company agreed on wage adjustments.", "options": {"A": "consultation", "B": "consult", "C": "consultant", "D": "consulting"}, "answer": "A", "analysis": "介系詞 After close 後接名詞 consultation。選 (A)。", "translation": "在與工會代表進行密切磋商後，公司就工資調整達成了共識。"}, {"id": 11, "target_seconds": 15, "question": "It is ________ that all international travel expense reports be submitted within 14 days.", "options": {"A": "mandatory", "B": "mandatorily", "C": "mandate", "D": "mandates"}, "answer": "A", "analysis": "It is + [形容詞] that 虛主詞句型。選 (A) mandatory。", "translation": "所有國際差旅費用報銷單必須在 14 天內提交，這是強制性的。"}, {"id": 12, "target_seconds": 15, "question": "New export ________ will take effect at the start of the next fiscal quarter.", "options": {"A": "restrictions", "B": "restrict", "C": "restrictive", "D": "restrictively"}, "answer": "A", "analysis": "名詞片語：export restrictions（出口管制/限制）。選 (A)。", "translation": "新的出口限制規章將在下一會計季度初生效。"}, {"id": 13, "target_seconds": 15, "question": "The manufacturing division brought its production waste levels into strict ________.", "options": {"A": "compliance", "B": "compliant", "C": "comply", "D": "compliantly"}, "answer": "A", "analysis": "into strict compliance（完全合規）。選 (A)。", "translation": "製造部門使其生產廢棄物水準嚴格符合規定。"}, {"id": 14, "target_seconds": 15, "question": "Free legal ________ is provided to small business founders through the civic enterprise initiative.", "options": {"A": "consultation", "B": "consult", "C": "consultant", "D": "consulting"}, "answer": "A", "analysis": "形容詞 legal 後接名詞 (A) consultation。", "translation": "透過市政企業倡議，為小型企業創辦人提供免費法律諮詢。"}, {"id": 15, "target_seconds": 15, "question": "Security training remains ________ for any contractor accessing the data facility.", "options": {"A": "mandatory", "B": "mandatorily", "C": "mandate", "D": "mandates"}, "answer": "A", "analysis": "連綴動詞 remains + 形容詞 (A) mandatory。", "translation": "對於任何進出數據設施的承包商而言，安全培訓仍是強制的。"}, {"id": 16, "target_seconds": 15, "question": "The building code placed height ________ on commercial structures in historical zones.", "options": {"A": "restrictions", "B": "restrict", "C": "restrictive", "D": "restricted"}, "answer": "A", "analysis": "名詞受詞：placed height restrictions。選 (A)。", "translation": "建築法規對歷史街區的商業建築設置了高度限制。"}, {"id": 17, "target_seconds": 15, "question": "Suppliers must remain ________ with environmental sustainability standards.", "options": {"A": "compliant", "B": "compliance", "C": "comply", "D": "compliantly"}, "answer": "A", "analysis": "remain compliant with...（符合……標準）。選 (A)。", "translation": "供應商必須始終遵守環境永續發展標準。"}, {"id": 18, "target_seconds": 15, "question": "The committee completed its final ________ with stakeholder representatives yesterday.", "options": {"A": "consultation", "B": "consult", "C": "consulting", "D": "consultant"}, "answer": "A", "analysis": "形容詞 final 後接名詞 consultation。選 (A)。", "translation": "委員會昨日完成了與利益相關者代表的最終磋商。"}, {"id": 19, "target_seconds": 15, "question": "A ________ ten-day quarantine period was imposed on all imported livestock.", "options": {"A": "mandatory", "B": "mandatorily", "C": "mandate", "D": "mandates"}, "answer": "A", "analysis": "形容詞修飾名詞 period。選 (A) mandatory。", "translation": "對所有進口牲畜實施了強制性的十天隔離期。"}, {"id": 20, "target_seconds": 15, "question": "Contractual ________ prohibit employees from disclosing trade secrets to outside entities.", "options": {"A": "restrictions", "B": "restrict", "C": "restrictive", "D": "restricting"}, "answer": "A", "analysis": "名詞主詞：Contractual restrictions（合約限制條款）。選 (A)。", "translation": "合約限制條款禁止員工向外部實體洩露商業機密。"}]}, "afternoon": {"quick_recall": [{"prompt": "to ensure strict ________ [名詞，法規遵從/符合規定] with safety codes.", "clue": "法規遵循", "answer": "compliance"}, {"prompt": "to schedule a legal ________ [名詞，諮詢會/商討].", "clue": "諮詢商談", "answer": "consultation"}, {"prompt": "Attendance at orientation is strictly ________ [形容詞，強制的/必須的].", "clue": "強制的", "answer": "mandatory"}, {"prompt": "The government lifted trade ________ [複數名詞，限制管制].", "clue": "限制管制", "answer": "restrictions"}, {"prompt": "The facility is fully ________ [形容詞，合規的] with EPA rules.", "clue": "合規的 (be ... with)", "answer": "compliant"}, {"prompt": "to ________ [動詞，遵守] with company directives.", "clue": "遵守規定", "answer": "comply with"}], "spaced_traps": [{"id": 1, "target_seconds": 20, "question": "The pharmaceutical plant operates in strict ________ with international drug safety standards.", "options": {"A": "compliance", "B": "compliant", "C": "comply", "D": "compliantly"}, "answer": "A", "trap_point": "in strict compliance with 固定片語！", "analysis": "介系詞片語選名詞 (A) compliance。", "translation": "該製藥廠的運作嚴格遵守國際藥品安全標準。"}, {"id": 2, "target_seconds": 20, "question": "The CEO convened a special ________ with economic advisors prior to the market opening.", "options": {"A": "consultation", "B": "consult", "C": "consulting", "D": "consultant"}, "answer": "A", "trap_point": "a special consultation 名詞！", "analysis": "冠詞與形容詞後接名詞 (A) consultation。", "translation": "執行長在開市前召集經濟顧問召開了一次專題諮詢會。"}, {"id": 3, "target_seconds": 20, "question": "Submitting quarterly emissions logs is ________ for all chemical processing facilities.", "options": {"A": "mandatory", "B": "mandate", "C": "mandatorily", "D": "mandates"}, "answer": "A", "trap_point": "is + mandatory 形容詞！", "analysis": "連綴動詞後接形容詞主詞補語 (A) mandatory。", "translation": "提交季度排放日誌對所有化學加工廠而言都是強制性的。"}, {"id": 4, "target_seconds": 20, "question": "The zoning board introduced spatial ________ regarding retail signboards.", "options": {"A": "restrictions", "B": "restrict", "C": "restrictive", "D": "restrictively"}, "answer": "A", "trap_point": "spatial restrictions（空間限制）名詞複數！", "analysis": "形容詞修飾名詞複數，選 (A) restrictions。", "translation": "分區委員會出台了有關零售招牌的空間限制規定。"}, {"id": 5, "target_seconds": 20, "question": "All third-party vendors must remain ________ with data security guidelines.", "options": {"A": "compliant", "B": "compliance", "C": "comply", "D": "compliantly"}, "answer": "A", "trap_point": "remain compliant with 表維持合規！", "analysis": "連綴動詞 remain 接形容詞 (A) compliant。", "translation": "所有第三方供應商必須始終遵守資料安全準則。"}, {"id": 6, "target_seconds": 20, "question": "The design blueprint was finalized after lengthy ________ with structural engineers.", "options": {"A": "consultation", "B": "consult", "C": "consultant", "D": "consulting"}, "answer": "A", "trap_point": "after lengthy + 名詞 consultation！", "analysis": "介系詞與形容詞後接名詞 (A) consultation。", "translation": "設計藍圖是在與結構工程師進行冗長磋商後最終敲定的。"}, {"id": 7, "target_seconds": 20, "question": "Participation in cybersecurity refresher training is ________ for remote personnel.", "options": {"A": "mandatory", "B": "mandatorily", "C": "mandate", "D": "mandates"}, "answer": "A", "trap_point": "is + mandatory（是強制的）！", "analysis": "選形容詞 (A) mandatory。", "translation": "遠端工作人員必須強制參加網路安全進修培訓。"}, {"id": 8, "target_seconds": 20, "question": "The logistics authority imposed seasonal speed ________ on freight trains.", "options": {"A": "restrictions", "B": "restrict", "C": "restrictive", "D": "restricted"}, "answer": "A", "trap_point": "speed restrictions（速度限制）名詞！", "analysis": "複合名詞結構，選 (A) restrictions。", "translation": "物流管理局對貨運列車實施了季節性速度限制。"}, {"id": 9, "target_seconds": 20, "question": "To achieve full ________, the accounting system underwent an external audit.", "options": {"A": "compliance", "B": "compliant", "C": "comply", "D": "compliantly"}, "answer": "A", "trap_point": "achieve full compliance 表達到完全合規！", "analysis": "動詞 achieve 後接名詞 (A) compliance。", "translation": "為達到完全合規，會計系統接受了外部審計。"}, {"id": 10, "target_seconds": 20, "question": "Patients may request an optional specialist ________ upon discharge.", "options": {"A": "consultation", "B": "consult", "C": "consultant", "D": "consulting"}, "answer": "A", "trap_point": "an optional specialist consultation 名詞！", "analysis": "名詞片語，選 (A) consultation。", "translation": "病患在出院時可申請自選的專科醫師諮詢。"}, {"id": 11, "target_seconds": 20, "question": "Wearing steel-toed boots is strictly ________ within the fabrication workshop.", "options": {"A": "mandatory", "B": "mandatorily", "C": "mandate", "D": "mandates"}, "answer": "A", "trap_point": "is strictly mandatory 形容詞！", "analysis": "選形容詞 (A) mandatory。", "translation": "在製造車間內穿著鋼頭靴是嚴格強制的。"}, {"id": 12, "target_seconds": 20, "question": "Foreign trade ________ led to a five percent decrease in quarterly export volumes.", "options": {"A": "restrictions", "B": "restrict", "C": "restrictive", "D": "restricting"}, "answer": "A", "trap_point": "trade restrictions（貿易限制）名詞主詞！", "analysis": "名詞複數作主詞，選 (A) restrictions。", "translation": "對外貿易限制導致季度出口量下降了 5%。"}, {"id": 13, "target_seconds": 20, "question": "Suppliers failing to remain ________ with ethics standards will have contracts canceled.", "options": {"A": "compliant", "B": "compliance", "C": "comply", "D": "compliantly"}, "answer": "A", "trap_point": "failing to remain compliant with！", "analysis": "連綴動詞 remain 後接形容詞 (A) compliant。", "translation": "未能始終遵守道德標準的供應商將被取消合約。"}, {"id": 14, "target_seconds": 20, "question": "The university hospital initiated a public health ________ service for regional clinics.", "options": {"A": "consultation", "B": "consult", "C": "consultant", "D": "consulting"}, "answer": "A", "trap_point": "public health consultation service 名詞！", "analysis": "名詞修飾 service，選 (A) consultation。", "translation": "大學醫院為地方診所開通了公共衛生諮詢服務。"}], "part7": {"passages": [{"text_type": "Corporate Compliance Circular (企業倫理合規年度通告)", "title": "Titan Holdings — Mandatory Ethics Compliance Review & Governance Directive", "content": "GOVERNANCE POLICY NOTICE: TH-ETH-2026-18\nISSUING BODY: Global Ethics & Legal Compliance Directorate, Titan Holdings Inc.\nDATE: November 21, 2026\nMANDATORY FOR: All Corporate Officers, Department Directors, and Regional Controllers\n\n1. Annual Ethics Certification Mandate\nTo maintain uncompromising integrity, foster transparent stakeholder relations, and satisfy international anti-corruption standards across all operating subsidiaries, Titan Holdings requires all managerial personnel to complete the 2026 Annual Ethics Compliance Certification. All certified assessments, anti-bribery declarations, and conflict-of-interest disclosure filings must be finalized prior to the statutory deadline of December 15.\n\n2. Mandatory In-Person Governance Workshop\nIn addition to online compliance coursework, an intensive four-hour interactive workshop will be held on December 3 in the Executive Auditorium. This specialized ethics governance workshop is mandatory strictly for personnel holding executive signing authority and procurement oversight duties across all corporate business units.\n\n*Penalties for Non-Compliance: Any employee who fails to complete their certification by December 15 will face immediate disciplinary measures, including administrative restrictions on procurement approvals and temporary suspension of corporate credit card charging privileges until full compliance verification is established by corporate legal counsel and documented in the employee personnel file.", "questions": [{"question": "What deadline is set for the annual compliance verification?", "options": {"A": "November 21", "B": "December 1", "C": "December 15", "D": "December 31"}, "answer": "C", "radar": "🔍 防漏看雷達：截止日期 'complete the annual compliance verification by December 15'！", "analysis": "內文明確要求在 12 月 15 日前完成年度合規審驗，故選 (C)。"}, {"question": "For whom is the ethics governance workshop mandatory?", "options": {"A": "Only summer interns", "B": "Personnel holding executive signing authority", "C": "Warehouse forklift drivers", "D": "External catering staff"}, "answer": "B", "radar": "🔍 防漏看雷達：適用對象 'mandatory for all personnel holding executive signing authority'！", "analysis": "文中指出擁有主管簽署權限的人員必須強制參加，故選 (B)。"}, {"question": "What penalty is imposed on employees failing to complete certification on time?", "options": {"A": "Forfeiture of paid annual leave", "B": "Administrative restrictions on procurement approvals", "C": "Immediate termination without notice", "D": "Reduction in medical coverage benefits"}, "answer": "B", "radar": "🔍 防漏看雷達：星號懲罰條款 '*Important Restriction: ... will face immediate administrative restrictions on procurement approvals'！", "analysis": "星號條款特別載明未按時完成將面臨採購審批的行政權限限制，故選 (B)。"}]}, {"text_type": "Environmental Audit Consultation Notice (環境工程排放檢驗與諮詢通告)", "title": "EcoLogix Environmental Group — Industrial Emissions Audit & Consultation Summary", "content": "ENVIRONMENTAL AUDIT REPORT: ECO-AUD-2026-91\nPREPARED FOR: Crestview Heavy Manufacturing Facilities, Unit 4\nPREPARED BY: EcoLogix Environmental Engineering Consultants\nDATE: November 21, 2026\n\n1. Audit Findings and Regulatory Compliance\nEcoLogix Environmental Group has concluded its comprehensive quarterly assessment of volatile organic compounds and chimney particulate emissions at the Unit 4 smelting complex. The environmental audit confirmed that the facility operates in full statutory compliance with current municipal air quality guidelines, exhaust velocity restrictions, and regional environmental protection standards, maintaining zero hazardous containment violations.\n\n2. Forthcoming Regulatory Emission Ceilings\nPlant operators must prepare for significantly tighter regional standards taking effect next year. Beginning in the first quarter of 2027, municipal regulatory restrictions will require 20% lower emission ceilings across all industrial smokestacks and catalytic combustion chambers, necessitating advanced electrostatic precipitators.\n\n*Engineering Consultation Deadline: To assist plant operators in engineering cost-effective filtration retrofits and emission scrubbing upgrades, EcoLogix specialists will hold complimentary on-site technical advisory sessions. Facility engineers may schedule consultations until December 5 through our online client portal. Bookings made after this date will incur standard consulting fees.", "questions": [{"question": "What did the environmental audit of the Apex Plant conclude?", "options": {"A": "The facility violated local water safety regulations", "B": "The facility operates in full compliance with current regional standards", "C": "The plant must close immediately for hazardous waste removal", "D": "All equipment must be sold at salvage auction"}, "answer": "B", "radar": "🔍 防漏看雷達：審核結論 'operates in full compliance with current regional particulate standards'！", "analysis": "首段指明工廠完全符合現行區域微粒排放標準，故選 (B)。"}, {"question": "What will 2027 regulatory restrictions require?", "options": {"A": "20% lower emission ceilings", "B": "50% increase in factory floor space", "C": "Doubling of daily work shifts", "D": "Complete conversion to solar power"}, "answer": "A", "radar": "🔍 防漏看雷達：未來標準 'mandate twenty percent lower emission ceilings'！", "analysis": "文中指明 2027 年新規將要求降低 20% 的排放上限，故選 (A)。"}, {"question": "Until what date may engineers schedule complimentary technical consultations?", "options": {"A": "November 10", "B": "November 21", "C": "December 5", "D": "December 31"}, "answer": "C", "radar": "🔍 防漏看雷達：星號附註諮詢日期 '*Consultation Note: ... through December 5'！", "analysis": "星號條款說明免費技術諮詢開放預約至 12 月 5 日，故選 (C)。"}]}]}}}, "19": {"day": 19, "date": "11/22", "phase": 3, "phase_name": "考前全真極速模擬與弱點獵殺", "topic": "Part 5 極速衝刺 ｜ 策略計畫、部門板塊與唯一依據", "morning": {"chunks": [{"chunk": "strategic plan", "meaning": "策略計畫", "scenario": "The executive committee unveiled a new strategic plan.", "paraphrase": "strategic = tactical = master", "alert": "名詞為 strategy，副詞為 strategically！"}, {"chunk": "logistics division", "meaning": "物流部門/事業部", "scenario": "The logistics division handled over a million shipments.", "paraphrase": "division = department = branch = sector", "alert": "常考 corporate division！"}, {"chunk": "sole distributor", "meaning": "唯一經銷商/獨家代理", "scenario": "Apex is the sole distributor of this medical scanner.", "paraphrase": "sole = exclusive = only", "alert": "副詞為 solely（僅僅/唯一地）！"}, {"chunk": "security protocol", "meaning": "安全協定/規範規程", "scenario": "Personnel must adhere to strict security protocol.", "paraphrase": "protocol = procedure = code of conduct = guidelines", "alert": "複數形為 protocols！"}, {"chunk": "solely responsible for", "meaning": "全權負責", "scenario": "The project lead is solely responsible for budget oversight.", "paraphrase": "solely responsible = exclusively in charge of", "alert": "副詞 solely 修飾形容詞！"}, {"chunk": "corporate division", "meaning": "企業事業部", "scenario": "Each corporate division submits monthly productivity reports.", "paraphrase": "division = business segment", "alert": "名詞作主詞！"}, {"chunk": "strategic realignment", "meaning": "策略性重新配置", "scenario": "The merger prompted a strategic realignment of assets.", "paraphrase": "realignment = restructuring = reorganization", "alert": "商業閱讀高頻詞彙！"}], "visual_anchor": {"title": "Phase 3 極速反射：15 秒視覺錨點極限突破", "rule_1": "👀 看到 [the ________ distributor / supplier] ➔ 秒選「sole」（唯一的/獨家的）！", "rule_2": "👀 看到 [________ plan / importance / partnership] ➔ 秒選「strategic」（策略性的）！", "golden_rule": "⚡ 教練金句：15 秒衝刺不猶豫，抓修飾關係秒殺選項！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "The executive board formulated a ________ plan to expand cloud services into Latin America.", "options": {"A": "strategic", "B": "strategy", "C": "strategically", "D": "strategize"}, "answer": "A", "analysis": "形容詞修飾名詞 plan。strategic plan 表『策略計畫』。選 (A)。", "translation": "執行董事會制定了一項將雲端服務擴展至拉丁美洲的策略計畫。"}, {"id": 2, "target_seconds": 15, "question": "Mr. Gomez was appointed general manager of the overseas logistics ________.", "options": {"A": "division", "B": "divide", "C": "divisible", "D": "divided"}, "answer": "A", "analysis": "名詞位置：logistics division 表『物流部門/事業部』。選 (A)。", "translation": "Gomez 先生被任命為海外物流事業部的總經理。"}, {"id": 3, "target_seconds": 15, "question": "Nexus Media is the ________ authorized distributor of these patented surgical instruments.", "options": {"A": "sole", "B": "solely", "C": "soleness", "D": "solitary"}, "answer": "A", "analysis": "形容詞修飾名詞 distributor。the sole authorized distributor 表『唯一授權經銷商』。選 (A)。", "translation": "Nexus 媒體是這些專利手術器械的唯一授權經銷商。"}, {"id": 4, "target_seconds": 15, "question": "All laboratory technicians must adhere strictly to established data security ________.", "options": {"A": "protocols", "B": "protocol", "C": "protocollary", "D": "protocoling"}, "answer": "A", "analysis": "名詞複數：security protocols（安全協定/規程）。選 (A)。", "translation": "所有實驗室技術人員必須嚴格遵守既定的資料安全規程。"}, {"id": 5, "target_seconds": 15, "question": "Senior management recognized the ________ importance of investing in artificial intelligence.", "options": {"A": "strategic", "B": "strategy", "C": "strategically", "D": "strategist"}, "answer": "A", "analysis": "形容詞修飾名詞 importance。strategic importance（策略重要性）。選 (A)。", "translation": "資深管理層認識到了投資人工智慧的策略重要性。"}, {"id": 6, "target_seconds": 15, "question": "The retail conglomerate decided to dissolve its unprofitable home entertainment ________.", "options": {"A": "division", "B": "divide", "C": "dividing", "D": "divisible"}, "answer": "A", "analysis": "所有格後接名詞 division（部門）。選 (A)。", "translation": "該零售集團決定解散其不盈利的家庭娛樂事業部。"}, {"id": 7, "target_seconds": 15, "question": "Under the agreement, Pinnacle holds the ________ commercial exploitation rights to the software.", "options": {"A": "sole", "B": "solely", "C": "soleness", "D": "solo"}, "answer": "A", "analysis": "形容詞修飾名詞 rights。the sole rights（唯一權利/獨家權利）。選 (A)。", "translation": "根據該協議，Pinnacle 擁有該軟體的獨家商業開發權利。"}, {"id": 8, "target_seconds": 15, "question": "The cybersecurity team implemented a multi-factor authentication ________ for remote workers.", "options": {"A": "protocol", "B": "protocols", "C": "protocollary", "D": "protocoling"}, "answer": "A", "analysis": "冠詞 a 後接單數名詞 protocol。選 (A)。", "translation": "網路安全團隊為遠端員工實施了多因素身份驗證協定。"}, {"id": 9, "target_seconds": 15, "question": "The regional director proposed a ________ realignment of sales personnel across districts.", "options": {"A": "strategic", "B": "strategy", "C": "strategically", "D": "strategize"}, "answer": "A", "analysis": "形容詞修飾名詞 realignment。選 (A) strategic。", "translation": "區域處長提議對各區銷售人員進行策略性重新配置。"}, {"id": 10, "target_seconds": 15, "question": "Each regional ________ must submit its annual expenditure budget by Friday.", "options": {"A": "division", "B": "divide", "C": "divided", "D": "divisible"}, "answer": "A", "analysis": "Each 後接單數名詞 division。選 (A)。", "translation": "各區域事業部必須在週五前提交其年度支出預算。"}, {"id": 11, "target_seconds": 15, "question": "Dr. Alvarez was the ________ researcher credited with discovering the polymer compound.", "options": {"A": "sole", "B": "solely", "C": "solitary", "D": "soleness"}, "answer": "A", "analysis": "the sole researcher（唯一的研發人員）。選 (A)。", "translation": "Alvarez 博士是被認定為發現該聚合物化合物的唯一研究員。"}, {"id": 12, "target_seconds": 15, "question": "Hospital staff followed rigorous hygiene ________ to prevent cross-contamination.", "options": {"A": "protocols", "B": "protocol", "C": "protocollary", "D": "protocoling"}, "answer": "A", "analysis": "名詞複數受詞 protocols。選 (A)。", "translation": "醫院工作人員遵守嚴格的衛生規程以防止交叉污染。"}, {"id": 13, "target_seconds": 15, "question": "The corporation formed a ________ partnership with an international green energy supplier.", "options": {"A": "strategic", "B": "strategy", "C": "strategically", "D": "strategist"}, "answer": "A", "analysis": "a strategic partnership（策略夥伴關係）。選 (A)。", "translation": "該公司與一家國際綠色能源供應商建立了策略夥伴關係。"}, {"id": 14, "target_seconds": 15, "question": "The manufacturing ________ surpassed its annual production quota two months early.", "options": {"A": "division", "B": "divide", "C": "divided", "D": "dividing"}, "answer": "A", "analysis": "名詞主詞：The manufacturing division。選 (A)。", "translation": "製造事業部提前兩個月超額完成了年度生產配額。"}, {"id": 15, "target_seconds": 15, "question": "The company acted as the ________ supplier of specialized titanium fasteners for the project.", "options": {"A": "sole", "B": "solely", "C": "solitary", "D": "solo"}, "answer": "A", "analysis": "the sole supplier（唯一供應商）。選 (A)。", "translation": "該公司擔任該項目專用鈦金屬緊固件的唯一供應商。"}, {"id": 16, "target_seconds": 15, "question": "Standard operating ________ must be displayed prominently near all conveyor belts.", "options": {"A": "protocols", "B": "protocol", "C": "protocollary", "D": "protocoling"}, "answer": "A", "analysis": "複數名詞主詞 protocols。選 (A)。", "translation": "標準作業規程必須在所有輸送帶附近顯著展示。"}, {"id": 17, "target_seconds": 15, "question": "The leadership council conducted a ________ review of emerging global market trends.", "options": {"A": "strategic", "B": "strategy", "C": "strategically", "D": "strategist"}, "answer": "A", "analysis": "a strategic review（策略審查）。選 (A)。", "translation": "領導委員會對新興全球市場趨勢進行了策略審查。"}, {"id": 18, "target_seconds": 15, "question": "Revenue generated by the software ________ increased by twenty-eight percent.", "options": {"A": "division", "B": "divide", "C": "divided", "D": "divisible"}, "answer": "A", "analysis": "the software division（軟體部門）。選 (A)。", "translation": "軟體部門產生的營收增長了 28%。"}, {"id": 19, "target_seconds": 15, "question": "The author granted the publishing house ________ rights to distribute the manuscript worldwide.", "options": {"A": "sole", "B": "solely", "C": "solitary", "D": "solo"}, "answer": "A", "analysis": "sole rights（獨家發行權）。選 (A)。", "translation": "作者授予該出版社在全球發行該手稿的獨家權利。"}, {"id": 20, "target_seconds": 15, "question": "Facility managers updated the fire evacuation ________ following the annual drill.", "options": {"A": "protocol", "B": "protocols", "C": "protocollary", "D": "protocoling"}, "answer": "A", "analysis": "the fire evacuation protocol。選 (A)。", "translation": "設施經理在年度演習後更新了火災疏散協定。"}]}, "afternoon": {"quick_recall": [{"prompt": "to formulate a ________ [形容詞，策略性的] corporate plan.", "clue": "策略性的", "answer": "strategic"}, {"prompt": "the head of the marketing ________ [名詞，部門/事業部].", "clue": "事業部門", "answer": "division"}, {"prompt": "the ________ [形容詞，唯一的/獨家的] authorized distributor.", "clue": "唯一的獨家的", "answer": "sole"}, {"prompt": "to adhere strictly to safety ________ [名詞，協定規程/標準禮節].", "clue": "協定規程", "answer": "protocols"}, {"prompt": "to act as the ________ [形容詞，唯一] agent in the territory.", "clue": "唯一獨家", "answer": "sole"}, {"prompt": "a ________ [形容詞，策略性] partnership between firms.", "clue": "策略聯盟", "answer": "strategic"}], "spaced_traps": [{"id": 1, "target_seconds": 20, "question": "The pharmaceutical conglomerate formulated a ________ roadmap for international market entry.", "options": {"A": "strategic", "B": "strategy", "C": "strategically", "D": "strategize"}, "answer": "A", "trap_point": "a strategic roadmap 形容詞！", "analysis": "形容詞修飾名詞 roadmap，選 (A) strategic。", "translation": "該製藥集團制定了進軍國際市場的策略路線圖。"}, {"id": 2, "target_seconds": 20, "question": "The vice president oversaw the complete reorganization of the overseas marketing ________.", "options": {"A": "division", "B": "divide", "C": "divided", "D": "divisible"}, "answer": "A", "trap_point": "marketing division（行銷事業部）！", "analysis": "名詞位置，選 (A) division。", "translation": "副總裁主持了海外行銷事業部的全面重組。"}, {"id": 3, "target_seconds": 20, "question": "Apex Global holds the ________ worldwide patent distribution license for the technology.", "options": {"A": "sole", "B": "solely", "C": "soleness", "D": "solitary"}, "answer": "A", "trap_point": "the sole license（獨家許可證）！", "analysis": "形容詞修飾名詞 license，選 (A) sole。", "translation": "Apex 全球擁有該技術的全球獨家專利發行許可。"}, {"id": 4, "target_seconds": 20, "question": "All laboratory technicians must strictly observe hazardous waste disposal ________.", "options": {"A": "protocols", "B": "protocol", "C": "protocollary", "D": "protocoling"}, "answer": "A", "trap_point": "disposal protocols（處置協定複數）！", "analysis": "名詞複數作受詞，選 (A) protocols。", "translation": "所有實驗室技術人員必須嚴格遵守危險廢棄物處置協定。"}, {"id": 5, "target_seconds": 20, "question": "Executives emphasized the ________ importance of strengthening supply chain resilience.", "options": {"A": "strategic", "B": "strategy", "C": "strategically", "D": "strategist"}, "answer": "A", "trap_point": "strategic importance（策略重要性）！", "analysis": "形容詞修飾名詞 importance，選 (A) strategic。", "translation": "主管們強調了加強供應鏈韌性的策略重要性。"}, {"id": 6, "target_seconds": 20, "question": "The electronics company announced the closure of its regional display ________.", "options": {"A": "division", "B": "divide", "C": "dividing", "D": "divisible"}, "answer": "A", "trap_point": "display division（顯示器部門）！", "analysis": "名詞作受詞，選 (A) division。", "translation": "該電子公司宣布關閉其區域顯示器事業部。"}, {"id": 7, "target_seconds": 20, "question": "The agency was granted ________ broadcast privileges for the presidential inauguration.", "options": {"A": "sole", "B": "solely", "C": "soleness", "D": "solo"}, "answer": "A", "trap_point": "sole broadcast privileges（獨家轉播特權）！", "analysis": "形容詞修飾名詞 privileges，選 (A) sole。", "translation": "該通訊社獲得了總統就職典禮的獨家轉播特權。"}, {"id": 8, "target_seconds": 20, "question": "The hospital updated its emergency patient triage ________ following the audit.", "options": {"A": "protocol", "B": "protocols", "C": "protocollary", "D": "protocoling"}, "answer": "A", "trap_point": "triage protocol（分診協定單數）！", "analysis": "名詞修飾名詞，選 (A) protocol。", "translation": "醫院在審計後更新了急診患者檢傷分類協定。"}, {"id": 9, "target_seconds": 20, "question": "The two airlines established a ________ alliance to share international route codes.", "options": {"A": "strategic", "B": "strategy", "C": "strategically", "D": "strategize"}, "answer": "A", "trap_point": "a strategic alliance（策略聯盟）！", "analysis": "形容詞修飾名詞 alliance，選 (A) strategic。", "translation": "兩家航空公司建立了策略聯盟以共享國際航線代碼。"}, {"id": 10, "target_seconds": 20, "question": "The newly formed semiconductor ________ achieved profitability within six months.", "options": {"A": "division", "B": "divide", "C": "divided", "D": "divisible"}, "answer": "A", "trap_point": "semiconductor division（半導體部門）！", "analysis": "名詞作主詞，選 (A) division。", "translation": "新成立的半導體部門在六個月內實現了盈利。"}, {"id": 11, "target_seconds": 20, "question": "The contractor was named the ________ provider of concrete foundations for the bridge.", "options": {"A": "sole", "B": "solely", "C": "solitary", "D": "soleness"}, "answer": "A", "trap_point": "the sole provider（唯一提供商）！", "analysis": "形容詞修飾 provider，選 (A) sole。", "translation": "該承包商被指定為橋樑混凝土基礎的唯一供應商。"}, {"id": 12, "target_seconds": 20, "question": "Plant supervisors must document all deviations from approved chemical handling ________.", "options": {"A": "protocols", "B": "protocol", "C": "protocollary", "D": "protocoling"}, "answer": "A", "trap_point": "handling protocols（操作協定）！", "analysis": "複數名詞受詞，選 (A) protocols。", "translation": "工廠主管必須記錄所有偏離核准化學品操作協定的情況。"}, {"id": 13, "target_seconds": 20, "question": "The board hired external management advisors to guide their ________ planning session.", "options": {"A": "strategic", "B": "strategy", "C": "strategically", "D": "strategist"}, "answer": "A", "trap_point": "strategic planning session！", "analysis": "形容詞修飾名詞 session，選 (A) strategic。", "translation": "董事會聘請了外部管理顧問來指導他們的策略規劃會議。"}, {"id": 14, "target_seconds": 20, "question": "Revenues in the consumer software ________ rose sixteen percent year-over-year.", "options": {"A": "division", "B": "divide", "C": "divided", "D": "divisible"}, "answer": "A", "trap_point": "consumer software division！", "analysis": "名詞位置，選 (A) division。", "translation": "消費類軟體部門的營收同比增長了 16%。"}], "part7": {"passages": [{"text_type": "Corporate Operational Reorganization Memo (跨國企業組織重組與架構公告)", "title": "Zenith Global — Enterprise Division Realignment and Protocols", "content": "ORGANIZATIONAL REALIGNMENT CHARTER: ZG-REORG-2026-19\nISSUED BY: Executive Board & Strategic Governance Council, Zenith Global Inc.\nDATE: November 22, 2026\nDISTRIBUTION: All Continental Division Heads and Regional Controllers\n\n1. Centralization of Enterprise Cloud Infrastructure\nTo eliminate redundant server maintenance costs, enhance network security, and streamline multinational client data processing, Zenith Global is consolidating its distributed information systems. The centralized Enterprise Cloud Infrastructure and international disaster recovery vault will be permanently stationed in Frankfurt, Germany, operating under strict European data privacy and cybersecurity directives across all regional corporate hubs.\n\n2. Exclusive Contractual Authority\nIn order to leverage bulk corporate purchasing power and standardize software deployment, the Frankfurt Strategic Operations Council is exclusively granted the authority to negotiate multinational software enterprise licenses and enterprise hardware procurement frameworks on behalf of all global affiliates.\n\n*Mandatory Security Standard: All cross-border data transactions between regional business units and the Frankfurt server repository must strictly comply with the Protocol 84-A encryption standard. Any legacy API connections failing to utilize Protocol 84-A by December 1 will be automatically terminated by corporate firewall automated protocols.", "questions": [{"question": "Where will the centralized Enterprise Cloud division be located?", "options": {"A": "London", "B": "Frankfurt", "C": "New York", "D": "Singapore"}, "answer": "B", "radar": "🔍 防漏看雷達：地點定位 'consolidate into a single centralized division based in Frankfurt'！", "analysis": "內文明確載明集中化事業部設立於法蘭克福，故選 (B)。"}, {"question": "What authority is exclusively granted to the Frankfurt hub?", "options": {"A": "To manufacture hardware devices", "B": "To negotiate multinational software licensing contracts", "C": "To hire external culinary staff", "D": "To construct regional airport lounges"}, "answer": "B", "radar": "🔍 防漏看雷達：獨家權限 'serve as the sole entity authorized to negotiate multinational software licensing contracts'！", "analysis": "文中說明法蘭克福中心是唯一獲授權談判跨國軟體授權合約的實體，故選 (B)。"}, {"question": "What standard must all inter-division data migrations adhere to?", "options": {"A": "Protocol 84-A encryption standards", "B": "Standard ISO email attachments", "C": "Paper mail delivery via courier", "D": "Unencrypted public FTP servers"}, "answer": "A", "radar": "🔍 防漏看雷達：星號協定條款 '*Security Protocol Clause: ... must adhere to Protocol 84-A encryption standards'！", "analysis": "星號條款特別註明資料遷移必須遵循 84-A 協定加密標準，故選 (A)。"}]}, {"text_type": "Commercial Supply Agreement (航空航天獨家供應合約條款)", "title": "Apex Aerospace — Exclusive Sole-Source Supply Contract & Performance Terms", "content": "COMMERCIAL PROCUREMENT AGREEMENT: AA-SUPPLY-2026-44\nBUYER: Apex Aerospace Manufacturing Corporation (Seattle, WA)\nSELLER: Crestview Metallurgy & Advanced Materials Group\nCONTRACT DATES: November 22, 2026 — November 21, 2029\n\nClause 2. Sole-Source Supplier Appointment:\nApex Aerospace officially appoints Crestview Metallurgy as the sole certified supplier of titanium alloy brackets and structural engine mounts for its next-generation commercial passenger aircraft program. No third-party metal fabrication contracts will be solicited or awarded during the active three-year term of this commercial agreement, establishing an exclusive aerospace parts manufacturing partnership.\n\nClause 5. Strategic Inventory Reserves & Warehousing:\nTo guarantee uninterrupted assembly plant workflow and mitigate supply chain volatility, Crestview Metallurgy must maintain its strategic safety reserve of finished titanium fasteners and forged brackets at its Seattle warehouse facility, positioned within twenty miles of the primary aircraft assembly center.\n\n*Secondary Sourcing Escape Clause: Apex Aerospace expressly reserves the unilateral right to engage secondary suppliers if Crestview fails to fulfill purchase orders within fourteen days of order receipt. In such event, Crestview will be held liable for differential procurement costs and expedited airfreight surcharges.", "questions": [{"question": "In what capacity is Crestview Metallurgy designated by Apex Aerospace?", "options": {"A": "As a temporary marketing advisor", "B": "As the sole certified supplier of titanium airframe forgings", "C": "As an independent freight forwarder", "D": "As an external accounting auditor"}, "answer": "B", "radar": "🔍 防漏看雷達：合作身分 'designates Crestview Metallurgy as the sole certified supplier'！", "analysis": "首段指明被指定為唯一的鈦金屬鍛件認證供應商，故選 (B)。"}, {"question": "Where must Crestview maintain its strategic buffer inventory?", "options": {"A": "Seattle warehouse", "B": "Frankfurt airport", "C": "Tokyo dockyards", "D": "Chicago rail yard"}, "answer": "A", "radar": "🔍 防漏看雷達：庫存地點 'maintain strategic buffer inventories ... at its Seattle warehouse'！", "analysis": "文中明確指出在西雅圖倉庫儲備至少 500 公噸的戰略緩衝庫存，故選 (A)。"}, {"question": "Under what condition may Apex Aerospace engage secondary suppliers?", "options": {"A": "If raw metal prices decrease by 10%", "B": "If Crestview fails to fulfill deliveries within five business days of order receipt", "C": "Whenever corporate executive board members visit Seattle", "D": "During winter weather closures only"}, "answer": "B", "radar": "🔍 防漏看雷達：星號條件條款 '*Contractual Contingency Clause: ... fails to fulfill delivery schedules within five business days'！", "analysis": "星號但書說明若 5 個工作日內未能交貨，Apex 有權尋求替代供應商，故選 (B)。"}]}]}}}, "20": {"day": 20, "date": "11/23", "phase": 3, "phase_name": "考前全真極速模擬與弱點獵殺", "topic": "Part 6 插入句前後脈絡 ｜ 有形資產、門檻與承租人", "morning": {"chunks": [{"chunk": "tangible assets", "meaning": "有形資產", "scenario": "Machinery and land represent tangible assets.", "paraphrase": "tangible = physical = concrete = corporeal", "alert": "反義詞為 intangible assets（無形資產）！"}, {"chunk": "cross the threshold", "meaning": "跨過門檻/超過界限", "scenario": "Revenues must cross the threshold to qualify for subsidies.", "paraphrase": "threshold = benchmark = boundary = limit", "alert": "常考 performance threshold, credit threshold！"}, {"chunk": "commercial tenant", "meaning": "商用承租人/店面租戶", "scenario": "The commercial tenant executed a five-year lease.", "paraphrase": "tenant = lessee = occupant = renter", "alert": "名詞形式為 tenancy！"}, {"chunk": "on the premises", "meaning": "在營業場所內/在處所內", "scenario": "Alcohol is prohibited on the premises.", "paraphrase": "premises = property = facility = grounds", "alert": "premises 恆用複數形！"}, {"chunk": "tangible evidence", "meaning": "具體有形的證據", "scenario": "Investigators searched for tangible evidence of compliance.", "paraphrase": "tangible evidence = concrete proof", "alert": "高頻形容詞搭配！"}, {"chunk": "vacate the premises", "meaning": "騰空遷出營業處所", "scenario": "The tenant must vacate the premises before the month ends.", "paraphrase": "vacate = leave = clear out", "alert": "重要商務法務片語！"}, {"chunk": "statutory threshold", "meaning": "法定門檻", "scenario": "Firms exceeding the statutory threshold must submit audits.", "paraphrase": "statutory threshold = legal limit", "alert": "法規高頻語塊！"}], "visual_anchor": {"title": "Part 6 插入句 (Sentence Insertion) 脈絡代名詞錨點", "rule_1": "👀 看到前句有具體名詞 [such investments / this tenant] ➔ 插入句必須含有承接代名詞！", "rule_2": "👀 注意固定處所介系詞搭配：恆用「on the premises」，不可用 in！", "golden_rule": "⚡ 教練金句：有形資產選 tangible，處所介系詞鎖定 on the premises！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "The technological startup struggled to show ________ evidence of customer acquisition.", "options": {"A": "tangible", "B": "tangibly", "C": "tangibleness", "D": "tangibles"}, "answer": "A", "analysis": "形容詞修飾名詞 evidence。tangible evidence 表『具體有形的證據』。選 (A)。", "translation": "該科技新創公司難以展示客戶獲取的具體有形證據。"}, {"id": 2, "target_seconds": 15, "question": "Sales representatives must cross the annual commission ________ to qualify for the president's bonus.", "options": {"A": "threshold", "B": "thresh", "C": "thresholds", "D": "thresholding"}, "answer": "A", "analysis": "名詞位置：commission threshold 表『佣金門檻』。選 (A)。", "translation": "業務代表必須跨過年度佣金門檻才能獲得總裁獎金的資格。"}, {"id": 3, "target_seconds": 15, "question": "The commercial lease explicitly prohibits the ________ from subletting office suites without consent.", "options": {"A": "tenant", "B": "tenancy", "C": "tenanted", "D": "tenants"}, "answer": "A", "analysis": "名詞單數受詞 the tenant（承租人）。選 (A)。", "translation": "商業租約明確禁止承租人在未經同意的情況下轉租辦公套房。"}, {"id": 4, "target_seconds": 15, "question": "Smoking is strictly prohibited anywhere on the corporate ________.", "options": {"A": "premises", "B": "premise", "C": "premising", "D": "premised"}, "answer": "A", "analysis": "on the premises 表『在營業場所/處所內』，名詞恆用複數形。選 (A)。", "translation": "在公司營業處所內的任何地方均嚴格禁止吸菸。"}, {"id": 5, "target_seconds": 15, "question": "Investing in automated warehouse robotics yielded ________ gains in delivery efficiency.", "options": {"A": "tangible", "B": "tangibly", "C": "tangibleness", "D": "tangibles"}, "answer": "A", "analysis": "形容詞修飾名詞 gains。tangible gains 表『實質/可感受到的收益』。選 (A)。", "translation": "對自動化倉庫機器人的投資在配送效率方面產生了顯著實質的收穫。"}, {"id": 6, "target_seconds": 15, "question": "The loan application was approved once the business reached the minimum credit ________.", "options": {"A": "threshold", "B": "thresh", "C": "thresholding", "D": "thresholds"}, "answer": "A", "analysis": "the minimum credit threshold（最低信用門檻）。選 (A)。", "translation": "一旦該企業達到最低信用門檻，貸款申請便獲得批准。"}, {"id": 7, "target_seconds": 15, "question": "Prospective ________ must provide three months of audited bank statements.", "options": {"A": "tenants", "B": "tenant", "C": "tenancy", "D": "tenanted"}, "answer": "A", "analysis": "形容詞 Prospective 後接名詞複數 (A) tenants（準承租人）。", "translation": "有意承租者必須提供三個月經審計的銀行對帳單。"}, {"id": 8, "target_seconds": 15, "question": "Security guards patrol the factory ________ twenty-four hours a day.", "options": {"A": "premises", "B": "premise", "C": "premised", "D": "premising"}, "answer": "A", "analysis": "名詞複數：the factory premises（工廠處所/廠區）。選 (A)。", "translation": "警衛全天 24 小時在廠區內巡邏。"}, {"id": 9, "target_seconds": 15, "question": "The new marketing campaign produced no ________ impact on store foot traffic.", "options": {"A": "tangible", "B": "tangibly", "C": "tangibleness", "D": "tangibles"}, "answer": "A", "analysis": "形容詞修飾 impact。tangible impact（實質影響）。選 (A)。", "translation": "新的行銷活動對店面客流量沒有產生任何實質影響。"}, {"id": 10, "target_seconds": 15, "question": "Applicants falling below the performance ________ will receive additional remedial coaching.", "options": {"A": "threshold", "B": "thresh", "C": "thresholds", "D": "thresholding"}, "answer": "A", "analysis": "the performance threshold（績效門檻）。選 (A)。", "translation": "低於績效門檻的申請人將接受額外的輔導補習。"}, {"id": 11, "target_seconds": 15, "question": "Under the rental contract, each ________ is responsible for interior suite maintenance.", "options": {"A": "tenant", "B": "tenants", "C": "tenancy", "D": "tenanted"}, "answer": "A", "analysis": "each 後接單數名詞 (A) tenant。", "translation": "根據租賃合約，每位承租人均須負責內部套房的維護。"}, {"id": 12, "target_seconds": 15, "question": "Unauthorized vehicles parked on the office ________ will be towed at the owner's expense.", "options": {"A": "premises", "B": "premise", "C": "premised", "D": "premising"}, "answer": "A", "analysis": "on the office premises。選 (A)。", "translation": "停放在辦公處所內的未授權車輛將由車主自費拖離。"}, {"id": 13, "target_seconds": 15, "question": "Physical machinery and industrial real estate represent ________ corporate assets.", "options": {"A": "tangible", "B": "tangibly", "C": "tangibleness", "D": "tangibles"}, "answer": "A", "analysis": "tangible assets（有形資產）。選 (A)。", "translation": "實體機械和工業房地產代表著企業的有形資產。"}, {"id": 14, "target_seconds": 15, "question": "The regulatory agency lowered the statutory reporting ________ for small businesses.", "options": {"A": "threshold", "B": "thresh", "C": "thresholds", "D": "thresholding"}, "answer": "A", "analysis": "the reporting threshold（通報門檻）。選 (A)。", "translation": "監管機構降低了小型企業的法定申報門檻。"}, {"id": 15, "target_seconds": 15, "question": "Long-term ________ are eligible for parking stall rent reductions.", "options": {"A": "tenants", "B": "tenant", "C": "tenancy", "D": "tenanted"}, "answer": "A", "analysis": "名詞複數主詞：Long-term tenants。選 (A)。", "translation": "長期租戶有資格享受停車位租金減免。"}, {"id": 16, "target_seconds": 15, "question": "Access to the server room is restricted to personnel on the hospital ________.", "options": {"A": "premises", "B": "premise", "C": "premised", "D": "premising"}, "answer": "A", "analysis": "on the hospital premises。選 (A)。", "translation": "進出伺服器室僅限於醫院場所內的人員。"}, {"id": 17, "target_seconds": 15, "question": "The restructuring initiative delivered ________ improvements in quarterly profit margins.", "options": {"A": "tangible", "B": "tangibly", "C": "tangibleness", "D": "tangibles"}, "answer": "A", "analysis": "tangible improvements（顯著實質的改善）。選 (A)。", "translation": "重組倡議在季度利潤率方面帶來了切實顯著的改善。"}, {"id": 18, "target_seconds": 15, "question": "Subscribers will receive a free gift once their cumulative purchases exceed the $200 ________.", "options": {"A": "threshold", "B": "thresh", "C": "thresholds", "D": "thresholding"}, "answer": "A", "analysis": "the $200 threshold（200 美元門檻）。選 (A)。", "translation": "一旦訂閱者的累計消費超過 200 美元門檻，即將獲得免費贈品。"}, {"id": 19, "target_seconds": 15, "question": "A commercial ________ must notify building management prior to major suite alterations.", "options": {"A": "tenant", "B": "tenants", "C": "tenancy", "D": "tenanted"}, "answer": "A", "analysis": "冠詞 A 後接單數名詞 (A) tenant。", "translation": "商業承租人在進行重大套房改建之前必須通知大樓管理處。"}, {"id": 20, "target_seconds": 15, "question": "Visitors entering the research ________ must sign non-disclosure declarations.", "options": {"A": "premises", "B": "premise", "C": "premised", "D": "premising"}, "answer": "A", "analysis": "the research premises（研發處所）。選 (A)。", "translation": "進入研發處所的訪客必須簽署保密協議。"}]}, "afternoon": {"quick_recall": [{"prompt": "to provide ________ [形容詞，有形的/具體的] evidence of growth.", "clue": "有形具體的", "answer": "tangible"}, {"prompt": "to cross the performance ________ [名詞，門檻/閥值].", "clue": "門檻", "answer": "threshold"}, {"prompt": "The commercial ________ [名詞，承租人/房客] signed the lease.", "clue": "承租人租戶", "answer": "tenant"}, {"prompt": "Smoking is banned on company ________ [名詞恆複數，處所/營業場所].", "clue": "營業處所", "answer": "premises"}, {"prompt": "Machinery and inventory are ________ [形容詞，有形的] assets.", "clue": "有形資產", "answer": "tangible"}, {"prompt": "to exceed the spending ________ [名詞，門檻界限].", "clue": "門檻", "answer": "threshold"}], "spaced_traps": [{"id": 1, "target_seconds": 20, "question": "The executive board required ________ financial proof before approving the merger budget.", "options": {"A": "tangible", "B": "tangibly", "C": "tangibleness", "D": "tangibles"}, "answer": "A", "trap_point": "tangible financial proof 形容詞！", "analysis": "形容詞修飾名詞 proof，選 (A) tangible（具體的）。", "translation": "執行董事會在批准合併預算之前要求提供具體的財務證明。"}, {"id": 2, "target_seconds": 20, "question": "The municipal tax credit applies only after annual capital investments exceed the $1M ________.", "options": {"A": "threshold", "B": "thresh", "C": "thresholds", "D": "thresholding"}, "answer": "A", "trap_point": "the $1M threshold（門檻名詞）！", "analysis": "冠詞後接名詞，選 (A) threshold。", "translation": "只有在年度資本投資超過 100 萬美元門檻後，市政稅收抵免才適用。"}, {"id": 3, "target_seconds": 20, "question": "The building superintendent sent a formal warning to the ________ in Suite 402.", "options": {"A": "tenant", "B": "tenants", "C": "tenancy", "D": "tenanted"}, "answer": "A", "trap_point": "the tenant in Suite 402 單數！", "analysis": "介系詞短語修飾單數名詞 (A) tenant。", "translation": "大樓管理員向 402 室的承租人發出了正式警告。"}, {"id": 4, "target_seconds": 20, "question": "Alcoholic beverages are not permitted anywhere on the factory ________.", "options": {"A": "premises", "B": "premise", "C": "premised", "D": "premising"}, "answer": "A", "trap_point": "on the factory premises 名詞恆複數！", "analysis": "處所 premises 恆用複數，選 (A)。", "translation": "工廠廠區內的任何地方均不允許攜帶酒精飲料。"}, {"id": 5, "target_seconds": 20, "question": "The joint research venture demonstrated ________ reductions in battery charging duration.", "options": {"A": "tangible", "B": "tangibly", "C": "tangibleness", "D": "tangibles"}, "answer": "A", "trap_point": "tangible reductions（顯著降低）形容詞！", "analysis": "形容詞修飾名詞 reductions，選 (A) tangible。", "translation": "該聯合研發項目展示了電池充電時間的顯著縮短。"}, {"id": 6, "target_seconds": 20, "question": "The customs officer verified that the shipment value remained below the tariff ________.", "options": {"A": "threshold", "B": "thresh", "C": "thresholds", "D": "thresholding"}, "answer": "A", "trap_point": "below the tariff threshold！", "analysis": "介系詞與冠詞後接名詞 (A) threshold。", "translation": "海關官員核實該貨物價值低於關稅起徵門檻。"}, {"id": 7, "target_seconds": 20, "question": "All prospective commercial ________ must undergo third-party credit background validation.", "options": {"A": "tenants", "B": "tenant", "C": "tenancy", "D": "tenanted"}, "answer": "A", "trap_point": "prospective commercial tenants 複數！", "analysis": "名詞複數主詞，選 (A) tenants。", "translation": "所有潛在的商業承租人均必須接受第三方信用背景審驗。"}, {"id": 8, "target_seconds": 20, "question": "Security personnel escort unbadged visitors across the warehouse ________ at all times.", "options": {"A": "premises", "B": "premise", "C": "premised", "D": "premising"}, "answer": "A", "trap_point": "the warehouse premises！", "analysis": "名詞複數選 (A) premises。", "translation": "安保人員始終陪同無證訪客穿過倉庫廠區。"}, {"id": 9, "target_seconds": 20, "question": "Corporate wellness initiatives produced ________ declines in employee sick leave.", "options": {"A": "tangible", "B": "tangibly", "C": "tangibleness", "D": "tangibles"}, "answer": "A", "trap_point": "tangible declines 形容詞！", "analysis": "選形容詞 (A) tangible。", "translation": "企業健康倡議帶來了員工病假的切實減少。"}, {"id": 10, "target_seconds": 20, "question": "Sales volume must reach the quarterly ________ to unlock wholesale volume discounts.", "options": {"A": "threshold", "B": "thresh", "C": "thresholds", "D": "thresholding"}, "answer": "A", "trap_point": "reach the quarterly threshold！", "analysis": "動詞 reach 後接名詞 (A) threshold。", "translation": "銷售量必須達到季度門檻方可解鎖批發大額折扣。"}, {"id": 11, "target_seconds": 20, "question": "A residential ________ may terminate the contract early with two months of penalty payments.", "options": {"A": "tenant", "B": "tenants", "C": "tenancy", "D": "tenanted"}, "answer": "A", "trap_point": "A residential tenant 單數名詞！", "analysis": "冠詞 A 後接單數名詞 (A) tenant。", "translation": "住宅承租人可透過繳納兩個月違約金提前終止合約。"}, {"id": 12, "target_seconds": 20, "question": "Unescorted contractors found on the corporate ________ will be asked to leave.", "options": {"A": "premises", "B": "premise", "C": "premised", "D": "premising"}, "answer": "A", "trap_point": "on the corporate premises！", "analysis": "固定片語選 (A) premises。", "translation": "在公司場所內發現的無人陪同承包商將被要求離開。"}, {"id": 13, "target_seconds": 20, "question": "Physical equipment inventory is classified under ________ fixed assets.", "options": {"A": "tangible", "B": "tangibly", "C": "tangibleness", "D": "tangibles"}, "answer": "A", "trap_point": "tangible fixed assets！", "analysis": "形容詞修飾名詞，選 (A) tangible（有形的）。", "translation": "實體設備庫存歸類於有形固定資產。"}, {"id": 14, "target_seconds": 20, "question": "Retail merchants whose transactions cross the revenue ________ must file state quarterly returns.", "options": {"A": "threshold", "B": "thresh", "C": "thresholds", "D": "thresholding"}, "answer": "A", "trap_point": "cross the revenue threshold！", "analysis": "動詞 cross 後接名詞 (A) threshold。", "translation": "交易額超過營收門檻的零售商必須申報州季度申報表。"}], "part7": {"passages": [{"text_type": "Commercial Lease Rules & Regulations (商業大樓租賃管理公約)", "title": "Parkview Commercial Plaza — Tenant Obligations & Energy Rebate Rules", "content": "TENANT LEASE COVENANT: PKV-RULES-2026-20\nPROPERTY: Parkview Commercial Plaza & Executive Office Suites\nISSUED BY: Property Management Directorate & Commercial Leasing Bureau\nDATE: November 23, 2026\n\nSection 4. Structural Alterations & Interior Architectural Modifications:\nCommercial tenants occupying office suites within Parkview Plaza must preserve architectural integrity and building structural balance. Lessees are prohibited from executing structural alterations, knocking down load-bearing partitions, or modifying plumbing conduits without obtaining prior written consent from Management and submitting certified structural engineering blueprints for formal review.\n\nSection 8. Sustainability Incentive & Monthly Energy Rebate:\nIn support of our corporate green building certification and municipal energy conservation goals, tenants whose monthly utility consumption remains below the monthly energy efficiency threshold of 2,500 kWh will qualify for a 10% rebate on their standard common-area maintenance fees for that billing cycle.\n\n*After-Hours Visitor Security Protocol: To safeguard commercial assets and prevent unauthorized access, the plaza implements strict evening access controls. All visitors entering the building after 7:00 PM must present photo identification at the concierge desk and be signed in by an authorized tenant representative. Unverified individuals will be denied entry.", "questions": [{"question": "What requirement must be met before executing structural alterations?", "options": {"A": "Paying a cash deposit", "B": "Obtaining prior written consent from Management", "C": "Publishing a local newspaper notice", "D": "Installing additional smoke alarms"}, "answer": "B", "radar": "🔍 防漏看雷達：改建前提 'without prior written consent from Parkview Plaza Management'！", "analysis": "文中明確規定未經管理處事先書面同意不得改建，故選 (B)。"}, {"question": "What is the monthly energy efficiency threshold to qualify for a rebate?", "options": {"A": "1,000 kWh", "B": "2,500 kWh", "C": "5,000 kWh", "D": "10,000 kWh"}, "answer": "B", "radar": "🔍 防漏看雷達：數字門檻 'below the 2,500 kWh efficiency threshold'！", "analysis": "內文規定低於 2,500 kWh 門檻可享 5% 回饋，故選 (B)。"}, {"question": "What must visitors do when accessing the premises after 7:00 PM?", "options": {"A": "Park on Level P3 only", "B": "Present photo identification at the concierge", "C": "Wear high-visibility reflective vests", "D": "Sign an annual lease agreement"}, "answer": "B", "radar": "🔍 防漏看雷達：星號但書條款 '*Security Directive: ... after 7:00 PM must present photo identification at the concierge'！", "analysis": "星號條款說明晚間 7 點後訪客必須在接待處出示附照片的身份證件，故選 (B)。"}]}, {"text_type": "Corporate Valuation & Asset Audit Report (企業資產評估與資本審計報告)", "title": "Pinnacle Capital — Tangible Asset Review & Audit Findings", "content": "FINANCIAL AUDIT DISCLOSURE: PIN-VAL-2026-80\nISSUING AUDITOR: Pinnacle Capital Valuation & Institutional Advisory Services\nAUDIT TARGET: Crestline Manufacturing Corporation\nDATE: November 23, 2026\nASSESSMENT PERIOD: Fiscal Year 2026 Comprehensive Review\n\n1. Appraised Tangible Valuation\nFollowing an exhaustive independent forensic audit of physical fabrication machinery, automated assembly plants, robotic tooling systems, and proprietary industrial real estate, Pinnacle Capital appraised Crestline Manufacturing's total net asset value at $84 million. This appraisal reflects a 12% expansion driven by capital investments in computerized machining lines and state-of-the-art warehouses across their domestic industrial footprint.\n\n2. Statutory Solvency Covenants\nUnder banking syndicate agreements and corporate debt covenants, Crestline Manufacturing is contractually required to maintain a statutory debt-to-equity threshold below 1.50 across all reporting quarters. Current debt metrics stand comfortably at 1.28, ensuring compliance with Tier 1 commercial credit terms.\n\n*Asset Inspection Frequency: To preserve corporate valuation validity and satisfy international accounting standards, physical asset inspections are conducted on corporate premises biennially (every two years) by certified chartered appraisers. The next comprehensive physical inventory inspection is slated for October 2028, with preliminary audit schedules released in June.", "questions": [{"question": "What total net asset value was appraised for Crestline Manufacturing?", "options": {"A": "$15 million", "B": "$50 million", "C": "$84 million", "D": "$150 million"}, "answer": "C", "radar": "🔍 防漏看雷達：資產估值定位 'represent $84 million in net asset value'！", "analysis": "首段指明有形資產估值為 8,400 萬美元，故選 (C)。"}, {"question": "What statutory debt-to-equity threshold must Crestline maintain?", "options": {"A": "Below 1.00", "B": "Below 1.50", "C": "Below 2.00", "D": "Below 3.50"}, "answer": "B", "radar": "🔍 防漏看雷達：財務指標門檻 'below the 1.50 statutory threshold'！", "analysis": "文中指明負債權益比須低於 1.50 門檻，故選 (B)。"}, {"question": "How often are physical asset inspections conducted on corporate premises?", "options": {"A": "Every six months", "B": "Annually", "C": "Biennially (every two years)", "D": "Every five years"}, "answer": "C", "radar": "🔍 防漏看雷達：星號檢查頻率 '*Audit Footnote: ... scheduled biennially unless otherwise required'！", "analysis": "星號小字載明每兩年（biennially）進行一次實體資產盤點檢查，故選 (C)。"}]}]}}}, "21": {"day": 21, "date": "11/24", "phase": 3, "phase_name": "考前全真極速模擬與弱點獵殺", "topic": "Part 7 雙篇交叉比對 ｜ 騰空撤離、有效期限與供應商", "morning": {"chunks": [{"chunk": "vacate the premises", "meaning": "騰空營業處所/遷離物業", "scenario": "The tenant promised to vacate the premises by Friday.", "paraphrase": "vacate = surrender = leave = clear out", "alert": "名詞形式為 vacation（假期）或 vacancy（空缺）！"}, {"chunk": "prior to expiration", "meaning": "在到期之前", "scenario": "Renew your pass prior to expiration to avoid lapses.", "paraphrase": "expiration = termination = end of term", "alert": "動詞形式為 expire！"}, {"chunk": "certified vendor", "meaning": "認證供應商/合作廠商", "scenario": "We order replacement valves from a certified vendor.", "paraphrase": "vendor = supplier = contractor = merchant", "alert": "動詞為 vend（販售）！"}, {"chunk": "issue an invoice", "meaning": "開立發票/請款單", "scenario": "The billing clerk will issue an invoice upon dispatch.", "paraphrase": "invoice = bill = payment statement", "alert": "動詞形式亦為 invoice！"}, {"chunk": "expiration date", "meaning": "有效期限/截止日", "scenario": "Check the expiration date stamped on the container.", "paraphrase": "expiration date = expiry date = validity period", "alert": "常見商務複合名詞！"}, {"chunk": "approved vendor list", "meaning": "合格供應商名單", "scenario": "Purchases must be made from the approved vendor list.", "paraphrase": "approved vendor = qualified contractor", "alert": "採購管理常見片語！"}, {"chunk": "cross-reference the documents", "meaning": "交叉比對文件", "scenario": "Always cross-reference the documents to detect discrepancies.", "paraphrase": "cross-reference = cross-check = compare", "alert": "Part 7 雙篇三篇核心技巧！"}], "visual_anchor": {"title": "Part 7 雙篇閱讀 (Double Passage) 交叉對照錨點", "rule_1": "👀 看到題幹問「Why did ... hire / What requirement ...」➔ 100% 須跨篇比對（篇一規定 + 篇二帳單/回信）！", "rule_2": "👀 注意到期與騰空詞彙：動詞「vacate」對應 leave/empty；名詞「expiration」對應 deadline！", "golden_rule": "⚡ 教練金句：雙篇題必有一題考交叉資訊，鎖定金額、日期與星號條款對照！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "Tenants are required to ________ the rented premises by midnight on the final day of the lease.", "options": {"A": "vacate", "B": "vacation", "C": "vacating", "D": "vacated"}, "answer": "A", "analysis": "required to + 原形動詞 vacate（騰空遷離）。選 (A)。", "translation": "租戶必須在租約最後一天的午夜前騰空所租處所。"}, {"id": 2, "target_seconds": 15, "question": "Subscribers will receive a renewal reminder thirty days prior to membership ________.", "options": {"A": "expiration", "B": "expire", "C": "expired", "D": "expiring"}, "answer": "A", "analysis": "介系詞 to 後接名詞 expiration（到期/屆滿）。選 (A)。", "translation": "訂閱者將在會員資格到期前 30 天收到續會提醒。"}, {"id": 3, "target_seconds": 15, "question": "The procurement team evaluated proposals from five certified software ________.", "options": {"A": "vendors", "B": "vendor", "C": "vending", "D": "vended"}, "answer": "A", "analysis": "數詞 five certified 後接名詞複數 vendors（供應商/廠商）。選 (A)。", "translation": "採購團隊評估了五家認證軟體供應商的提案。"}, {"id": 4, "target_seconds": 15, "question": "The accounts department issued a revised ________ reflecting the volume discount.", "options": {"A": "invoice", "B": "invoiced", "C": "invoicing", "D": "invoices"}, "answer": "A", "analysis": "冠詞 a revised 後接單數名詞 invoice（發票/請款單）。選 (A)。", "translation": "會計部門開立了反映批發折扣的修改後發票。"}, {"id": 5, "target_seconds": 15, "question": "Failure to ________ the warehouse by the agreed date will incur daily penalty fees.", "options": {"A": "vacate", "B": "vacation", "C": "vacated", "D": "vacates"}, "answer": "A", "analysis": "Failure to + 原形動詞 vacate。選 (A)。", "translation": "未能按約定日期騰空倉庫將招致每日罰金。"}, {"id": 6, "target_seconds": 15, "question": "Drivers must renew their commercial transport permits before the stated ________ date.", "options": {"A": "expiration", "B": "expire", "C": "expired", "D": "expires"}, "answer": "A", "analysis": "名詞修飾名詞：expiration date（有效期限/到期日）。選 (A)。", "translation": "司機必須在規定的到期日之前展延其商用運輸許可證。"}, {"id": 7, "target_seconds": 15, "question": "Apex Supplies has been the primary office equipment ________ for over a decade.", "options": {"A": "vendor", "B": "vendors", "C": "vending", "D": "vended"}, "answer": "A", "analysis": "the primary office equipment vendor。選單數名詞 (A)。", "translation": "Apex Supplies 十多年來一直是主要辦公設備供應商。"}, {"id": 8, "target_seconds": 15, "question": "Please remit payment according to the bank details listed on the attached ________.", "options": {"A": "invoice", "B": "invoices", "C": "invoicing", "D": "invoiced"}, "answer": "A", "analysis": "the attached + 單數名詞 invoice。選 (A)。", "translation": "請按照所附發票上列出的銀行資訊匯款。"}, {"id": 9, "target_seconds": 15, "question": "The commercial tenant promised to ________ the building before interior remodeling starts.", "options": {"A": "vacate", "B": "vacation", "C": "vacating", "D": "vacates"}, "answer": "A", "analysis": "promised to + 原形動詞 vacate。選 (A)。", "translation": "商業承租人承諾在內部裝修工程開始前騰空大樓。"}, {"id": 10, "target_seconds": 15, "question": "Software licenses will cease to function automatically upon ________.", "options": {"A": "expiration", "B": "expire", "C": "expired", "D": "expiring"}, "answer": "A", "analysis": "介系詞 upon 後接名詞 expiration。選 (A)。", "translation": "軟體授權在到期時將自動停止運作。"}, {"id": 11, "target_seconds": 15, "question": "Management will select an approved catering ________ for the annual holiday dinner.", "options": {"A": "vendor", "B": "vendors", "C": "vending", "D": "vended"}, "answer": "A", "analysis": "an approved catering vendor。選 (A)。", "translation": "管理層將為年度節慶晚宴選擇一家認可的餐飲外包商。"}, {"id": 12, "target_seconds": 15, "question": "Discrepancies on the shipping ________ must be reported to accounting within five days.", "options": {"A": "invoice", "B": "invoices", "C": "invoiced", "D": "invoicing"}, "answer": "A", "analysis": "the shipping invoice。選 (A)。", "translation": "出貨發票上的差異必須在五天內通報會計部。"}, {"id": 13, "target_seconds": 15, "question": "Employees must ________ all private lockers before the renovation crew arrives.", "options": {"A": "vacate", "B": "vacation", "C": "vacating", "D": "vacated"}, "answer": "A", "analysis": "助動詞 must + 原形動詞 vacate。選 (A)。", "translation": "員工必須在翻修工人抵達前騰空所有私人儲物櫃。"}, {"id": 14, "target_seconds": 15, "question": "Cardholders will be notified prior to the ________ of their complimentary benefits.", "options": {"A": "expiration", "B": "expire", "C": "expired", "D": "expires"}, "answer": "A", "analysis": "the expiration of... 選名詞 (A)。", "translation": "持卡人在其免費權益到期前將收到通知。"}, {"id": 15, "target_seconds": 15, "question": "The municipality partnered with a local solar technology ________ for public lighting.", "options": {"A": "vendor", "B": "vendors", "C": "vending", "D": "vended"}, "answer": "A", "analysis": "a local solar technology vendor。選 (A)。", "translation": "市政府與當地一家太陽能科技供應商合作進行公共照明。"}, {"id": 16, "target_seconds": 15, "question": "The billing specialist sent an electronic ________ to the client yesterday morning.", "options": {"A": "invoice", "B": "invoices", "C": "invoiced", "D": "invoicing"}, "answer": "A", "analysis": "an electronic invoice。選 (A)。", "translation": "帳單專員昨日上午向客戶發送了電子發票。"}, {"id": 17, "target_seconds": 15, "question": "The court ordered the company to ________ the disputed industrial premises immediately.", "options": {"A": "vacate", "B": "vacation", "C": "vacated", "D": "vacating"}, "answer": "A", "analysis": "ordered the company to + 原形動詞 vacate。選 (A)。", "translation": "法院命令該公司立即騰空有爭議的工業處所。"}, {"id": 18, "target_seconds": 15, "question": "Coupons are non-transferable and become invalid upon contract ________.", "options": {"A": "expiration", "B": "expire", "C": "expired", "D": "expiring"}, "answer": "A", "analysis": "upon contract expiration。選名詞 (A)。", "translation": "優惠券不可轉讓，並在合約到期時失效。"}, {"id": 19, "target_seconds": 15, "question": "A certified cloud service ________ must guarantee 99.9% uptime reliability.", "options": {"A": "vendor", "B": "vendors", "C": "vending", "D": "vended"}, "answer": "A", "analysis": "A certified cloud service vendor。選 (A)。", "translation": "經認證的雲端服務供應商必須保證 99.9% 的正常運作可靠度。"}, {"id": 20, "target_seconds": 15, "question": "Payment terms state that each ________ is due thirty days following receipt.", "options": {"A": "invoice", "B": "invoices", "C": "invoicing", "D": "invoiced"}, "answer": "A", "analysis": "each 後接單數名詞 invoice。選 (A)。", "translation": "付款條款規定每張發票在收到後 30 天內到期應付。"}]}, "afternoon": {"quick_recall": [{"prompt": "to ________ [動詞，騰空/遷出] the leased property.", "clue": "騰空遷離", "answer": "vacate"}, {"prompt": "prior to the ________ [名詞，到期/屆滿] of the contract.", "clue": "到期日", "answer": "expiration"}, {"prompt": "to contract an approved parts ________ [名詞，供應商/廠商].", "clue": "供應商廠商", "answer": "vendor"}, {"prompt": "to remit payment upon receipt of the ________ [名詞，發票/請款單].", "clue": "發票請款單", "answer": "invoice"}, {"prompt": "the ________ [名詞，有效期限] date on the coupon.", "clue": "到期日 (expiration ...)", "answer": "expiration"}, {"prompt": "Failure to ________ [動詞，騰空] the room will incur fees.", "clue": "騰空清空", "answer": "vacate"}], "spaced_traps": [{"id": 1, "target_seconds": 20, "question": "The commercial lease mandates that tenants ________ the office suite within forty-eight hours.", "options": {"A": "vacate", "B": "vacation", "C": "vacating", "D": "vacated"}, "answer": "A", "trap_point": "mandates that tenants vacate（原形動詞）！", "analysis": "虛擬語氣省略 should，選原形動詞 (A) vacate。", "translation": "商業租約規定承租人必須在 48 小時內騰空辦公套房。"}, {"id": 2, "target_seconds": 20, "question": "Subscribers must redeem reward vouchers prior to certificate ________.", "options": {"A": "expiration", "B": "expire", "C": "expired", "D": "expiring"}, "answer": "A", "trap_point": "certificate expiration（憑證到期）名詞！", "analysis": "名詞修飾名詞，選 (A) expiration。", "translation": "訂閱者必須在憑證到期之前兌換獎勵券。"}, {"id": 3, "target_seconds": 20, "question": "The procurement director requested quotation bids from three accredited hardware ________.", "options": {"A": "vendors", "B": "vendor", "C": "vending", "D": "vended"}, "answer": "A", "trap_point": "three accredited hardware vendors 複數！", "analysis": "數詞修飾名詞複數，選 (A) vendors。", "translation": "採購處長向三家經認可的硬體供應商索取了報價。"}, {"id": 4, "target_seconds": 20, "question": "The accounts department corrected an arithmetic error on the commercial ________.", "options": {"A": "invoice", "B": "invoiced", "C": "invoicing", "D": "invoices"}, "answer": "A", "trap_point": "the commercial invoice 單數！", "analysis": "冠詞修飾單數名詞，選 (A) invoice。", "translation": "會計部門更正了商業發票上的一處計算錯誤。"}, {"id": 5, "target_seconds": 20, "question": "The municipality ordered the contractor to ________ the public park site by Friday.", "options": {"A": "vacate", "B": "vacation", "C": "vacated", "D": "vacating"}, "answer": "A", "trap_point": "ordered sb to + 原形動詞 vacate！", "analysis": "不定詞接原形動詞，選 (A) vacate。", "translation": "市政府命令承包商在週五前騰空公園施工現場。"}, {"id": 6, "target_seconds": 20, "question": "The promotional warranty becomes void upon policy ________.", "options": {"A": "expiration", "B": "expire", "C": "expired", "D": "expires"}, "answer": "A", "trap_point": "upon policy expiration 名詞！", "analysis": "介系詞後接名詞 (A) expiration。", "translation": "促銷保固在保單到期時自動失效。"}, {"id": 7, "target_seconds": 20, "question": "The hotel outsourced banquet laundry services to a reputable local ________.", "options": {"A": "vendor", "B": "vendors", "C": "vending", "D": "vended"}, "answer": "A", "trap_point": "a reputable local vendor 單數！", "analysis": "冠詞 a 後接單數名詞 (A) vendor。", "translation": "飯店將宴會洗衣服務外包給當地一家信譽良好的供應商。"}, {"id": 8, "target_seconds": 20, "question": "The accounting manager approved the contractor's milestone completion ________.", "options": {"A": "invoice", "B": "invoices", "C": "invoicing", "D": "invoiced"}, "answer": "A", "trap_point": "completion invoice（請款發票）！", "analysis": "名詞位置，選 (A) invoice。", "translation": "會計經理批准了承包商的里程碑完工請款發票。"}, {"id": 9, "target_seconds": 20, "question": "Building regulations require tenants to ________ the rooftop terrace during storms.", "options": {"A": "vacate", "B": "vacation", "C": "vacating", "D": "vacates"}, "answer": "A", "trap_point": "require sb to + 原形動詞 vacate！", "analysis": "不定詞接原形動詞，選 (A) vacate。", "translation": "大樓法規要求租戶在暴風雨期間騰空屋頂露台。"}, {"id": 10, "target_seconds": 20, "question": "A reminder was sent two weeks prior to the annual software ________.", "options": {"A": "expiration", "B": "expire", "C": "expired", "D": "expiring"}, "answer": "A", "trap_point": "prior to the annual software expiration！", "analysis": "冠詞形容詞後接名詞，選 (A) expiration。", "translation": "在年度軟體授權到期前兩週發送了提醒。"}, {"id": 11, "target_seconds": 20, "question": "The airline signed an agreement with an international catering ________.", "options": {"A": "vendor", "B": "vendors", "C": "vending", "D": "vended"}, "answer": "A", "trap_point": "an international catering vendor！", "analysis": "選單數名詞 (A) vendor。", "translation": "航空公司與一家國際餐飲外包供應商簽署了協議。"}, {"id": 12, "target_seconds": 20, "question": "Please ensure that the client's tax registration number appears on the final ________.", "options": {"A": "invoice", "B": "invoices", "C": "invoiced", "D": "invoicing"}, "answer": "A", "trap_point": "on the final invoice！", "analysis": "冠詞形容詞後接單數名詞 (A) invoice。", "translation": "請確保客戶的稅務登記編號出現在最終發票上。"}, {"id": 13, "target_seconds": 20, "question": "Tenants failing to ________ the property will forfeit their security deposit.", "options": {"A": "vacate", "B": "vacation", "C": "vacating", "D": "vacated"}, "answer": "A", "trap_point": "failing to + 原形動詞 vacate！", "analysis": "to 後接原形動詞，選 (A) vacate。", "translation": "未能騰空該物業的租戶將被沒收保證金。"}, {"id": 14, "target_seconds": 20, "question": "The warranty period is non-extendable following policy ________.", "options": {"A": "expiration", "B": "expire", "C": "expired", "D": "expires"}, "answer": "A", "trap_point": "following policy expiration 名詞！", "analysis": "介系詞短語選名詞 (A) expiration。", "translation": "保單到期後，保固期不可展延。"}], "part7": {"passages": [{"text_type": "Lease Expiration & Move-Out Protocol Notice (商業辦公室退租與驗收通告)", "title": "Highland Commerce Tower — Notice of Suite Vacate Protocols & Inspection", "content": "COMMERCIAL LEASE EXPIRATION DIRECTIVE: HCT-VAC-2026-21\nBUILDING: Highland Commerce Tower, Downtown Corporate Center\nTO: Nexus Media Corporation (Suite 800)\nFROM: Building Management & Commercial Tenancy Bureau\nDATE: November 24, 2026\n\n1. Lease Expiration and Move-Out Timetable\nThis official notice serves to confirm that Nexus Media's commercial lease for Suite 800 will officially expire on December 31, 2026. In accordance with lease covenants, the premises must be vacated completely by 5:00 PM on that final day, with all company personnel, modular furniture, and electronic server equipment removed from the premises.\n\n2. Move-Out Inspection & Security Deposit Return\nThe building operations manager will conduct a thorough formal exit inspection with your facility representative on December 30. Highland Commerce Tower currently holds a $12,000 commercial security deposit on account. Nexus Media will receive its full $12,000 deposit refund within fifteen business days, provided that the final walk-through reveals no unapproved structural alterations, wall perforations, or damaged flooring fixtures.\n\n*Baseline Condition Restoration: Tenants are contractually bound to restore all commercial carpeting to baseline professional cleanliness before final walk-through. Failure to present certified carpet steam cleaning invoices will result in a mandatory $2,500 restoration deduction from the escrow deposit.", "questions": [{"question": "When does Nexus Media's commercial lease officially expire?", "options": {"A": "November 24", "B": "December 15", "C": "December 31", "D": "January 15"}, "answer": "C", "radar": "🔍 防漏看雷達：合約到期日 'lease expires on December 31'！", "analysis": "文中明確載明租約將於 12 月 31 日到期，故選 (C)。"}, {"question": "By what time on the final lease day must Suite 800 be vacated?", "options": {"A": "12:00 PM", "B": "3:00 PM", "C": "5:00 PM", "D": "11:59 PM"}, "answer": "C", "radar": "🔍 防漏看雷達：騰空時間 'must be completely vacated by 5:00 PM'！", "analysis": "內文指明必須在當天下午 5:00 前完全騰空，故選 (C)。"}, {"question": "What condition must be met for Nexus Media to receive its full $12,000 deposit refund?", "options": {"A": "Pre-paying for six months of future storage", "B": "The final walk-through reveals no unapproved structural alterations", "C": "Purchasing replacement elevators for the building", "D": "Signing an extended lease for a smaller suite"}, "answer": "B", "radar": "🔍 防漏看雷達：星號押金但書 '*Deposit Refund Condition: ... provided that the final walk-through inspection reveals no unapproved structural alterations'！", "analysis": "星號條款說明無未批准結構改動方可全額退還 12,000 美元押金，故選 (B)。"}]}, {"text_type": "Commercial Moving & Restoration Invoice (商業搬遷與深層清潔服務發票)", "title": "Apex Office Relocations — Final Moving Invoice #8841 & Service Summary", "content": "COMMERCIAL MOVING & RESTORATION INVOICE\nINVOICE NUMBER: #8841 | DATE: November 24, 2026\nCLIENT: Nexus Media Corporation (Suite 800, Highland Commerce Tower)\nVENDOR: Apex Office Relocations & Commercial Cleaning Services Inc.\nDISPATCH REFERENCE: RELOC-NW-9921 | ACCOUNT NO: NEX-8802\n\nItemized Services Rendered:\n1. Commercial Crate Rental & Delivery (50 heavy-duty plastic secure crates): $500\n2. Heavy Server Rack & Office Furniture Relocation & Truck Loading: $2,800\n3. Carpet Deep Steam Cleaning & Baseline Restoration (Suite 800): $1,200\nTOTAL AMOUNT DUE: $4,500\nPAYMENT TERMS: Net 30 days upon invoice receipt via wire transfer.\n\n*Cross-Passage Compliance Attestation: Per Highland Commerce Tower vacate guidelines, carpet steam cleaning must be completed prior to the landlord walk-through inspection scheduled for December 30. Our technician team has scheduled on-site hot water extraction cleaning for December 28 to guarantee full compliance with lease return terms, thereby ensuring Nexus Media satisfies all baseline restoration criteria to protect their full deposit refund. Certified cleaning certificates, chemical compliance receipts, and moisture inspection logs will be delivered directly to building management upon completion of services to guarantee immediate escrow deposit release.", "questions": [{"question": "What is the total amount due on Apex Relocations Invoice #8841?", "options": {"A": "$500", "B": "$1,200", "C": "$2,800", "D": "$4,500"}, "answer": "D", "radar": "🔍 防漏看雷達：總金額 'Total Due: $4,500'！", "analysis": "發票總額載明為 4,500 美元，故選 (D)。"}, {"question": "How much was charged specifically for carpet steam cleaning and restoration?", "options": {"A": "$500", "B": "$1,200", "C": "$2,800", "D": "$4,500"}, "answer": "B", "radar": "🔍 防漏看雷達：單項費用 'Carpet Deep Steam Cleaning ... : $1,200'！", "analysis": "項目清單明列地毯深度蒸汽清洗費用為 1,200 美元，故選 (B)。"}, {"question": "Cross-Passage Question: Why did Nexus Media hire Apex to steam-clean the carpet?", "options": {"A": "To comply with Highland Tower's baseline condition requirement and protect their deposit", "B": "To sell the used carpet at an online auction", "C": "Because the landlord refused to enter the suite", "D": "To qualify for commercial tenant insurance"}, "answer": "A", "radar": "🔍 防漏看雙篇交叉雷達：對照文件一『original carpet restored to baseline condition』與文件二星號附註！", "analysis": "雙篇交叉比對：文件一要求地毯恢復原狀以全額退還押金，文件二由 Apex 完成地毯清潔以通過 12/30 檢查，故選 (A)。"}]}]}}}, "22": {"day": 22, "date": "11/25", "phase": 3, "phase_name": "考前全真極速模擬與弱點獵殺", "topic": "多義詞情境切換 ｜ coverage, condition, stock, conduct", "morning": {"chunks": [{"chunk": "insurance coverage", "meaning": "保險理賠涵蓋範圍", "scenario": "The policy provides comprehensive insurance coverage.", "paraphrase": "coverage = protection = scope = insurance benefits", "alert": "亦可指 media coverage（新聞報導）！"}, {"chunk": "in pristine condition", "meaning": "保持完好如新的狀態", "scenario": "The leased equipment was returned in pristine condition.", "paraphrase": "condition = state = shape = order", "alert": "可指『狀態』也可指『條件』（terms and conditions）！"}, {"chunk": "in stock", "meaning": "有現貨庫存", "scenario": "All replacement parts are currently in stock.", "paraphrase": "in stock = available = on hand", "alert": "可指『庫存』也可指『股票』（corporate stock）！"}, {"chunk": "conduct an audit", "meaning": "進行審計調查", "scenario": "External accountants will conduct an audit next week.", "paraphrase": "conduct = carry out = perform = execute", "alert": "可作動詞『實施』也可作名詞『行為/操守』！"}, {"chunk": "address the issue", "meaning": "處理/解決問題", "scenario": "The committee met to address the issue of delays.", "paraphrase": "address = resolve = tackle = deal with", "alert": "可作動詞『處理/演說』也可作名詞『地址/演講』！"}, {"chunk": "media coverage", "meaning": "媒體報導/新聞宣傳", "scenario": "The product launch received widespread media coverage.", "paraphrase": "media coverage = press reporting", "alert": "商業情境高頻詞義！"}, {"chunk": "on condition that", "meaning": "在……條件下/前提是", "scenario": "The loan was approved on condition that records be audited.", "paraphrase": "on condition that = provided that", "alert": "常用於商務合約前提！"}], "visual_anchor": {"title": "多義詞 (Polysemy) 商務情境一秒切換錨點", "rule_1": "👀 看到「coverage」➔ 保險情境是『理賠範圍』，新聞情境是『媒體報導』！", "rule_2": "👀 看到「conduct」➔ 動詞是『實施/執行（conduct a survey/audit）』，名詞是『個人操守』！", "golden_rule": "⚡ 教練金句：多義詞不背死翻譯，看前後受詞決定真正詞義！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "The comprehensive insurance policy provides extensive ________ for water damage.", "options": {"A": "coverage", "B": "cover", "C": "covered", "D": "covering"}, "answer": "A", "analysis": "名詞位置：extensive coverage（廣泛的保險涵蓋範圍）。選 (A)。", "translation": "該綜合保險單為水損提供了廣泛的理賠保障。"}, {"id": 2, "target_seconds": 15, "question": "Used company vehicles are sold in as-is ________ with no supplementary warranties.", "options": {"A": "condition", "B": "conditions", "C": "conditioned", "D": "conditional"}, "answer": "A", "analysis": "片語：in as-is condition（依現狀出售）。選單數名詞 (A)。", "translation": "二手公司車輛按現狀出售，不附帶任何補充保固。"}, {"id": 3, "target_seconds": 15, "question": "The warehouse manager confirmed that high-demand electronics are currently in ________.", "options": {"A": "stock", "B": "stocks", "C": "stocked", "D": "stocking"}, "answer": "A", "analysis": "片語：in stock（有庫存/現貨）。選 (A)。", "translation": "倉庫經理證實高需求電子產品目前有現貨。"}, {"id": 4, "target_seconds": 15, "question": "The compliance officer will ________ an internal review of foreign procurement ledgers.", "options": {"A": "conduct", "B": "conductor", "C": "conducted", "D": "conducting"}, "answer": "A", "analysis": "will + 原形動詞 conduct（實施/進行審查）。選 (A)。", "translation": "法遵專員將對外國採購帳冊進行內部審查。"}, {"id": 5, "target_seconds": 15, "question": "During the keynote address, the director promised to ________ employee retention challenges.", "options": {"A": "address", "B": "addressing", "C": "addressed", "D": "addresses"}, "answer": "A", "analysis": "promised to + 原形動詞 address（處理/解決問題）。選 (A)。", "translation": "在主題演講中，處長承諾將解決員工留任難題。"}, {"id": 6, "target_seconds": 15, "question": "Media ________ of the international renewable energy summit was overwhelmingly favorable.", "options": {"A": "coverage", "B": "cover", "C": "covers", "D": "covered"}, "answer": "A", "analysis": "名詞主詞：Media coverage（媒體報導）。選 (A)。", "translation": "對該國際再生能源高峰會的媒體報導極為正面。"}, {"id": 7, "target_seconds": 15, "question": "Acceptance of the settlement offer is subject to one crucial ________.", "options": {"A": "condition", "B": "conditions", "C": "conditional", "D": "conditioned"}, "answer": "A", "analysis": "one crucial condition（一項關鍵條件）。選 (A)。", "translation": "接受和解要約取決於一項關鍵條件。"}, {"id": 8, "target_seconds": 15, "question": "Investors were eager to acquire shares of corporate ________ following the positive earnings report.", "options": {"A": "stock", "B": "stocks", "C": "stocked", "D": "stocking"}, "answer": "A", "analysis": "shares of corporate stock（公司股份/股票）。選 (A)。", "translation": "在公佈積極的財報後，投資者渴望購買公司股票。"}, {"id": 9, "target_seconds": 15, "question": "The clinical team will ________ human trials under strict oversight.", "options": {"A": "conduct", "B": "conductor", "C": "conducting", "D": "conducted"}, "answer": "A", "analysis": "will + 原形動詞 conduct trials（進行試驗）。選 (A)。", "translation": "臨床團隊將在嚴密監督下進行人體試驗。"}, {"id": 10, "target_seconds": 15, "question": "The CEO convened a press briefing to ________ public safety concerns.", "options": {"A": "address", "B": "addressing", "C": "addressed", "D": "addresses"}, "answer": "A", "analysis": "to + 原形動詞 address concerns（回應關切/處理疑慮）。選 (A)。", "translation": "執行長召集新聞簡報會以回應公眾對安全的關切。"}, {"id": 11, "target_seconds": 15, "question": "The warranty offers comprehensive repair ________ for mechanical breakdowns.", "options": {"A": "coverage", "B": "cover", "C": "covering", "D": "covered"}, "answer": "A", "analysis": "repair coverage（維修涵蓋範圍）。選 (A)。", "translation": "保固為機械故障提供全面的維修保障。"}, {"id": 12, "target_seconds": 15, "question": "All leased equipment must be returned in pristine ________.", "options": {"A": "condition", "B": "conditions", "C": "conditioned", "D": "conditional"}, "answer": "A", "analysis": "in pristine condition（保持完好原始狀態）。選 (A)。", "translation": "所有租賃設備必須在保持完好狀態下歸還。"}, {"id": 13, "target_seconds": 15, "question": "Automotive parts that are out of ________ will be backordered immediately.", "options": {"A": "stock", "B": "stocks", "C": "stocked", "D": "stocking"}, "answer": "A", "analysis": "out of stock（缺貨）。選 (A)。", "translation": "缺貨的汽車零件將立即進行延期交貨登記。"}, {"id": 14, "target_seconds": 15, "question": "Independent investigators were hired to ________ an impartial evaluation of the incident.", "options": {"A": "conduct", "B": "conductor", "C": "conducted", "D": "conducting"}, "answer": "A", "analysis": "to + 原形動詞 conduct（進行評估）。選 (A)。", "translation": "聘請了獨立調查員對該起事件進行公正評估。"}, {"id": 15, "target_seconds": 15, "question": "Management formed a dedicated task force to ________ customer shipping delays.", "options": {"A": "address", "B": "addressing", "C": "addressed", "D": "addresses"}, "answer": "A", "analysis": "to + 原形動詞 address（處理延誤）。選 (A)。", "translation": "管理層成立了專門的工作小組來處理客戶發貨延遲問題。"}, {"id": 16, "target_seconds": 15, "question": "The sports event received round-the-clock television ________ across twenty nations.", "options": {"A": "coverage", "B": "cover", "C": "covers", "D": "covered"}, "answer": "A", "analysis": "television coverage（電視轉播報導）。選 (A)。", "translation": "該體育賽事在 20 個國家獲得了全天候的電視轉播報導。"}, {"id": 17, "target_seconds": 15, "question": "Bonus disbursements are granted on ________ that quarterly sales targets are surpassed.", "options": {"A": "condition", "B": "conditions", "C": "conditional", "D": "conditioned"}, "answer": "A", "analysis": "on condition that...（在……條件下/前提是）。選 (A)。", "translation": "獎金發放的前提是季度銷售目標獲得超額完成。"}, {"id": 18, "target_seconds": 15, "question": "The boutique keeps a limited ________ of handcrafted leather wallets in reserve.", "options": {"A": "stock", "B": "stocks", "C": "stocked", "D": "stocking"}, "answer": "A", "analysis": "a limited stock（有限庫存）。選 (A)。", "translation": "該精品店儲備了數量有限的手工皮夾現貨。"}, {"id": 19, "target_seconds": 15, "question": "All research fellows must ________ themselves in a professional manner.", "options": {"A": "conduct", "B": "conductor", "C": "conducted", "D": "conducting"}, "answer": "A", "analysis": "conduct oneself（舉止行為）。選 (A)。", "translation": "所有研究人員必須以專業方式行事規範自己。"}, {"id": 20, "target_seconds": 15, "question": "The newly elected mayor delivered an inspiring ________ to city municipal employees.", "options": {"A": "address", "B": "addressing", "C": "addressed", "D": "addresses"}, "answer": "A", "analysis": "an inspiring address（鼓舞人心的演說）。選 (A)。", "translation": "新當選的市長對市政員工發表了鼓舞人心的演說。"}]}, "afternoon": {"quick_recall": [{"prompt": "insurance ________ [名詞，保險理賠涵蓋範圍/媒體報導].", "clue": "涵蓋範圍/報導", "answer": "coverage"}, {"prompt": "The car was returned in pristine ________ [名詞，狀況/條件].", "clue": "車況/狀況", "answer": "condition"}, {"prompt": "Items that are out of ________ [名詞，庫存/現貨] will be reordered.", "clue": "缺貨庫存", "answer": "stock"}, {"prompt": "to ________ [動詞，實施/進行] a market research study.", "clue": "實施進行", "answer": "conduct"}, {"prompt": "to ________ [動詞，處理/解決] client complaints.", "clue": "處理應對", "answer": "address"}, {"prompt": "on ________ [名詞，條件] that all debts are cleared.", "clue": "前提條件 (on ... that)", "answer": "condition"}], "spaced_traps": [{"id": 1, "target_seconds": 20, "question": "The dental insurance plan offers extensive ________ for preventive cleanings.", "options": {"A": "coverage", "B": "cover", "C": "covered", "D": "covering"}, "answer": "A", "trap_point": "extensive coverage（廣泛保險範圍）名詞！", "analysis": "形容詞修飾名詞，選 (A) coverage。", "translation": "牙科保險計畫為預防性洗牙提供了廣泛的給付保障。"}, {"id": 2, "target_seconds": 20, "question": "The pre-owned laptop was certified to be in excellent working ________.", "options": {"A": "condition", "B": "conditions", "C": "conditioned", "D": "conditional"}, "answer": "A", "trap_point": "in excellent working condition 名詞！", "analysis": "片語選單數名詞 (A) condition。", "translation": "二手筆記型電腦經認證處於良好的工作狀態。"}, {"id": 3, "target_seconds": 20, "question": "The retail store ran out of ________ of the popular holiday tablet on opening day.", "options": {"A": "stock", "B": "stocks", "C": "stocked", "D": "stocking"}, "answer": "A", "trap_point": "ran out of stock（庫存耗盡）！", "analysis": "片語選名詞 (A) stock。", "translation": "這家零售店在開業當天熱銷節日平板電腦的庫存就宣告耗盡。"}, {"id": 4, "target_seconds": 20, "question": "The external audit firm will ________ a comprehensive forensic review of account ledgers.", "options": {"A": "conduct", "B": "conductor", "C": "conducted", "D": "conducting"}, "answer": "A", "trap_point": "will + 原形動詞 conduct！", "analysis": "助動詞 will 接原形動詞，選 (A) conduct。", "translation": "外部審計公司將對帳目進行全面的鑑識審查。"}, {"id": 5, "target_seconds": 20, "question": "The customer relations director scheduled an emergency meeting to ________ service complaints.", "options": {"A": "address", "B": "addressing", "C": "addressed", "D": "addresses"}, "answer": "A", "trap_point": "to + 原形動詞 address！", "analysis": "不定詞接原形動詞，選 (A) address（處理）。", "translation": "客戶關係主管安排了緊急會議以處理服務投訴。"}, {"id": 6, "target_seconds": 20, "question": "International press ________ of the technological breakthrough elevated corporate share prices.", "options": {"A": "coverage", "B": "cover", "C": "covers", "D": "covered"}, "answer": "A", "trap_point": "press coverage（新聞報導）名詞！", "analysis": "複合名詞結構，選 (A) coverage。", "translation": "國際新聞界對該技術突破的報導推高了公司股價。"}, {"id": 7, "target_seconds": 20, "question": "The warranty agreement was approved on ________ that repairs be performed by certified technicians.", "options": {"A": "condition", "B": "conditions", "C": "conditional", "D": "conditioned"}, "answer": "A", "trap_point": "on condition that 虛擬語氣！", "analysis": "片語選單數名詞 (A) condition。", "translation": "保固協議獲得批准，前提是由認證技術人員進行維修。"}, {"id": 8, "target_seconds": 20, "question": "The retail chain maintains an extensive ________ of replacement batteries in its hub.", "options": {"A": "stock", "B": "stocks", "C": "stocked", "D": "stocking"}, "answer": "A", "trap_point": "an extensive stock 名詞！", "analysis": "冠詞形容詞後接名詞，選 (A) stock（現貨庫存）。", "translation": "這家零售連鎖店在其中心庫存有大量的備用電池。"}, {"id": 9, "target_seconds": 20, "question": "The regulatory committee resolved to ________ a formal inquiry into the pricing discrepancy.", "options": {"A": "conduct", "B": "conductor", "C": "conducting", "D": "conducted"}, "answer": "A", "trap_point": "resolved to + 原形動詞 conduct！", "analysis": "不定詞後接原形動詞，選 (A) conduct。", "translation": "監管委員會決議對價格差異展開正式調查。"}, {"id": 10, "target_seconds": 20, "question": "The CEO will deliver an opening ________ to welcoming conference participants.", "options": {"A": "address", "B": "addressing", "C": "addressed", "D": "addresses"}, "answer": "A", "trap_point": "an opening address（開幕演說）名詞！", "analysis": "冠詞形容詞後接名詞，選 (A) address。", "translation": "執行長將向與會者發表開幕演說。"}, {"id": 11, "target_seconds": 20, "question": "The supplemental medical policy provides worldwide emergency medical ________.", "options": {"A": "coverage", "B": "cover", "C": "covering", "D": "covered"}, "answer": "A", "trap_point": "emergency medical coverage 名詞！", "analysis": "名詞修飾名詞，選 (A) coverage。", "translation": "補充醫療保單提供全球緊急醫療涵蓋保障。"}, {"id": 12, "target_seconds": 20, "question": "Vehicles returned with exterior damage are not considered in acceptable ________.", "options": {"A": "condition", "B": "conditions", "C": "conditioned", "D": "conditional"}, "answer": "A", "trap_point": "in acceptable condition！", "analysis": "片語選單數名詞 (A) condition。", "translation": "歸還時有外觀損壞的車輛不被視為處於可接受狀態。"}, {"id": 13, "target_seconds": 20, "question": "Automobile dealerships keep a substantial ________ of seasonal winter tires on hand.", "options": {"A": "stock", "B": "stocks", "C": "stocked", "D": "stocking"}, "answer": "A", "trap_point": "a substantial stock！", "analysis": "名詞位置，選 (A) stock。", "translation": "汽車經銷店備有大量現貨的季節性冬季輪胎。"}, {"id": 14, "target_seconds": 20, "question": "The human resources manager will ________ exit interviews with retiring personnel.", "options": {"A": "conduct", "B": "conductor", "C": "conducted", "D": "conducting"}, "answer": "A", "trap_point": "will + 原形動詞 conduct！", "analysis": "助動詞後接原形動詞，選 (A) conduct。", "translation": "人力資源經理將對退休人員進行離職訪談。"}], "part7": {"passages": [{"text_type": "Commercial Insurance Policy Covenant (商業財產綜合保險手冊)", "title": "Veritas Underwriters — Facility Property Coverage Terms & Maintenance Requirements", "content": "PROPERTY UNDERWRITING POLICY: VER-PROP-2026-22\nINSURANCE CARRIER: Veritas Commercial Underwriters Group LLC\nPOLICYHOLDER: Crestline Advanced Technology Campus\nEFFECTIVE DATES: November 25, 2026 — November 24, 2027\n\nSection 2. Aggregate Coverage Limits and Insured Perils:\nVeritas Underwriters provides comprehensive property loss protection for all manufacturing plants, research cleanrooms, and executive office facilities situated within the Crestline Technology Campus. The policy provides a total aggregate insurance coverage of $5 million against structural fire, water main rupture, windstorm damage, and verified industrial equipment collapse occurring on insured corporate premises during the policy period, with supplemental debris removal indemnification.\n\nSection 6. Fire Suppression System Maintenance Covenants:\nTo keep policy terms fully operational, the insured must adhere to strict fire safety protocols. Sprinkler valves, backflow preventers, and pressure gauges must receive servicing quarterly (every three months) by state-certified fire protection contractors, with dated inspection tags affixed to each main manifold.\n\n*Exclusion Clause: Coverage is nullified in instances of gross negligence. The policy expressly excludes damage resulting from uncertified electrical rewiring, unauthorized panel modifications, or non-compliant machinery installations performed without certified municipal electrical permits.", "questions": [{"question": "What total aggregate insurance coverage does the Veritas policy provide?", "options": {"A": "$1 million", "B": "$2.5 million", "C": "$5 million", "D": "$10 million"}, "answer": "C", "radar": "🔍 防漏看雷達：保額數字 '$5 million aggregate coverage'！", "analysis": "文中明確指出提供 500 萬美元的總額理賠保障，故選 (C)。"}, {"question": "How often must sprinkler valves receive servicing to maintain policy condition?", "options": {"A": "Monthly", "B": "Quarterly (every three months)", "C": "Semi-annually", "D": "Annually"}, "answer": "B", "radar": "🔍 防漏看雷達：保養頻率 'mandatory quarterly servicing'！", "analysis": "內文規定必須進行每季度（quarterly）強制保養，故選 (B)。"}, {"question": "What is expressly excluded from coverage according to the exclusion clause?", "options": {"A": "Damage from electrical power surges", "B": "Damage resulting from uncertified electrical rewiring", "C": "Accidental plumbing leaks", "D": "Roof hail damage"}, "answer": "B", "radar": "🔍 防漏看雷達：星號除外條款 '*Coverage Exclusions: Damage resulting from civil unrest or uncertified electrical rewiring'！", "analysis": "星號條款特別列出未認證線路改動所致損壞不予理賠，故選 (B)。"}]}, {"text_type": "Annual General Meeting Keynote Address (股東週年大會主席致詞與股利公告)", "title": "Crestline Technology — Annual General Meeting Keynote Address & Dividend Notice", "content": "ANNUAL GENERAL MEETING DISCLOSURE: CREST-AGM-2026\nCOMPANY: Crestline Technology Enterprises Inc.\nLOCATION: Fairmont Grand Ballroom, Boston, MA & Virtual Webcast\nDATE: November 25, 2026\nPRESIDING OFFICER: Chairman and CEO Katherine Sterling\n\n1. Strategic Corporate Restructuring Review\nIn her opening address to shareholders, Chairman Katherine Sterling reviewed the transformative initiatives implemented during the past fiscal year. Most notably, Crestline Technology conducted extensive restructuring across three manufacturing divisions, consolidating redundant overseas fabrication lines and optimizing lean automation across domestic facilities to bolster productivity, operating margins, customer retention, and free cash flow.\n\n2. Financial Performance and Shareholder Valuation\nThese decisive operational efficiencies yielded unprecedented financial growth. Over the previous twelve months, corporate stock valuation increased by 24%, outperforming standard technology market indices and strengthening our investment-grade commercial credit profile with international rating agencies.\n\n*Fourth-Quarter Cash Dividend Declaration: In recognition of this robust operational performance, the Board of Directors has declared a fourth-quarter cash dividend. Common stock shareholders will receive $0.65 per share on December 20, payable to shareholders of record as of the close of business on December 5.", "questions": [{"question": "What did Crestline Technology conduct across three manufacturing divisions?", "options": {"A": "Extensive restructuring", "B": "Total liquidation of real estate", "C": "Mass layoffs of engineering staff", "D": "Outsourcing of all computing"}, "answer": "A", "radar": "🔍 防漏看雷達：首段行動 'conducted extensive restructuring across three manufacturing divisions'！", "analysis": "演講中說明在三個製造事業部進行了大規模重組，故選 (A)。"}, {"question": "By what percentage did corporate stock valuation increase?", "options": {"A": "12%", "B": "18%", "C": "24%", "D": "35%"}, "answer": "C", "radar": "🔍 防漏看雷達：百分比增長 'resulting in a 24% boost in corporate stock valuation'！", "analysis": "文中指明公司股票估值提升了 24%，故選 (C)。"}, {"question": "What cash dividend per share will common stock shareholders receive on December 20?", "options": {"A": "$0.25", "B": "$0.50", "C": "$0.65", "D": "$1.00"}, "answer": "C", "radar": "🔍 防漏看雷達：星號股息金額 '*Notice of Dividend Authorization: ... quarterly cash dividend of $0.65 per share'！", "analysis": "星號條款明確說明每股現金股息為 0.65 美元，故選 (C)。"}]}]}}}, "23": {"day": 23, "date": "11/26", "phase": 3, "phase_name": "考前全真極速模擬與弱點獵殺", "topic": "Part 7 三篇閱讀獵殺 ｜ 資訊定位與反向排除", "morning": {"chunks": [{"chunk": "cross-check the data", "meaning": "交叉核對數據", "scenario": "Auditors cross-check the data to verify invoice accuracy.", "paraphrase": "cross-check = reconcile = compare = corroborate", "alert": "Part 7 多篇閱讀必備技巧！"}, {"chunk": "resolve the discrepancy", "meaning": "解決差異/消除不一致", "scenario": "Managers met to resolve the discrepancy in delivery dates.", "paraphrase": "discrepancy = variance = inconsistency = divergence", "alert": "discrepancy 為名詞！"}, {"chunk": "contract amendment", "meaning": "合約修正案/補充條款", "scenario": "Both parties signed a contract amendment yesterday.", "paraphrase": "amendment = revision = modification = addendum", "alert": "動詞為 amend！"}, {"chunk": "written confirmation", "meaning": "書面確認函/證實", "scenario": "We require written confirmation before dispatching goods.", "paraphrase": "written confirmation = documented proof = written verification", "alert": "動詞為 confirm！"}, {"chunk": "detect an error", "meaning": "察覺錯誤/發現漏洞", "scenario": "Software sensors detect an error in the circuit board.", "paraphrase": "detect an error = identify a mistake", "alert": "動詞片語！"}, {"chunk": "billing statement", "meaning": "帳單對帳單", "scenario": "The billing statement reflects all promotional discounts.", "paraphrase": "billing statement = account statement", "alert": "常見商務財務文件！"}, {"chunk": "reverse elimination", "meaning": "反向排除法", "scenario": "Apply reverse elimination to find the NOT question answer.", "paraphrase": "reverse elimination = process of elimination", "alert": "TOEIC Part 7 核心高分策略！"}], "visual_anchor": {"title": "Part 7 三篇閱讀 (Triple Passages) 反向排除法錨點", "rule_1": "👀 看到「NOT mentioned / EXCEPT」題型 ➔ 100% 採用反向排除法，原文找到三項，剩下一項秒選！", "rule_2": "👀 多篇交叉題通常落在該大題第 4、5 小題 ➔ 鎖定「首篇規定」+「次篇回覆」+「末篇帳單/修正案」聯立求解！", "golden_rule": "⚡ 教練金句：三篇題莫慌張，先讀題幹定關鍵字，再回正文精準獵殺！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "The internal audit team worked to ________ inventory discrepancies between warehouses.", "options": {"A": "resolve", "B": "resolution", "C": "resolving", "D": "resolved"}, "answer": "A", "analysis": "worked to + 原形動詞 resolve（解決/消除分歧）。選 (A)。", "translation": "內部審計團隊致力於解決各倉庫之間的庫存差異。"}, {"id": 2, "target_seconds": 15, "question": "Accounting clerks noticed a substantial ________ between the purchase order and the vendor bill.", "options": {"A": "discrepancy", "B": "discrepant", "C": "discrepancies", "D": "discrepantly"}, "answer": "A", "analysis": "冠詞 a substantial 後接單數名詞 discrepancy（差異/不一致）。選 (A)。", "translation": "會計文員注意到採購訂單與供應商帳單之間存在重大差異。"}, {"id": 3, "target_seconds": 15, "question": "The executive board approved a constitutional ________ expanding employee voting rights.", "options": {"A": "amendment", "B": "amend", "C": "amending", "D": "amended"}, "answer": "A", "analysis": "冠詞 a constitutional 後接名詞 amendment（修正案）。選 (A)。", "translation": "執行董事會批准了一項擴大員工投票權的章程修正案。"}, {"id": 4, "target_seconds": 15, "question": "Travelers must present written ________ of hotel reservations upon arrival at immigration.", "options": {"A": "confirmation", "B": "confirm", "C": "confirming", "D": "confirmed"}, "answer": "A", "analysis": "形容詞 written 後接名詞 confirmation（書面確認函）。選 (A)。", "translation": "旅客抵達移民海關時必須出示飯店預訂的書面確認函。"}, {"id": 5, "target_seconds": 15, "question": "Inspectors will ________ manufacturing records against automated sensor logs.", "options": {"A": "cross-check", "B": "cross-checked", "C": "cross-checking", "D": "cross-checks"}, "answer": "A", "analysis": "will + 原形動詞 cross-check（交叉核對）。選 (A)。", "translation": "檢查員將交叉核對生產紀錄與自動化感測器日誌。"}, {"id": 6, "target_seconds": 15, "question": "The billing department quickly issued a refund to resolve the billing ________.", "options": {"A": "discrepancy", "B": "discrepant", "C": "discrepancies", "D": "discrepantly"}, "answer": "A", "analysis": "the billing discrepancy 單數名詞。選 (A)。", "translation": "帳單部門迅速發放了退款以解決帳單差異。"}, {"id": 7, "target_seconds": 15, "question": "The proposed lease ________ requires final sign-off from the property manager.", "options": {"A": "amendment", "B": "amend", "C": "amending", "D": "amended"}, "answer": "A", "analysis": "The proposed lease amendment。選名詞 (A)。", "translation": "提議的租約修正案需要物業經理的最終簽署。"}, {"id": 8, "target_seconds": 15, "question": "Guests will receive an email ________ within ten minutes of completing registration.", "options": {"A": "confirmation", "B": "confirm", "C": "confirmed", "D": "confirming"}, "answer": "A", "analysis": "an email confirmation（電子郵件確認函）。選 (A)。", "translation": "賓客將在完成註冊後十分鐘內收到電子郵件確認函。"}, {"id": 9, "target_seconds": 15, "question": "Analysts must ________ external market data with internal sales forecasts.", "options": {"A": "cross-check", "B": "cross-checked", "C": "cross-checking", "D": "cross-checks"}, "answer": "A", "analysis": "must + 原形動詞 cross-check。選 (A)。", "translation": "分析師必須交叉核對外部市場數據與內部銷售預測。"}, {"id": 10, "target_seconds": 15, "question": "Any numerical ________ on the financial balance sheet must be investigated immediately.", "options": {"A": "discrepancy", "B": "discrepant", "C": "discrepancies", "D": "discrepantly"}, "answer": "A", "analysis": "Any numerical discrepancy。選單數名詞 (A)。", "translation": "資產負債表上的任何數字差異都必須立即調查。"}, {"id": 11, "target_seconds": 15, "question": "The legal team drafted an ________ to extend the software licensing agreement.", "options": {"A": "amendment", "B": "amend", "C": "amending", "D": "amended"}, "answer": "A", "analysis": "drafted an amendment（起草修正案）。選 (A)。", "translation": "法律團隊起草了一項延長軟體授權協議的修正案。"}, {"id": 12, "target_seconds": 15, "question": "Please retain your booking ________ number for customer service inquiries.", "options": {"A": "confirmation", "B": "confirm", "C": "confirming", "D": "confirmed"}, "answer": "A", "analysis": "booking confirmation number（預訂確認號碼）。選 (A)。", "translation": "請保留您的預訂確認號碼以便客服查詢。"}, {"id": 13, "target_seconds": 15, "question": "Warehouse supervisors ________ shipping manifests daily to prevent inventory loss.", "options": {"A": "cross-check", "B": "cross-checked", "C": "cross-checking", "D": "cross-checks"}, "answer": "A", "analysis": "主詞 supervisors + 動詞原形 cross-check。選 (A)。", "translation": "倉庫主管每日交叉核對出貨清單以防止庫存損失。"}, {"id": 14, "target_seconds": 15, "question": "The audit team highlighted a minor ________ in payroll tax withholdings.", "options": {"A": "discrepancy", "B": "discrepant", "C": "discrepancies", "D": "discrepantly"}, "answer": "A", "analysis": "a minor discrepancy。選 (A)。", "translation": "審計團隊指出了薪資代扣所得稅方面的一處輕微差異。"}, {"id": 15, "target_seconds": 15, "question": "Shareholders voted in favor of the bylaws ________ proposed by the board.", "options": {"A": "amendment", "B": "amend", "C": "amended", "D": "amending"}, "answer": "A", "analysis": "the bylaws amendment。選 (A)。", "translation": "股東投票贊成董事會提議的章程修正案。"}, {"id": 16, "target_seconds": 15, "question": "An SMS ________ will be dispatched once your package leaves the regional facility.", "options": {"A": "confirmation", "B": "confirm", "C": "confirmed", "D": "confirming"}, "answer": "A", "analysis": "An SMS confirmation（簡訊確認）。選 (A)。", "translation": "包裹離開區域設施後，將發送簡訊確認。"}, {"id": 17, "target_seconds": 15, "question": "Engineers will ________ telemetry data from both ground radar stations.", "options": {"A": "cross-check", "B": "cross-checked", "C": "cross-checking", "D": "cross-checks"}, "answer": "A", "analysis": "will + 原形動詞 cross-check。選 (A)。", "translation": "工程師將交叉核對來自兩個地面雷達站的遙測數據。"}, {"id": 18, "target_seconds": 15, "question": "The discrepancy in cargo weight was resolved prior to flight departure.", "options": {"A": "discrepancy", "B": "discrepant", "C": "discrepancies", "D": "discrepantly"}, "answer": "A", "analysis": "The discrepancy in cargo weight。選 (A)。", "translation": "貨物重量的差異在航班起飛前得到了解決。"}, {"id": 19, "target_seconds": 15, "question": "A contractual ________ was signed to modify the construction milestone schedule.", "options": {"A": "amendment", "B": "amend", "C": "amended", "D": "amending"}, "answer": "A", "analysis": "A contractual amendment。選 (A)。", "translation": "簽署了一項合約修正案以修改施工里程碑進度表。"}, {"id": 20, "target_seconds": 15, "question": "Subscribers must provide verbal ________ before account cancellation can proceed.", "options": {"A": "confirmation", "B": "confirm", "C": "confirming", "D": "confirmed"}, "answer": "A", "analysis": "verbal confirmation（口頭確認）。選 (A)。", "translation": "在進行帳戶註銷前，訂閱者必須提供口頭確認。"}]}, "afternoon": {"quick_recall": [{"prompt": "to ________ [動詞，交叉核對] data across multiple sources.", "clue": "交叉核對", "answer": "cross-check"}, {"prompt": "a significant ________ [名詞，差異/不一致] in billing amounts.", "clue": "數字差異不一致", "answer": "discrepancy"}, {"prompt": "to draft a contract ________ [名詞，修正案/補充條款].", "clue": "修正案", "answer": "amendment"}, {"prompt": "to receive written ________ [名詞，確認函/證實] of reservation.", "clue": "確認函", "answer": "confirmation"}, {"prompt": "to resolve the invoice ________ [名詞，差異處].", "clue": "帳單差異", "answer": "discrepancy"}, {"prompt": "The booking ________ [名詞，確認] code was sent via email.", "clue": "確認代碼", "answer": "confirmation"}], "spaced_traps": [{"id": 1, "target_seconds": 20, "question": "The accountant worked diligently to resolve the financial ________ on the invoice.", "options": {"A": "discrepancy", "B": "discrepant", "C": "discrepancies", "D": "discrepantly"}, "answer": "A", "trap_point": "the financial discrepancy 單數！", "analysis": "冠詞形容詞後接單數名詞 (A) discrepancy。", "translation": "會計師辛勤工作以解決發票上的財務差異。"}, {"id": 2, "target_seconds": 20, "question": "The municipal council ratified the proposed environmental policy ________.", "options": {"A": "amendment", "B": "amend", "C": "amending", "D": "amended"}, "answer": "A", "trap_point": "policy amendment（政策修正案）名詞！", "analysis": "名詞修飾名詞，選 (A) amendment。", "translation": "市議會批准了提議的環境政策修正案。"}, {"id": 3, "target_seconds": 20, "question": "Subscribers will receive an automated dispatch ________ upon courier departure.", "options": {"A": "confirmation", "B": "confirm", "C": "confirming", "D": "confirmed"}, "answer": "A", "trap_point": "dispatch confirmation 名詞！", "analysis": "複合名詞結構，選 (A) confirmation。", "translation": "訂閱者在快遞出發時將收到自動發送確認函。"}, {"id": 4, "target_seconds": 20, "question": "Audit specialists will ________ warehouse pallet counts against electronic manifests.", "options": {"A": "cross-check", "B": "cross-checked", "C": "cross-checking", "D": "cross-checks"}, "answer": "A", "trap_point": "will + 原形動詞 cross-check！", "analysis": "助動詞 will 接原形動詞，選 (A) cross-check。", "translation": "審計專家將交叉核對倉庫托盤數量與電子艙單。"}, {"id": 5, "target_seconds": 20, "question": "A sudden ________ in fuel consumption telemetry triggered an engine shutdown.", "options": {"A": "discrepancy", "B": "discrepant", "C": "discrepancies", "D": "discrepantly"}, "answer": "A", "trap_point": "A sudden discrepancy 單數名詞！", "analysis": "冠詞形容詞後接單數名詞 (A) discrepancy。", "translation": "燃油消耗遙測數據的突然差異引發了發動機停機。"}, {"id": 6, "target_seconds": 20, "question": "The landlord agreed to execute a formal lease ________ adjusting monthly rent.", "options": {"A": "amendment", "B": "amend", "C": "amending", "D": "amended"}, "answer": "A", "trap_point": "lease amendment（租約修正案）！", "analysis": "選名詞 (A) amendment。", "translation": "房東同意簽署一份調整月租金的正式租約修正案。"}, {"id": 7, "target_seconds": 20, "question": "Please retain the electronic transaction ________ for expense reimbursement.", "options": {"A": "confirmation", "B": "confirm", "C": "confirmed", "D": "confirming"}, "answer": "A", "trap_point": "transaction confirmation 名詞！", "analysis": "名詞修飾名詞，選 (A) confirmation。", "translation": "請保留電子交易確認單以便辦理報銷。"}, {"id": 8, "target_seconds": 20, "question": "Supervisors must ________ medical device serial numbers before packaging.", "options": {"A": "cross-check", "B": "cross-checked", "C": "cross-checking", "D": "cross-checks"}, "answer": "A", "trap_point": "must + 原形動詞 cross-check！", "analysis": "助動詞接原形動詞，選 (A) cross-check。", "translation": "主管在包裝前必須交叉核對醫療器械的序列號。"}, {"id": 9, "target_seconds": 20, "question": "The auditor documented a four percent ________ in retail store physical inventory.", "options": {"A": "discrepancy", "B": "discrepant", "C": "discrepancies", "D": "discrepantly"}, "answer": "A", "trap_point": "a four percent discrepancy！", "analysis": "冠詞修飾單數名詞，選 (A) discrepancy。", "translation": "審計員記錄了零售店實體庫存中 4% 的差異。"}, {"id": 10, "target_seconds": 20, "question": "Shareholders approved the corporate charter ________ by an overwhelming margin.", "options": {"A": "amendment", "B": "amend", "C": "amended", "D": "amending"}, "answer": "A", "trap_point": "corporate charter amendment！", "analysis": "選名詞 (A) amendment。", "translation": "股東以壓倒性優勢批准了公司章程修正案。"}, {"id": 11, "target_seconds": 20, "question": "Clients must present booking ________ when claiming reserved conference rooms.", "options": {"A": "confirmation", "B": "confirm", "C": "confirming", "D": "confirmed"}, "answer": "A", "trap_point": "booking confirmation 名詞！", "analysis": "選名詞 (A) confirmation。", "translation": "客戶在領取預留會議室時必須出示預訂確認函。"}, {"id": 12, "target_seconds": 20, "question": "Shipping coordinators must ________ freight container codes with bill of lading documents.", "options": {"A": "cross-check", "B": "cross-checked", "C": "cross-checking", "D": "cross-checks"}, "answer": "A", "trap_point": "must + 原形動詞 cross-check！", "analysis": "選原形動詞 (A) cross-check。", "translation": "運輸協調員必須交叉核對貨櫃代碼與提單文件。"}, {"id": 13, "target_seconds": 20, "question": "The financial controller resolved the tax calculation ________ before filing.", "options": {"A": "discrepancy", "B": "discrepant", "C": "discrepancies", "D": "discrepantly"}, "answer": "A", "trap_point": "tax calculation discrepancy！", "analysis": "選名詞 (A) discrepancy。", "translation": "財務總監在申報前解決了稅款計算差異。"}, {"id": 14, "target_seconds": 20, "question": "The corporate agreement is subject to a bilateral contract ________.", "options": {"A": "amendment", "B": "amend", "C": "amended", "D": "amending"}, "answer": "A", "trap_point": "bilateral contract amendment！", "analysis": "選名詞 (A) amendment。", "translation": "該企業協議受雙邊合約修正案的約束。"}], "part7": {"passages": [{"text_type": "Freight Operations Protocol Manual (鐵路貨運地磅檢驗與爭議處理程序)", "title": "Global Rail Freight — Discrepancy Resolution Protocol & Scale Audits", "content": "OPERATIONAL COMPLIANCE DIRECTIVE: GRF-SOP-2026-23\nISSUED BY: Terminal Safety & Freight Billing Operations, Global Rail Freight\nDATE: November 26, 2026\nMANDATORY FOR: All Yard Masters, Scale Operators, and Regional Billing Specialists\n\n1. Implementation Date and Manifest Verification\nTo prevent rail car axle overloading and resolve shipping billing disputes, Global Rail Freight announces that its updated manifest cross-checking protocol will officially take effect on December 1 across all inland and coastal intermodal terminals. Automated weigh-in-motion sensor pads will scan all incoming container traffic against electronic bills of lading before trains depart freight yards.\n\n2. Discrepancy Thresholds & Secondary Scale Audits\nUnder the updated operating protocol, any recorded container weight discrepancy exceeding 50 kilograms from the declared manifest weight triggers mandatory manual re-weighing on certified stationary platform scales. Associated billing invoices are frozen automatically until weight discrepancies are thoroughly investigated and reconciled by technical inspection crews.\n\n*Billing Release Authorization: To unfreeze invoices with flagged discrepancies, operating staff must obtain formal written confirmation from the regional terminal manager. Verbal authorizations or broker emails are strictly unacceptable under federal intermodal transport regulations.", "questions": [{"question": "When does the new manifest cross-checking protocol take effect?", "options": {"A": "November 26", "B": "December 1", "C": "December 15", "D": "January 1"}, "answer": "B", "radar": "🔍 防漏看雷達：生效日期 'Beginning December 1'！", "analysis": "內文明確載明於 12 月 1 日正式生效，故選 (B)。"}, {"question": "What weight discrepancy triggers manual re-weighing?", "options": {"A": "Exceeding 10 kilograms", "B": "Exceeding 25 kilograms", "C": "Exceeding 50 kilograms", "D": "Exceeding 100 kilograms"}, "answer": "C", "radar": "🔍 防漏看雷達：數字門檻 'discrepancy exceeding 50 kilograms'！", "analysis": "文中指出差異超過 50 公斤即須重新手動稱重，故選 (C)。"}, {"question": "What is required to unfreeze invoices with flagged discrepancies?", "options": {"A": "A telephone call from the client", "B": "Written confirmation from the regional terminal manager", "C": "A discount of 20% applied to all shipments", "D": "Approval from the city mayor"}, "answer": "B", "radar": "🔍 防漏看雷達：星號但書條件 '*Billing Amendment Clause: ... pending written confirmation from the regional terminal manager'！", "analysis": "星號條款說明有待區域站點經理的書面確認方可解凍發票，故選 (B)。"}]}, {"text_type": "Terminal Operational Correspondence (海運碼頭集裝箱重量確認信函)", "title": "North Port Terminal — Container #4492 Weight Confirmation & Resolution", "content": "OPERATIONAL CORRESPONDENCE & WRITTEN CONFIRMATION\nDATE: November 26, 2026\nTO: Regional Freight Billing Office, Global Rail Freight Intermodal\nFROM: Marcus Vance, Regional Terminal Manager, North Port Intermodal Terminal\nSUBJECT: Written Confirmation — Container #4492 Discrepancy Resolution & Release\n\nDear Regional Billing Team,\n\nIn accordance with our discrepancy audit procedures and terminal weight safety regulations, I have personally reviewed the secondary stationary scale verification data for Container #4492, which arrived aboard the Pacific Trader. The initial weight discrepancy of 62 kilograms recorded on the automated rail sensor was thoroughly investigated by terminal technicians.\n\nOur inspection confirmed that the discrepancy was caused by moisture absorbed by outer wooden packaging during ocean transit through high-humidity maritime zones. The physical payload itself conforms strictly to manifest safety specifications.\n\nScale Calibration Attestation:\nStationary Scale #4 was re-calibrated yesterday by certified state weights and measures inspectors, verifying accuracy within 0.05%.\n\n*Action Directive: Per Document 1 discrepancy resolution guidelines, this email serves as the official written confirmation from the regional terminal manager required to unfreeze Invoice #9021. Please release Invoice #9021 immediately for standard processing without billing penalties.", "questions": [{"question": "What initial discrepancy was observed for Container #4492?", "options": {"A": "15 kilograms", "B": "50 kilograms", "C": "62 kilograms", "D": "120 kilograms"}, "answer": "C", "radar": "🔍 防漏看雷達：數字定位 'The initial discrepancy of 62 kilograms'！", "analysis": "文中指明最初記錄的差異為 62 公斤，故選 (C)。"}, {"question": "What caused the weight discrepancy according to Marcus Vance?", "options": {"A": "Theft of internal electrical parts", "B": "Moisture absorbed by outer wooden packaging during ocean transit", "C": "Incorrect scale calibration at origin", "D": "Extra metal tools stored inside"}, "answer": "B", "radar": "🔍 防漏看雷達：成因定位 'attributed to moisture absorbed by outer wooden packaging during ocean transit'！", "analysis": "經理說明差異係因海運過程中外包裝吸水所致，故選 (B)。"}, {"question": "Cross-Passage Question: What does Marcus Vance's email accomplish according to Document 1?", "options": {"A": "It provides the written confirmation needed to unfreeze Invoice #9021", "B": "It cancels the container lease entirely", "C": "It rejects the shipment and orders it returned to origin", "D": "It demands that the supplier be removed from the approved vendor list"}, "answer": "A", "radar": "🔍 防漏看跨篇交叉雷達：對照文件一星號『pending written confirmation』與文件二主旨與結尾！", "analysis": "雙篇交叉比對：文件一規定發票凍結直到站點經理提供書面確認，文件二 Marcus Vance 正式提供確認並要求放行發票，故選 (A)。"}]}]}}}, "24": {"day": 24, "date": "11/27", "phase": 3, "phase_name": "考前全真極速模擬與弱點獵殺", "topic": "考前 48 小時錯題庫極速回放 ｜ 4 大盲區極速自檢", "morning": {"chunks": [{"chunk": "adhere strictly to", "meaning": "嚴格遵守……規章", "scenario": "Personnel must adhere strictly to the rules.", "paraphrase": "adhere to = abide by = comply with = conform to", "alert": "adhere 固定接 to！"}, {"chunk": "in accordance with", "meaning": "依照/根據……規定", "scenario": "The audit was conducted in accordance with national laws.", "paraphrase": "in accordance with = in compliance with", "alert": "固定商務法務片語！"}, {"chunk": "subject to change", "meaning": "可能發生變更/須視情況而定", "scenario": "Fares are subject to change without advance notice.", "paraphrase": "subject to change = conditional = liable to modification", "alert": "subject 作形容詞！"}, {"chunk": "prior to departure", "meaning": "在出發之前", "scenario": "Confirm your seat assignment prior to departure.", "paraphrase": "prior to = before = ahead of", "alert": "prior 後接 to！"}, {"chunk": "under the supervision of", "meaning": "在……監督指導下", "scenario": "Interns work under the supervision of senior researchers.", "paraphrase": "under the supervision of = supervised by", "alert": "名詞形式為 supervision！"}, {"chunk": "eligible for promotion", "meaning": "符合晉升資格", "scenario": "High performers are eligible for promotion after one year.", "paraphrase": "eligible for = qualified for", "alert": "eligible 後接 for！"}, {"chunk": "compatible with the system", "meaning": "與該系統相容", "scenario": "Ensure the device is compatible with the operating system.", "paraphrase": "compatible with = adaptable to", "alert": "compatible 後接 with！"}], "visual_anchor": {"title": "考前 48 小時四大盲區秒殺檢查表", "rule_1": "👀 【動詞時態與語態】：看到主詞與動詞之間，先問『主動還是被動』？『有 S 還是沒 S』？", "rule_2": "👀 【詞性夾心位置】：will / has / be 與後方動詞之間的破洞 ➔ 100% 填入「副詞 (-ly)」！", "golden_rule": "⚡ 教練金句：四大盲區一秒自檢，抓緊固定介係詞與夾心副詞！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "All laboratory technicians must adhere strictly ________ established chemical protocols.", "options": {"A": "to", "B": "with", "C": "for", "D": "at"}, "answer": "A", "analysis": "adhere strictly to...（嚴格遵守……）。adhere 固定搭配介系詞 to！選 (A)。", "translation": "所有實驗室技術人員必須嚴格遵守既定的化學品規程。"}, {"id": 2, "target_seconds": 15, "question": "The executive committee will meet in ________ with the corporate governance guidelines.", "options": {"A": "accordance", "B": "accord", "C": "according", "D": "accorded"}, "answer": "A", "analysis": "in accordance with...（依據/依照……規定）。選名詞 (A)。", "translation": "執行委員會將依照企業管治準則召開會議。"}, {"id": 3, "target_seconds": 15, "question": "Shipping schedules are ________ to change due to severe winter weather.", "options": {"A": "subject", "B": "subjected", "C": "subjecting", "D": "subjects"}, "answer": "A", "analysis": "be subject to change（可能發生變更）。選形容詞 (A)。", "translation": "由於嚴冬惡劣天氣，出貨時間表可能會發生變動。"}, {"id": 4, "target_seconds": 15, "question": "________ to the announcement, the CEO briefed senior division directors.", "options": {"A": "Prior", "B": "Subsequent", "C": "Following", "D": "Pending"}, "answer": "A", "analysis": "Prior to + 名詞（在……之前）。選 (A)。", "translation": "在公告發布之前，執行長向資深事業部處長進行了簡報。"}, {"id": 5, "target_seconds": 15, "question": "The factory was constructed under the immediate ________ of chief architect Vance.", "options": {"A": "supervision", "B": "supervise", "C": "supervised", "D": "supervising"}, "answer": "A", "analysis": "under the supervision of...（在……的監督指導之下）。選名詞 (A)。", "translation": "該工廠是在首席建築師 Vance 的直接監督下興建的。"}, {"id": 6, "target_seconds": 15, "question": "Ms. Chen was placed in ________ of global marketing logistics.", "options": {"A": "charge", "B": "charged", "C": "charging", "D": "charger"}, "answer": "A", "analysis": "in charge of...（負責……）。選 (A)。", "translation": "Chen 女士被任命負責全球行銷物流。"}, {"id": 7, "target_seconds": 15, "question": "Employees who complete two years of service become ________ for the tuition reimbursement plan.", "options": {"A": "eligible", "B": "eligibility", "C": "eligibly", "D": "eligibles"}, "answer": "A", "analysis": "become eligible for...（符合……資格）。選形容詞 (A)。", "translation": "服務滿兩年的員工即具備申請學費全額補助計畫的資格。"}, {"id": 8, "target_seconds": 15, "question": "The board announced that Mr. Sato will ________ take over the European division.", "options": {"A": "officially", "B": "official", "C": "officials", "D": "officiate"}, "answer": "A", "analysis": "助動詞夾心餅乾：will + [副詞 -ly] + take over (動詞)。選 (A) officially。", "translation": "董事會宣布 Sato 先生將正式接管歐洲事業部。"}, {"id": 9, "target_seconds": 15, "question": "Customers receiving damaged items are ________ to a prompt replacement.", "options": {"A": "entitled", "B": "entitle", "C": "entitlement", "D": "entitling"}, "answer": "A", "analysis": "be entitled to + 名詞（有權獲得……）。選 (A)。", "translation": "收到瑕疵物品的顧客有權獲得及時更換。"}, {"id": 10, "target_seconds": 15, "question": "Non-profit foundations are ________ from paying municipal commercial taxes.", "options": {"A": "exempted", "B": "exempt", "C": "exemption", "D": "exempting"}, "answer": "A", "analysis": "are exempted from...（被免除……）。選 (A)。", "translation": "非營利基金會獲免繳市政商用稅。"}, {"id": 11, "target_seconds": 15, "question": "The revised accounting software is fully ________ with our current operating system.", "options": {"A": "compatible", "B": "compatibility", "C": "compatibly", "D": "compatibles"}, "answer": "A", "analysis": "be compatible with...（與……相容）。選 (A)。", "translation": "修改後的會計軟體與我們目前的作業系統完全相容。"}, {"id": 12, "target_seconds": 15, "question": "________ the unexpected rise in fuel costs, the airline maintained high profitability.", "options": {"A": "Despite", "B": "Although", "C": "Even if", "D": "Whereas"}, "answer": "A", "analysis": "介系詞 + 名詞片語：Despite the unexpected rise...。選 (A)。", "translation": "儘管燃油成本意外上漲，該航空公司仍保持了較高的盈利能力。"}, {"id": 13, "target_seconds": 15, "question": "Senior leaders found the new inventory interface remarkably ________ to master.", "options": {"A": "easy", "B": "easily", "C": "easiness", "D": "ease"}, "answer": "A", "analysis": "find + O + [形容詞受詞補語]：found the interface easy to master。選 (A)。", "translation": "資深領導發現新的庫存介面非常容易掌握。"}, {"id": 14, "target_seconds": 15, "question": "The managing director requested that the contract ________ by legal counsel.", "options": {"A": "be reviewed", "B": "was reviewed", "C": "reviewed", "D": "is reviewing"}, "answer": "A", "analysis": "命令要求建議動詞 requested that + S + (should) 原形動詞：be reviewed。選 (A)。", "translation": "常務董事要求該合約由法律顧問進行審查。"}, {"id": 15, "target_seconds": 15, "question": "Please submit all expense claims by Friday; ________, payments will be deferred.", "options": {"A": "otherwise", "B": "unless", "C": "although", "D": "despite"}, "answer": "A", "analysis": "分號後轉折副詞：; otherwise , S+V。選 (A)。", "translation": "請在週五前提交所有報銷申請；否則，款項將延後支付。"}, {"id": 16, "target_seconds": 15, "question": "The warehouse will process rush orders ________ they are confirmed before noon.", "options": {"A": "provided that", "B": "even if", "C": "as though", "D": "barring"}, "answer": "A", "analysis": "條件連接詞：provided that（只要/前提是）。選 (A)。", "translation": "只要急件在中午前確認，倉庫即可予以處理。"}, {"id": 17, "target_seconds": 15, "question": "Anyone ________ in attending the workshop should complete online registration.", "options": {"A": "interested", "B": "interesting", "C": "interest", "D": "interests"}, "answer": "A", "analysis": "先行詞 Anyone 後接被動分詞 interested [who is interested]。選 (A)。", "translation": "任何對參加研討會感興趣的人都應完成線上註冊。"}, {"id": 18, "target_seconds": 15, "question": "________ unforeseen delays at customs, the consignment will arrive tomorrow morning.", "options": {"A": "Barring", "B": "Unless", "C": "Although", "D": "Without"}, "answer": "A", "analysis": "除外介系詞：Barring + 名詞（除非有……）。選 (A)。", "translation": "除非海關出現無法預見的延誤，否則該批貨物將於明晨送達。"}, {"id": 19, "target_seconds": 15, "question": "Tenants are scheduled to ________ the top two penthouse suites next week.", "options": {"A": "occupy", "B": "occupancy", "C": "occupant", "D": "occupied"}, "answer": "A", "analysis": "scheduled to + 原形動詞 occupy。選 (A)。", "translation": "租戶預定下週進駐頂層的兩間閣樓套房。"}, {"id": 20, "target_seconds": 15, "question": "Applicants must satisfy all stated academic ________ before being scheduled for interviews.", "options": {"A": "criteria", "B": "criterion", "C": "criterias", "D": "criterial"}, "answer": "A", "analysis": "複數名詞受詞：all stated academic criteria。選 (A)。", "translation": "申請人必須滿足所有規定的學術標準方可獲安排面試。"}]}, "afternoon": {"quick_recall": [{"prompt": "to adhere strictly ________ [介系詞] guidelines.", "clue": "嚴格遵守 (adhere ...)", "answer": "to"}, {"prompt": "in ________ [名詞] with corporate regulations.", "clue": "依照規定 (in ... with)", "answer": "accordance"}, {"prompt": "Prices are ________ [形容詞] to adjustment without notice.", "clue": "可能變動 (be ... to)", "answer": "subject"}, {"prompt": "The manager found the system ________ [形容詞補語] to operate.", "clue": "find + O + OC 形容詞", "answer": "easy / intuitive"}, {"prompt": "He recommended that all staff ________ [原形動詞] present.", "clue": "要求建議 that 省略 should", "answer": "be"}, {"prompt": "be ________ [形容詞] for the annual promotion.", "clue": "符合資格 (be ... for)", "answer": "eligible"}], "spaced_traps": [{"id": 1, "target_seconds": 20, "question": "All research associates must adhere strictly ________ the laboratory code of ethics.", "options": {"A": "to", "B": "with", "C": "for", "D": "at"}, "answer": "A", "trap_point": "adhere 固定搭配介系詞 to！", "analysis": "adhere strictly to... 選 (A)。", "translation": "所有助理研究員必須嚴格遵守實驗室道德準則。"}, {"id": 2, "target_seconds": 20, "question": "The financial audit was performed in ________ with national accounting guidelines.", "options": {"A": "accordance", "B": "accord", "C": "according", "D": "accorded"}, "answer": "A", "trap_point": "in accordance with 表依據規章！", "analysis": "固定片語選名詞 (A) accordance。", "translation": "財務審計是依照國家會計準則進行的。"}, {"id": 3, "target_seconds": 20, "question": "Delivery timelines are ________ to modification depending on shipping container availability.", "options": {"A": "subject", "B": "subjected", "C": "subjecting", "D": "subjects"}, "answer": "A", "trap_point": "be subject to modification 表可能會變動！", "analysis": "形容詞作補語，選 (A) subject。", "translation": "交付時間表視海運貨櫃供應情況而可能發生變更。"}, {"id": 4, "target_seconds": 20, "question": "________ to joining the executive board, Dr. Vance directed clinical trials.", "options": {"A": "Prior", "B": "Subsequent", "C": "Following", "D": "Pending"}, "answer": "A", "trap_point": "Prior to + V-ing（在…之前）！", "analysis": "時間介系詞選 (A) Prior to。", "translation": "在加入執行董事會之前，Vance 博士指導了臨床試驗。"}, {"id": 5, "target_seconds": 20, "question": "Subterranean foundation repair was executed under the ________ of structural experts.", "options": {"A": "supervision", "B": "supervise", "C": "supervised", "D": "supervising"}, "answer": "A", "trap_point": "under the supervision of... 名詞！", "analysis": "介系詞短語選名詞 (A) supervision。", "translation": "地下基礎修復工程是在結構專家的監督下進行的。"}, {"id": 6, "target_seconds": 20, "question": "The board placed Mr. Gomez in ________ of overseas supply chain logistics.", "options": {"A": "charge", "B": "charged", "C": "charging", "D": "charger"}, "answer": "A", "trap_point": "in charge of... 固定搭配！", "analysis": "選名詞 (A) charge。", "translation": "董事會指派 Gomez 先生負責海外供應鏈物流。"}, {"id": 7, "target_seconds": 20, "question": "Employees completing the certification workshop become ________ for promotion.", "options": {"A": "eligible", "B": "eligibility", "C": "eligibly", "D": "eligibles"}, "answer": "A", "trap_point": "become eligible for... 形容詞！", "analysis": "連綴動詞 become 接形容詞 (A) eligible。", "translation": "完成認證研討會的員工即具備升遷資格。"}, {"id": 8, "target_seconds": 20, "question": "The spokesperson announced that Dr. Lin will ________ step down as medical director.", "options": {"A": "officially", "B": "official", "C": "officials", "D": "officiate"}, "answer": "A", "trap_point": "will + [副詞] + step down 夾心位置！", "analysis": "副詞修飾動詞片語，選 (A) officially。", "translation": "發言人宣布 Lin 博士將正式辭去醫療處長一職。"}, {"id": 9, "target_seconds": 20, "question": "Clients who receive damaged merchandise are ________ to an immediate refund.", "options": {"A": "entitled", "B": "entitle", "C": "entitlement", "D": "entitling"}, "answer": "A", "trap_point": "be entitled to + 名詞！", "analysis": "選過去分詞形容詞 (A) entitled（有權享有）。", "translation": "收到破損商品的客戶有權立即獲得退款。"}, {"id": 10, "target_seconds": 20, "question": "Non-profit medical institutions are ________ from regional property taxes.", "options": {"A": "exempted", "B": "exempt", "C": "exemption", "D": "exempting"}, "answer": "A", "trap_point": "are exempted from... 被動！", "analysis": "選過去分詞 (A) exempted。", "translation": "非營利醫療機構獲免除區域物業稅。"}, {"id": 11, "target_seconds": 20, "question": "The software upgrade is completely ________ with existing server architecture.", "options": {"A": "compatible", "B": "compatibility", "C": "compatibly", "D": "compatibles"}, "answer": "A", "trap_point": "be completely compatible with！", "analysis": "連綴動詞接形容詞 (A) compatible。", "translation": "該軟體升級與現有的伺服器架構完全相容。"}, {"id": 12, "target_seconds": 20, "question": "________ the severe winter storm, the freight carrier completed all priority deliveries.", "options": {"A": "Despite", "B": "Although", "C": "Even if", "D": "Whereas"}, "answer": "A", "trap_point": "Despite + 名詞片語！", "analysis": "介系詞表儘管，選 (A) Despite。", "translation": "儘管遭遇嚴重的冬季暴風雪，貨運承運商仍完成了所有優先配送。"}, {"id": 13, "target_seconds": 20, "question": "Inspectors found the updated factory layout remarkably ________ to navigate.", "options": {"A": "easy", "B": "easily", "C": "easiness", "D": "ease"}, "answer": "A", "trap_point": "find + O + [形容詞受詞補語]！", "analysis": "受詞補語位置填形容詞 (A) easy。", "translation": "檢查員發現更新後的工廠佈局非常容易穿行。"}, {"id": 14, "target_seconds": 20, "question": "The audit committee recommended that the accounts ________ independently certified.", "options": {"A": "be", "B": "were", "C": "are", "D": "have been"}, "answer": "A", "trap_point": "recommended that + S + (should) 原形動詞！", "analysis": "虛擬語氣省略 should，選原形動詞 (A) be。", "translation": "審計委員會建議帳目由獨立機構進行認證。"}], "part7": {"passages": [{"text_type": "Internal Audit Directive (企業審計部48小時錯誤排查與送審手冊)", "title": "Global Audit Directorate — 48-Hour Final Error Inspection & Pre-Audit Checklist", "content": "INTERNAL AUDIT DIRECTIVE: GAD-CHK-2026-24\nTO: All Continental Division Controllers, Finance Directors, and Legal Staff\nFROM: Global Audit Directorate & Chief Compliance Officer\nDATE: November 27, 2026\nURGENCY: 48-Hour Final Pre-Audit Compliance Cycle\n\n1. Pre-Audit Self-Inspection Mandate\nAs we approach the fiscal year-end regulatory closing, all division controllers must complete the mandatory 4-Point Self-Inspection Checklist by Friday at 5:00 PM without exception. This exhaustive quality filter guarantees that all contracts, procurement filings, and transactional balance sheets comply with international accounting standards before external statutory inspectors commence on-site audits.\n\n2. Critical Inspection Categories\nAudit diagnostics demonstrate that corporate filings frequently fail due to linguistic and syntactical inaccuracies. The inspection checklist systematically reviews four grammatical areas: verb tenses, passive constructions, parts of speech, and preposition pairings across all departmental purchase orders, international vendor agreements, commercial invoicing files, and compliance records.\n\n*Automatic Rejection Criteria: Compliance officers will exercise zero tolerance for sloppy documentation. Procurement documentation will be rejected automatically if flagged for persistent preposition errors or missing supervisory signatures. Corrected filings must be re-submitted within twenty-four hours to avoid division audit penalties.", "questions": [{"question": "What must all division controllers complete by Friday at 5:00 PM?", "options": {"A": "A total inventory liquidation", "B": "The 4-Point Self-Inspection Checklist", "C": "An overseas executive interview", "D": "A commercial real estate appraisal"}, "answer": "B", "radar": "🔍 防漏看雷達：行動要求 'complete the 4-Point Self-Inspection Checklist'！", "analysis": "文中明確要求在週五下午 5:00 前完成四點自我檢查清單，故選 (B)。"}, {"question": "What four grammatical areas are covered by the inspection checklist?", "options": {"A": "Pronunciation, spelling, handwriting, punctuation", "B": "Verb tenses, passive constructions, parts of speech, preposition pairings", "C": "Font size, margins, page numbers, color gradients", "D": "Translation, interpretation, subtitles, audio levels"}, "answer": "B", "radar": "🔍 防漏看雷達：四項盲區 'verb tenses, passive constructions, parts of speech alignment, and preposition pairings'！", "analysis": "內文列出動詞時態、被動結構、詞性對齊與介係詞搭配四大盲區，故選 (B)。"}, {"question": "What causes procurement documentation to be rejected automatically?", "options": {"A": "Minor typographical errors on cover pages", "B": "Persistent preposition errors or missing supervisory signatures", "C": "Submissions sent via electronic mail", "D": "Documents printed on recycled paper"}, "answer": "B", "radar": "🔍 防漏看雷達：星號警戒條款 '*Critical Warning: ... persistent preposition errors or missing supervisory signatures'！", "analysis": "星號條款特別註明若有持續性介係詞錯誤或缺少主管簽字將遭自動退件，故選 (B)。"}]}, {"text_type": "Regulatory Certification Document (金融監管品質驗證與交易分類帳審計證書)", "title": "Lexington Financial — Quality Verification Certificate & Trading Ledger Audit", "content": "REGULATORY CERTIFICATION DOCUMENT: LEX-FIN-CERT-2026\nISSUING BODY: Lexington Financial Regulatory Oversight Office & Compliance Registry\nDATE: November 27, 2026\nAUDIT PERIOD: Comprehensive Fiscal Year 2026 Ledger Certification\n\n1. Institutional Scope & Solvency Verification\nThe Regulatory Oversight Office certifies that Lexington Financial maintains 12,000 corporate trading accounts in strict compliance with international banking liquidity standards, anti-money laundering frameworks, and capital adequacy directives. Forensic ledger audits confirmed zero discrepancies across multi-currency settlement reserves and custodial trust funds held in regional branches across North America, Europe, and Asia.\n\n2. Clearinghouse Interoperability Standards\nAll automated ledger processing systems are engineered to be fully compatible with central bank clearinghouse protocols, ensuring seamless straight-through transaction processing, instant counterparty verification, and zero settlement delays during high-volume international trading sessions across global currency markets.\n\n*Mandatory Reconciliation Timeline: To safeguard our Tier 1 institutional clearing license, internal compliance monitoring operates continuously. Accounts identified with documentation discrepancies must be reconciled within 48 hours of automated notification. Accounts remaining unverified after forty-eight hours will be subjected to immediate transaction freezes and escalated to corporate compliance legal counsel.", "questions": [{"question": "How many corporate trading accounts does Lexington Financial maintain?", "options": {"A": "1,200", "B": "5,000", "C": "12,000", "D": "24,000"}, "answer": "C", "radar": "🔍 防漏看雷達：帳戶數字 'all 12,000 corporate trading accounts'！", "analysis": "文中明確指出管理 12,000 個企業交易帳戶，故選 (C)。"}, {"question": "What standard are the automated ledger processing systems compatible with?", "options": {"A": "Central bank clearinghouse protocols", "B": "Local municipal library catalogs", "C": "Uncertified overseas internet servers", "D": "Manual paper card filing systems"}, "answer": "A", "radar": "🔍 防漏看雷達：相容標準 'compatible with central bank clearinghouse protocols'！", "analysis": "內文指出系統與央行結算所協定完全相容，故選 (A)。"}, {"question": "Within how many hours must accounts with documentation discrepancies be reconciled?", "options": {"A": "24 hours", "B": "48 hours", "C": "72 hours", "D": "120 hours"}, "answer": "B", "radar": "🔍 防漏看雷達：星號時限 '*Mandatory Attestation: ... reconciled within forty-eight hours'！", "analysis": "星號條款註明必須在 48 小時內完成對帳調節，故選 (B)。"}]}]}}}, "25": {"day": 25, "date": "11/28", "phase": 3, "phase_name": "考前全真極速模擬與弱點獵殺", "topic": "考前 24 小時金色證書配速心法與實戰答題手冊", "morning": {"chunks": [{"chunk": "substantially boost revenue", "meaning": "大幅提升營收", "scenario": "The new product will substantially boost revenue.", "paraphrase": "substantially = significantly = considerably = vastly", "alert": "副詞修飾動詞！"}, {"chunk": "adhere strictly to", "meaning": "嚴格遵守……規程", "scenario": "Personnel must adhere strictly to protocols.", "paraphrase": "adhere strictly to = abide rigorously by", "alert": "必考介系詞 to！"}, {"chunk": "hold off on the project", "meaning": "暫緩擱置該專案", "scenario": "We decided to hold off on the project until next quarter.", "paraphrase": "hold off on = postpone = delay = defer", "alert": "片語動詞！"}, {"chunk": "eligible for the award", "meaning": "符合獲獎資格", "scenario": "Only full-time staff are eligible for the award.", "paraphrase": "eligible for = qualified for = entitled to", "alert": "必考介系詞 for！"}, {"chunk": "allocate time wisely", "meaning": "明智分配時間", "scenario": "Pacing requires candidates to allocate time wisely.", "paraphrase": "allocate time wisely = budget time efficiently", "alert": "實戰考試必備配速心法！"}, {"chunk": "trust visual anchors", "meaning": "信任視覺錨點", "scenario": "In Part 5, trust visual anchors to eliminate guesswork.", "paraphrase": "trust visual anchors = rely on visual grammatical markers", "alert": "25 天特訓核心心法！"}, {"chunk": "achieve 860+ golden certificate", "meaning": "勇奪 860+ 多益金色證書", "scenario": "With steady practice, you will achieve 860+ golden certificate.", "paraphrase": "achieve 860+ = earn the golden credential", "alert": "衝刺終極目標！"}], "visual_anchor": {"title": "考前 24 小時金色證書實戰配速心法手冊", "rule_1": "👀 【Part 5 答題節奏】：每題 15 秒秒殺，最長絕不超過 20 秒，遇到長句找視覺錨點（破洞前後單字）！", "rule_2": "👀 【Part 7 獵殺節奏】：先看題幹定位關鍵字，單篇快讀，雙篇三篇慢讀「星號附註與金額日期」，必有交叉解！", "golden_rule": "⚡ 教練金句：沉著冷靜，相信語感，1,000 題淬鍊，金色必達！"}, "part5": [{"id": 1, "target_seconds": 15, "question": "The executive committee is confident that the new strategy will ________ boost shareholder value.", "options": {"A": "substantially", "B": "substantial", "C": "substantiate", "D": "substantiality"}, "answer": "A", "analysis": "will + [副詞] + boost (動詞原形)。副詞修飾動詞，選 (A) substantially。", "translation": "執行委員會確信新策略將大幅提升股東價值。"}, {"id": 2, "target_seconds": 15, "question": "All personnel must adhere strictly ________ confidential data security protocols.", "options": {"A": "to", "B": "with", "C": "for", "D": "at"}, "answer": "A", "analysis": "adhere strictly to... 選 (A)。", "translation": "所有人員必須嚴格遵守機密資料安全規程。"}, {"id": 3, "target_seconds": 15, "question": "The board unanimously approved the budget ________ the proposal was revised to address regulatory concerns.", "options": {"A": "once", "B": "in spite of", "C": "prior to", "D": "owing to"}, "answer": "A", "analysis": "從屬連接詞 + 完整子句 S+V：once 表『一旦……就……』。選 (A)。", "translation": "一旦該提案經過修改以解決法規疑慮，董事會便一致通過了預算。"}, {"id": 4, "target_seconds": 15, "question": "Employees who show exceptional dedication are ________ for leadership advancements.", "options": {"A": "eligible", "B": "compatible", "C": "accustomed", "D": "resistant"}, "answer": "A", "analysis": "be eligible for...（符合……資格）。選 (A)。", "translation": "表現出卓越奉獻精神的員工符合晉升領導職務的資格。"}, {"id": 5, "target_seconds": 15, "question": "Management decided to ________ the marketing campaign until market conditions improve.", "options": {"A": "hold off on", "B": "step down", "C": "take over", "D": "back down"}, "answer": "A", "analysis": "片語動詞：hold off on...（暫緩/推遲）。選 (A)。", "translation": "管理層決定暫緩行銷活動直到市況好轉。"}, {"id": 6, "target_seconds": 15, "question": "The factory was constructed in strict ________ with all municipal environmental codes.", "options": {"A": "compliance", "B": "compliant", "C": "comply", "D": "compliantly"}, "answer": "A", "analysis": "in strict compliance with... 選名詞 (A)。", "translation": "工廠的興建嚴格遵守所有市政環境法規。"}, {"id": 7, "target_seconds": 15, "question": "Senior partners will ________ resources to the emerging artificial intelligence division.", "options": {"A": "allocate", "B": "allocation", "C": "allocated", "D": "allocating"}, "answer": "A", "analysis": "will + 原形動詞 allocate。選 (A)。", "translation": "資深合夥人將把資源分配給新興的人工智慧事業部。"}, {"id": 8, "target_seconds": 15, "question": "The hotel offers ________ penthouse suites for corporate conference dignitaries.", "options": {"A": "exclusive", "B": "exclusively", "C": "exclusivity", "D": "exclude"}, "answer": "A", "analysis": "形容詞修飾 suites。exclusive suites（專屬套房）。選 (A)。", "translation": "飯店為企業會議貴賓提供專屬閣樓套房。"}, {"id": 9, "target_seconds": 15, "question": "Inspectors verified that the titanium welds were completed with extreme ________.", "options": {"A": "precision", "B": "precise", "C": "precisely", "D": "preciseness"}, "answer": "A", "analysis": "介系詞 with extreme + 名詞 (A) precision。", "translation": "檢查員核實鈦金屬焊接是以極高的精準度完成的。"}, {"id": 10, "target_seconds": 15, "question": "The commercial tenant promised to ________ the office suite by midnight Friday.", "options": {"A": "vacate", "B": "vacation", "C": "vacated", "D": "vacating"}, "answer": "A", "analysis": "promised to + 原形動詞 vacate。選 (A)。", "translation": "商業承租人承諾在週五午夜前騰空辦公套房。"}, {"id": 11, "target_seconds": 15, "question": "The airline announced that flights will depart on schedule ________ minor snow flurries.", "options": {"A": "despite", "B": "although", "C": "even if", "D": "whereas"}, "answer": "A", "analysis": "介系詞 despite + 名詞片語。選 (A)。", "translation": "航空公司宣布儘管有微小飄雪，航班仍將按時啟程。"}, {"id": 12, "target_seconds": 15, "question": "Tenants are prohibited from making alterations anywhere on the corporate ________.", "options": {"A": "premises", "B": "premise", "C": "premised", "D": "premising"}, "answer": "A", "analysis": "on the corporate premises（在公司處所內）。選 (A)。", "translation": "禁止租戶在公司處所內的任何地方進行改動。"}, {"id": 13, "target_seconds": 15, "question": "Attendance at the annual ethics briefing is strictly ________ for senior directors.", "options": {"A": "mandatory", "B": "mandate", "C": "mandatorily", "D": "mandates"}, "answer": "A", "analysis": "is strictly mandatory 形容詞。選 (A)。", "translation": "資深處長必須強制參加年度道德簡報會。"}, {"id": 14, "target_seconds": 15, "question": "The warranty covers mechanical repairs ________ proper service logs are submitted.", "options": {"A": "provided that", "B": "even if", "C": "as though", "D": "barring"}, "answer": "A", "analysis": "provided that = 只要/前提是。選 (A)。", "translation": "只要提交適當的維修日誌，保固即涵蓋機械修理。"}, {"id": 15, "target_seconds": 15, "question": "The laboratory technician calibrated optic sensors to guarantee ________ results.", "options": {"A": "accurate", "B": "accurately", "C": "accuracy", "D": "accurateness"}, "answer": "A", "analysis": "形容詞修飾名詞 results。選 (A) accurate。", "translation": "實驗室技術人員校準了光學傳感器以保證結果準確。"}, {"id": 16, "target_seconds": 15, "question": "The hospital initiated a comprehensive review to ________ patient waiting times.", "options": {"A": "streamline", "B": "streamlined", "C": "streamlines", "D": "streamlining"}, "answer": "A", "analysis": "to + 原形動詞 streamline。選 (A)。", "translation": "醫院啟動了全面審查以簡化病患等待時間。"}, {"id": 17, "target_seconds": 15, "question": "The newly appointed CEO intends to ________ a series of corporate green initiatives.", "options": {"A": "initiate", "B": "initiating", "C": "initiated", "D": "initiation"}, "answer": "A", "analysis": "intends to + 原形動詞 initiate。選 (A)。", "translation": "新任命的執行長打算發起一系列企業環保倡議。"}, {"id": 18, "target_seconds": 15, "question": "Subscribers will be notified prior to the ________ of their membership pass.", "options": {"A": "expiration", "B": "expire", "C": "expired", "D": "expiring"}, "answer": "A", "analysis": "prior to the expiration of... 選名詞 (A)。", "translation": "訂閱者將在其會員通行證到期前收到通知。"}, {"id": 19, "target_seconds": 15, "question": "The engineering firm is the ________ provider of high-speed rail signaling software.", "options": {"A": "sole", "B": "solely", "C": "solitary", "D": "solo"}, "answer": "A", "analysis": "the sole provider（唯一提供商）。選 (A)。", "translation": "該工程公司是高鐵信號軟體的唯一供應商。"}, {"id": 20, "target_seconds": 15, "question": "Contractors ________ the safety guidelines will be denied entry to the industrial site.", "options": {"A": "violating", "B": "violate", "C": "violated", "D": "violation"}, "answer": "A", "analysis": "Contractors [who violate] 簡化為主動分詞 (A) violating。", "translation": "違反安全準則的承包商將被拒絕進入工業現場。"}]}, "afternoon": {"quick_recall": [{"prompt": "Part 5 target speed: ________ [幾秒] per question.", "clue": "金色證書目標每題秒數", "answer": "15-20 seconds"}, {"prompt": "Seeing 'will _____ verb', immediately choose an ________ [詞性].", "clue": "詞性，夾心位置", "answer": "Adverb (-ly)"}, {"prompt": "In Part 7, always pay close attention to ________ [星號小字與附註].", "clue": "陷阱常出沒處", "answer": "Fine print / footnotes (*Note)"}, {"prompt": "The golden milestone score: ________ [幾分以上] points.", "clue": "金色證書門檻", "answer": "860+"}, {"prompt": "On double passages, look for cross-document ________ [交叉對照].", "clue": "跨篇交叉比對", "answer": "cross-referencing"}, {"prompt": "The golden exam rule: never stay stuck on a question for over ________ [幾秒] seconds.", "clue": "停筆停滯上限", "answer": "40 seconds"}], "spaced_traps": [{"id": 1, "target_seconds": 20, "question": "The executive board is confident that the restructuring will ________ enhance profit margins.", "options": {"A": "substantially", "B": "substantial", "C": "substantiate", "D": "substantiality"}, "answer": "A", "trap_point": "will + [副詞] + enhance 夾心位置！", "analysis": "副詞修飾動詞，選 (A) substantially。", "translation": "執行董事會確信重組將大幅提高利潤率。"}, {"id": 2, "target_seconds": 20, "question": "Personnel must adhere strictly ________ the revised digital encryption protocols.", "options": {"A": "to", "B": "with", "C": "for", "D": "at"}, "answer": "A", "trap_point": "adhere strictly to... 固定搭配！", "analysis": "選介系詞 (A) to。", "translation": "人員必須嚴格遵守修改後的數位加密協定。"}, {"id": 3, "target_seconds": 20, "question": "The city council approved the transit budget ________ the environmental impact report was finalized.", "options": {"A": "once", "B": "in spite of", "C": "prior to", "D": "owing to"}, "answer": "A", "trap_point": "連接詞 once 接完整子句 S+V！", "analysis": "選從屬連接詞 (A) once。", "translation": "一旦環境影響報告定稿，市議會即批准了交通預算。"}, {"id": 4, "target_seconds": 20, "question": "Employees demonstrating exceptional initiative are ________ for corporate fellowships.", "options": {"A": "eligible", "B": "compatible", "C": "accustomed", "D": "resistant"}, "answer": "A", "trap_point": "be eligible for... 形容詞！", "analysis": "選形容詞 (A) eligible。", "translation": "展現非凡主動性的員工符合申請企業研究員獎學金的資格。"}, {"id": 5, "target_seconds": 20, "question": "Management resolved to ________ the product launch until semiconductor supplies stabilize.", "options": {"A": "hold off on", "B": "step down", "C": "take over", "D": "back down"}, "answer": "A", "trap_point": "hold off on 表暫緩推遲！", "analysis": "片語動詞選 (A) hold off on。", "translation": "管理層決議暫緩產品發表直到半導體供應穩定。"}, {"id": 6, "target_seconds": 20, "question": "The commercial facility operates in strict ________ with all federal safety mandates.", "options": {"A": "compliance", "B": "compliant", "C": "comply", "D": "compliantly"}, "answer": "A", "trap_point": "in strict compliance with... 名詞！", "analysis": "固定片語選名詞 (A) compliance。", "translation": "商業設施的運作嚴格遵守所有聯邦安全法令。"}, {"id": 7, "target_seconds": 20, "question": "The leadership council voted to ________ additional funding to renewable energy research.", "options": {"A": "allocate", "B": "allocation", "C": "allocated", "D": "allocating"}, "answer": "A", "trap_point": "voted to + 原形動詞 allocate！", "analysis": "不定詞接原形動詞，選 (A) allocate。", "translation": "領導委員會投票決定向可再生能源研究分配額外資金。"}, {"id": 8, "target_seconds": 20, "question": "The hotel chain provides ________ concierge services for executive suite guests.", "options": {"A": "exclusive", "B": "exclusively", "C": "exclusivity", "D": "exclude"}, "answer": "A", "trap_point": "exclusive concierge services 形容詞！", "analysis": "形容詞修飾名詞，選 (A) exclusive。", "translation": "連鎖飯店為行政套房賓客提供專屬禮賓服務。"}, {"id": 9, "target_seconds": 20, "question": "The laser cutting arm performs with microscopic ________ on semiconductor wafers.", "options": {"A": "precision", "B": "precise", "C": "precisely", "D": "preciseness"}, "answer": "A", "trap_point": "with microscopic precision 名詞！", "analysis": "介系詞與形容詞後接名詞 (A) precision。", "translation": "雷射切割手臂在半導體晶圓上以微觀級精準度作業。"}, {"id": 10, "target_seconds": 20, "question": "Tenants are legally obligated to ________ the commercial building upon lease expiration.", "options": {"A": "vacate", "B": "vacation", "C": "vacated", "D": "vacating"}, "answer": "A", "trap_point": "obligated to + 原形動詞 vacate！", "analysis": "不定詞接原形動詞，選 (A) vacate。", "translation": "租戶在租約到期時承擔騰空商業建築的法律義務。"}, {"id": 11, "target_seconds": 20, "question": "The cargo ship departed on time ________ adverse oceanic weather warnings.", "options": {"A": "despite", "B": "although", "C": "even if", "D": "whereas"}, "answer": "A", "trap_point": "despite + 名詞片語！", "analysis": "介系詞選 (A) despite。", "translation": "儘管有不利的海洋天氣警報，貨輪仍按時啟航。"}, {"id": 12, "target_seconds": 20, "question": "Contractors may not operate heavy equipment anywhere on the plant ________.", "options": {"A": "premises", "B": "premise", "C": "premised", "D": "premising"}, "answer": "A", "trap_point": "on the plant premises 名詞恆複數！", "analysis": "選名詞 (A) premises。", "translation": "承包商不得在廠區內的任何地方操作重型設備。"}, {"id": 13, "target_seconds": 20, "question": "Fire safety drill attendance is strictly ________ for all warehouse personnel.", "options": {"A": "mandatory", "B": "mandate", "C": "mandatorily", "D": "mandates"}, "answer": "A", "trap_point": "is strictly mandatory 形容詞！", "analysis": "連綴動詞接形容詞 (A) mandatory。", "translation": "所有倉庫人員必須嚴格強制參加消防演習。"}, {"id": 14, "target_seconds": 20, "question": "The warranty will be honored ________ original purchase receipts are provided.", "options": {"A": "provided that", "B": "even if", "C": "as though", "D": "barring"}, "answer": "A", "trap_point": "provided that 表只要/前提是！", "analysis": "條件連接詞選 (A) provided that。", "translation": "只要提供原始購買收據，保固即獲兌現。"}], "part7": {"passages": [{"text_type": "Exam Strategy Protocol (多益860+金色證書官方臨場作答配速指南)", "title": "25-Day Sprint Coaching Directorate — Exam Day Pacing Protocol & Strategic Rules", "content": "TOEIC 860+ MASTER COACHING DIRECTIVE: SPRINT-DAY25-PACING\nISSUED BY: Antigravity TOEIC Elite Sprint Coaching Directorate\nTARGET EXAM DATE: November 29, 2026\nAUDIENCE: All Sprint Candidates Targeting the 860+ Golden Certificate\n\n1. Part 5 Timing Rules & Reflex Execution\nTo conquer the 200-question TOEIC marathon tomorrow, tactical time allocation is paramount. In Part 5, questions test core grammar mechanics and corporate vocabulary. Your recommended target speed for Part 5 questions tomorrow is 15 to 20 seconds per question. Rely on structural clues, identify the missing part of speech, and execute with absolute conviction.\n\n2. The 40-Second Golden Rule\nNever allow a stubborn question to derail your exam rhythm. The maximum time you should ever spend on a single question without guessing and moving on is 40 seconds. If a question remains uncertain after forty seconds, choose your best reasoned guess, mark your score sheet, and proceed immediately to preserve energy for double and triple passages.\n\n*The Part 7 Trap Detector: In reading comprehension, ETS frequently conceals the 860+ discriminating answers in the fine print (*Note, *Important, *Clause, or parenthetical conditions) at the bottom of passages. Scan the asterisks first when answering condition questions!", "questions": [{"question": "What is the recommended target speed for Part 5 questions tomorrow?", "options": {"A": "5 to 10 seconds", "B": "15 to 20 seconds", "C": "45 to 60 seconds", "D": "Over 90 seconds"}, "answer": "B", "radar": "🔍 防漏看雷達：配速心法 'Part 5 at 15 to 20 seconds per question'！", "analysis": "文中明確指示 Part 5 每題配速保持在 15 至 20 秒，故選 (B)。"}, {"question": "What is the maximum time you should ever spend on a single question without guessing and moving on?", "options": {"A": "20 seconds", "B": "40 seconds", "C": "75 seconds", "D": "120 seconds"}, "answer": "B", "radar": "🔍 防漏看雷達：停滯上限 'Never spend over 40 seconds on any single item'！", "analysis": "內文告誡絕不在單一題目停滯超過 40 秒，故選 (B)。"}, {"question": "Where does ETS frequently conceal the 860+ discriminating answers in Part 7?", "options": {"A": "In the document title fonts", "B": "In the fine print (*Note, *Important, *Clause) at the bottom", "C": "In the copyright year footer", "D": "In the author's initials"}, "answer": "B", "radar": "🔍 防漏看雷達：星號叮嚀 '*Final Coaching Directive: Pay close attention to fine print (*Note, *Important, *Clause)'！", "analysis": "星號條款特別指出 ETS 常在星號小字與附註條款中隱藏 860+ 關鍵鑑別題正解，故選 (B)。"}]}, {"text_type": "Milestone Recognition & Victory Memo (25天衝刺結訓祝賀與金色證書里程碑)", "title": "TOEIC 860+ Golden Certificate Journey — Final Victory Message & Milestone Recognition", "content": "EXECUTIVE VALEDICTORY ADDRESS: SPRINT-FINAL-2026\nTO: Every Dedicated Candidate in the 25-Day Sprint\nFROM: Antigravity Chief Coach & The Golden Certificate Sprint Directorate\nDATE: November 28, 2026\nSUBJECT: 25 Days Completed — The 860+ Golden Certificate Awaits!\n\nCongratulations on completing the most rigorous, comprehensive TOEIC preparation curriculum ever engineered! Over the past twenty-five days, you have systematically tackled 1,000 questions (500 precision morning questions, 350 high-difficulty afternoon spaced traps, and 150 authentic long-form Part 7 questions). You have mastered every subtle grammatical trap, corporate vocabulary collocations, and cross-passage reasoning patterns through relentless discipline and active recall.\n\nThe Decisive Exam Mindset:\nTomorrow in the examination hall, your greatest asset is complete composure and trust in trained visual anchors. You have internalized every sentence structure and scanning reflex necessary to dissect questions with razor-sharp precision and flawless stamina across the entire two-hour test.\n\n*Milestone Achievement: Achieving a score of 860+ unlocks qualification for international corporate executive certification and opens premier career mobility across multinational enterprises. Stand tall, execute with confidence, and claim your Golden Certificate tomorrow! You are fully prepared to conquer.", "questions": [{"question": "How many total rigorous questions were tackled throughout the 25-day sprint?", "options": {"A": "250 questions", "B": "500 questions", "C": "750 questions", "D": "1,000 questions"}, "answer": "D", "radar": "🔍 防漏看雷達：總題量統計 'tackled 1,000 rigorous questions'！", "analysis": "文中明確總結 25 天特訓共完成了 1,000 道高強度精選試題，故選 (D)。"}, {"question": "What key attitude should you carry into the test room tomorrow?", "options": {"A": "Panic and rapid guessing", "B": "Complete composure and trust in trained visual anchors", "C": "Exhaustion and indifference", "D": "Over-analyzing every single preposition"}, "answer": "B", "radar": "🔍 防漏看雷達：心態金句 'Enter the test room tomorrow with complete composure. Trust the instincts and visual reflexes'！", "analysis": "文中勉勵保持完全沉著冷靜並信任訓練出來的視覺錨點，故選 (B)。"}, {"question": "What milestone benefit does an 860+ score unlock according to the note?", "options": {"A": "Free airline tickets for life", "B": "Qualification for international corporate executive certification", "C": "Automatic enrollment in medical school", "D": "Exemption from all corporate taxes"}, "answer": "B", "radar": "🔍 防漏看雷達：星號里程碑效益 '*Golden Milestone Note: ... qualify for international corporate executive certification'！", "analysis": "星號小字載明 860+ 分數具備國際企業高階主管認證資格，故選 (B)。"}]}]}}}}

